  (6812, 8, 15, 'BE', 'Offensive zur Personalgewinnung bei BVG und S-Bahn', '{803}', 6754, 2, 3, null, 'Schnellere Qualifizierung, Anerkennung ausländischer Abschlüsse und eigene Ausbildung setzen direkt am Mangel an; ohne bessere Bedingungen verlassen viele den Beruf wieder.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=41', null, 'gemischt', '2026-09-30', false, true, null),
  (6813, 8, 15, 'BE', 'Nahverkehrsanbindung neuer Stadtgebiete fertigstellen, bevor sie bezogen werden', '{801}', 6749, 2, 2, null, 'Häufigere Fahrten und direkte Verbindungen verbessern das Angebot spürbar und ziehen mehr Fahrgäste an; das Land muss die zusätzlichen Fahrten dauerhaft bezahlen und braucht Fahrpersonal.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=42', null, 'belegt', '2026-09-30', false, true, null),
  (6814, 8, 16, 'BE', 'Kleinbuslinien und Rufbusse in Außenbezirken und am Stadtrand', '{801}', 6750, 1, 3, null, 'Schließt Lücken dort, wo Linienbusse fast leer fahren würden; Rufbusse befördern wenige Menschen je Fahrt und sind teuer, ersetzen also keinen dichten Takt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=60', null, 'gemischt', '2026-09-30', false, true, null),
  (6815, 8, 16, 'BE', 'Anwerbung und Ausbildung von Fahrpersonal bei der BVG ausweiten', '{803}', 6754, 2, 3, null, 'Schnellere Qualifizierung, Anerkennung ausländischer Abschlüsse und eigene Ausbildung setzen direkt am Mangel an; ohne bessere Bedingungen verlassen viele den Beruf wieder.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=61', null, 'gemischt', '2026-09-30', false, true, null),
  (6816, 8, 16, 'BE', 'Arbeitsbedingungen bei der BVG verbessern', '{803}', 6753, 2, 3, null, 'Bessere Bezahlung macht den Fahrdienst attraktiver und hält Beschäftigte; das Land kann Tariftreue in der Vergabe und bei eigenen Unternehmen durchsetzen, muss die Mehrkosten aber tragen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=61', null, 'gemischt', '2026-09-30', false, true, null),
  (6817, 8, 17, 'BE', 'U-Bahn, S-Bahn, Straßenbahn und Bus vor allem in den Außenbezirken ausbauen', '{801}', 6749, 2, 2, null, 'Häufigere Fahrten und direkte Verbindungen verbessern das Angebot spürbar und ziehen mehr Fahrgäste an; das Land muss die zusätzlichen Fahrten dauerhaft bezahlen und braucht Fahrpersonal.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=48', null, 'belegt', '2026-09-30', false, true, null),
  (6818, 8, 17, 'BE', 'Rufbusse dort, wo Ortsteile unzureichend erschlossen sind', '{801}', 6750, 1, 3, null, 'Schließt Lücken dort, wo Linienbusse fast leer fahren würden; Rufbusse befördern wenige Menschen je Fahrt und sind teuer, ersetzen also keinen dichten Takt.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=48', null, 'gemischt', '2026-09-30', false, true, null),
  (6819, 8, 17, 'BE', 'Gleiche Bezahlung auch bei Tochtergesellschaften wie der BT Berlin Transport', '{803}', 6753, 2, 3, null, 'Bessere Bezahlung macht den Fahrdienst attraktiver und hält Beschäftigte; das Land kann Tariftreue in der Vergabe und bei eigenen Unternehmen durchsetzen, muss die Mehrkosten aber tragen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=10', null, 'gemischt', '2026-09-30', false, true, null),
  (6820, 3, 14, null, 'Wiederinbetriebnahme der vorhandenen Kernkraftwerke rechtlich ermöglichen', '{304}', 6708, 1, 1, null, 'Mehr Kraftwerksleistung könnte die Börsenpreise in einzelnen Stunden senken; die abgeschalteten Kernkraftwerke sind weitgehend zurückgebaut, eine Wiederinbetriebnahme wäre teuer, langwierig und rechtlich neu zu regeln, und Kohlestrom wird durch den Emissionshandel teurer.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', null, 'gemischt', '2026-09-30', false, true, null),
  (6821, 3, 14, null, 'Heimische Erdgasförderung ausbauen, auch mit Fracking', '{303}', null, 1, 2, null, 'Mehr heimisches Gas verringert die Importe etwas; der Gaspreis bildet sich aber auf dem europäischen Markt, und die möglichen Mengen sind im Vergleich zum Verbrauch klein. Genehmigungen, vor allem für Fracking, dauern lange.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', null, 'gemischt', '2026-09-30', false, true, null),
  (6822, 3, 11, null, 'Europäischen Energiebinnenmarkt stärken, internationale Energiepartnerschaften ausbauen', '{303}', null, 1, 3, null, 'Mehr Lieferländer machen Deutschland weniger anfällig für Preissprünge bei einzelnen Lieferanten; die Maßnahme bleibt allgemein und nennt keine konkreten Schritte.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'offen', '2026-09-30', false, true, null),
  (6823, 3, 13, null, 'Gasverbrauch schneller senken, Umstieg auf erneuerbare Energien', '{303}', null, 1, 2, null, 'Weniger Gasverbrauch verringert die Importabhängigkeit und damit das Risiko von Preissprüngen; die Wirkung auf die Rechnungen der Haushalte stellt sich erst über Jahre ein.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=43', null, 'gemischt', '2026-09-30', false, true, null),
  (6825, 1, 17, null, 'Bürgerversicherung statt Zwei-Klassen-Medizin', '{103}', 6681, 2, 1, null, 'Nimmt Praxen den finanziellen Anreiz, Privatversicherte bei Terminen vorzuziehen; ob die Wartezeiten insgesamt sinken, hängt von der Höhe der neuen Vergütung ab. Der Umbau der privaten Krankenversicherung ist rechtlich und praktisch sehr aufwendig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=26', null, 'gemischt', '2026-09-30', false, true, null),
  (6826, 1, 17, null, 'Hausärzte höher vergüten', '{101}', null, 1, 2, null, 'Macht die Niederlassung als Hausarzt attraktiver; ob das allein genug Nachwuchs bringt, ist offen, denn viele junge Ärztinnen und Ärzte wünschen sich vor allem Anstellung und Teilzeit. Die Mehrkosten tragen die Beitragszahlenden.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'gemischt', '2026-09-30', false, true, null),
  (6827, 1, 17, null, 'Mehr Medizinstudienplätze', '{101}', 6824, 2, 2, null, 'Mehr Absolventinnen und Absolventen setzen am Nachwuchsmangel an, wirken aber erst nach etwa zwölf Jahren Studium und Weiterbildung; ob sie Hausärzte auf dem Land werden, ist offen. Studienplätze finanzieren die Länder, der Bund kann nur mitfinanzieren.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'gemischt', '2026-09-30', false, true, null),
  (6829, 3, 17, null, 'Netze aus öffentlichen Mitteln statt über den Strompreis finanzieren', '{301}', 6703, 2, 2, null, 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', null, 'belegt', '2026-09-30', false, true, null),
  (6830, 3, 17, null, 'Stromnetze verstaatlichen und Netzentgelte auf ein Minimum senken', '{301}', null, 1, 1, null, 'Ohne Renditen für private Netzbetreiber könnten die Netzentgelte etwas sinken; der Kauf der Netze würde viele Milliarden kosten, und der Ausbau bliebe trotzdem zu bezahlen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', null, 'offen', '2026-09-30', false, true, null),
  (6831, 3, 17, null, 'CO₂-Preis abschaffen', '{302,305}', 6706, 2, 1, null, 'Würde Gas- und Heizölpreise direkt senken; ab 2028 gilt aber der europäische Emissionshandel für Gebäude und Verkehr, den Deutschland nicht allein abschaffen kann.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'belegt', '2026-09-30', false, true, null),
  (6832, 3, 17, null, 'Mit Russland über Gaslieferungen durch Nord Stream verhandeln', '{303}', 6828, 1, 0, null, 'Mehr Pipelinegas könnte den Gaspreis senken, würde die Abhängigkeit von einem einzelnen Lieferland aber wieder erhöhen; die EU hat mit der Verordnung (EU) 2026/261 die Einfuhr von russischem Gas verboten (Pipelinegas spätestens ab Herbst 2027), eine Wiederaufnahme wäre EU-rechtswidrig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'gemischt', '2026-09-30', false, true, null),
  (6833, 3, 17, null, 'Langfristige Lieferverträge für Energieimporte nach dem niedrigsten Preis', '{303}', null, 1, 2, null, 'Langfristige Verträge können Preisschwankungen dämpfen; sie binden aber auch an Preise, wenn der Markt fällt, und ein Kriterium nur nach dem Preis erhöht die Abhängigkeit von einzelnen Lieferländern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'gemischt', '2026-09-30', false, true, null),
  (6834, 3, 17, null, 'Neue Gaskraftwerke als Reserve für Dunkelflauten', '{304}', null, 1, 2, null, 'Mehr Reservekraftwerke können Preisspitzen in wind- und sonnenarmen Stunden dämpfen; sie senken den Durchschnittspreis kaum, weil gerade Gaskraftwerke den Preis dann setzen, und müssen über Umlagen oder Steuern bezahlt werden.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', null, 'gemischt', '2026-09-30', false, true, null),
  (6835, 3, 17, null, 'Repowering: alte Windanlagen durch neue ersetzen', '{304}', 6707, 2, 2, null, 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', null, 'gemischt', '2026-09-30', false, true, null),
  (6836, 3, 17, null, 'Einbau von Wärmepumpen fördern, ohne andere Heizungen zu benachteiligen', '{305}', null, 1, 3, null, 'Förderung erleichtert den Umstieg von Gas und Öl; ohne Vorgaben für neue Heizungen bleiben viele Haushalte bei fossilen Heizungen und damit von deren Preisen abhängig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'gemischt', '2026-09-30', false, true, null),
  (6842, 8, 17, null, 'Niedrigere Preise bei Bus und Bahn, Deutschlandticket dauerhaft zu bezahlbarem Preis', '{804}', 6837, 2, 2, null, 'Ein niedrigerer Preis entlastet alle Fahrgäste direkt; das Neun-Euro-Ticket und die Einführung des Deutschlandtickets haben die Nutzung deutlich erhöht. Jeder Euro weniger kostet Bund und Länder Hunderte Millionen im Jahr, den Preis legen die Länder fest.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', null, 'belegt', '2026-09-30', false, true, null),
  (6843, 8, 17, null, 'Verfallende Infrastruktur instand setzen, großes Investitionsprogramm', '{802}', 6744, 2, 2, null, 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', null, 'gemischt', '2026-09-30', false, true, null),
  (6844, 8, 17, null, 'Bahn mit Netz und Zügen wieder als „Deutsche Bundesbahn“ führen', '{802}', 6745, 2, 3, null, 'Setzt an der vom Bundesrechnungshof kritisierten Steuerung an; wie viel das für Pünktlichkeit bringt, ist kaum untersucht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=30', null, 'offen', '2026-09-30', false, true, null),
  (6845, 8, 17, null, 'Integriertes, getaktetes Bahn- und ÖPNV-Konzept nach Schweizer Vorbild', '{801}', null, 2, 2, null, 'Ein abgestimmter Taktfahrplan mit verlässlichen Anschlüssen hat in der Schweiz das Angebot auch in der Fläche deutlich verbessert; in Deutschland setzt er Netzausbau und Absprachen mit allen Ländern voraus und dauert Jahre.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=30', null, 'gemischt', '2026-09-30', false, true, null),
  (6846, 8, 12, null, 'Preis des Deutschlandtickets dauerhaft auf aktuellem Niveau halten, mit den Ländern auskömmlich finanzieren', '{804}', null, 1, 2, null, 'Verhindert weitere Preiserhöhungen, senkt den Preis aber nicht; die steigenden Kosten der Verkehrsbetriebe müssen Bund und Länder dann ausgleichen, und den Preis legen die Länder fest.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=35', null, 'belegt', '2026-09-30', false, true, null),
  (6847, 8, 12, null, 'Bundeseinheitlich vergünstigtes Deutschlandticket für soziale Gruppen', '{804}', 6838, 1, 2, null, 'Entlastet Gruppen mit wenig Geld wie Auszubildende, Studierende oder Menschen mit geringem Einkommen gezielt; für alle anderen ändert sich nichts. Der Bund kann es nur gemeinsam mit den Ländern einführen und mitfinanzieren.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=35', null, 'belegt', '2026-09-30', false, true, null),
  (6848, 8, 13, null, 'Deutschlandticket für 49 Euro', '{804}', 6837, 2, 2, null, 'Ein niedrigerer Preis entlastet alle Fahrgäste direkt; das Neun-Euro-Ticket und die Einführung des Deutschlandtickets haben die Nutzung deutlich erhöht. Jeder Euro weniger kostet Bund und Länder Hunderte Millionen im Jahr, den Preis legen die Länder fest.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=49', null, 'belegt', '2026-09-30', false, true, null),
  (6849, 8, 13, null, 'Azubi-Deutschland-Ticket', '{804}', 6838, 1, 2, null, 'Entlastet Gruppen mit wenig Geld wie Auszubildende, Studierende oder Menschen mit geringem Einkommen gezielt; für alle anderen ändert sich nichts. Der Bund kann es nur gemeinsam mit den Ländern einführen und mitfinanzieren.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=78', null, 'belegt', '2026-09-30', false, true, null),
  (6850, 8, 16, null, '9-Euro-Ticket sofort wieder einführen', '{804}', null, 3, 1, null, 'Senkt den Preis für alle drastisch und hat 2022 die Nutzung stark erhöht; kostet Bund und Länder zusätzlich viele Milliarden Euro im Jahr, und die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=36', null, 'belegt', '2026-09-30', false, true, null),
  (6851, 8, 16, null, 'Mehrwertsteuer im Nah- und Fernverkehr abschaffen', '{804}', null, 1, 1, null, 'Könnte Fahrpreise um bis zu 7 Prozent senken, wenn die Ersparnis weitergegeben wird; das EU-Mehrwertsteuerrecht erlaubt eine vollständige Befreiung für den Personenverkehr nicht ohne Weiteres.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', null, 'offen', '2026-09-30', false, true, null),
  (6852, 8, 11, 'ST', 'Deutschlandticket erhalten, Nutzen für den ländlichen Raum stärken', '{804}', 6839, 1, 3, null, 'Sichert den bundesweit einheitlichen Preis, verhindert aber weitere Preiserhöhungen nicht; das Land zahlt seinen Anteil schon heute.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=62', null, 'belegt', '2026-09-30', false, true, null),
  (6853, 8, 12, 'ST', 'Deutschlandticket langfristig bezahlbar absichern', '{804}', 6839, 1, 3, null, 'Sichert den bundesweit einheitlichen Preis, verhindert aber weitere Preiserhöhungen nicht; das Land zahlt seinen Anteil schon heute.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=42', null, 'belegt', '2026-09-30', false, true, null),
  (6854, 8, 12, 'ST', 'Deutschlandticket für Senioren mit rund 20 Euro im Monat fördern', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=42', null, 'belegt', '2026-09-30', false, true, null),
  (6855, 8, 13, 'ST', 'Vergünstigte Deutschlandtickets für Auszubildende, Freiwillige und Menschen mit geringem Einkommen', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=29', null, 'belegt', '2026-09-30', false, true, null),
  (6856, 8, 14, 'ST', 'Deutschlandticket bleibt Teil des Angebots', '{804}', 6839, 1, 3, null, 'Sichert den bundesweit einheitlichen Preis, verhindert aber weitere Preiserhöhungen nicht; das Land zahlt seinen Anteil schon heute.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=67', null, 'belegt', '2026-09-30', false, true, null),
  (6857, 8, 15, 'ST', 'Deutschlandticket für alle Schüler', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=201', null, 'belegt', '2026-09-30', false, true, null),
  (6858, 8, 16, 'ST', 'Senioren-Tickets und ermäßigte Tarife für Ältere', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=58', null, 'belegt', '2026-09-30', false, true, null),
  (6859, 8, 16, 'ST', 'Günstiges Jugendticket bis hin zum Nulltarif', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=64', null, 'belegt', '2026-09-30', false, true, null),
  (6860, 8, 17, 'ST', 'Kostenloser Nahverkehr für Schulkinder und Auszubildende', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=33', null, 'belegt', '2026-09-30', false, true, null),
  (6861, 8, 17, 'ST', 'Bezahlbare Sozialtickets für Menschen mit geringem Einkommen', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=33', null, 'belegt', '2026-09-30', false, true, null),
  (6862, 8, 11, 'MV', 'Vergünstigtes Deutschlandticket für junge Menschen bis 27 Jahre', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=124', null, 'belegt', '2026-09-30', false, true, null),
  (6863, 8, 11, 'MV', 'Gratis-Ticket für Auszubildende (wahlweise Führerscheinzuschuss)', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=124', null, 'belegt', '2026-09-30', false, true, null),
  (6864, 8, 12, 'MV', 'Deutschlandticket weiter mit Landesmitteln unterstützen', '{804}', 6839, 1, 3, null, 'Sichert den bundesweit einheitlichen Preis, verhindert aber weitere Preiserhöhungen nicht; das Land zahlt seinen Anteil schon heute.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=24', null, 'belegt', '2026-09-30', false, true, null),
  (6865, 8, 12, 'MV', 'MV-Jugendticket für Schüler und Auszubildende nach Art des Azubitickets', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=5', null, 'belegt', '2026-09-30', false, true, null),
  (6866, 8, 13, 'MV', 'Deutschlandticket für alle unter 27 kostenfrei', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://gruene-mv.de/?wpdmdl=33772#page=23', null, 'belegt', '2026-09-30', false, true, null),
  (6867, 8, 13, 'MV', 'Deutschlandticket für Menschen mit geringem Einkommen deutlich vergünstigen', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://gruene-mv.de/?wpdmdl=33772#page=23', null, 'belegt', '2026-09-30', false, true, null),
  (6868, 8, 14, 'MV', 'Deutschlandticket mit Landeszuschüssen erhalten', '{804}', 6839, 1, 3, null, 'Sichert den bundesweit einheitlichen Preis, verhindert aber weitere Preiserhöhungen nicht; das Land zahlt seinen Anteil schon heute.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=61', null, 'belegt', '2026-09-30', false, true, null),
  (6869, 8, 14, 'MV', 'Kostengünstige Azubi-Tickets weiter fördern', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=110', null, 'belegt', '2026-09-30', false, true, null),
  (6870, 8, 15, 'MV', 'Landesweites Azubi-Ticket', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=34', null, 'belegt', '2026-09-30', false, true, null),
  (6871, 8, 16, 'MV', 'Nahverkehr für unter 21-Jährige kostenfrei', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=20', null, 'belegt', '2026-09-30', false, true, null),
  (6872, 8, 16, 'MV', 'Ermäßigtes Deutschlandticket auch für Studierende auf 29 Euro deckeln', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=20', null, 'belegt', '2026-09-30', false, true, null),
  (6873, 8, 17, 'MV', 'Kostenloser Nahverkehr für Schulkinder und Auszubildende', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=90', null, 'belegt', '2026-09-30', false, true, null),
  (6874, 8, 12, 'BE', 'Günstigeres Sozialticket', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=47', null, 'belegt', '2026-09-30', false, true, null),
  (6875, 8, 13, 'BE', 'Berliner Klimaticket für 9 Euro im Monat für Menschen mit wenig Geld', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=82', null, 'belegt', '2026-09-30', false, true, null),
  (6876, 8, 16, 'BE', 'Sozialticket wieder auf 9 Euro senken', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=57', null, 'belegt', '2026-09-30', false, true, null),
  (6877, 8, 16, 'BE', 'Preisanstieg bei BVG und S-Bahn stoppen, kostenloses Schülerticket erhalten', '{804}', null, 1, 3, null, 'Verhindert weitere Erhöhungen der Berliner Tarife; für das Deutschlandticket, das viele nutzen, gilt der bundesweit festgelegte Preis weiter. Das Land muss die steigenden Kosten der Verkehrsbetriebe ausgleichen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=8', null, 'offen', '2026-09-30', false, true, null),
  (6878, 8, 17, 'BE', 'Kostenloses Schülerticket in der ganzen Region Berlin-Brandenburg', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=48', null, 'belegt', '2026-09-30', false, true, null),
  (6893, 11, 11, null, 'Einkommensteuertarif schrittweise abflachen, Grundfreibetrag erhöhen', '{1104}', 6885, 2, 1, null, 'Erhöht das Nettoeinkommen fast aller Steuerzahlenden, am stärksten in absoluten Beträgen bei höheren Einkommen; die Kosten sind hoch und die Finanzierung ist nicht geklärt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', null, 'belegt', '2026-09-30', false, true, null),
  (6894, 11, 11, null, 'Sozialversicherungsbeiträge wieder in Richtung 40 % senken', '{1104}', 6887, 1, 2, null, 'Verhindert weitere Beitragssteigerungen, senkt die Abgaben aber nicht; dafür wären Reformen in Rente, Gesundheit und Pflege nötig, die noch offen sind.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', null, 'gemischt', '2026-09-30', false, true, null),
  (6895, 11, 11, null, 'Agrardieselrückvergütung wieder vollständig einführen', '{1101}', 6892, 1, 3, null, 'Senkt die Energiekosten landwirtschaftlicher Betriebe um wenige Hundert Millionen Euro im Jahr; auf die Lebensmittelpreise wirkt das kaum.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=36', null, 'offen', '2026-09-30', false, true, null),
  (6896, 11, 12, null, 'Mehrwertsteuer auf Lebensmittel von 7 auf 5 % senken', '{1101}', 6879, 1, 3, null, 'Senkt die Preise einmalig um knapp 2 %, wenn der Handel die Senkung weitergibt; an den Ursachen der Preissteigerung ändert das nichts. Rechtlich und finanziell ohne große Hürden möglich.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=24', null, 'gemischt', '2026-09-30', false, true, null),
  (6897, 11, 12, null, 'Behörden stärken, die die Zusammensetzung von Lebensmittelpreisen öffentlich machen und Wettbewerbsverstöße prüfen', '{1102}', 6881, 1, 3, null, 'Macht Preise und Margen entlang der Lieferkette sichtbar und kann Kartellverfahren anstoßen; ob Transparenz allein die Preise senkt, ist kaum untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=24', null, 'offen', '2026-09-30', false, true, null),
  (6898, 11, 12, null, 'Mindestlohn spätestens 2026 auf 15 Euro', '{1103,1105}', 6889, 2, 3, null, 'Erhöht die Löhne im Niedriglohnbereich direkt; Studien zur Einführung 2015 und zur Erhöhung 2022 fanden kaum Jobverluste. Der Bundestag kann die Höhe per Gesetz festlegen, wie 2022 geschehen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, 'belegt', '2026-09-30', false, true, null),
  (6899, 11, 12, null, 'Bundestariftreuegesetz, Allgemeinverbindlicherklärung erleichtern', '{1103,1105}', 6890, 1, 3, null, 'Wer nach Tarif arbeitet, verdient im Schnitt mehr; Tariftreue greift aber nur bei öffentlichen Aufträgen, und wie stark die Tarifbindung dadurch steigt, ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, 'gemischt', '2026-09-30', false, true, null),
  (6900, 11, 12, null, 'Rund 95 % der Steuerzahlenden entlasten, Spitzeneinkommen und Vermögen stärker beteiligen', '{1104}', 6884, 2, 2, null, 'Erhöht das Nettoeinkommen von Geringverdienenden und der Mitte direkt; die Gegenfinanzierung über höhere Steuern für hohe Einkommen oder Vermögen ist umsetzbar, aber politisch und rechtlich aufwendig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, 'belegt', '2026-09-30', false, true, null),
  (6901, 11, 13, null, 'Wettbewerbsrecht weiterentwickeln, Verbraucher besser vor Monopolen schützen', '{1102}', 6883, 1, 3, null, 'Kann weitere Konzentration im Handel bremsen, wie es die Monopolkommission empfiehlt; auf die Preise wirkt das erst langfristig und nicht sicher.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=27', 'https://www.monopolkommission.de/publikationen/lebensmittel/s/wettbewerb-in-der-lebensmittellieferkette', 'gemischt', '2026-09-30', false, true, null),
  (6902, 11, 13, null, 'Mindestlohn zunächst 15 Euro, Referenzwert 60 % des Medianlohns', '{1103,1105}', 6889, 2, 3, null, 'Erhöht die Löhne im Niedriglohnbereich direkt; Studien zur Einführung 2015 und zur Erhöhung 2022 fanden kaum Jobverluste. Der Bundestag kann die Höhe per Gesetz festlegen, wie 2022 geschehen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=67', null, 'belegt', '2026-09-30', false, true, null),
  (6903, 11, 13, null, 'Allgemeinverbindlicherklärung erleichtern, Tariftreuegesetz', '{1103,1105}', 6890, 1, 3, null, 'Wer nach Tarif arbeitet, verdient im Schnitt mehr; Tariftreue greift aber nur bei öffentlichen Aufträgen, und wie stark die Tarifbindung dadurch steigt, ist offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=67', null, 'gemischt', '2026-09-30', false, true, null),
  (6904, 11, 13, null, 'Minijobs schrittweise in sozialversicherungspflichtige Beschäftigung überführen', '{1105}', 6891, 1, 3, null, 'Minijobs sind überwiegend schlecht bezahlt; ob ihre Umwandlung zu höheren Stundenlöhnen führt oder nur zu mehr Sozialversicherung bei gleichem Netto, ist umstritten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', null, 'gemischt', '2026-09-30', false, true, null),
  (6905, 11, 13, null, 'Steuergutschriften für niedrige Einkommen, Grundfreibetrag erhöhen', '{1104}', 6884, 2, 2, null, 'Erhöht das Nettoeinkommen von Geringverdienenden und der Mitte direkt; die Gegenfinanzierung über höhere Steuern für hohe Einkommen oder Vermögen ist umsetzbar, aber politisch und rechtlich aufwendig.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=74', null, 'belegt', '2026-09-30', false, true, null),
  (6906, 11, 14, null, 'Linear-progressiver Chancentarif ohne Mittelstandsbauch, Grundfreibetrag um mindestens 1.000 Euro anheben', '{1104}', 6885, 2, 1, null, 'Erhöht das Nettoeinkommen fast aller Steuerzahlenden, am stärksten in absoluten Beträgen bei höheren Einkommen; die Kosten sind hoch und die Finanzierung ist nicht geklärt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=14', null, 'belegt', '2026-09-30', false, true, null),
  (6907, 11, 14, null, 'Sozialabgaben nicht über 40 % steigen lassen', '{1104}', 6887, 1, 2, null, 'Verhindert weitere Beitragssteigerungen, senkt die Abgaben aber nicht; dafür wären Reformen in Rente, Gesundheit und Pflege nötig, die noch offen sind.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=21', null, 'gemischt', '2026-09-30', false, true, null),
  (6908, 11, 15, null, 'Grundfreibetrag auf 15.000 Euro erhöhen und indexieren', '{1104}', 6886, 2, 1, null, 'Entlastet besonders kleine Einkommen spürbar; die Steuerausfälle lägen im hohen zweistelligen Milliardenbereich, eine Finanzierung ist nicht geklärt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=59', null, 'belegt', '2026-09-30', false, true, null),
  (6909, 11, 15, null, 'Krankenversicherung der Bürgergeldbeziehenden vollständig aus dem Bundeshaushalt zahlen, um Beitragserhöhungen zu verhindern', '{1104}', 6888, 1, 2, null, 'Senkt die Kranken- und Pflegebeiträge etwas, weil der Bund die Kosten trägt; die Entlastung der Beschäftigten ist gering und belastet den Bundeshaushalt mit rund zehn Milliarden Euro im Jahr.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=22', null, 'gemischt', '2026-09-30', false, true, null),
  (6910, 11, 16, null, 'Grundnahrungsmittel von der Mehrwertsteuer befreien, Weitergabe gesetzlich sichern', '{1101}', 6880, 2, 2, null, 'Senkt die Preise für Grundnahrungsmittel um bis zu 6,5 % und entlastet vor allem Haushalte mit wenig Geld, wenn die Senkung weitergegeben wird; seit 2022 erlaubt das EU-Recht einen Nullsatz. Dagegen spricht der hohe Steuerausfall, und ob der Handel die Senkung vollständig weitergibt, ist umstritten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=6', null, 'gemischt', '2026-09-30', false, true, null),
  (6911, 11, 16, null, 'Monopole im Lebensmittelhandel zerschlagen, Preiswächter mit Durchgriffsrechten', '{1102}', 6882, 1, 1, null, 'Setzt an der Konzentration im Lebensmittelhandel an; ob kleinere Händler niedrigere Preise bringen, ist offen. Eine Entflechtung ohne Rechtsverstoß ist verfassungsrechtlich umstritten und dauert Jahre.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=6', null, 'gemischt', '2026-09-30', false, true, null),
  (6912, 11, 16, null, 'Neue Preisaufsicht als unabhängige Bundesbehörde', '{1102}', 6881, 1, 3, null, 'Macht Preise und Margen entlang der Lieferkette sichtbar und kann Kartellverfahren anstoßen; ob Transparenz allein die Preise senkt, ist kaum untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=7', null, 'offen', '2026-09-30', false, true, null),
  (6913, 11, 16, null, 'Übergewinnsteuer von 90 % auf Extragewinne in Krisen', '{1102}', null, 1, 1, null, 'Soll Anreize nehmen, Preise in Krisen über die Kosten hinaus zu erhöhen; ob das die Preise senkt, ist kaum untersucht. Die Abgrenzung von Übergewinnen ist rechtlich schwierig, ein Satz von 90 % verfassungsrechtlich umstritten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=7', null, 'offen', '2026-09-30', false, true, null),
  (6914, 11, 16, null, 'Steuern für die Mehrheit senken, Vermögensteuer für sehr große Vermögen', '{1104}', 6884, 2, 2, null, 'Erhöht das Nettoeinkommen von Geringverdienenden und der Mitte direkt; die Gegenfinanzierung über höhere Steuern für hohe Einkommen oder Vermögen ist umsetzbar, aber politisch und rechtlich aufwendig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=10', null, 'belegt', '2026-09-30', false, true, null),
  (6915, 11, 16, null, 'Mindestlohn mindestens 15 Euro, spätestens 2026 16 Euro', '{1103,1105}', 6889, 2, 3, null, 'Erhöht die Löhne im Niedriglohnbereich direkt; Studien zur Einführung 2015 und zur Erhöhung 2022 fanden kaum Jobverluste. Der Bundestag kann die Höhe per Gesetz festlegen, wie 2022 geschehen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'belegt', '2026-09-30', false, true, null),
  (6916, 11, 16, null, 'Bundestariftreuegesetz und Aktionsplan für Tarifbindung', '{1103,1105}', 6890, 1, 3, null, 'Wer nach Tarif arbeitet, verdient im Schnitt mehr; Tariftreue greift aber nur bei öffentlichen Aufträgen, und wie stark die Tarifbindung dadurch steigt, ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=26', null, 'gemischt', '2026-09-30', false, true, null),
  (6917, 11, 16, null, 'Volle Sozialversicherung ab dem ersten Euro statt Minijobs', '{1105}', 6891, 1, 3, null, 'Minijobs sind überwiegend schlecht bezahlt; ob ihre Umwandlung zu höheren Stundenlöhnen führt oder nur zu mehr Sozialversicherung bei gleichem Netto, ist umstritten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=26', null, 'gemischt', '2026-09-30', false, true, null),
  (6918, 11, 17, null, 'Bundeskartellamt für wirksame Fusionskontrolle stärken', '{1102}', 6883, 1, 3, null, 'Kann weitere Konzentration im Handel bremsen, wie es die Monopolkommission empfiehlt; auf die Preise wirkt das erst langfristig und nicht sicher.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=15', 'https://www.monopolkommission.de/publikationen/lebensmittel/s/wettbewerb-in-der-lebensmittellieferkette', 'gemischt', '2026-09-30', false, true, null),
  (6919, 11, 17, null, 'Grundfreibetrag deutlich erhöhen, an der Armutsgefährdungsschwelle orientiert', '{1104}', 6886, 2, 1, null, 'Entlastet besonders kleine Einkommen spürbar; die Steuerausfälle lägen im hohen zweistelligen Milliardenbereich, eine Finanzierung ist nicht geklärt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', null, 'belegt', '2026-09-30', false, true, null),
  (6920, 11, 17, null, 'Freibetrag bei den Sozialabgaben, gegenfinanziert durch höhere Beitragsbemessungsgrenzen', '{1104}', null, 2, 2, null, 'Entlastet kleine Einkommen bei den Sozialabgaben, die für sie oft schwerer wiegen als die Einkommensteuer; gegenfinanziert durch höhere Beiträge besser Verdienender. Die Umsetzung in allen Sozialversicherungen ist aufwendig, Vorbilder gibt es nur bei Midijobs.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', null, 'offen', '2026-09-30', false, true, null),
  (6921, 11, 17, null, 'Streichung der Agrardiesel-Ermäßigung zurücknehmen', '{1101}', 6892, 1, 3, null, 'Senkt die Energiekosten landwirtschaftlicher Betriebe um wenige Hundert Millionen Euro im Jahr; auf die Lebensmittelpreise wirkt das kaum.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=19', null, 'offen', '2026-09-30', false, true, null),
  (6922, 11, 17, null, 'Mindestlohn unverzüglich auf 15 Euro', '{1103,1105}', 6889, 2, 3, null, 'Erhöht die Löhne im Niedriglohnbereich direkt; Studien zur Einführung 2015 und zur Erhöhung 2022 fanden kaum Jobverluste. Der Bundestag kann die Höhe per Gesetz festlegen, wie 2022 geschehen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, 'belegt', '2026-09-30', false, true, null),
  (6923, 11, 17, null, 'Minijobs in sozialversicherungspflichtige Beschäftigung überführen', '{1105}', 6891, 1, 3, null, 'Minijobs sind überwiegend schlecht bezahlt; ob ihre Umwandlung zu höheren Stundenlöhnen führt oder nur zu mehr Sozialversicherung bei gleichem Netto, ist umstritten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, 'gemischt', '2026-09-30', false, true, null),
  (6924, 11, 17, null, 'Öffentliche Aufträge nur an Unternehmen mit Tariflohn, Allgemeinverbindlichkeit erleichtern', '{1103,1105}', 6890, 1, 3, null, 'Wer nach Tarif arbeitet, verdient im Schnitt mehr; Tariftreue greift aber nur bei öffentlichen Aufträgen, und wie stark die Tarifbindung dadurch steigt, ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, 'gemischt', '2026-09-30', false, true, null),
  (6925, 11, 17, null, 'Beiträge für Bürgergeldbeziehende aus Steuern finanzieren', '{1104}', 6888, 1, 2, null, 'Senkt die Kranken- und Pflegebeiträge etwas, weil der Bund die Kosten trägt; die Entlastung der Beschäftigten ist gering und belastet den Bundeshaushalt mit rund zehn Milliarden Euro im Jahr.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=26', null, 'gemischt', '2026-09-30', false, true, null),
  (6926, 11, 17, null, 'Starkes Kartellrecht, marktbeherrschende Konzerne entflechten', '{1102}', 6882, 1, 1, null, 'Setzt an der Konzentration im Lebensmittelhandel an; ob kleinere Händler niedrigere Preise bringen, ist offen. Eine Entflechtung ohne Rechtsverstoß ist verfassungsrechtlich umstritten und dauert Jahre.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=31', null, 'gemischt', '2026-09-30', false, true, null),
  (6927, 11, 17, null, 'Preisüberwacher nach Schweizer Vorbild', '{1102}', 6881, 1, 3, null, 'Macht Preise und Margen entlang der Lieferkette sichtbar und kann Kartellverfahren anstoßen; ob Transparenz allein die Preise senkt, ist kaum untersucht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=31', null, 'offen', '2026-09-30', false, true, null),
  (6928, 11, 17, null, 'Mehrwertsteuer auf Grundnahrungsmittel auf 0 %', '{1101}', 6880, 2, 2, null, 'Senkt die Preise für Grundnahrungsmittel um bis zu 6,5 % und entlastet vor allem Haushalte mit wenig Geld, wenn die Senkung weitergegeben wird; seit 2022 erlaubt das EU-Recht einen Nullsatz. Dagegen spricht der hohe Steuerausfall, und ob der Handel die Senkung vollständig weitergibt, ist umstritten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=31', null, 'gemischt', '2026-09-30', false, true, null),
  (6938, 12, 11, null, 'Auskömmliche Finanzierung von Autobahnen, Brücken und Straßen', '{1201}', 6929, 2, 3, null, 'Mehr und planbares Geld ist eine Voraussetzung, um den Rückstand bei den Brücken aufzuholen; laut Bundesrechnungshof fehlen der Autobahn GmbH aber auch Personal und Steuerung. Seit 2025 steht mit dem Sondervermögen Infrastruktur zusätzliches Geld bereit.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', 'https://www.bundesrechnungshof.de/SharedDocs/Pressemitteilungen/DE/2025/brueckenmodernisierung.html', 'gemischt', '2026-09-30', false, true, null),
  (6939, 12, 11, null, 'Ersatzneubauten per Anzeigeverfahren statt Planfeststellung zulassen', '{1201,1203}', 6933, 2, 3, null, 'Verkürzt die Zeit bis zum Ersatz maroder Brücken, bei denen sich an Lage und Umweltwirkung wenig ändert; seit 2023 gibt es dafür schon Erleichterungen. Nach Bundesrechnungshof und KfW bremsen vor allem Personal und Geld, nicht nur die Verfahren.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', null, 'gemischt', '2026-09-30', false, true, null),
  (6940, 12, 11, null, 'Neue Radwege und Ausbau des Radnetzes', '{1204}', 6936, 2, 2, null, 'Getrennte, durchgehende Radwege senken das Unfallrisiko nach vielen Studien; an Kreuzungen, wo die meisten schweren Unfälle passieren, hängt es von der Gestaltung ab. Bauen müssen Länder und Kommunen, der Bund kann fördern.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=75', null, 'gemischt', '2026-09-30', false, true, null),
  (6941, 12, 12, null, 'Autobahnnetz und vor allem Brücken dringend sanieren', '{1201}', 6929, 2, 3, null, 'Mehr und planbares Geld ist eine Voraussetzung, um den Rückstand bei den Brücken aufzuholen; laut Bundesrechnungshof fehlen der Autobahn GmbH aber auch Personal und Steuerung. Seit 2025 steht mit dem Sondervermögen Infrastruktur zusätzliches Geld bereit.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=36', 'https://www.bundesrechnungshof.de/SharedDocs/Pressemitteilungen/DE/2025/brueckenmodernisierung.html', 'gemischt', '2026-09-30', false, true, null),
  (6942, 12, 12, null, 'Deutschlandpakt zur Planungs- und Genehmigungsbeschleunigung fortsetzen', '{1201,1203}', 6933, 2, 3, null, 'Verkürzt die Zeit bis zum Ersatz maroder Brücken, bei denen sich an Lage und Umweltwirkung wenig ändert; seit 2023 gibt es dafür schon Erleichterungen. Nach Bundesrechnungshof und KfW bremsen vor allem Personal und Geld, nicht nur die Verfahren.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=9', null, 'gemischt', '2026-09-30', false, true, null),
  (6943, 12, 12, null, 'Lösung für kommunale Altschulden, Kommunalfinanzen verbessern', '{1202}', 6934, 1, 2, null, 'Gibt überschuldeten Kommunen wieder Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden die Kommunen. Eine Altschuldenlösung braucht eine Einigung von Bund und Ländern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=18', null, 'gemischt', '2026-09-30', false, true, null),
  (6944, 12, 12, null, 'Größere Planungskapazitäten der Kommunen, gemeinsamer Personaleinsatz', '{1203}', null, 1, 2, null, 'Setzt am Personalmangel der Bauverwaltungen an, den die KfW als größtes Hemmnis nennt; wie der Bund dazu beitragen will, bleibt offen, zuständig sind Länder und Kommunen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=18', null, 'offen', '2026-09-30', false, true, null),
  (6945, 12, 12, null, 'Verkehr von der Straße auf Schiene und Wasserstraße lenken', '{1201}', 6935, 1, 2, null, 'Schwere Lkw belasten Brücken am stärksten, weniger Lkw verlangsamen den Verschleiß; eine spürbare Verlagerung braucht aber Jahre und mehr Kapazität auf der Schiene.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null),
  (6946, 12, 12, null, 'Bundesweit vernetzte Radschnellwege und Fahrradparkhäuser fördern', '{1204}', 6936, 2, 2, null, 'Getrennte, durchgehende Radwege senken das Unfallrisiko nach vielen Studien; an Kreuzungen, wo die meisten schweren Unfälle passieren, hängt es von der Gestaltung ab. Bauen müssen Länder und Kommunen, der Bund kann fördern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=36', null, 'gemischt', '2026-09-30', false, true, null),
  (6947, 12, 12, null, 'Vision Zero im Straßenverkehrsrecht verankern', '{1204}', null, 1, 3, null, 'Ein gesetzliches Ziel ohne Verkehrstote kann Behörden verpflichten, Sicherheit bei Planung und Anordnungen stärker zu gewichten; welche Regeln sich konkret ändern, bleibt offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=36', null, 'offen', '2026-09-30', false, true, null),
  (6948, 12, 13, null, 'Überjährige Finanzierung für den Erhalt von Straßen und Brücken über den Deutschlandfonds', '{1201}', 6929, 2, 3, null, 'Mehr und planbares Geld ist eine Voraussetzung, um den Rückstand bei den Brücken aufzuholen; laut Bundesrechnungshof fehlen der Autobahn GmbH aber auch Personal und Steuerung. Seit 2025 steht mit dem Sondervermögen Infrastruktur zusätzliches Geld bereit.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', 'https://www.bundesrechnungshof.de/SharedDocs/Pressemitteilungen/DE/2025/brueckenmodernisierung.html', 'gemischt', '2026-09-30', false, true, null),
  (6949, 12, 13, null, 'Sanierung statt Neubau im Straßennetz', '{1201}', 6930, 2, 3, null, 'Bündelt knappe Planungs- und Baukapazitäten auf den Erhalt, wie es der Bundesrechnungshof für die Brücken fordert; weniger Neubau kann Engpässe auf überlasteten Strecken länger bestehen lassen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', 'https://www.bundesrechnungshof.de/SharedDocs/Statements/DE/2025/brueckenmodernisierung.html', 'gemischt', '2026-09-30', false, true, null),
  (6950, 12, 13, null, 'Ausbau eines guten Radwegenetzes dauerhaft finanzieren', '{1204}', 6936, 2, 2, null, 'Getrennte, durchgehende Radwege senken das Unfallrisiko nach vielen Studien; an Kreuzungen, wo die meisten schweren Unfälle passieren, hängt es von der Gestaltung ab. Bauen müssen Länder und Kommunen, der Bund kann fördern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=47', null, 'gemischt', '2026-09-30', false, true, null),
  (6951, 12, 13, null, 'Kommunen flächendeckend Tempo 30 innerorts ermöglichen', '{1204}', 6937, 2, 3, null, 'Niedrigere Geschwindigkeit verringert Zahl und Schwere von Unfällen mit Radfahrenden und Fußgängern deutlich; auf Landstraßen und an Hauptverkehrsachsen, wo viele schwere Radunfälle passieren, ändert es nichts.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=48', null, 'belegt', '2026-09-30', false, true, null),
  (6952, 12, 13, null, 'Altschuldenfonds von Bund und Ländern', '{1202}', 6934, 1, 2, null, 'Gibt überschuldeten Kommunen wieder Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden die Kommunen. Eine Altschuldenlösung braucht eine Einigung von Bund und Ländern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=108', null, 'gemischt', '2026-09-30', false, true, null),
  (6953, 12, 14, null, 'Ersatzneubauten genehmigungsfrei stellen, Planungszeiten halbieren', '{1201,1203}', 6933, 2, 3, null, 'Verkürzt die Zeit bis zum Ersatz maroder Brücken, bei denen sich an Lage und Umweltwirkung wenig ändert; seit 2023 gibt es dafür schon Erleichterungen. Nach Bundesrechnungshof und KfW bremsen vor allem Personal und Geld, nicht nur die Verfahren.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null),
  (6954, 12, 14, null, 'Baustellen-Turbo: Ausschreibungen belohnen schnelles, fristgerechtes Bauen', '{1203}', null, 1, 3, null, 'Bonus-Malus-Regeln in Bauverträgen können Bauzeiten verkürzen und sind erprobt; an fehlendem Personal und Geld ändern sie nichts.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null),
  (6955, 12, 14, null, 'Finanzierungskreislauf Straße mit Lkw-Maut und privatem Kapital', '{1201}', 6932, 2, 2, null, 'Macht die Finanzierung der Autobahnen planbarer und unabhängiger vom Haushalt; öffentlich-private Partnerschaften waren laut Bundesrechnungshof bisher oft teurer als konventionelle Vergabe.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null),
  (6956, 12, 15, null, 'Planvolle, kontinuierliche Sanierung von Straßen und Brücken', '{1201}', 6929, 2, 3, null, 'Mehr und planbares Geld ist eine Voraussetzung, um den Rückstand bei den Brücken aufzuholen; laut Bundesrechnungshof fehlen der Autobahn GmbH aber auch Personal und Steuerung. Seit 2025 steht mit dem Sondervermögen Infrastruktur zusätzliches Geld bereit.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=15', 'https://www.bundesrechnungshof.de/SharedDocs/Pressemitteilungen/DE/2025/brueckenmodernisierung.html', 'gemischt', '2026-09-30', false, true, null),
  (6957, 12, 15, null, 'Keine Umweltverträglichkeitsprüfung bei Ersatzbauten, effizientere Baustellen', '{1201,1203}', 6933, 2, 3, null, 'Verkürzt die Zeit bis zum Ersatz maroder Brücken, bei denen sich an Lage und Umweltwirkung wenig ändert; seit 2023 gibt es dafür schon Erleichterungen. Nach Bundesrechnungshof und KfW bremsen vor allem Personal und Geld, nicht nur die Verfahren.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=45', null, 'gemischt', '2026-09-30', false, true, null),
  (6958, 12, 16, null, 'Gemeindefinanzreform und Altschuldenfonds für überschuldete Kommunen', '{1202}', 6934, 1, 2, null, 'Gibt überschuldeten Kommunen wieder Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden die Kommunen. Eine Altschuldenlösung braucht eine Einigung von Bund und Ländern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=13', null, 'gemischt', '2026-09-30', false, true, null),
  (6959, 12, 16, null, 'Innerorts Tempo 30 außer auf Hauptverkehrsachsen', '{1204}', 6937, 2, 3, null, 'Niedrigere Geschwindigkeit verringert Zahl und Schwere von Unfällen mit Radfahrenden und Fußgängern deutlich; auf Landstraßen und an Hauptverkehrsachsen, wo viele schwere Radunfälle passieren, ändert es nichts.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', null, 'belegt', '2026-09-30', false, true, null),
  (6960, 12, 16, null, 'Beim Straßenbau auf die Sanierung des Bestands konzentrieren, keine neuen Autobahnen', '{1201}', 6930, 2, 3, null, 'Bündelt knappe Planungs- und Baukapazitäten auf den Erhalt, wie es der Bundesrechnungshof für die Brücken fordert; weniger Neubau kann Engpässe auf überlasteten Strecken länger bestehen lassen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', 'https://www.bundesrechnungshof.de/SharedDocs/Statements/DE/2025/brueckenmodernisierung.html', 'gemischt', '2026-09-30', false, true, null),
  (6961, 12, 16, null, 'Güterverkehr von der Straße auf die Schiene verlagern', '{1201}', 6935, 1, 2, null, 'Schwere Lkw belasten Brücken am stärksten, weniger Lkw verlangsamen den Verschleiß; eine spürbare Verlagerung braucht aber Jahre und mehr Kapazität auf der Schiene.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=37', null, 'gemischt', '2026-09-30', false, true, null),
  (6962, 12, 16, null, 'Flächendeckendes bundesweites Radverkehrsnetz, sichere Radwege', '{1204}', 6936, 2, 2, null, 'Getrennte, durchgehende Radwege senken das Unfallrisiko nach vielen Studien; an Kreuzungen, wo die meisten schweren Unfälle passieren, hängt es von der Gestaltung ab. Bauen müssen Länder und Kommunen, der Bund kann fördern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=44', null, 'gemischt', '2026-09-30', false, true, null),
  (6963, 12, 17, null, 'Investitionen in Brücken und Straßen aus der Schuldenbremse ausklammern, großes Investitionsprogramm', '{1201,1202}', 6931, 2, 2, null, 'Mehr Geld für Bund, Länder und Kommunen kann Sanierungsstau abbauen; ob es bei Straßen und Brücken ankommt und verbaut werden kann, hängt von Personal und Verfahren ab. Braucht eine Grundgesetzänderung, wie sie 2025 für das Sondervermögen beschlossen wurde.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=15', null, 'gemischt', '2026-09-30', false, true, null),
  (6964, 12, 17, null, 'Gerechte Altschuldenlösung, Kommunen mit nötigen Mitteln ausstatten', '{1202}', 6934, 1, 2, null, 'Gibt überschuldeten Kommunen wieder Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden die Kommunen. Eine Altschuldenlösung braucht eine Einigung von Bund und Ländern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=16', null, 'gemischt', '2026-09-30', false, true, null),
  (6965, 12, 17, null, 'Mehr Geld für Straßenbau und die Erneuerung von Brücken', '{1201}', 6929, 2, 3, null, 'Mehr und planbares Geld ist eine Voraussetzung, um den Rückstand bei den Brücken aufzuholen; laut Bundesrechnungshof fehlen der Autobahn GmbH aber auch Personal und Steuerung. Seit 2025 steht mit dem Sondervermögen Infrastruktur zusätzliches Geld bereit.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', 'https://www.bundesrechnungshof.de/SharedDocs/Pressemitteilungen/DE/2025/brueckenmodernisierung.html', 'gemischt', '2026-09-30', false, true, null),
  (6970, 13, 11, null, 'Ausbau in die Fläche mit Wettbewerb, Kooperationsmodellen und verlässlicher Förderung', '{1301,1302}', 6967, 2, 3, null, 'Schließt Lücken, die der Markt nicht schließt; laut WIK ist die heutige Förderung aber teuer, anfällig für Überförderung und verdrängt teils privaten Ausbau – es kommt auf die Ausgestaltung an.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=30', 'https://www.wik.org/fileadmin/user_upload/Unternehmen/Veroeffentlichungen/Kurzstudien/2026/WIK_Kurzstudie_Anreizwirkung_der_derzeitigen_Gigabitfoerderung_auf_den_eigenwirtschaftlichen_Glasfaserausbau_in_Deutschland.pdf', 'gemischt', '2026-09-30', false, true, null),
  (6971, 13, 11, null, 'Mobilfunk- und Glasfaserausbau ins überragende öffentliche Interesse stellen, Genehmigungsturbo', '{1301,1302}', 6966, 1, 3, null, 'Verkürzt Genehmigungen für Masten und Leitungen und senkt Tiefbaukosten; wo sich der Ausbau wirtschaftlich nicht lohnt oder das Gelände schwierig ist, ändert das allein wenig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=30', null, 'gemischt', '2026-09-30', false, true, null),
  (6972, 13, 12, null, 'Breitbandinternet in ländlichen Räumen ausbauen', '{1301}', 6969, 1, 3, null, 'Nennt das Ziel, aber keinen Weg, wie die Lücken geschlossen werden sollen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=52', null, 'offen', '2026-09-30', false, true, null),
  (6973, 13, 13, null, 'Genehmigungen beschleunigen, alternative Verlegemethoden, Open Access', '{1301,1302}', 6966, 1, 3, null, 'Verkürzt Genehmigungen für Masten und Leitungen und senkt Tiefbaukosten; wo sich der Ausbau wirtschaftlich nicht lohnt oder das Gelände schwierig ist, ändert das allein wenig.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=35', null, 'gemischt', '2026-09-30', false, true, null),
  (6974, 13, 13, null, 'Gigabitförderung für ländliche und strukturschwache Regionen bedarfsorientiert erhöhen', '{1301}', 6967, 2, 3, null, 'Schließt Lücken, die der Markt nicht schließt; laut WIK ist die heutige Förderung aber teuer, anfällig für Überförderung und verdrängt teils privaten Ausbau – es kommt auf die Ausgestaltung an.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=35', 'https://www.wik.org/fileadmin/user_upload/Unternehmen/Veroeffentlichungen/Kurzstudien/2026/WIK_Kurzstudie_Anreizwirkung_der_derzeitigen_Gigabitfoerderung_auf_den_eigenwirtschaftlichen_Glasfaserausbau_in_Deutschland.pdf', 'gemischt', '2026-09-30', false, true, null),
  (6975, 13, 13, null, 'Mindestbandbreite schrittweise erhöhen', '{1301}', 6968, 1, 2, null, 'Ein höherer Anspruch verpflichtet die Anbieter, auch unversorgte Haushalte anzuschließen; bei deutlich höheren Bandbreiten wird das teuer und langwierig, die Kosten tragen Anbieter oder Staat.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=35', null, 'gemischt', '2026-09-30', false, true, null),
  (6976, 13, 14, null, 'Passgenaue Förderung nur, wo sich privater Ausbau nicht rechnet', '{1301,1302}', 6967, 2, 3, null, 'Schließt Lücken, die der Markt nicht schließt; laut WIK ist die heutige Förderung aber teuer, anfällig für Überförderung und verdrängt teils privaten Ausbau – es kommt auf die Ausgestaltung an.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=38', 'https://www.wik.org/fileadmin/user_upload/Unternehmen/Veroeffentlichungen/Kurzstudien/2026/WIK_Kurzstudie_Anreizwirkung_der_derzeitigen_Gigabitfoerderung_auf_den_eigenwirtschaftlichen_Glasfaserausbau_in_Deutschland.pdf', 'gemischt', '2026-09-30', false, true, null),
  (6977, 13, 14, null, 'Mobilfunk- und Glasfaserausbau als überragendes öffentliches Interesse', '{1301,1302}', 6966, 1, 3, null, 'Verkürzt Genehmigungen für Masten und Leitungen und senkt Tiefbaukosten; wo sich der Ausbau wirtschaftlich nicht lohnt oder das Gelände schwierig ist, ändert das allein wenig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=41', null, 'gemischt', '2026-09-30', false, true, null),
  (6978, 13, 15, null, 'Ausbau der digitalen Infrastruktur beschleunigen', '{1301}', 6969, 1, 3, null, 'Nennt das Ziel, aber keinen Weg, wie die Lücken geschlossen werden sollen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=15', null, 'offen', '2026-09-30', false, true, null),
  (6979, 13, 16, null, 'Kommunalen und gemeinnützigen Glasfaserausbau fördern, Doppelausbau verhindern', '{1301}', null, 2, 2, null, 'Kommunale Netzgesellschaften haben in manchen Regionen Lücken geschlossen, die private Anbieter ließen; sie brauchen Kapital und Fachpersonal. Doppelausbau zu verhindern, kann Mittel für unversorgte Gebiete frei machen, schränkt aber Wettbewerb ein.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=57', null, 'gemischt', '2026-09-30', false, true, null),
  (6980, 13, 16, null, 'Recht auf Internetzugang mit 100 Mbit/s', '{1301}', 6968, 1, 2, null, 'Ein höherer Anspruch verpflichtet die Anbieter, auch unversorgte Haushalte anzuschließen; bei deutlich höheren Bandbreiten wird das teuer und langwierig, die Kosten tragen Anbieter oder Staat.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=57', null, 'gemischt', '2026-09-30', false, true, null),
  (6981, 13, 16, null, 'Ein gemeinsames Mobilfunk- und Glasfasernetz für alle Anbieter', '{1301,1302}', null, 1, 1, null, 'Ein gemeinsames Netz spart Doppelinvestitionen und kann Lücken schließen; laut Grundgesetz (Art. 87f) erbringen aber private Anbieter die Telekommunikation, ein Umbau der bestehenden Netze wäre rechtlich und finanziell sehr aufwendig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=57', null, 'offen', '2026-09-30', false, true, null),
  (6982, 13, 17, null, 'Schnelles Internet als staatliche Aufgabe gewährleisten', '{1301}', 6969, 1, 3, null, 'Nennt das Ziel, aber keinen Weg, wie die Lücken geschlossen werden sollen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=16', null, 'offen', '2026-09-30', false, true, null),
  (6989, 14, 11, null, 'Sichere digitale Identität mit eigenem Postfach für Behördengänge (DeutschlandID)', '{1401}', 6983, 2, 2, null, 'Ein Zugang für alle Leistungen macht Angebote leichter auffindbar, was Nutzer laut eGovernment MONITOR vermissen; schneller wird es nur, wenn die Anträge dahinter auch digital bearbeitet werden. Braucht die Mitarbeit von Ländern und Kommunen, das Onlinezugangsgesetz zeigt, wie lange das dauert.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=29', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'gemischt', '2026-09-30', false, true, null),
  (6990, 14, 11, null, 'Bundesdigitalministerium einrichten', '{1401}', 6985, 1, 3, null, 'Klare Zuständigkeit kann Projekte beschleunigen; seit 2025 gibt es ein solches Ministerium. Für Bürgerinnen und Bürger ändert sich erst etwas, wenn Leistungen tatsächlich digital und schneller werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=30', null, 'offen', '2026-09-30', false, true, null),
  (6991, 14, 11, null, 'Once-Only-Prinzip konsequent umsetzen', '{1403}', 6984, 2, 2, null, 'Setzt direkt daran an, dass Nachweise immer wieder eingereicht werden müssen; Länder wie Österreich und Estland zeigen, dass es funktioniert. Die Registermodernisierung ist aber ein Vorhaben über viele Jahre, und die Länder können nicht zur Anbindung verpflichtet werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=79', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5', 'belegt', '2026-09-30', false, true, null),
  (6992, 14, 11, null, 'Digitalen Vollzug zum Standard machen', '{1401,1402}', 6986, 2, 2, null, 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=79', null, 'gemischt', '2026-09-30', false, true, null),
  (6993, 14, 11, null, 'Gesetze auf den Regelfall ausrichten, mehr Ermessen, Experimentierklausel', '{1404}', 6988, 1, 3, null, 'Kann Entscheidungen beschleunigen und Einzelfallprüfungen vermeiden; wie stark Vorschriften dadurch tatsächlich schlanker werden, ist offen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=79', null, 'offen', '2026-09-30', false, true, null),
  (6994, 14, 12, null, 'Alle Zuständigkeiten der Verwaltungsdigitalisierung in einem Ministerium bündeln', '{1401}', 6985, 1, 3, null, 'Klare Zuständigkeit kann Projekte beschleunigen; seit 2025 gibt es ein solches Ministerium. Für Bürgerinnen und Bürger ändert sich erst etwas, wenn Leistungen tatsächlich digital und schneller werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=38', null, 'offen', '2026-09-30', false, true, null),
  (6995, 14, 12, null, 'System der einmaligen Datenübermittlung, Staatsvertrag mit den Ländern, Registermodernisierung', '{1403}', 6984, 2, 2, null, 'Setzt direkt daran an, dass Nachweise immer wieder eingereicht werden müssen; Länder wie Österreich und Estland zeigen, dass es funktioniert. Die Registermodernisierung ist aber ein Vorhaben über viele Jahre, und die Länder können nicht zur Anbindung verpflichtet werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=38', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5', 'belegt', '2026-09-30', false, true, null),
  (6996, 14, 12, null, 'DeutschlandID für zentralen Zugang zu Verwaltungsdiensten', '{1401}', 6983, 2, 2, null, 'Ein Zugang für alle Leistungen macht Angebote leichter auffindbar, was Nutzer laut eGovernment MONITOR vermissen; schneller wird es nur, wenn die Anträge dahinter auch digital bearbeitet werden. Braucht die Mitarbeit von Ländern und Kommunen, das Onlinezugangsgesetz zeigt, wie lange das dauert.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=38', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'gemischt', '2026-09-30', false, true, null),
  (6997, 14, 12, null, 'Automatisierung und KI für schnellere Verwaltungsprozesse', '{1401,1402}', 6986, 2, 2, null, 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=38', null, 'gemischt', '2026-09-30', false, true, null),
  (6998, 14, 12, null, 'Staat als Arbeitgeber attraktiver machen: Homeoffice, Job-Sharing, weniger Befristungen', '{1402}', 6987, 2, 1, null, 'Setzt am Personalmangel an; der Bund regelt aber nur die Bedingungen seiner eigenen Beschäftigten, die meisten Stellen mit Bürgerkontakt liegen bei Ländern und Kommunen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=38', null, 'gemischt', '2026-09-30', false, true, null),
  (6999, 14, 13, null, 'Deutschland-App für alle Verwaltungsleistungen, gemeinsam mit Ländern und Kommunen', '{1401}', 6983, 2, 2, null, 'Ein Zugang für alle Leistungen macht Angebote leichter auffindbar, was Nutzer laut eGovernment MONITOR vermissen; schneller wird es nur, wenn die Anträge dahinter auch digital bearbeitet werden. Braucht die Mitarbeit von Ländern und Kommunen, das Onlinezugangsgesetz zeigt, wie lange das dauert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=34', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'gemischt', '2026-09-30', false, true, null),
  (7000, 14, 13, null, 'Automatisierung, KI und antragslose Verfahren', '{1401,1402}', 6986, 2, 2, null, 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null),
  (7001, 14, 13, null, 'Ermessensspielräume der Entscheider erhöhen', '{1404}', 6988, 1, 3, null, 'Kann Entscheidungen beschleunigen und Einzelfallprüfungen vermeiden; wie stark Vorschriften dadurch tatsächlich schlanker werden, ist offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=34', null, 'offen', '2026-09-30', false, true, null),
  (7002, 14, 13, null, 'Registermodernisierung und -vernetzung, Daten nur einmal einpflegen', '{1403}', 6984, 2, 2, null, 'Setzt direkt daran an, dass Nachweise immer wieder eingereicht werden müssen; Länder wie Österreich und Estland zeigen, dass es funktioniert. Die Registermodernisierung ist aber ein Vorhaben über viele Jahre, und die Länder können nicht zur Anbindung verpflichtet werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=34', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5', 'belegt', '2026-09-30', false, true, null),
  (7003, 14, 14, null, 'Once-only-Garantie, alle relevanten Register digitalisieren und vernetzen', '{1403}', 6984, 2, 2, null, 'Setzt direkt daran an, dass Nachweise immer wieder eingereicht werden müssen; Länder wie Österreich und Estland zeigen, dass es funktioniert. Die Registermodernisierung ist aber ein Vorhaben über viele Jahre, und die Länder können nicht zur Anbindung verpflichtet werden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=38', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5', 'belegt', '2026-09-30', false, true, null),
  (7004, 14, 14, null, 'Bundesministerium für Digitalisierung mit Befugnissen für die Verwaltungsdigitalisierung', '{1401}', 6985, 1, 3, null, 'Klare Zuständigkeit kann Projekte beschleunigen; seit 2025 gibt es ein solches Ministerium. Für Bürgerinnen und Bürger ändert sich erst etwas, wenn Leistungen tatsächlich digital und schneller werden.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=38', null, 'offen', '2026-09-30', false, true, null),
  (7005, 14, 14, null, 'Government as a Platform mit allen digitalen Verwaltungsanwendungen, digitale Wallet', '{1401}', 6983, 2, 2, null, 'Ein Zugang für alle Leistungen macht Angebote leichter auffindbar, was Nutzer laut eGovernment MONITOR vermissen; schneller wird es nur, wenn die Anträge dahinter auch digital bearbeitet werden. Braucht die Mitarbeit von Ländern und Kommunen, das Onlinezugangsgesetz zeigt, wie lange das dauert.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=39', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'gemischt', '2026-09-30', false, true, null),
  (7006, 14, 14, null, 'Weniger Ministerien und Behörden, klarere Zuständigkeiten', '{1404}', null, 1, 3, null, 'Klarere Zuständigkeiten können Abstimmungen verkürzen; die Bundesministerien haben aber wenig direkten Kontakt mit Bürgerinnen und Bürgern, und an der Menge der Vorschriften ändert das wenig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=37', null, 'offen', '2026-09-30', false, true, null),
  (7007, 14, 15, null, 'Digitalisierung der Verwaltung vorantreiben', '{1401}', null, 1, 3, null, 'Nennt das Ziel, aber keinen Weg.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=15', null, 'offen', '2026-09-30', false, true, null),
  (7008, 14, 16, null, 'Geräte und fachkundiges Personal vor Ort, um beim Ausfüllen von Onlineanträgen zu helfen', '{1401}', null, 1, 1, null, 'Hilft Menschen, die mit Onlineanträgen nicht zurechtkommen; an der Bearbeitung ändert es nichts und braucht zusätzliches Personal in Kommunen, auf die der Bund kaum Zugriff hat.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=57', null, 'offen', '2026-09-30', false, true, null),
  (7009, 14, 17, null, 'Verwaltungen als Arbeitgeber attraktiver machen', '{1402}', 6987, 2, 1, null, 'Setzt am Personalmangel an; der Bund regelt aber nur die Bedingungen seiner eigenen Beschäftigten, die meisten Stellen mit Bürgerkontakt liegen bei Ländern und Kommunen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=16', null, 'gemischt', '2026-09-30', false, true, null),
  (7010, 14, 17, null, 'Zentrales Online-Portal als One-Stop-Shop mit Once-Only-Prinzip', '{1401,1403}', 6983, 2, 2, null, 'Ein Zugang für alle Leistungen macht Angebote leichter auffindbar, was Nutzer laut eGovernment MONITOR vermissen; schneller wird es nur, wenn die Anträge dahinter auch digital bearbeitet werden. Braucht die Mitarbeit von Ländern und Kommunen, das Onlinezugangsgesetz zeigt, wie lange das dauert.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=18', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'gemischt', '2026-09-30', false, true, null),
  (7016, 15, 11, null, 'Pendlerpauschale erhöhen', '{1502}', 7013, 1, 3, null, 'Entlastet Pendelnde über die Steuer; wer wenig verdient und kaum Steuern zahlt, hat wenig davon.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', null, 'gemischt', '2026-09-30', false, true, null),
  (7017, 15, 11, null, 'Klimabonus aus den CO₂-Einnahmen', '{1502}', 7012, 1, 2, null, 'Gleicht die Mehrkosten durch den CO₂-Preis für viele Haushalte aus, senkt den Spritpreis aber nicht; wer viel fahren muss, wird nur teilweise entlastet. Ein Auszahlungsweg an alle Haushalte muss erst aufgebaut werden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', null, 'gemischt', '2026-09-30', false, true, null),
  (7018, 15, 11, null, 'Ladeinfrastruktur angemessen ausbauen', '{1505}', 7015, 1, 3, null, 'Hilft, wer nicht zu Hause laden kann, vor allem in Mehrparteienhäusern; öffentliches Laden bleibt aber meist teurer und aufwendiger als eine eigene Wallbox.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', null, 'gemischt', '2026-09-30', false, true, null),
  (7019, 15, 12, null, 'Befristeter Steuerabzugsbetrag für in Deutschland produzierte E-Autos, auch Gebrauchte und Leasing', '{1504}', 7014, 2, 3, null, 'Setzt direkt am Preis an, den Haushalte als größtes Hindernis nennen; soziales Leasing hat in Frankreich viele Haushalte mit kleinem Einkommen erreicht. Frühere Prämien in Deutschland wurden zum Teil mitgenommen und kamen vor allem besser Verdienenden zugute.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=7', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null),
  (7020, 15, 12, null, 'Laden an öffentlichen Ladesäulen günstiger als Tanken, Schnellladepflicht für Tankstellen', '{1505}', 7015, 1, 3, null, 'Hilft, wer nicht zu Hause laden kann, vor allem in Mehrparteienhäusern; öffentliches Laden bleibt aber meist teurer und aufwendiger als eine eigene Wallbox.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=7', null, 'gemischt', '2026-09-30', false, true, null),
  (7021, 15, 12, null, 'Klimageld, wenn ab 2027 der europäische CO₂-Preis gilt', '{1502}', 7012, 1, 2, null, 'Gleicht die Mehrkosten durch den CO₂-Preis für viele Haushalte aus, senkt den Spritpreis aber nicht; wer viel fahren muss, wird nur teilweise entlastet. Ein Auszahlungsweg an alle Haushalte muss erst aufgebaut werden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null),
  (7022, 15, 13, null, 'Staatliche Unterstützung beim Kauf verbrauchsarmer E-Autos, Social Leasing, Ladekarte', '{1504}', 7014, 2, 3, null, 'Setzt direkt am Preis an, den Haushalte als größtes Hindernis nennen; soziales Leasing hat in Frankreich viele Haushalte mit kleinem Einkommen erreicht. Frühere Prämien in Deutschland wurden zum Teil mitgenommen und kamen vor allem besser Verdienenden zugute.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=40', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null),
  (7023, 15, 13, null, 'Überzogene Preise an Ladesäulen beenden', '{1505}', 7015, 1, 3, null, 'Hilft, wer nicht zu Hause laden kann, vor allem in Mehrparteienhäusern; öffentliches Laden bleibt aber meist teurer und aufwendiger als eine eigene Wallbox.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=40', null, 'gemischt', '2026-09-30', false, true, null),
  (7024, 15, 13, null, 'Sozial gestaffeltes Klimageld aus den CO₂-Einnahmen', '{1502}', 7012, 1, 2, null, 'Gleicht die Mehrkosten durch den CO₂-Preis für viele Haushalte aus, senkt den Spritpreis aber nicht; wer viel fahren muss, wird nur teilweise entlastet. Ein Auszahlungsweg an alle Haushalte muss erst aufgebaut werden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=40', null, 'gemischt', '2026-09-30', false, true, null),
  (7025, 15, 14, null, 'Energiesteuer auf Kraftstoffe bis auf null abschmelzen, CO₂-Preis soll sie ersetzen, Kfz-Steuer abschaffen', '{1502}', null, 1, 1, null, 'Ersetzt eine Steuer durch den CO₂-Preis; ob Sprit dadurch billiger wird, hängt von dessen Höhe ab. Die EU-Mindestsätze kann Deutschland nicht allein ändern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=17', null, 'offen', '2026-09-30', false, true, null),
  (7026, 15, 15, null, 'Energiesteuer senken', '{1502}', null, 2, 2, null, 'Senkt den Spritpreis direkt; die Tankrabatte 2022 und 2026 wurden laut Monopolkommission großteils weitergegeben. Eine dauerhafte Senkung kostet je 10 Cent mehrere Milliarden Euro im Jahr, eine Gegenfinanzierung nennt das Programm nicht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Policy_Briefs/Monopolkommission-Policy-Brief-16-2026-Tankrabatt.pdf', 'belegt', '2026-09-30', false, true, null),
  (7027, 15, 15, null, 'CO₂-Abgaben ersatzlos abschaffen', '{1502}', 7011, 2, 1, null, 'Senkt den Spritpreis 2026 um rund 15 bis 18 Cent je Liter; ab 2028 gilt aber der europäische Emissionshandel für Verkehr, den Deutschland nicht allein abschaffen kann. Die Einnahmen fehlen für Entlastungen an anderer Stelle.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=58', null, 'belegt', '2026-09-30', false, true, null),
  (7028, 15, 16, null, 'Soziales Klimageld von 320 Euro im Jahr pro Person', '{1502}', 7012, 1, 2, null, 'Gleicht die Mehrkosten durch den CO₂-Preis für viele Haushalte aus, senkt den Spritpreis aber nicht; wer viel fahren muss, wird nur teilweise entlastet. Ein Auszahlungsweg an alle Haushalte muss erst aufgebaut werden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=7', null, 'gemischt', '2026-09-30', false, true, null),
  (7029, 15, 16, null, 'Sozial gestaffelte Förderung kleiner E-Fahrzeuge für Pendelnde auf dem Land', '{1504}', 7014, 2, 3, null, 'Setzt direkt am Preis an, den Haushalte als größtes Hindernis nennen; soziales Leasing hat in Frankreich viele Haushalte mit kleinem Einkommen erreicht. Frühere Prämien in Deutschland wurden zum Teil mitgenommen und kamen vor allem besser Verdienenden zugute.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null),
  (7030, 15, 16, null, 'Investitionen in öffentliche Ladeinfrastruktur mit günstigen Tarifen', '{1505}', 7015, 1, 3, null, 'Hilft, wer nicht zu Hause laden kann, vor allem in Mehrparteienhäusern; öffentliches Laden bleibt aber meist teurer und aufwendiger als eine eigene Wallbox.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', null, 'gemischt', '2026-09-30', false, true, null),
  (7031, 15, 16, null, 'Pendlerpauschale durch ein Mobilitätsgeld ersetzen', '{1502}', null, 1, 3, null, 'Ein fester Betrag je Kilometer entlastet Pendelnde mit kleinem Einkommen stärker als die Pauschale, besser Verdienende weniger; der Spritpreis selbst ändert sich nicht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=36', null, 'offen', '2026-09-30', false, true, null),
  (7032, 15, 17, null, 'CO₂-Preis abschaffen', '{1502}', 7011, 2, 1, null, 'Senkt den Spritpreis 2026 um rund 15 bis 18 Cent je Liter; ab 2028 gilt aber der europäische Emissionshandel für Verkehr, den Deutschland nicht allein abschaffen kann. Die Einnahmen fehlen für Entlastungen an anderer Stelle.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'belegt', '2026-09-30', false, true, null),
  (7033, 15, 17, null, 'Volksleasing für umweltfreundliche Fahrzeuge aus europäischer Produktion, Kaufprämien im niedrigen Preissegment', '{1504}', 7014, 2, 3, null, 'Setzt direkt am Preis an, den Haushalte als größtes Hindernis nennen; soziales Leasing hat in Frankreich viele Haushalte mit kleinem Einkommen erreicht. Frühere Prämien in Deutschland wurden zum Teil mitgenommen und kamen vor allem besser Verdienenden zugute.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null),
  (7040, 16, 11, null, 'Heizungsgesetz der Ampel abschaffen, technologieoffene Wärmelösungen', '{1602}', 7036, 1, 3, null, 'Schafft Wahlfreiheit und beendet den Streit um die 65-Prozent-Vorgabe; ist aber selbst eine weitere Änderung der Regeln, und mit dem steigenden CO₂-Preis bleibt offen, welche Heizung sich langfristig lohnt. 2026 mit dem Gebäudemodernisierungsgesetz weitgehend umgesetzt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'gemischt', '2026-09-30', false, true, null),
  (7041, 16, 11, null, 'Verlässliche, technologieoffene Förderung', '{1601}', 7034, 2, 3, null, 'Senkt die Investition, die viele Haushalte scheuen oder nicht aufbringen können, und setzt damit an den laut KfW größten Hindernissen an. Ob sie Haushalte mit wenig Geld erreicht, hängt von der Staffelung ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null),
  (7042, 16, 12, null, 'Förderung vor allem für die, die sich den Umstieg sonst nicht leisten können', '{1601}', 7034, 2, 3, null, 'Senkt die Investition, die viele Haushalte scheuen oder nicht aufbringen können, und setzt damit an den laut KfW größten Hindernissen an. Ob sie Haushalte mit wenig Geld erreicht, hängt von der Staffelung ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=33', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null),
  (7043, 16, 12, null, 'Beschlossene Gesetze umsetzen, Planungssicherheit', '{1602}', 7037, 1, 3, null, 'Vermeidet weitere Wechsel der Regeln; die Vorgaben selbst waren stark umstritten, und ob sie Regierungswechsel überdauern, ist offen – 2026 wurden sie grundlegend geändert.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=33', null, 'gemischt', '2026-09-30', false, true, null),
  (7044, 16, 12, null, 'Lokale Wärmepläne und Kommunen mit Fördermitteln unterstützen', '{1603}', 7038, 2, 2, null, 'Beschleunigt die Wärmepläne, auf die viele Eigentümer warten, und den Bau von Wärmenetzen; planen und bauen müssen die Kommunen, der Bund kann nur Geld und Beratung geben.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=33', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/analysen-kompakt/2026/ak-09-2026.html', 'gemischt', '2026-09-30', false, true, null),
  (7045, 16, 12, null, 'Soziales Wärmepumpen-Leasing für ärmere Haushalte', '{1601,1604}', 7035, 2, 2, null, 'Nimmt Haushalten die hohe Anfangsinvestition ab, die laut KfW oft fehlt; solche Angebote gibt es bisher nur vereinzelt, ihre Wirkung in der Breite ist kaum untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', null, 'offen', '2026-09-30', false, true, null),
  (7046, 16, 13, null, 'Gebäudeenergiegesetz beibehalten, Planungssicherheit bis 2045', '{1602}', 7037, 1, 3, null, 'Vermeidet weitere Wechsel der Regeln; die Vorgaben selbst waren stark umstritten, und ob sie Regierungswechsel überdauern, ist offen – 2026 wurden sie grundlegend geändert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=44', null, 'gemischt', '2026-09-30', false, true, null),
  (7047, 16, 13, null, 'Förderung von bis zu 70 % ausbauen', '{1601}', 7034, 2, 3, null, 'Senkt die Investition, die viele Haushalte scheuen oder nicht aufbringen können, und setzt damit an den laut KfW größten Hindernissen an. Ob sie Haushalte mit wenig Geld erreicht, hängt von der Staffelung ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=44', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null),
  (7048, 16, 13, null, 'Wärme-Contracting durch Stadtwerke und Firmen', '{1601}', 7035, 2, 2, null, 'Nimmt Haushalten die hohe Anfangsinvestition ab, die laut KfW oft fehlt; solche Angebote gibt es bisher nur vereinzelt, ihre Wirkung in der Breite ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=44', null, 'offen', '2026-09-30', false, true, null),
  (7049, 16, 13, null, 'Klimakomponente im Wohngeld stärken', '{1604}', null, 1, 3, null, 'Hilft Haushalten mit Wohngeld, höhere Heizkosten oder Mieten nach einer Sanierung zu tragen; erreicht nur Wohngeldbeziehende und ändert nichts daran, ob die Heizung erneuert wird.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=44', null, 'gemischt', '2026-09-30', false, true, null),
  (7050, 16, 14, null, 'Heizungsgesetz vollständig auslaufen lassen, CO₂-Zertifikatehandel statt Einzelvorschriften', '{1602}', 7036, 1, 3, null, 'Schafft Wahlfreiheit und beendet den Streit um die 65-Prozent-Vorgabe; ist aber selbst eine weitere Änderung der Regeln, und mit dem steigenden CO₂-Preis bleibt offen, welche Heizung sich langfristig lohnt. 2026 mit dem Gebäudemodernisierungsgesetz weitgehend umgesetzt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=45', null, 'gemischt', '2026-09-30', false, true, null),
  (7051, 16, 14, null, 'Kappungsgrenzen bei energetischen Sanierungen lockern', '{1604}', null, 1, 3, null, 'Erhöht den Anreiz für Vermieter, Heizung und Gebäude zu erneuern, was Heizkosten der Mieter senken kann; zugleich dürfen Mieten nach der Sanierung stärker steigen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'gemischt', '2026-09-30', false, true, null),
  (7052, 16, 15, null, 'Gebäudeenergiegesetz abschaffen, Verbot von Gas- und Ölheizungen aufheben', '{1602}', 7036, 1, 3, null, 'Schafft Wahlfreiheit und beendet den Streit um die 65-Prozent-Vorgabe; ist aber selbst eine weitere Änderung der Regeln, und mit dem steigenden CO₂-Preis bleibt offen, welche Heizung sich langfristig lohnt. 2026 mit dem Gebäudemodernisierungsgesetz weitgehend umgesetzt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=37', null, 'gemischt', '2026-09-30', false, true, null),
  (7053, 16, 16, null, 'Heizungstausch nach Einkommen fördern, bis zu 100 % für niedrige Einkommen; 25 Mrd. Euro im Jahr', '{1601}', null, 2, 1, null, 'Beseitigt die Kostenhürde für Haushalte mit kleinem und mittlerem Einkommen weitgehend; 25 Milliarden Euro im Jahr sind ein Vielfaches der heutigen Förderung, die Finanzierung hängt an neuen Steuern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null),
  (7054, 16, 16, null, 'Umlage für energetische Sanierung abschaffen, Warmmietenneutralität verankern', '{1604}', 7039, 1, 3, null, 'Schützt Mieterinnen und Mieter vor Mietsteigerungen durch den Heizungstausch; zugleich sinkt der Anreiz für Vermieter, die Heizung zu erneuern, sodass Mieter länger die Kosten alter Heizungen tragen können.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', null, 'gemischt', '2026-09-30', false, true, null),
  (7055, 16, 16, null, 'Vermieter verpflichten, Fördermittel zu nutzen und weiterzugeben', '{1604}', null, 1, 2, null, 'Kann die Kosten für Mieter senken, wenn saniert wird; eine Pflicht zur Förderung ist ungewöhnlich und schwer durchzusetzen, und sie verpflichtet nicht zur Sanierung selbst.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', null, 'offen', '2026-09-30', false, true, null),
  (7056, 16, 16, null, 'Städte und Gemeinden beim Ausbau von Nah- und Fernwärmenetzen unterstützen', '{1603}', 7038, 2, 2, null, 'Beschleunigt die Wärmepläne, auf die viele Eigentümer warten, und den Bau von Wärmenetzen; planen und bauen müssen die Kommunen, der Bund kann nur Geld und Beratung geben.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=35', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/analysen-kompakt/2026/ak-09-2026.html', 'gemischt', '2026-09-30', false, true, null),
  (7057, 16, 17, null, 'Einbau von Wärmepumpen fördern, ohne andere Technologien zu benachteiligen', '{1601}', 7034, 2, 3, null, 'Senkt die Investition, die viele Haushalte scheuen oder nicht aufbringen können, und setzt damit an den laut KfW größten Hindernissen an. Ob sie Haushalte mit wenig Geld erreicht, hängt von der Staffelung ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-09-30', false, true, null),
  (7058, 16, 17, null, 'Heizungsgesetz sofort abschaffen und durch sinnvolle Regelungen ersetzen', '{1602}', 7036, 1, 3, null, 'Schafft Wahlfreiheit und beendet den Streit um die 65-Prozent-Vorgabe; ist aber selbst eine weitere Änderung der Regeln, und mit dem steigenden CO₂-Preis bleibt offen, welche Heizung sich langfristig lohnt. 2026 mit dem Gebäudemodernisierungsgesetz weitgehend umgesetzt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'gemischt', '2026-09-30', false, true, null),
  (7059, 16, 17, null, 'Ausbau der Fernwärme unterstützen', '{1603}', 7038, 2, 2, null, 'Beschleunigt die Wärmepläne, auf die viele Eigentümer warten, und den Bau von Wärmenetzen; planen und bauen müssen die Kommunen, der Bund kann nur Geld und Beratung geben.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=12', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/analysen-kompakt/2026/ak-09-2026.html', 'gemischt', '2026-09-30', false, true, null),
  (7067, 12, 11, 'ST', 'Landesweiter Brückensanierungsplan', '{1202}', 7060, 2, 3, null, 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=62', null, 'gemischt', '2026-09-30', false, true, null),
  (7068, 12, 11, 'ST', 'Planung und Genehmigung beschleunigen, Bearbeitungsfristen, vereinfachte Verfahren für Ersatzneubauten', '{1203}', 7062, 2, 3, null, 'Das Land kann Bauordnung, Vergaberecht und Verwaltungsabläufe selbst ändern und so Verfahren verkürzen; laut KfW bremst aber vor allem fehlendes Personal.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=55', null, 'gemischt', '2026-09-30', false, true, null),
  (7069, 12, 11, 'ST', 'Mehr Radwege bauen, regionale Radwegekonzepte unterstützen', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=63', null, 'gemischt', '2026-09-30', false, true, null),
  (7070, 12, 11, 'ST', 'Radfahrausbildung und Verkehrssicherheitsangebote, auch für Ältere', '{1204}', 7066, 1, 3, null, 'Richtet sich an Gruppen mit hohem Risiko, etwa ältere Menschen auf Pedelecs; wie stark Trainings die Zahl schwerer Unfälle senken, ist kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=63', null, 'offen', '2026-09-30', false, true, null),
  (7071, 12, 12, 'ST', 'Straßen und Brücken instand setzen, Sanierung hat Priorität', '{1202}', 7060, 2, 3, null, 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=43', null, 'gemischt', '2026-09-30', false, true, null),
  (7072, 12, 12, 'ST', 'Mindestens zehn Prozent der Landesstraßenbaumittel für Fuß- und Radverkehr, geschlossenes Radverkehrsnetz', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=42', null, 'gemischt', '2026-09-30', false, true, null),
  (7073, 12, 12, 'ST', 'Vision Zero, Verkehrserziehung und Unfallprävention stärken', '{1204}', 7066, 1, 3, null, 'Richtet sich an Gruppen mit hohem Risiko, etwa ältere Menschen auf Pedelecs; wie stark Trainings die Zahl schwerer Unfälle senken, ist kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=43', null, 'offen', '2026-09-30', false, true, null),
  (7074, 12, 13, 'ST', 'Erhalt von Straßen und Brücken vor Neubau priorisieren', '{1202}', 7060, 2, 3, null, 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=30', null, 'gemischt', '2026-09-30', false, true, null),
  (7075, 12, 13, 'ST', 'Reform der Kommunalfinanzierung, Altschuldenfonds', '{1202}', 7061, 1, 2, null, 'Gibt Kommunen Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden sie selbst, und der Landeshaushalt ist begrenzt.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=97', null, 'gemischt', '2026-09-30', false, true, null),
  (7076, 12, 13, 'ST', 'Radwegemittel auf mindestens 15 Mio. Euro im Jahr, Radwege an Landes- und Kreisstraßen', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=27', null, 'gemischt', '2026-09-30', false, true, null),
  (7077, 12, 14, 'ST', 'Erhalt von Landes- und Kreisstraßen hat Priorität, Investitionsquote erhöhen', '{1202}', 7060, 2, 3, null, 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=65', null, 'gemischt', '2026-09-30', false, true, null),
  (7078, 12, 14, 'ST', 'Planungs- und Genehmigungsverfahren beschleunigen, interkommunale Kooperation', '{1203}', 7062, 2, 3, null, 'Das Land kann Bauordnung, Vergaberecht und Verwaltungsabläufe selbst ändern und so Verfahren verkürzen; laut KfW bremst aber vor allem fehlendes Personal.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=58', null, 'gemischt', '2026-09-30', false, true, null),
  (7079, 12, 14, 'ST', 'Radwegenetz weiter ausbauen, sicher für Schülerinnen und Schüler', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=57', null, 'gemischt', '2026-09-30', false, true, null),
  (7080, 12, 15, 'ST', 'Investitionsstau bei Straßen und Brücken unverzüglich abbauen, Gesamtkonzept zur Finanzierung', '{1202}', 7060, 2, 3, null, 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=197', null, 'gemischt', '2026-09-30', false, true, null),
  (7081, 12, 15, 'ST', 'Planungsverfahren für Radwege vereinfachen und beschleunigen', '{1203,1204}', 7062, 2, 3, null, 'Das Land kann Bauordnung, Vergaberecht und Verwaltungsabläufe selbst ändern und so Verfahren verkürzen; laut KfW bremst aber vor allem fehlendes Personal.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=204', null, 'gemischt', '2026-09-30', false, true, null),
  (7082, 12, 15, 'ST', 'Landesförderung für kommunale Radverkehrsnetze deutlich erhöhen', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=204', null, 'gemischt', '2026-09-30', false, true, null),
  (7083, 12, 16, 'ST', 'Fuß- und Radwege, Straßen und Brücken nachhaltig instand halten', '{1202}', 7060, 2, 3, null, 'Mehr Geld und klare Prioritäten für den Erhalt bauen den Sanierungsstau ab; seit 2025 stehen den Ländern Mittel aus dem Sondervermögen Infrastruktur zur Verfügung. Ob sie verbaut werden, hängt von Personal und Verfahren ab.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=81', null, 'gemischt', '2026-09-30', false, true, null),
  (7084, 12, 16, 'ST', 'Sichere, durchgehende Radwege für Kinder und Jugendliche', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=64', null, 'gemischt', '2026-09-30', false, true, null),
  (7085, 12, 16, 'ST', 'Sichere Schulwege mit Tempo 30 und markierten Querungen', '{1204}', 7065, 2, 3, null, 'Niedrigere Geschwindigkeit verringert Zahl und Schwere von Unfällen mit Radfahrenden und Fußgängern; seit 2024 können Länder und Kommunen Tempo 30 leichter anordnen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=65', null, 'belegt', '2026-09-30', false, true, null),
  (7086, 12, 17, 'ST', 'Kommunalfinanzausgleich stärken, Investitionsprogramme, Entschuldung', '{1202}', 7061, 1, 2, null, 'Gibt Kommunen Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden sie selbst, und der Landeshaushalt ist begrenzt.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=19', null, 'gemischt', '2026-09-30', false, true, null),
  (7087, 12, 17, 'ST', 'Bau und Sanierung beschleunigen: leistungsbezogene Vergabe, verbindliche Bauzeitenpläne', '{1203}', 7062, 2, 3, null, 'Das Land kann Bauordnung, Vergaberecht und Verwaltungsabläufe selbst ändern und so Verfahren verkürzen; laut KfW bremst aber vor allem fehlendes Personal.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=32', null, 'gemischt', '2026-09-30', false, true, null),
  (7088, 12, 17, 'ST', 'Alltagstaugliche, sichere Radwege', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=33', null, 'gemischt', '2026-09-30', false, true, null),
  (7089, 12, 11, 'MV', 'Finanzausgleichsgesetz novellieren, kommunale Finanzausstattung dauerhaft stärken', '{1202}', 7061, 1, 2, null, 'Gibt Kommunen Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden sie selbst, und der Landeshaushalt ist begrenzt.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=41', null, 'gemischt', '2026-09-30', false, true, null),
  (7090, 12, 11, 'MV', 'Straßenbauverwaltung des Landes finanziell und personell stärken', '{1203}', 7063, 2, 2, null, 'Setzt am größten Hemmnis an, das die KfW nennt; Ingenieurinnen und Ingenieure sind knapp, neue Stellen lassen sich nicht sofort besetzen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=114', null, 'gemischt', '2026-09-30', false, true, null),
  (7091, 12, 11, 'MV', 'Landesbeschleunigungsgesetz mit Fristen und parallelen Genehmigungsschritten', '{1203}', 7062, 2, 3, null, 'Das Land kann Bauordnung, Vergaberecht und Verwaltungsabläufe selbst ändern und so Verfahren verkürzen; laut KfW bremst aber vor allem fehlendes Personal.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=104', null, 'gemischt', '2026-09-30', false, true, null),
  (7092, 12, 11, 'MV', 'Kommunen bei Erhalt, Sanierung und Pflege der Radwege stärker unterstützen', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=23', null, 'gemischt', '2026-09-30', false, true, null),
