  (7176, 16, 14, 'BE', 'Fern- und Nahwärmenetze im Stadtgebiet ausweiten', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=87', null, 'gemischt', '2026-09-30', false, true, null),
  (7177, 16, 16, 'BE', 'Wärmeagentur, Beratung und Förderung, mehr Personal für die Bezirke', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=195', null, 'gemischt', '2026-09-30', false, true, null),
  (7178, 16, 17, 'BE', 'Konsequenter Ausbau der Fernwärme, gesteuert über die kommunale Wärmeplanung', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=46', null, 'gemischt', '2026-09-30', false, true, null),
  (7221, 2, 12, null, 'Kurzzeitvermietung in Ballungsgebieten auf ein Mindestmaß reduzieren', '{201,205}', 7232, 1, 2, null, 'Weniger Ferienwohnungen und Leerstand bringen Wohnungen zurück auf den Mietmarkt, vor allem in Großstädten; bundesweit ist der Anteil klein. Zweckentfremdungsverbote erlassen die Länder, der Bund kann den Rahmen setzen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=20', null, 'gemischt', '2026-09-30', false, true, null),
  (7222, 2, 11, null, 'Ballungsräume entlasten: Verkehrswege und Nahverkehr ins Umland bedarfsgerecht ausbauen', '{205}', null, 1, 2, null, 'Bessere Verbindungen machen das Umland als Wohnort attraktiver und können die Nachfrage in den Großstädten dämpfen; wie stark, ist kaum untersucht, und der Ausbau dauert Jahre.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=77', null, 'offen', '2026-09-30', false, true, null),
  (7223, 2, 16, null, 'Wohngeld-Antrag stark vereinfachen, Anträge binnen drei Monaten bescheiden', '{202}', null, 1, 3, null, 'Entlastet Haushalte mit geringem Einkommen direkt, wenn mehr Berechtigte das Wohngeld tatsächlich erhalten; zusätzliche Wohnungen entstehen dadurch nicht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=8', null, 'gemischt', '2026-09-30', false, true, null),
  (7225, 14, 14, null, 'Vorausgefüllte Steuererklärung bis zur vollautomatisierten Einkommensteuerveranlagung („Easy Tax“)', '{1401,1402}', 6986, 2, 2, null, 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=15', null, 'gemischt', '2026-09-30', false, true, null),
  (7226, 14, 14, null, 'Elterngeld und Familienleistungen digitalisieren und automatisieren, KI-basierte Beantragung', '{1401,1402}', 6986, 2, 2, null, 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=30', null, 'gemischt', '2026-09-30', false, true, null),
  (7227, 16, 11, null, 'Investitionen in Klimatechnologien und Energieeffizienz steuerlich schneller absetzbar, auch für Vermieter', '{1604}', null, 1, 2, null, 'Macht den Heizungstausch auch für Vermieter steuerlich attraktiver, sodass mehr Mietwohnungen umgestellt werden können; ob Mieterinnen und Mieter dabei sparen, hängt von der Umlage ab, und die Maßnahme ist nicht auf Mietwohnungen zugeschnitten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', null, 'offen', '2026-09-30', false, true, null),
  (7229, 11, 11, null, 'Menschen in Helfertätigkeiten auf dem Weg zur Fachkraft fördern', '{1105}', 7228, 1, 2, null, 'Ein Berufsabschluss führt oft aus dem Niedriglohnbereich heraus, weil Fachkräfte deutlich mehr verdienen als Helfer; die Wirkung stellt sich erst über Jahre ein, und die Programme nennen kaum konkrete Instrumente.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=15', null, 'gemischt', '2026-09-30', false, true, null),
  (7230, 11, 16, null, 'Anspruch auf verlängerte Umschulung und erleichterte Externenprüfung für Menschen ohne Ausbildung', '{1105}', 7228, 1, 2, null, 'Ein Berufsabschluss führt oft aus dem Niedriglohnbereich heraus, weil Fachkräfte deutlich mehr verdienen als Helfer; die Wirkung stellt sich erst über Jahre ein, und die Programme nennen kaum konkrete Instrumente.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=40', null, 'gemischt', '2026-09-30', false, true, null),
  (7231, 10, 12, null, 'Digitale Produkte und Beratung in der Pflege nutzen, um Prävention zu fördern und Pflegebedürftigkeit vorzubeugen', '{1003}', 6234, 1, 3, null, 'Prävention und Rehabilitation können Pflegebedürftigkeit bei Einzelnen verzögern; an der Alterung der Bevölkerung ändern sie nichts, und ihre Wirkung auf die Zahl der Pflegebedürftigen ist schwer zu belegen. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'gemischt', '2026-09-30', false, true, null),
  (7233, 2, 17, null, 'Umwandlung von Wohnungen in Ferienwohnungen und Leerstand strenger regulieren', '{201}', 7232, 1, 2, null, 'Weniger Ferienwohnungen und Leerstand bringen Wohnungen zurück auf den Mietmarkt, vor allem in Großstädten; bundesweit ist der Anteil klein. Zweckentfremdungsverbote erlassen die Länder, der Bund kann den Rahmen setzen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'gemischt', '2026-09-30', false, true, null),
  (7261, 15, 12, null, 'Befristeter Steuerabzugsbetrag für in Deutschland produzierte E-Autos, auch Gebrauchte und Leasing', '{1501}', 7258, 1, 3, null, 'Jedes ersetzte Verbrennerfahrzeug braucht kein Benzin oder Diesel mehr. Bei 4,1 % Elektroanteil im Pkw-Bestand (1. 1. 2026) und langer Erneuerungszeit wirkt das erst über Jahre und schützt nicht vor einem Preisschock im laufenden Jahr.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=7', 'https://www.kba.de/DE/Presse/Pressemitteilungen/Fahrzeugbestand/2026/pm09_fz_bestand_pm_komplett.html', 'gemischt', '2026-10-01', false, true, null),
  (7262, 15, 13, null, 'Staatliche Unterstützung beim Kauf verbrauchsarmer E-Autos, Social Leasing, Ladekarte', '{1501}', 7258, 1, 3, null, 'Jedes ersetzte Verbrennerfahrzeug braucht kein Benzin oder Diesel mehr. Bei 4,1 % Elektroanteil im Pkw-Bestand (1. 1. 2026) und langer Erneuerungszeit wirkt das erst über Jahre und schützt nicht vor einem Preisschock im laufenden Jahr.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=40', 'https://www.kba.de/DE/Presse/Pressemitteilungen/Fahrzeugbestand/2026/pm09_fz_bestand_pm_komplett.html', 'gemischt', '2026-10-01', false, true, null),
  (7263, 15, 16, null, 'Sozial gestaffelte Förderung kleiner E-Fahrzeuge für Pendelnde auf dem Land', '{1501}', 7258, 1, 3, null, 'Jedes ersetzte Verbrennerfahrzeug braucht kein Benzin oder Diesel mehr. Bei 4,1 % Elektroanteil im Pkw-Bestand (1. 1. 2026) und langer Erneuerungszeit wirkt das erst über Jahre und schützt nicht vor einem Preisschock im laufenden Jahr.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=32', 'https://www.kba.de/DE/Presse/Pressemitteilungen/Fahrzeugbestand/2026/pm09_fz_bestand_pm_komplett.html', 'gemischt', '2026-10-01', false, true, null),
  (7264, 15, 17, null, 'Volksleasing für umweltfreundliche Fahrzeuge aus europäischer Produktion, Kaufprämien im niedrigen Preissegment', '{1501}', 7258, 1, 3, null, 'Jedes ersetzte Verbrennerfahrzeug braucht kein Benzin oder Diesel mehr. Bei 4,1 % Elektroanteil im Pkw-Bestand (1. 1. 2026) und langer Erneuerungszeit wirkt das erst über Jahre und schützt nicht vor einem Preisschock im laufenden Jahr.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', 'https://www.kba.de/DE/Presse/Pressemitteilungen/Fahrzeugbestand/2026/pm09_fz_bestand_pm_komplett.html', 'gemischt', '2026-10-01', false, true, null),
  (7265, 15, 11, null, 'Technologieoffenheit: E-Fuels, Wasserstoff und nachhaltige Biokraftstoffe neben der Elektromobilität nutzen', '{1501}', 7259, 1, 1, null, 'Strombasierte Kraftstoffe entkoppeln den Preis vom Rohöl, sind aber nicht kommerziell verfügbar und würden zunächst etwa 2 Euro je Liter kosten (Benzin im Großhandel 0,50). Bis 2035 deckt es höchstens die Hälfte des Bedarfs von Luft-, Schifffahrt und Chemie. Das Verbrennerverbot ist EU-Recht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=75', 'https://www.pik-potsdam.de/members/Ueckerdt/E-Fuels_Stand-und-Projektionen_PIK-Potsdam.pdf', 'offen', '2026-10-01', false, true, null),
  (7266, 15, 14, null, 'Statt eines Verbrennerverbots alternative Kraftstoffe wie E-Fuels ermöglichen', '{1501}', 7259, 1, 1, null, 'Strombasierte Kraftstoffe entkoppeln den Preis vom Rohöl, sind aber nicht kommerziell verfügbar und würden zunächst etwa 2 Euro je Liter kosten (Benzin im Großhandel 0,50). Bis 2035 deckt es höchstens die Hälfte des Bedarfs von Luft-, Schifffahrt und Chemie. Das Verbrennerverbot ist EU-Recht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=42', 'https://www.pik-potsdam.de/members/Ueckerdt/E-Fuels_Stand-und-Projektionen_PIK-Potsdam.pdf', 'offen', '2026-10-01', false, true, null),
  (7267, 15, 15, null, 'Synthetische Kraftstoffe berücksichtigen und bei den Abgaben wie Elektrofahrzeuge behandeln', '{1501}', 7259, 1, 1, null, 'Strombasierte Kraftstoffe entkoppeln den Preis vom Rohöl, sind aber nicht kommerziell verfügbar und würden zunächst etwa 2 Euro je Liter kosten (Benzin im Großhandel 0,50). Bis 2035 deckt es höchstens die Hälfte des Bedarfs von Luft-, Schifffahrt und Chemie. Das Verbrennerverbot ist EU-Recht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=44', 'https://www.pik-potsdam.de/members/Ueckerdt/E-Fuels_Stand-und-Projektionen_PIK-Potsdam.pdf', 'offen', '2026-10-01', false, true, null),
  (7268, 15, 17, null, 'Verbrauchsarme Verbrenner und alternative Kraftstoffe fördern', '{1501}', 7259, 1, 1, null, 'Strombasierte Kraftstoffe entkoppeln den Preis vom Rohöl, sind aber nicht kommerziell verfügbar und würden zunächst etwa 2 Euro je Liter kosten (Benzin im Großhandel 0,50). Bis 2035 deckt es höchstens die Hälfte des Bedarfs von Luft-, Schifffahrt und Chemie. Das Verbrennerverbot ist EU-Recht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', 'https://www.pik-potsdam.de/members/Ueckerdt/E-Fuels_Stand-und-Projektionen_PIK-Potsdam.pdf', 'offen', '2026-10-01', false, true, null),
  (7269, 15, 11, null, 'In angespannter Lage Energie- und Umsatzsteuer für Güter des täglichen Bedarfs schnell senken dürfen', '{1501}', 7260, 1, 1, null, 'Senkt den Preis sofort, aber nur befristet; der Tankrabatt 2026 kam laut Monopolkommission zu einem großen Teil, aber nicht vollständig an. Die schnelle Senkung der Umsatzsteuer braucht EU-Zustimmung. Das Programm nennt Güter des täglichen Bedarfs, nicht nur Kraftstoff.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', 'https://www.monopolkommission.de/fileadmin/monopolkommission/Indexierte_Dateien/PDFs/Policy_Briefs/Monopolkommission-Policy-Brief-16-2026-Tankrabatt.pdf#page=1', 'gemischt', '2026-10-01', false, true, null),
  (7270, 15, 11, null, 'Europäischen Energiebinnenmarkt stärken, internationale Energiepartnerschaften ausbauen', '{1501}', null, 1, 3, null, 'Mehr Lieferländer machen Deutschland weniger anfällig für Preissprünge bei einzelnen Lieferanten; die Maßnahme nennt weder Öl noch konkrete Schritte.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'offen', '2026-10-01', false, true, null),
  (7271, 15, 17, null, 'Langfristige Lieferverträge für Energieimporte nach dem niedrigsten Preis', '{1501}', null, 1, 2, null, 'Langfristige Verträge können Preisschwankungen dämpfen, binden aber auch an Preise, wenn der Markt fällt; die Maßnahme nennt kein Öl, sondern Energieimporte allgemein.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'offen', '2026-10-01', false, true, null),
  (7325, 17, 11, null, 'Länder und Kommunen mit einem Investitionsprogramm beim Ausbau von Betreuungsplätzen unterstützen.', '{1701}', 7280, 2, 2, null, 'Investitionshilfen können zusätzliche Plätze und erreichbare Angebote ermöglichen. Die Wirkung hängt von kommunaler Planung, Kofinanzierung und verfügbarem Personal ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7326, 17, 11, null, 'Die steuerliche Absetzbarkeit von Kinderbetreuungskosten verbessern.', '{1705}', 7306, 1, 3, null, 'Steuerliche Abzüge können einen Teil der Kosten kompensieren. Die Entlastung ist geringer oder fehlt bei Familien mit niedriger Steuerlast und löst weder Platzmangel noch hohe laufende Beiträge direkt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=63', 'https://www.oecd.org/en/publications/education-at-a-glance-2024_c00cad36-en.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7327, 17, 12, null, 'Fachkräfteoffensive für Kitas und Schulen mit mehr Ausbildungskapazitäten und entlohnter Erzieherausbildung vereinbaren; mehr Fachkräfte sollen mehr Plätze und weniger Schließzeiten ermöglichen.', '{1701,1702,1704}', 7295, 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7328, 17, 12, null, 'Kostenfreie Bildung ab der Kita.', '{1705}', 7303, 2, 2, null, 'Geringere Beiträge entlasten Familien und können den Zugang erleichtern, beseitigen aber nicht alle Zusatzkosten. Mehr Nachfrage kann bei knappen Plätzen den Zugang erschweren, wenn der Ausbau nicht Schritt hält.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=26', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7329, 17, 13, null, 'Steuerliche Anreize für Unternehmen, die selbst oder gemeinsam mit anderen Betreuungsplätze schaffen.', '{1701}', 7281, 2, 3, null, 'Anreize können zusätzliche betriebliche Plätze mobilisieren, besonders für Beschäftigte mit passenden Arbeitszeiten. Wie viele zusätzliche Plätze dadurch entstehen, ist für die konkrete Ausgestaltung unsicher.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=76', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7330, 17, 13, null, 'Fachkräfte für Kitas und Kindertagespflege gewinnen und sichern: vergütete, schulgeldfreie Ausbildung, attraktivere Arbeitsplätze, erleichterte Anerkennung und Weiterbildung.', '{1702,1704}', 7295, 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=75', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7331, 17, 13, null, 'Einkommensabhängige Kita-Gebühren als Standard einführen.', '{1705}', 7305, 2, 2, null, 'Einkommensabhängige Beiträge können die Belastung gezielter bei Familien mit geringem Einkommen senken. Der Bund kann Vorgaben zur Staffelung machen, Höhe und Erhebung der Beiträge liegen aber bei Ländern und Kommunen; die Angebotsknappheit bleibt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=76', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'nicht_blind'),
  (7332, 17, 14, null, 'Kindertagespflege als weitere Säule der Kindertagesbetreuung stärken.', '{1701}', 7301, 2, 2, null, 'Bundesunterstützung kann die Länder beim Erhalt und Ausbau ergänzender Betreuungsplätze unterstützen. Die konkrete Wirkung hängt von Umsetzung und dauerhafter Finanzierung vor Ort ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7333, 17, 14, null, 'Startchancen-Programm für Kitas mit akutem Platzmangel oder hohem Anteil sozial benachteiligter Kinder.', '{1701}', 7321, 2, 2, null, 'Gezielte Mittel können zusätzliche Kapazitäten und Förderung an Orten mit hohem Bedarf unterstützen. Ob Plätze entstehen, hängt von Umsetzung, Personal und ergänzender kommunaler Finanzierung ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7334, 17, 14, null, 'Ausbau von Betriebskindergärten unterstützen und bürokratische Hürden abbauen.', '{1701}', 7281, 2, 3, null, 'Anreize können zusätzliche betriebliche Plätze mobilisieren, besonders für Beschäftigte mit passenden Arbeitszeiten. Wie viele zusätzliche Plätze dadurch entstehen, ist für die konkrete Ausgestaltung unsicher.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=31', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7335, 17, 14, null, 'Bundeseinheitliche Kita-Qualitätsstandards mit bedarfsgerechtem Betreuungsschlüssel inklusive Ausfallzeiten, weniger Bürokratie und multiprofessionellen Teams.', '{1702,1703,1704}', 7320, 2, 2, null, 'Gemeinsame Standards können regionale Mindestqualität und Ausfallberücksichtigung verbessern. Ihre Umsetzung erfordert Abstimmung mit den Ländern und zusätzliche Mittel, wenn sie über bestehende Ausstattung hinausgehen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=7', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7336, 17, 14, null, 'Erzieherausbildung und Weiterbildung schulgeldfrei und vergütet anbieten, Ausbildungskapazitäten der Länder erhöhen.', '{1702}', 7295, 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=8', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7337, 17, 14, null, 'Bei Arbeitskämpfen in Kitas verpflichtende Schlichtung, Mindestankündigungsfristen und Notbetrieb vorsehen.', '{1704}', 7312, 1, 2, null, 'Vorankündigung und Schlichtung könnten Familien mehr Planungssicherheit geben. Sie verhindern weder krankheitsbedingte Ausfälle noch lösen sie Personalengpässe; arbeitsrechtliche Ausgestaltung ist anspruchsvoll.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=19', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7338, 17, 14, null, 'Kinderbetreuungskosten über ein Lebenschancen-BAföG mitfinanzieren.', '{1705}', 7308, 1, 2, null, 'Ein zweckgebundener Zuschuss kann einzelne Familien bei den Kosten entlasten. Seine Reichweite hängt von Anspruchshöhe und Zugang ab und beeinflusst das Platzangebot nicht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=10', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7339, 17, 14, null, 'Steuerlichen Abzug von Kinderbetreuungskosten verbessern.', '{1705}', 7306, 1, 3, null, 'Steuerliche Abzüge können einen Teil der Kosten kompensieren. Die Entlastung ist geringer oder fehlt bei Familien mit niedriger Steuerlast und löst weder Platzmangel noch hohe laufende Beiträge direkt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=31', 'https://www.oecd.org/en/publications/education-at-a-glance-2024_c00cad36-en.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7340, 17, 15, null, 'Ausreichend Kindergarten- und Kitaplätze in Wohnraumnähe bereitstellen, mit Vorrang für Familien mit zwei arbeitenden Eltern und arbeitende Alleinerziehende.', '{1701}', 7317, 1, 1, null, 'Eine Priorisierung kann Plätze für bestimmte Familien zugänglicher machen, erhöht aber nicht die Zahl der Plätze und kann andere Familien benachteiligen. Ein bundesweiter Eingriff in die Vergabe erfordert Abstimmung mit Ländern und Kommunen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7341, 17, 15, null, 'Krippen und Kitas ausreichend und qualifiziert besetzen; ein Betreuungsgehalt soll die Nachfrage nach Kitaplätzen und damit den Fachkräftemangel senken.', '{1701,1702}', 7315, 1, 2, null, 'Ein Betreuungsgehalt kann einzelne Familien finanziell entlasten, stellt aber keine bedarfsgerechte externe Betreuung sicher. Ob es die Platznachfrage dauerhaft senkt, ist unklar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=153', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7342, 17, 15, null, 'Betriebskindergärten stärker fördern.', '{1701}', 7281, 2, 3, null, 'Anreize können zusätzliche betriebliche Plätze mobilisieren, besonders für Beschäftigte mit passenden Arbeitszeiten. Wie viele zusätzliche Plätze dadurch entstehen, ist für die konkrete Ausgestaltung unsicher.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=153', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7343, 17, 16, null, 'Rechtsanspruch auf Ganztagsbetreuung umsetzen und ausreichend Kitaplätze schaffen.', '{1701}', 7280, 2, 2, null, 'Investitionshilfen können zusätzliche Plätze und erreichbare Angebote ermöglichen. Die Wirkung hängt von kommunaler Planung, Kofinanzierung und verfügbarem Personal ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7344, 17, 16, null, 'Familienentlastende Infrastruktur mit guter Erreichbarkeit ausbauen, Kitas in allen Stadtteilen.', '{1701}', 7280, 2, 2, null, 'Investitionshilfen können zusätzliche Plätze und erreichbare Angebote ermöglichen. Die Wirkung hängt von kommunaler Planung, Kofinanzierung und verfügbarem Personal ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7345, 17, 16, null, 'Betreuungsschlüssel auf höchstens eine Fachkraft für drei Kinder unter drei Jahren und 7,5 ältere Kinder verbessern, unter Berücksichtigung von Ausfall- und Vorbereitungszeiten.', '{1702,1703}', 7290, 2, 2, null, 'Einheitliche Mindeststandards können die Qualität und Berücksichtigung von Ausfällen stärken. Die Länder setzen sie um; Personalverfügbarkeit und Finanzierung bestimmen die tatsächliche Wirkung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7346, 17, 16, null, 'Löhne in den Sozial- und Erziehungsdiensten erhöhen und Refinanzierung der Tarifverträge sichern.', '{1702}', 7292, 2, 2, null, 'Die Refinanzierung kann Trägern ermöglichen, tarifliche Löhne zu zahlen und Personal zu halten. Der Bund kann Kosten mittragen, aber die tatsächliche Personalgewinnung ist nicht garantiert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7347, 17, 16, null, 'Zugang zur Erzieher*innen-Ausbildung erleichtern und Ausbildungsqualität erhöhen.', '{1702}', 7295, 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7348, 17, 16, null, 'Kitas für alle Kinder gebührenfrei machen.', '{1705}', 7303, 2, 2, null, 'Geringere Beiträge entlasten Familien und können den Zugang erleichtern, beseitigen aber nicht alle Zusatzkosten. Mehr Nachfrage kann bei knappen Plätzen den Zugang erschweren, wenn der Ausbau nicht Schritt hält.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7349, 17, 17, null, 'Unternehmen stärker zur Bereitstellung von Kita-Plätzen verpflichten, im Gegenzug steuerliche Vorteile.', '{1701}', 7281, 2, 3, null, 'Anreize können zusätzliche betriebliche Plätze mobilisieren, besonders für Beschäftigte mit passenden Arbeitszeiten. Wie viele zusätzliche Plätze dadurch entstehen, ist für die konkrete Ausgestaltung unsicher.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=32', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7350, 17, 17, null, 'Länder und Kommunen bei der Ausbildung von mehr Erziehern unterstützen, Arbeitsbedingungen in Bildungseinrichtungen verbessern.', '{1702}', 7295, 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=25', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7351, 17, 17, null, 'Für Kinder ab drei Jahren mit festgestellten Deutschdefiziten verpflichtender, beitragsfreier Kita-Besuch mit Sprachbildung.', '{1705}', 7318, 1, 1, null, 'Frühe Sprachförderung kann den Förderzugang verbessern, aber eine Pflicht erhöht nicht das knappe Platzangebot. Bedarfsermittlung, Zuständigkeit und Durchsetzung sind anspruchsvoll.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7352, 17, 17, null, 'Kita-Beiträge stabilisieren oder senken, mittelfristig Beitragsfreiheit.', '{1705}', 7303, 2, 2, null, 'Geringere Beiträge entlasten Familien und können den Zugang erleichtern, beseitigen aber nicht alle Zusatzkosten. Mehr Nachfrage kann bei knappen Plätzen den Zugang erschweren, wenn der Ausbau nicht Schritt hält.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7353, 17, 11, 'ST', 'Konzept vorlegen, das den Bedarf erfasst, die Finanzierung stabilisiert und den Personalschlüssel verbessert.', '{1701,1702,1703,1704}', 7276, 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=49', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7354, 17, 11, 'ST', 'Wohnortnahe Betreuung erhalten und über flexible Modelle, Kooperationen und Zusammenschlüsse an die regionale Nachfrage anpassen.', '{1701}', 7276, 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=49', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7355, 17, 11, 'ST', 'Dokumentationspflichten abbauen, Arbeitsalltag digital unterstützen, Leitungskräfte entlasten.', '{1702}', 7296, 1, 3, null, 'Weniger unnötige Dokumentation kann Fachkräfte und Leitung entlasten. Freigesetzte Zeit ersetzt keine zusätzlichen Betreuungskräfte und hängt von einer sorgfältigen Auswahl der Pflichten ab.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=49', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7356, 17, 11, 'ST', 'Kindertagespflege durch faire Vergütung, Beratung und Sachkostenförderung stärken.', '{1701,1702}', 7299, 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=49', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7357, 17, 11, 'ST', 'Kitas bedarfsgerecht ausbauen und sanieren, flexible Öffnungszeitenmodelle fördern.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=50', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7358, 17, 12, 'ST', 'Zusätzliche Personalmittel über „Kita STABIL“ bereitstellen und das Programm über 2028 hinaus fortsetzen.', '{1701,1702}', 7313, 2, 2, null, 'Zusätzliche Personalressourcen können Ausfälle auffangen und Betreuung stabilisieren. Eine dauerhafte Wirkung setzt verlässliche Finanzierung und verfügbare Fachkräfte voraus.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=27', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7359, 17, 12, 'ST', 'Flexible Öffnungszeiten von Kitas bis in Randzeiten ausbauen.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=28', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7360, 17, 12, 'ST', 'Rechtsanspruch auf bis zu zehn Stunden Betreuung von Geburt bis zum 14. Lebensjahr aufrechterhalten.', '{1701}', 7322, 1, 1, null, 'Ein Anspruch für ältere Kinder geht über das für dieses Thema erforderliche Kita-Angebot hinaus und schafft keinen Platz. Umfang, Zuständigkeiten und Finanzierung machen die Umsetzung schwierig.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=27', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7361, 17, 12, 'ST', 'Tatsächlichen Personalschlüssel in Kitas schrittweise verbessern.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=28', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7362, 17, 12, 'ST', 'Kitas mit besonderen sozialen Herausforderungen zusätzlich unterstützen.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=28', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7363, 17, 12, 'ST', 'Kurzfristige Entlastung von Eltern mit mehreren Kindern bei den Betreuungskosten sichern.', '{1705}', 7304, 1, 3, null, 'Ermäßigungen mindern die finanzielle Belastung größerer Familien, ohne die Kosten für alle Eltern abzuschaffen. Die Entlastung erreicht nur Familien, die die jeweilige Regelung nutzen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=28', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7364, 17, 13, 'ST', 'Nachhaltige kommunale Kitaplanung finanzieren.', '{1701}', 7276, 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7365, 17, 13, 'ST', 'Programm „HeimatKita“: wohnortnahe Betreuung zusichern und Kleinst-Kitas unterstützen.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7366, 17, 13, 'ST', 'Befristete Personalsicherung durch „Kita STABIL“ in eine langfristige strukturelle Verbesserung überführen.', '{1702}', 7313, 2, 2, null, 'Zusätzliche Personalressourcen können Ausfälle auffangen und Betreuung stabilisieren. Eine dauerhafte Wirkung setzt verlässliche Finanzierung und verfügbare Fachkräfte voraus.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7367, 17, 13, 'ST', 'Mindestpersonalschlüssel anheben, Sonderförderung für Kitas mit besonderen Bedarfen und Kita-Sozialarbeit ausbauen.', '{1702,1703}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7368, 17, 13, 'ST', 'Bezahlung und Arbeitsbedingungen für Erzieher*innen verbessern, von Bürokratie entlasten.', '{1702}', 7291, 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7369, 17, 13, 'ST', 'Erzieher*innen im Anerkennungsjahr unabhängig von der Trägerschaft angemessen vergüten.', '{1702}', 7294, 2, 2, null, 'Vergütung kann den Zugang zur Ausbildung erleichtern und die Zahl der Auszubildenden erhöhen. Ein unmittelbarer Effekt auf verfügbare Fachkräfte entsteht erst nach Ausbildungsabschluss.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7370, 17, 13, 'ST', 'Beitragsermäßigung für Mehrkinderfamilien dauerhaft sichern, Modell zur sozialen Staffelung der Kitabeiträge erarbeiten.', '{1705}', 7304, 1, 3, null, 'Ermäßigungen mindern die finanzielle Belastung größerer Familien, ohne die Kosten für alle Eltern abzuschaffen. Die Entlastung erreicht nur Familien, die die jeweilige Regelung nutzen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=57', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7371, 17, 14, 'ST', 'Flexible Öffnungszeiten am tatsächlichen Bedarf der Familien ausrichten.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=23', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7372, 17, 14, 'ST', 'Landesmodellprojekt für Gemeinschaftsbüros mit Kinderbetreuung und mobile Betreuungsreserven.', '{1701,1704}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=24', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7373, 17, 14, 'ST', 'Kurzfristig einspringende Betreuungszusammenschlüsse für Zeiten außerhalb der üblichen Öffnungszeiten unterstützen.', '{1701,1704}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=24', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7374, 17, 14, 'ST', 'Erzieherinnen und Erzieher entsprechend ausbilden und von Dokumentationspflichten entlasten.', '{1702}', 7293, 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=24', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7375, 17, 14, 'ST', 'Betreuungsschlüssel an den Förderbedarf anpassen und unterstützendes Personal einsetzen.', '{1702,1703}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=25', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7376, 17, 14, 'ST', 'Geschwisterkindregelung bei den Elternbeiträgen ändern, ohne sie abzuschaffen.', '{1705}', 7304, 1, 3, null, 'Ermäßigungen mindern die finanzielle Belastung größerer Familien, ohne die Kosten für alle Eltern abzuschaffen. Die Entlastung erreicht nur Familien, die die jeweilige Regelung nutzen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=25', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7377, 17, 15, 'ST', 'Krippen und Kindergärten ab dem ersten Kind mit dauerhaft gesicherter Landesfinanzierung kostenfrei machen.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=18', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7378, 17, 16, 'ST', 'Uneingeschränkten Rechtsanspruch auf zehn Stunden Betreuung täglich in Kindertageseinrichtungen schaffen.', '{1701}', 7319, 2, 1, null, 'Ein längerer Anspruch kann den Betreuungsumfang für Familien mit entsprechendem Bedarf direkt verbessern. Er verlangt zusätzliche Plätze und Personal und ist ohne entsprechende Kapazitäten innerhalb einer Wahlperiode schwer erfüllbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7379, 17, 16, 'ST', 'Multiprofessionelle Teams in Kitas flächendeckend aufbauen und die nötigen personellen und finanziellen Ressourcen sichern.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=27', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7380, 17, 16, 'ST', 'Personalschlüssel auf 1:3 in Krippen und 1:7,5 in Kindergärten verbessern.', '{1702,1703}', 7286, 3, 2, null, 'Die konkreten Zielwerte setzen direkt an der Personalausstattung an, die pädagogische Interaktionen ermöglicht. Die Verbesserung ist wirksam, erfordert angesichts des Fachkräftemangels aber zusätzliche Personal- und Finanzressourcen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7381, 17, 16, 'ST', 'Für die Kindertagespflege Leistungs-, Entgelt- und Qualitätsvereinbarungen mit den Jugendämtern abschließen.', '{1702}', 7299, 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7382, 17, 16, 'ST', 'Bildung in Kindertageseinrichtungen für alle Eltern beitragsfrei machen.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7383, 17, 16, 'ST', 'Kostenlose Mittagsversorgung für Kinder in Kitas und Kindertagespflege.', '{1705}', 7310, 1, 2, null, 'Kostenfreie Mahlzeiten senken einen Teil der Familienausgaben, lassen Elternbeiträge und weitere Zusatzkosten aber bestehen. Die Wirkung auf die Gesamtbelastung ist daher begrenzt.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7384, 17, 16, 'ST', 'Finanzierung an den tatsächlichen Personalkosten ausrichten; Elternbeiträge und Mehrkosten besserer Personalschlüssel vollständig vom Land finanzieren.', '{1702,1703,1705}', 7307, 2, 2, null, 'Eine Finanzierung der tatsächlichen Kosten kann bessere Personalausstattung ermöglichen und Beitragsbelastungen begrenzen. Die Ausgabenhöhe und die Verteilung zwischen Land, Kommunen und Trägern sind anspruchsvoll.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=29', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7385, 17, 16, 'ST', 'Alle Kita-Standorte im Land erhalten.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=46', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7386, 17, 17, 'ST', 'Ausbildungskapazitäten für Erzieher ausweiten und Studienplätze in der Kindheitspädagogik ausbauen.', '{1702}', 7293, 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7387, 17, 17, 'ST', 'Ausbildungs- und Arbeitsbedingungen im frühkindlichen Bereich durch Bezahlung, verlässliche Arbeitszeiten und Ausbildungsvergütung aufwerten.', '{1702}', 7291, 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7388, 17, 17, 'ST', 'Personal-Kind-Betreuungsschlüssel stärken.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7389, 17, 17, 'ST', 'Beitragsfreie Kitas einführen.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=46', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7390, 17, 11, 'MV', 'Planungs- und Genehmigungsverfahren für Kitas beschleunigen.', '{1701}', 7273, 2, 3, null, 'Kürzere Verfahren können den Ausbau erleichtern, schaffen aber weder Bauflächen noch Personal. Verwaltungsvereinfachungen sind innerhalb einer Wahlperiode realistisch.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=42', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7391, 17, 11, 'MV', 'Kindertagesbetreuung für Hochschulangehörige schaffen.', '{1701}', 7324, 1, 2, null, 'Ein gezieltes Angebot kann den Zugang für Hochschulangehörige verbessern, löst aber nur einen kleinen Teil des allgemeinen Platzmangels. Personal- und Investitionsbedarf bleiben bestehen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=68', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7392, 17, 11, 'MV', 'Freiwerdende Ressourcen für bessere Betreuungsschlüssel einsetzen.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7393, 17, 11, 'MV', 'Mit relevanten Akteuren einen Perspektivplan zur Verbesserung der Erzieher-Kind-Relation entwickeln.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7394, 17, 11, 'MV', 'Multiprofessionelle Teams mit spezialisierten Fachkräften in Kindergärten vorschreiben.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7395, 17, 11, 'MV', 'Mittel aus dem Kita-Qualitätsgesetz in qualitätssteigernde Maßnahmen, insbesondere pädagogische Leitungszeit, investieren.', '{1702}', 7314, 2, 2, null, 'Zusätzliche pädagogische Leitungs- und Personalzeit kann die Arbeit in Einrichtungen verbessern. Die Wirkung hängt davon ab, dass Mittel zusätzlich und dauerhaft für qualifiziertes Personal eingesetzt werden.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7396, 17, 11, 'MV', 'Pädagogische Teams durch Hauswirtschafts- und Verwaltungskräfte entlasten.', '{1702}', 7297, 2, 2, null, 'Zusätzliche Unterstützung kann pädagogischen Fachkräften mehr Zeit für Kinder geben. Sie benötigt weiteres Personal und verbessert nicht automatisch die Fachkraft-Kind-Relation.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=45', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7397, 17, 12, 'MV', 'Runde Tische mit den Kommunen je Landkreis und kreisfreier Stadt für verlässliche Bedarfsplanung einrichten.', '{1701}', 7276, 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=4', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7398, 17, 12, 'MV', 'Gruppengröße in Krippen ab 2027 auf fünf, im Kindergarten ab 2028 auf 13 Kinder je Fachkraft senken.', '{1703}', 7289, 2, 2, null, 'Die festen Stufen verbessern die Personalausstattung, bleiben aber deutlich hinter den fachlichen Empfehlungen von 1:3 und 1:7,5 zurück. Der Zeitplan ist bestimmt, das zusätzliche Personal muss bei Fachkräftemangel aber erst gewonnen werden.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=4', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'nicht_blind'),
  (7399, 17, 12, 'MV', 'Multiprofessionelle Teams schrittweise als Grundausstattung an Kitas einführen, beginnend bei Kitas mit besonderen Herausforderungen.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=67', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7400, 17, 12, 'MV', 'Beitragsfreiheit der Kitas fortführen.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=64', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7401, 17, 13, 'MV', 'Anspruch auf einen vollen Ganztagsplatz für alle Kinder einführen.', '{1701}', 7272, 2, 2, null, 'Ein erfüllter Anspruch verbessert den Zugang direkt, setzt aber ausreichende Plätze und Personal voraus. Die Umsetzung hängt deshalb von regionaler Kapazität und Finanzierung ab.', 'https://gruene-mv.de/?wpdmdl=33772#page=41', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7402, 17, 13, 'MV', 'Landesweites Modellprojekt mit flexibler Kinderbetreuung für junge Eltern.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://gruene-mv.de/?wpdmdl=33772#page=84', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7403, 17, 13, 'MV', 'Betreuungsschlüssel deutlich verbessern und sinkende Geburtenzahlen für kleinere Gruppen statt Personalabbau nutzen.', '{1702,1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://gruene-mv.de/?wpdmdl=33772#page=41', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7404, 17, 13, 'MV', 'Kindertagespflegepersonen, die Fachstandards erfüllen, entsprechend bezahlen.', '{1702}', 7299, 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://gruene-mv.de/?wpdmdl=33772#page=41', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7405, 17, 13, 'MV', 'Beitragsfreie Kita beibehalten.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://gruene-mv.de/?wpdmdl=33772#page=41', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7406, 17, 14, 'MV', 'Bestehenden Betreuungsanspruch überall verlässlich erfüllen und passgenaue Angebote sichern.', '{1701,1704}', 7272, 2, 2, null, 'Ein erfüllter Anspruch verbessert den Zugang direkt, setzt aber ausreichende Plätze und Personal voraus. Die Umsetzung hängt deshalb von regionaler Kapazität und Finanzierung ab.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7407, 17, 14, 'MV', 'Landesfinanzierung für Kita und Kindertagespflege an den tatsächlichen Bedarf anpassen.', '{1701}', 7275, 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=37', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7408, 17, 14, 'MV', 'Private Träger und Betriebskindergärten bei Einhaltung der Qualitätsstandards öffentlich fördern.', '{1701}', 7275, 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7409, 17, 14, 'MV', 'Kindertagespflege rechtssicher stärken, Bürokratie abbauen, verlässliche Rahmenbedingungen schaffen.', '{1701}', 7299, 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7410, 17, 14, 'MV', 'Tageseltern angemessen vergüten und Betreuung über das dritte Lebensjahr hinaus ermöglichen.', '{1701}', 7299, 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7411, 17, 14, 'MV', 'Fachkraft-Kind-Relation stufenweise, evidenzbasiert und gegenfinanziert verbessern.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7412, 17, 14, 'MV', 'Zusätzliche Mittel vorrangig in Personal, Sprachförderung und Verlässlichkeit investieren.', '{1702,1704}', 7314, 2, 2, null, 'Zusätzliche pädagogische Leitungs- und Personalzeit kann die Arbeit in Einrichtungen verbessern. Die Wirkung hängt davon ab, dass Mittel zusätzlich und dauerhaft für qualifiziertes Personal eingesetzt werden.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7413, 17, 14, 'MV', 'Mehr Fachkräfte durch niedrigere Ausbildungshürden, stärkere Praxisanteile und bedarfsgerechte Ausbildungskapazitäten gewinnen.', '{1702,1703}', 7293, 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7414, 17, 14, 'MV', 'Erzieherausbildung dual weiterentwickeln, weitere pädagogische und therapeutische Fachkräfte flexibler in Kitas einsetzen.', '{1702}', 7293, 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=82', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7415, 17, 14, 'MV', 'Beschäftigte von Kindertageseinrichtungen bei gleicher Qualifikation und Leistung gleich bezahlen.', '{1702}', 7291, 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7416, 17, 14, 'MV', 'Kita-Leitungen durch bessere Arbeitsbedingungen, weniger Berichtspflichten, digitale Verwaltung und klare Zuständigkeiten stärken.', '{1702}', 7296, 1, 3, null, 'Weniger unnötige Dokumentation kann Fachkräfte und Leitung entlasten. Freigesetzte Zeit ersetzt keine zusätzlichen Betreuungskräfte und hängt von einer sorgfältigen Auswahl der Pflichten ab.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=83', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7417, 17, 15, 'MV', 'Betreuungsschlüssel in Krippen auf 1:4 und in Kindergärten auf 1:10 verbessern.', '{1702,1703}', 7288, 2, 2, null, 'Die Zielwerte verbessern die Personalausstattung gegenüber ungünstigen Ausgangslagen, bleiben aber hinter den fachlichen Empfehlungen zurück. Zusätzliches Personal ist nötig.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=20', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7418, 17, 15, 'MV', 'Erzieher angelehnt an den TVöD vergüten und von Dokumentationspflichten entlasten.', '{1702}', 7291, 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=20', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7419, 17, 15, 'MV', 'Beitragsfreie Kitas erhalten.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=19', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7420, 17, 15, 'MV', 'Kindertagespflegepersonen stärker unterstützen.', '{1701}', 7299, 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=20', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7421, 17, 16, 'MV', 'Beitragsfreiheit in Kitas erhalten.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7422, 17, 16, 'MV', 'Garantie für eine wohnortnahe Tagesbetreuung für jedes Kind.', '{1701}', 7272, 2, 2, null, 'Ein erfüllter Anspruch verbessert den Zugang direkt, setzt aber ausreichende Plätze und Personal voraus. Die Umsetzung hängt deshalb von regionaler Kapazität und Finanzierung ab.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7423, 17, 16, 'MV', 'Gruppengröße in der Krippe schrittweise auf vier Kinder je Gruppe senken.', '{1703}', 7288, 2, 2, null, 'Die Zielwerte verbessern die Personalausstattung gegenüber ungünstigen Ausgangslagen, bleiben aber hinter den fachlichen Empfehlungen zurück. Zusätzliches Personal ist nötig.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', 'https://www.dji.de/themen/kinderbetreuung/plaetze-und-personalschluessel.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7424, 17, 16, 'MV', 'Arbeitszeiten in Kitas und Kindertagespflege an Arbeitswege und -zeiten der Eltern anpassen.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=15', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7425, 17, 17, 'MV', 'Erzieherberuf tariflich aufwerten, Arbeitsbedingungen verbessern und verlässliche Personalausstattung sichern.', '{1702}', 7291, 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7426, 17, 17, 'MV', 'Betreuungsschlüssel verbessern, damit mehr Zeit für individuelle Förderung bleibt.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7427, 17, 17, 'MV', 'Beitragsfreie Kita sichern und Kostenbeteiligung des Landes erhöhen.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=45', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7428, 17, 11, 'BE', 'Flexiblere und längere Betreuungsangebote ausbauen, etwa Betriebskindergärten und zusätzliche Tagesmütter und -väter.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7429, 17, 11, 'BE', 'Kita-Qualitätsoffensive mit Schwerpunkt Sprachbildung und Qualifizierung des pädagogischen Personals.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7430, 17, 11, 'BE', 'Multiprofessionelle Strukturen und Kita-Sozialarbeit stärken.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7431, 17, 11, 'BE', '24-Stunden-Kitas mit Betreuung zu Rand- und Nachtzeiten ausbauen.', '{1701}', 7278, 1, 1, null, 'Nachtbetreuung hilft nur Familien mit entsprechendem Bedarf und löst die allgemeine Angebotslücke kaum. Der hohe Personal- und Organisationsaufwand erschwert eine Umsetzung in der Wahlperiode.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7432, 17, 11, 'BE', 'Flexible, kostenfreie Betreuungsangebote, insbesondere zu Randzeiten.', '{1705}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7433, 17, 12, 'BE', 'Sanierung und Neubau von Kitas in den Kiezen als Investitionsschwerpunkt des Sondervermögens.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=7', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7434, 17, 12, 'BE', 'Finanzierung landeseigener Kita-Betriebe mit Investitionsmitteln stabilisieren, wohnortnahes Angebot in allen Bezirken.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7435, 17, 12, 'BE', 'Betreuungsschlüssel weiter verbessern und mittelbare pädagogische Arbeit durch mehr Personalzeit stärken.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7436, 17, 12, 'BE', 'Personalschlüssel nur nach tatsächlich anwesendem Personal berechnen; Urlaub, Krankheit und Fortbildung zählen nicht mit.', '{1702,1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7437, 17, 12, 'BE', 'Kitas mit zusätzlichem Fachpersonal für Sprachbildung stärken und den Personalzuschlag für Sprachförderung wieder einführen.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7438, 17, 12, 'BE', 'Personalzuschlag für Integrationskitas erhöhen.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7439, 17, 13, 'BE', 'Allen Familien zum ersten Geburtstag automatisch einen Kitagutschein mit Zugang zu Beratung und Kitaplatzvermittlung zusenden.', '{1701}', 7282, 1, 3, null, 'Eine automatische Information und Vermittlung kann administrative Hürden senken. Sie erhöht das Platzangebot nicht und hilft nur, wenn passende Plätze verfügbar sind.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=182', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7440, 17, 13, 'BE', 'Kitaplätze transparent und diskriminierungsfrei vergeben.', '{1701}', 7283, 1, 3, null, 'Transparente Verfahren können Mehrfachanmeldungen und ungerechte Zugänge reduzieren. Ein digitales System schafft selbst keine zusätzlichen Betreuungsplätze.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=182', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7441, 17, 13, 'BE', 'Betriebskitas unterstützen und ergänzende Betreuung außerhalb der Öffnungszeiten für Alleinerziehende und Schichtarbeitende ausweiten.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=110', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7442, 17, 13, 'BE', 'Kita-Platzausbau bei der Planung neuer Unterbringungsstandorte berücksichtigen.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=146', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7443, 17, 13, 'BE', 'Betreuungsschlüssel in Kitas weiter verbessern.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=182', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7444, 17, 14, 'BE', 'Landesweites Fast-Track-Genehmigungsverfahren mit Bearbeitungsgarantie, um Verwaltungshindernisse beim Kita-Ausbau abzubauen.', '{1701}', 7273, 2, 3, null, 'Kürzere Verfahren können den Ausbau erleichtern, schaffen aber weder Bauflächen noch Personal. Verwaltungsvereinfachungen sind innerhalb einer Wahlperiode realistisch.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=7', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7445, 17, 14, 'BE', 'Freie Kitaträger bei der Finanzierung den landeseigenen Kitas gleichstellen.', '{1701}', 7275, 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=7', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7446, 17, 14, 'BE', 'Freien Kitaträgern Beiträge für zusätzliche pädagogische Leistungen außerhalb des Kitagutscheins ermöglichen.', '{1705}', 7323, 0, 3, null, 'Zusätzliche kostenpflichtige Leistungen verbessern die Bezahlbarkeit der Grundbetreuung nicht und können die Belastung von Familien erhöhen. Die Erlaubnis ist administrativ umsetzbar, wirkt aber dem Kostenziel nicht entgegen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=7', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7447, 17, 14, 'BE', 'Sonderqualifikationen pädagogischer Fachkräfte in Kitas zusätzlich vergüten.', '{1702}', 7291, 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=7', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7448, 17, 14, 'BE', 'Mittelbare pädagogische Arbeit vollständig anerkennen und in die Personalschlüssel einrechnen.', '{1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=6', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7449, 17, 14, 'BE', 'Fachkräftemangel im Erziehungssektor bekämpfen und Betreuungsschlüssel in Berliner Kitas deutlich verbessern.', '{1702,1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=8', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7450, 17, 14, 'BE', 'Kitagutschein automatisch mit der Geburtsurkunde ausstellen.', '{1701}', 7282, 1, 3, null, 'Eine automatische Information und Vermittlung kann administrative Hürden senken. Sie erhöht das Platzangebot nicht und hilft nur, wenn passende Plätze verfügbar sind.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=8', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7451, 17, 14, 'BE', 'Digitale Plattform für Kita- und Schulanmeldungen mit Echtzeit-Anmeldung und Mehrfachanmeldungen schaffen.', '{1701}', 7283, 1, 3, null, 'Transparente Verfahren können Mehrfachanmeldungen und ungerechte Zugänge reduzieren. Ein digitales System schafft selbst keine zusätzlichen Betreuungsplätze.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7452, 17, 14, 'BE', 'Über Anträge auf staatliche Leistungen einschließlich Kitagutscheinen binnen vier Wochen entscheiden und auszahlen.', '{1701}', 7285, 1, 3, null, 'Schnellere Bescheide erleichtern die Planung und beseitigen Verzögerungen im Verwaltungszugang. Sie schaffen keinen Platz, wenn das Angebot fehlt.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7453, 17, 14, 'BE', 'Dauerhaft ausreichend Kita- und Tagespflegeplätze mit flexibleren Öffnungszeiten, Notfallangeboten und 24-Stunden-Kitas schaffen.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7454, 17, 14, 'BE', 'Kinderbetreuung zu Hause für Menschen im Schichtdienst staatlich unterstützen.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7455, 17, 14, 'BE', 'Mobilen Kinderbetreuungsservice für Eltern mit besonderen Arbeitszeiten (MoKiS) deutlich ausbauen.', '{1701}', 7277, 2, 2, null, 'Bedarfsgerechte Zeiten und Ersatzangebote können Versorgungslücken für Familien mit besonderen Arbeitszeiten abfedern. Personalbedarf, Nachfrage und Qualität begrenzen die flächendeckende Umsetzung.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', 'https://www.dji.de/themen/kinderbetreuung/eltern-wuenschen-sich-flexiblere-betreuungsangebote.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7456, 17, 15, 'BE', 'Landeserziehungsgeld für Kinder unter drei Jahren in Höhe der vergleichbaren Kosten eines Kita-Platzes einführen.', '{1705}', 7309, 1, 2, null, 'Ein Geldbetrag kann Familien finanziell entlasten, sichert aber keinen Kita-Platz und kann die Nachfrage nach Betreuung sogar senken. Die Kosten hängen von Anspruch und Leistungshöhe ab.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=59', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7457, 17, 15, 'BE', 'Kostenfreiheit der Kita beibehalten.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=59', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7458, 17, 15, 'BE', 'Angebot an Kita-Plätzen erhalten und bedarfsgerecht ausbauen.', '{1701}', 7272, 2, 2, null, 'Ein erfüllter Anspruch verbessert den Zugang direkt, setzt aber ausreichende Plätze und Personal voraus. Die Umsetzung hängt deshalb von regionaler Kapazität und Finanzierung ab.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=60', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7459, 17, 15, 'BE', '„Blaulicht“-Kita für Polizei, Feuerwehr und Rettungsdienste schaffen; kleine und mittelgroße Kita-Träger sowie Betriebskindergärten fördern.', '{1701}', 7279, 2, 2, null, 'Betriebskitas schaffen zusätzliche Plätze und können Arbeitszeiten besser abdecken. Sie erreichen nicht alle Familien und benötigen Personal sowie tragfähige Trägerfinanzierung.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=60', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7460, 17, 15, 'BE', 'Bestehende Hochschul-Kitas ausbauen.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=37', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7461, 17, 15, 'BE', 'Betreuungsschlüssel erhöhen und längere Öffnungszeiten für Eltern mit besonderen Arbeitszeiten ermöglichen.', '{1702,1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=60', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7462, 17, 16, 'BE', 'Personalschlüssel verbessern; Ziel sind rechnerisch drei Kinder unter drei Jahren bzw. 7,5 Kinder über drei Jahren je Fachkraft.', '{1703}', 7286, 3, 2, null, 'Die konkreten Zielwerte setzen direkt an der Personalausstattung an, die pädagogische Interaktionen ermöglicht. Die Verbesserung ist wirksam, erfordert angesichts des Fachkräftemangels aber zusätzliche Personal- und Finanzressourcen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=184', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7463, 17, 16, 'BE', 'Fehlzeiten und mittelbare Arbeitszeiten in der Personalzumessung berücksichtigen; nur ausgebildete Fachkräfte voll auf den Personalschlüssel anrechnen.', '{1702,1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=184', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7464, 17, 16, 'BE', 'Geltende Personalzuschläge mit Fachwelt und Praxis prüfen, öffnen und verbessern.', '{1702,1703}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=184', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7465, 17, 16, 'BE', 'Gesundheits-, Lärm- und Hitzeschutz in allen Kitas einführen, um das Arbeitsfeld für Fachkräfte attraktiv zu halten.', '{1702}', 7316, 1, 2, null, 'Bessere Arbeitsbedingungen können Belastungen mindern und die Bindung von Personal unterstützen. Der direkte Beitrag zu mehr verfügbaren Betreuungsstunden ist begrenzt und nicht gut untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=185', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7466, 17, 16, 'BE', 'Modellprogramm Kita-Sozialarbeit erhalten und ausweiten, mittelfristig für zehn Prozent der Kitakinder, langfristig flächendeckend.', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=185', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7467, 17, 16, 'BE', 'Bestehende Kita-Plätze durch planvolle Sanierungen sichern.', '{1701}', 7274, 2, 2, null, 'Zusätzliche und gesicherte Plätze wirken unmittelbar gegen Angebotslücken; der tatsächliche Effekt hängt von Personalverfügbarkeit und regionaler Planung ab. Investitionen und laufende Kosten begrenzen das Tempo.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=185', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'belegt', '2026-10-01', false, true, 'blind'),
  (7468, 17, 16, 'BE', 'Raum und Personal trotz sinkender Kinderzahlen im Kita-System halten.', '{1701,1702}', 7276, 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=186', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7469, 17, 16, 'BE', 'Anteil der landeseigenen Kita-Betriebe am Platzangebot auf ein Drittel erhöhen.', '{1701}', 7275, 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=186', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7470, 17, 16, 'BE', 'Eigenanteil der Kitaträger an der Platzfinanzierung schrittweise abschmelzen.', '{1701}', 7275, 2, 2, null, 'Eine verlässliche Finanzierung kann Plätze erhalten und Ausbau ermöglichen. Der Effekt hängt davon ab, ob Mittel zusätzlich bereitgestellt und tatsächlich für Kapazitäten eingesetzt werden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=186', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7471, 17, 16, 'BE', 'Allen Familien zum ersten Geburtstag einen verständlichen, mehrsprachigen Kita-Gutschein zusenden und aufsuchende Sozialarbeit zum Abbau von Zugangshürden stärken.', '{1701}', 7282, 1, 3, null, 'Eine automatische Information und Vermittlung kann administrative Hürden senken. Sie erhöht das Platzangebot nicht und hilft nur, wenn passende Plätze verfügbar sind.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7472, 17, 16, 'BE', 'Jugendämtern Zugriff auf einen Teil der Kitaplätze geben und das Freihalten von Plätzen finanzieren.', '{1701}', 7284, 1, 2, null, 'Reservierte Plätze können einzelne Zugangsprobleme abfedern, verringern aber die Zahl regulär verfügbarer Plätze. Der Nutzen hängt von lokaler Nachfrage und verlässlicher Finanzierung ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7473, 17, 16, 'BE', 'Vergütung in der Kindertagespflege so bemessen, dass sie Lebenshaltungskosten und Mieten deckt.', '{1701}', 7299, 2, 2, null, 'Faire Entgelte, Beratung und klare Vereinbarungen können Tagespflegepersonen halten und zusätzliche Plätze ermöglichen. Die Zahl der erreichbaren Plätze bleibt von der Gewinnung und Bindung der Betreuungspersonen abhängig.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7474, 17, 16, 'BE', 'Verbesserten Kita-Betreuungsschlüssel ohne finanzielle Einbußen auf die Kindertagespflege übertragen.', '{1703}', 7300, 2, 2, null, 'Eine bessere Personalausstattung kann die Betreuungsqualität erhöhen. Eine Übertragung ohne Einkommensverluste erfordert zusätzliche Finanzierung und muss zur Struktur der Tagespflege passen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7475, 17, 16, 'BE', 'Ausreichend barrierefreie Kitaplätze in Wohnortnähe schaffen und Kitas mit heil-, sozial- und inklusionspädagogischen Fachkräften ausstatten.', '{1701,1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=188', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7476, 17, 16, 'BE', 'Gezielt für das Berufsfeld Kita werben und Quereinsteigende bis zum DQR-Niveau 6 qualifizieren.', '{1702}', 7293, 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=189', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7477, 17, 16, 'BE', 'Qualitätsinitiative für die Ausbildung starten und den Anteil staatlicher Schulen an der Erzieher*innenausbildung erhöhen.', '{1702}', 7293, 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=189', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7478, 17, 16, 'BE', 'Praxisstunden in der Ausbildung vergüten und ausdrückliche Ausbildungsverträge einführen.', '{1702}', 7294, 2, 2, null, 'Vergütung kann den Zugang zur Ausbildung erleichtern und die Zahl der Auszubildenden erhöhen. Ein unmittelbarer Effekt auf verfügbare Fachkräfte entsteht erst nach Ausbildungsabschluss.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=189', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7479, 17, 16, 'BE', 'Gebührenfreiheit der Bildung von der Kita bis zur Hochschule als Grundsatz beibehalten.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=153', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-01', false, true, 'blind'),
  (7480, 17, 16, 'BE', 'Verpflichtende Zusatzzahlungen über Kitafördervereine zurückweisen.', '{1705}', 7311, 1, 3, null, 'Das Verhindern verpflichtender Zusatzforderungen kann unerwartete Kosten begrenzen. Es senkt nicht automatisch die regulären Elternbeiträge und muss mit der Finanzierung zusätzlicher Leistungen vereinbar sein.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=187', null, 'offen', '2026-10-01', false, true, 'blind'),
  (7508, 9, 11, null, 'Videoschutz an öffentlichen Gefahrenorten ausbauen und automatisierte Gesichtserkennung an Bahnhöfen, Flughäfen und Kriminalitätsschwerpunkten einsetzen.', '{901}', null, 1, 1, null, 'Kameras an Brennpunkten senken laut Meta-Analyse leicht die Kriminalität, kaum aber Gewalt. Automatische Gesichtserkennung im öffentlichen Raum lässt die KI-Verordnung der EU nur in engen Ausnahmen zu.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7509, 9, 11, null, 'Digitale Befugnisse für alle Bundessicherheitsbehörden: Quellen-TKÜ, Online-Durchsuchung und automatische Datenanalyse mit KI.', '{902}', 7484, 1, 2, null, 'Automatisierte Analysen und Online-Befugnisse können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7510, 9, 11, null, 'Gerichte personell besser ausstatten, konkurrenzfähig besolden, digitalisieren und Verfahren beschleunigen.', '{902}', 7481, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten nach der Personalbedarfsberechnung als ein Hauptgrund für rund eine Million offene Verfahren. Mehr Personal setzt dort an. Der Bund kann über einen Pakt aber nur mitfinanzieren, und Nachwuchs ist knapp.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', 'https://www.drb.de/newsroom/presse-mediencenter/nachrichten-auf-einen-blick/nachricht/news/staatsanwaltschaften-am-limit-1', 'belegt', '2026-10-02', false, true, 'blind'),
  (7511, 9, 11, null, 'Beweislastumkehr beim Einziehen von Vermögen unklarer Herkunft, Geldwäsche konsequenter bekämpfen.', '{902}', 7489, 1, 2, null, 'Eine leichtere Einziehung von Vermögen trifft kriminelle Strukturen finanziell. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum. Eine volle Beweislastumkehr steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=46', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7512, 9, 11, null, 'Auf Heranwachsende von 18 bis 21 Jahren soll künftig allgemeines Strafrecht statt Jugendstrafrecht angewendet werden.', '{903}', 7492, 1, 2, null, 'Dafür spricht, dass Intensivtäter früher gestoppt werden können. Rückfallstudien zeigen aber keinen Vorteil härterer Sanktionen bei jungen Menschen, eher höhere Rückfallraten. Für Kinder fehlen zudem geeignete Einrichtungen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', 'https://www.uni-konstanz.de/rtf/kis/heinz-sanktionen-jugendstrafrecht-12-thesen.htm', 'belegt', '2026-10-02', false, true, 'blind'),
  (7513, 9, 11, null, 'Strafrecht verschärfen zum besseren Schutz besonders gefährdeter Gruppen, vor allem Frauen; Höchststrafe für Stalking erhöhen.', '{904}', 7491, 1, 3, null, 'Höhere Strafen sind rechtlich leicht umsetzbar und benennen das Unrecht klarer. Die Forschung zeigt aber übereinstimmend: Abschreckend wirkt vor allem das Risiko, erwischt zu werden, kaum die Höhe der Strafe.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', 'https://prohic.nl/wp-content/uploads/2020/11/2020-06-02-DeterrenceMetaNagin.2013.pdf', 'belegt', '2026-10-02', false, true, 'blind'),
  (7514, 9, 11, null, 'Sicherheitskonzept für Opfer häuslicher Gewalt entwickeln und Frauenhäuser stärken.', '{904}', 7494, 2, 2, null, 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'belegt', '2026-10-02', false, true, 'blind'),
  (7515, 9, 11, null, 'Elektronische Fußfessel verstärkt einsetzen, damit Gewalttäter Abstand zu ehemaligen Partnerinnen halten.', '{904}', 7495, 2, 3, null, 'In Spanien wurde seit 2009 keine Frau getötet, deren Täter überwacht wurde. Die Maßnahme setzt bei Hochrisikofällen an. Sie erreicht aber nur wenige Fälle und setzt voraus, dass die Gewalt bereits angezeigt wurde.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', 'https://www.france24.com/en/20200926-domestic-violence-electronic-bracelets-are-a-first-step-but-we-have-to-go-further', 'belegt', '2026-10-02', false, true, 'blind'),
  (7516, 9, 11, null, 'Gruppenvergewaltigungen und Körperverletzungen mit Messer deutlich härter bestrafen.', '{908,902}', 7491, 1, 3, null, 'Höhere Strafen sind rechtlich leicht umsetzbar und benennen das Unrecht klarer. Die Forschung zeigt aber übereinstimmend: Abschreckend wirkt vor allem das Risiko, erwischt zu werden, kaum die Höhe der Strafe.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', 'https://prohic.nl/wp-content/uploads/2020/11/2020-06-02-DeterrenceMetaNagin.2013.pdf', 'belegt', '2026-10-02', false, true, 'blind'),
  (7517, 9, 11, null, 'Regelmäßige Abschiebungen nach Afghanistan und Syrien, vor allem von Straftätern und Gefährdern.', '{905,907}', 7497, 1, 2, null, 'Die Maßnahme verhindert weitere Taten der Abgeschobenen im Inland. Sie betrifft aber nur einen kleinen Teil der Tatverdächtigen und lässt die Ursachen laut Forschung unberührt. Ob sie gelingt, hängt von der Mitarbeit der Herkunftsstaaten ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', 'https://www.swp-berlin.org/10.18449/2021S12/', 'offen', '2026-10-02', false, true, 'blind'),
  (7518, 9, 11, null, 'Ausreisepflichtige Straftäter und Gefährder nach der Haft in unbefristeten Ausreisearrest nehmen können.', '{905,907}', null, 1, 0, null, 'Die Haft würde Gefährder bis zur Ausreise festhalten. Unbefristeter Arrest verstößt aber gegen die EU-Rückführungsrichtlinie (höchstens 18 Monate) und gegen das Grundrecht auf Freiheit.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7519, 9, 11, null, 'Speicherpflicht für IP-Adressen und Portnummern für Internetanbieter.', '{906,907}', null, 2, 2, null, 'Ohne gespeicherte IP-Adressen bleiben viele Hinweise auf Online-Taten unaufklärbar. Eine Max-Planck-Studie fand für die frühere Vorratsdatenspeicherung aber keine höhere Aufklärungsquote. Das EU-Recht lässt eine Speicherpflicht nur in engen Grenzen zu.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', 'https://heise.de/newsticker/meldung/Studie-Vorratsdatenspeicherung-verbessert-die-Aufklaerungsquote-nicht-1423035.html', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7520, 9, 11, null, 'Telekommunikationsüberwachung und Funkzellenauswertung ausweiten, insbesondere beim Enkeltrick.', '{906}', null, 1, 2, null, 'Mit Telekommunikationsüberwachung lassen sich Banden beim Enkeltrick verfolgen. Viele Täter sitzen aber im Ausland, und neue Befugnisse müssen vor dem Fernmeldegeheimnis bestehen. Zur Wirkung gibt es kaum Daten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=40', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7521, 9, 11, null, 'Europol stärken und zur Zentralstelle mit gemeinsamem Datenhaus ausbauen, auch gegen Cyberkriminalität und Terrorismus.', '{906,902}', 7488, 1, 1, null, 'Viele Online- und organisierte Taten kommen aus dem Ausland, deshalb setzt eine bessere Zusammenarbeit an einer Ursache an. Operative Befugnisse für Europol erfordern aber eine Änderung der EU-Verträge mit allen Mitgliedstaaten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=47', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7522, 9, 11, null, 'Nachrichtendiensten die notwendigen Befugnisse zur frühzeitigen Gefahrenaufklärung geben.', '{907}', 7498, 2, 2, null, 'Eine frühe Aufklärung von Netzwerken und Gefährdern kann schwere Anschläge verhindern. Unabhängige Wirkungsstudien fehlen, und neue Befugnisse stoßen auf verfassungsrechtliche Grenzen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=41', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7523, 9, 11, null, 'Antisemitische Straftat führt zum Verlust des humanitären Schutzes und zur Abschiebung.', '{907}', null, 1, 1, null, 'Die Maßnahme entfernt antisemitische Straftäter und kann abschrecken. Ein Widerruf des Schutzstatus ist nach EU-Recht und Flüchtlingskonvention aber nur bei schweren Taten möglich und hängt von Herkunftsstaaten ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=46', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7524, 9, 11, null, 'Vereine und Verbände, die vom Verfassungsschutz beobachtet werden, von staatlichen Kooperationen und Geldern ausschließen.', '{907}', 7504, 1, 2, null, 'Die Maßnahme verhindert, dass extremistische Strukturen staatlich mitfinanziert werden. Auf Straftaten wirkt sie nur indirekt. Ein Ausschluss allein wegen einer Beobachtung oder wegen einzelner Mitglieder ist rechtlich angreifbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7525, 9, 11, null, 'Extremisten und Straftäter, die Feinde des Staates sind, entwaffnen.', '{907}', 7501, 2, 3, null, 'Ohne legale Waffen sind schwere Gewalttaten von Extremisten schwerer möglich, und das Waffenrecht erlaubt den Entzug bereits. Illegal beschaffte Waffen erfasst die Maßnahme nicht, und Wirkungsstudien fehlen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7526, 9, 11, null, 'Gesetz gegen Extremismus: Werben für Terrororganisationen wird strafbar, mit Regelausweisung und Verlust der Staatsangehörigkeit bei Doppelstaatlern.', '{907}', 7503, 1, 2, null, 'Neue Straftatbestände können Werbung für Terror oder verfassungsfeindliche Ziele früher ahnden. Sie überschneiden sich teils mit geltendem Recht und müssen vor der Meinungsfreiheit bestehen. Zur Wirkung auf Gewalttaten gibt es keine Belege.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7527, 9, 11, null, 'Bundesprogramm „Demokratie leben“ künftig im Bundesinnenministerium ansiedeln.', '{907}', null, 0, 3, null, 'Ein Ressortwechsel kann das Programm stärker mit der Sicherheitsarbeit verzahnen. Er ändert aber weder Umfang noch Inhalt der Prävention, daher ist keine Wirkung auf Straftaten zu erwarten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=45', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7528, 9, 11, null, 'Ambulante und stationäre Versorgungsangebote für psychische Erkrankungen bedarfsgerecht verbessern, besonders für Kinder und Jugendliche.', '{911}', null, 1, 2, null, 'Eine bessere ambulante und stationäre Versorgung erreicht auch schwer Erkrankte, deren Gewaltrisiko eine Behandlung senkt. Die Zusage ist aber allgemein und vor allem auf Kinder und Jugendliche ausgerichtet.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=70', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7529, 9, 12, null, 'Personalaufbau bei den Sicherheitsbehörden fortsetzen, begründet mit der Sichtbarkeit der Polizei.', '{901}', 7506, 2, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung in andere Gebiete. Die meisten Orte liegen aber in der Zuständigkeit der Landespolizei, und Personal fehlt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=42', 'https://nij.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-02', false, true, 'blind'),
  (7530, 9, 12, null, 'Moderne Ausrüstung und zeitgemäße Befugnisse für Polizei- und Sicherheitsbehörden.', '{902}', 7482, 2, 2, null, 'Mehr und besser ausgestattete Ermittler können mehr Taten aufklären, und Studien aus den USA finden weniger Kriminalität bei mehr Polizei. Der Bund steuert aber nur BKA und Bundespolizei. Ohne konkreten Umfang ist die Wirkung unbestimmt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=42', null, 'gemischt', '2026-10-02', false, true, 'blind'),
  (7531, 9, 12, null, 'Gesetzliche Grundlage für KI-gestützte Datenanalyse bei Bundeskriminalamt und Bundespolizei.', '{902}', 7484, 1, 2, null, 'Automatisierte Analysen und Online-Befugnisse können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=43', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7532, 9, 12, null, 'Erneuter Pakt für den Rechtsstaat: Justiz mit den Ländern personell und materiell besser ausstatten.', '{902}', 7481, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten nach der Personalbedarfsberechnung als ein Hauptgrund für rund eine Million offene Verfahren. Mehr Personal setzt dort an. Der Bund kann über einen Pakt aber nur mitfinanzieren, und Nachwuchs ist knapp.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=43', 'https://www.drb.de/newsroom/presse-mediencenter/nachrichten-auf-einen-blick/nachricht/news/staatsanwaltschaften-am-limit-1', 'belegt', '2026-10-02', false, true, 'blind'),
  (7533, 9, 12, null, 'Strafprozessordnung auf Effektivität reformieren.', '{902}', null, 1, 2, null, 'Eine effizientere Strafprozessordnung kann Verfahren beschleunigen. Die Zusage nennt aber keinen Inhalt, und der Hauptengpass ist das Personal.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=43', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7534, 9, 12, null, 'Digitalisierung der Justiz mit bundesweit kompatiblen Systemen fortsetzen.', '{902}', 7483, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und IT-Projekte der Justiz brauchen viele Jahre und die Mitarbeit der Länder.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=43', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7535, 9, 12, null, 'Organisierte Kriminalität: Definition modernisieren und Sicherheitsbehörden stärken, Wirtschaftskriminalität im Fokus.', '{902}', 7489, 1, 2, null, 'Eine leichtere Einziehung von Vermögen trifft kriminelle Strukturen finanziell. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum. Eine volle Beweislastumkehr steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=43', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7536, 9, 12, null, 'Sexuelle Handlungen ohne eindeutiges Einverständnis unter Strafe stellen.', '{908}', 7493, 1, 3, null, 'In Schweden stiegen die Verurteilungen nach der Reform deutlich. Deutschland erfasst seit 2016 aber schon Taten gegen den erkennbaren Willen, daher ist der Zusatznutzen kleiner. An der geringen Anzeigebereitschaft ändert die Reform wenig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', 'https://www.thelocal.se/20200616/how-swedens-new-consent-law-led-to-a-75-rise-in-rape-convictions/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7537, 9, 12, null, 'Erhebliche sexuelle Belästigung wie Catcalling unter Strafe stellen.', '{908}', null, 1, 3, null, 'Eine Strafbarkeit verbaler Belästigung macht deutlich, dass sie Unrecht ist, und schließt eine Lücke. Durchsetzen lässt sie sich aber schwer, weil Täter selten bekannt sind, und belastbare Wirkungsdaten fehlen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7538, 9, 12, null, 'Gewaltschutzgesetz verschärfen: Fußfessel, Anti-Gewalt-Trainings für Täter, Aufenthaltsverbote, Hausarrest.', '{904}', 7495, 2, 3, null, 'In Spanien wurde seit 2009 keine Frau getötet, deren Täter überwacht wurde. Die Maßnahme setzt bei Hochrisikofällen an. Sie erreicht aber nur wenige Fälle und setzt voraus, dass die Gewalt bereits angezeigt wurde.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', 'https://www.france24.com/en/20200926-domestic-violence-electronic-bracelets-are-a-first-step-but-we-have-to-go-further', 'belegt', '2026-10-02', false, true, 'blind'),
  (7539, 9, 12, null, 'Bundesweiter Rechtsanspruch auf Schutz und Beratung, Zugang zu Frauenhäusern und Beratungsstellen; Gewalthilfegesetz.', '{904}', 7494, 2, 2, null, 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'belegt', '2026-10-02', false, true, 'blind'),
  (7540, 9, 12, null, 'Geschlechtsspezifische Gewalt EU-weit als Straftatbestand festschreiben lassen.', '{904}', null, 1, 1, null, 'Ein EU-weiter Straftatbestand vereinheitlicht den Schutz. In Deutschland sind die meisten Taten aber schon strafbar, und die Maßnahme hängt von einer Einigung in der EU ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7541, 9, 12, null, 'Log-in-Falle: IP-Adresse bei verdächtigem Benutzerkonto erfassen, um Stammdaten zu ermitteln.', '{906}', 7487, 1, 3, null, 'Die Login-Falle kann anonyme Konten gezielt identifizieren und ist rechtlich wenig umstritten. Sie wirkt aber nur bei Konten, die erneut genutzt werden, und erfasst Betrug aus dem Ausland kaum. Zur Wirkung gibt es kaum Daten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7542, 9, 12, null, 'Regeln gegen Hasskriminalität und Netzstraftaten umsetzen; Plattformbetreiber müssen illegale Inhalte entfernen.', '{906,907}', null, 1, 2, null, 'Löschpflichten verringern die Verbreitung von Hass und illegalen Inhalten. Sie führen aber nicht zur Verfolgung der Täter und helfen gegen Betrug kaum. Der europäische Digital Services Act lässt wenig Raum für eigene nationale Regeln.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7543, 9, 12, null, 'Finanzquellen rechtsextremistischer Netzwerke offenlegen und austrocknen.', '{907}', null, 1, 2, null, 'Wenn Finanzquellen wegfallen, verlieren Netzwerke Handlungsfähigkeit. Ein konkretes Instrument nennt die Zusage nicht, und Wirkungsstudien fehlen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=42', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7544, 9, 12, null, 'Islamismusprävention weiter stärken.', '{907}', 7502, 2, 2, null, 'Eine Auswertung eines Aussteigerprogramms fand bei 94 % der Betreuten keine neuen Straftaten, allerdings ohne Vergleichsgruppe. Belastbare Wirkungsstudien sind selten. Ob der Bund für ein Fördergesetz zuständig ist, ist umstritten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=42', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/546159/ein-weg-aus-dem-rechtsextremismus/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7545, 9, 12, null, 'Sicherheitsbehörden mit nötigen Mitteln ausstatten, um islamistische Netzwerke zu zerschlagen.', '{907}', 7498, 2, 2, null, 'Eine frühe Aufklärung von Netzwerken und Gefährdern kann schwere Anschläge verhindern. Unabhängige Wirkungsstudien fehlen, und neue Befugnisse stoßen auf verfassungsrechtliche Grenzen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=42', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7546, 9, 12, null, 'Rasche und konsequente Abschiebungen bei verweigerter Ausreise, insbesondere von Straftätern.', '{905}', 7497, 1, 2, null, 'Die Maßnahme verhindert weitere Taten der Abgeschobenen im Inland. Sie betrifft aber nur einen kleinen Teil der Tatverdächtigen und lässt die Ursachen laut Forschung unberührt. Ob sie gelingt, hängt von der Mitarbeit der Herkunftsstaaten ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=56', 'https://www.swp-berlin.org/10.18449/2021S12/', 'offen', '2026-10-02', false, true, 'blind'),
  (7547, 9, 13, null, 'Bundespolizei und BKA sollen das nötige Personal, Technik, Know-how und verfassungskonforme Befugnisse erhalten.', '{902}', 7482, 2, 2, null, 'Mehr und besser ausgestattete Ermittler können mehr Taten aufklären, und Studien aus den USA finden weniger Kriminalität bei mehr Polizei. Der Bund steuert aber nur BKA und Bundespolizei. Ohne konkreten Umfang ist die Wirkung unbestimmt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=133', null, 'gemischt', '2026-10-02', false, true, 'blind'),
  (7548, 9, 13, null, 'Neuauflage des Pakts für den Rechtsstaat mit den Ländern; genügend Richter und Staatsanwälte, gut ausgestattete Gerichte.', '{902}', 7481, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten nach der Personalbedarfsberechnung als ein Hauptgrund für rund eine Million offene Verfahren. Mehr Personal setzt dort an. Der Bund kann über einen Pakt aber nur mitfinanzieren, und Nachwuchs ist knapp.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=113', 'https://www.drb.de/newsroom/presse-mediencenter/nachrichten-auf-einen-blick/nachricht/news/staatsanwaltschaften-am-limit-1', 'belegt', '2026-10-02', false, true, 'blind'),
  (7549, 9, 13, null, 'Datenzugriff für Strafverfolgung im digitalen Raum über Quick-Freeze ausbauen.', '{902,906}', 7486, 1, 3, null, 'Quick Freeze ist grundrechtsschonend und schnell umsetzbar. Es greift aber nur bei Daten, die zum Zeitpunkt der Anordnung noch vorhanden sind. Bei IP-Adressen ist das oft nicht mehr der Fall, daher ist der Nutzen bei Onlinebetrug begrenzt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=115', 'https://heise.de/newsticker/meldung/Studie-Vorratsdatenspeicherung-verbessert-die-Aufklaerungsquote-nicht-1423035.html', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7550, 9, 13, null, 'Geringfügige Delikte aus dem Strafrecht nehmen und Ersatzfreiheitsstrafe vermeiden, um die Justiz zu entlasten.', '{902}', 7490, 1, 3, null, 'Allein Fahren ohne Fahrschein macht rund 6 % der Verurteilungen und über die Hälfte der Ersatzfreiheitsstrafen aus. Eine Streichung entlastet Justiz und Haft spürbar. Die Aufklärung schwerer Taten verbessert sie nur indirekt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=114', null, 'belegt', '2026-10-02', false, true, 'blind'),
  (7551, 9, 13, null, 'KI-gestützte Analyseinstrumente der Polizei für die Strafverfolgung stärker nutzbar machen, polizeiliche Daten automatisiert verknüpfen.', '{902}', 7484, 1, 2, null, 'Automatisierte Analysen und Online-Befugnisse können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=115', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7552, 9, 13, null, 'Gemeinsame Zentren der Polizei in Grenzregionen ausbauen, Europol zu einem Europäischen Kriminalamt weiterentwickeln.', '{902}', 7488, 1, 1, null, 'Viele Online- und organisierte Taten kommen aus dem Ausland, deshalb setzt eine bessere Zusammenarbeit an einer Ursache an. Operative Befugnisse für Europol erfordern aber eine Änderung der EU-Verträge mit allen Mitgliedstaaten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7553, 9, 13, null, 'Rechtsanspruch auf Schutz und Beratung bei Partnerschaftsgewalt; Frauenhäuser, Beratungsstellen und Schutzwohnungen mit Bundesbeteiligung flächendeckend sichern.', '{904}', 7494, 2, 2, null, 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=118', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'belegt', '2026-10-02', false, true, 'blind'),
  (7554, 9, 13, null, 'Annäherungsverbote bei häuslicher Gewalt wirksam kontrollieren, auch mit elektronischer Fußfessel.', '{904}', 7495, 2, 3, null, 'In Spanien wurde seit 2009 keine Frau getötet, deren Täter überwacht wurde. Die Maßnahme setzt bei Hochrisikofällen an. Sie erreicht aber nur wenige Fälle und setzt voraus, dass die Gewalt bereits angezeigt wurde.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=118', 'https://www.france24.com/en/20200926-domestic-violence-electronic-bracelets-are-a-first-step-but-we-have-to-go-further', 'belegt', '2026-10-02', false, true, 'blind'),
  (7555, 9, 13, null, 'Istanbul-Konvention umsetzen mit mehr Prävention, Ausbau der Täterarbeit und konsequenter Strafverfolgung.', '{904}', 7496, 2, 2, null, 'Eine Meta-Analyse findet bis zu zwei Jahre nach Täterprogrammen deutlich weniger Rückfälle, danach keinen gesicherten Effekt mehr. Die Angebote liegen überwiegend bei den Ländern, der Bund kann fördern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=118', 'https://pure.qub.ac.uk/en/publications/the-effectiveness-of-interventions-to-prevent-recidivism-in-perpe/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7556, 9, 13, null, 'Sexualstrafrecht mit der Zustimmungslösung reformieren.', '{908}', 7493, 1, 3, null, 'In Schweden stiegen die Verurteilungen nach der Reform deutlich. Deutschland erfasst seit 2016 aber schon Taten gegen den erkennbaren Willen, daher ist der Zusatznutzen kleiner. An der geringen Anzeigebereitschaft ändert die Reform wenig.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=119', 'https://www.thelocal.se/20200616/how-swedens-new-consent-law-led-to-a-75-rise-in-rape-convictions/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7557, 9, 13, null, 'Einsatz von K.-o.-Tropfen bei sexuellen Übergriffen als strafverschärfenden Umstand ins Strafgesetzbuch aufnehmen.', '{908}', 7491, 1, 3, null, 'Höhere Strafen sind rechtlich leicht umsetzbar und benennen das Unrecht klarer. Die Forschung zeigt aber übereinstimmend: Abschreckend wirkt vor allem das Risiko, erwischt zu werden, kaum die Höhe der Strafe.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=119', 'https://prohic.nl/wp-content/uploads/2020/11/2020-06-02-DeterrenceMetaNagin.2013.pdf', 'belegt', '2026-10-02', false, true, 'blind'),
  (7558, 9, 13, null, 'Flächendeckend medizinische Notfallversorgung mit anonymer Spurensicherung für Vergewaltigungsopfer.', '{908}', null, 2, 3, null, 'Mit anonymer Spurensicherung können Betroffene Beweise sichern, bevor sie über eine Anzeige entscheiden. Das kann die Anzeigebereitschaft erhöhen. Krankenkassen zahlen schon, flächendeckend fehlt das Angebot. Studien zur Wirkung gibt es kaum.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=118', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7559, 9, 13, null, 'Ausreisepflichtige Straftäter nach Verbüßung der Strafe vorrangig zurückführen.', '{905}', 7497, 1, 2, null, 'Die Maßnahme verhindert weitere Taten der Abgeschobenen im Inland. Sie betrifft aber nur einen kleinen Teil der Tatverdächtigen und lässt die Ursachen laut Forschung unberührt. Ob sie gelingt, hängt von der Mitarbeit der Herkunftsstaaten ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=130', 'https://www.swp-berlin.org/10.18449/2021S12/', 'offen', '2026-10-02', false, true, 'blind'),
  (7560, 9, 13, null, 'BKA und Verfassungsschutz mit Personal, Technik und Befugnissen gegen Terrorismus ausstatten.', '{907}', 7498, 2, 2, null, 'Eine frühe Aufklärung von Netzwerken und Gefährdern kann schwere Anschläge verhindern. Unabhängige Wirkungsstudien fehlen, und neue Befugnisse stoßen auf verfassungsrechtliche Grenzen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=137', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7561, 9, 13, null, 'Top-Gefährder länderübergreifend lückenlos überwachen und strafrechtlich verfolgen.', '{907}', 7498, 2, 2, null, 'Eine frühe Aufklärung von Netzwerken und Gefährdern kann schwere Anschläge verhindern. Unabhängige Wirkungsstudien fehlen, und neue Befugnisse stoßen auf verfassungsrechtliche Grenzen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=137', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7562, 9, 13, null, 'Extremistische Netzwerke früh erkennen, Vereinsverbote konsequent aussprechen.', '{907}', 7500, 1, 3, null, 'Verbote zerschlagen Strukturen, Vermögen und Treffpunkte, und das Innenministerium kann sie selbst aussprechen. Mitglieder organisieren sich aber oft neu. Zur Wirkung auf Straftaten gibt es kaum Studien.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=137', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7563, 9, 13, null, 'Verfassungsfeinde konsequent entwaffnen, besonders in der rechtsextremen Szene.', '{907}', 7501, 2, 3, null, 'Ohne legale Waffen sind schwere Gewalttaten von Extremisten schwerer möglich, und das Waffenrecht erlaubt den Entzug bereits. Illegal beschaffte Waffen erfasst die Maßnahme nicht, und Wirkungsstudien fehlen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=137', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7564, 9, 13, null, 'Ausstiegs- und Deradikalisierungsangebote finanziell stärken und per Demokratiefördergesetz absichern.', '{907}', 7502, 2, 2, null, 'Eine Auswertung eines Aussteigerprogramms fand bei 94 % der Betreuten keine neuen Straftaten, allerdings ohne Vergleichsgruppe. Belastbare Wirkungsstudien sind selten. Ob der Bund für ein Fördergesetz zuständig ist, ist umstritten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=137', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/546159/ein-weg-aus-dem-rechtsextremismus/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7565, 9, 13, null, 'Strafverfolgung bei Hasskriminalität im Netz stärken, auch mit Login-Falle und Accountsperren.', '{907,902}', 7487, 1, 3, null, 'Die Login-Falle kann anonyme Konten gezielt identifizieren und ist rechtlich wenig umstritten. Sie wirkt aber nur bei Konten, die erneut genutzt werden, und erfasst Betrug aus dem Ausland kaum. Zur Wirkung gibt es kaum Daten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=140', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7566, 9, 13, null, 'Periodischen Sicherheitsbericht gesetzlich verankern.', '{909}', 7505, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder können verzerrte Wahrnehmungen korrigieren und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung tatsächlich ändern, ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=133', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7567, 9, 13, null, 'Polizeistatistik reformieren, um Hasskriminalität besser zu erfassen.', '{909}', 7505, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder können verzerrte Wahrnehmungen korrigieren und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung tatsächlich ändern, ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=133', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7568, 9, 13, null, 'Psychiatrisch-psychosoziale Krisendienste bedarfsgerecht ausbauen und psychiatrische Versorgung stärken.', '{911}', null, 2, 2, null, 'Bei Psychosen und Sucht senkt Behandlung das Gewaltrisiko deutlich, Krisendienste erreichen Unbehandelte früh. Die meisten Gewalttaten gehen aber nicht auf Erkrankungen zurück. Der Ausbau liegt großteils bei Ländern und Kommunen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=95', 'https://www.aerztezeitung.de/Medizin/Ein-Risikofaktor-fuer-Gewalttaten-303442.html', 'belegt', '2026-10-02', false, true, 'blind'),
  (7569, 9, 13, null, 'Waffenrecht verschärfen, Verfügbarkeit tödlicher Schusswaffen einschränken, Schreckschusswaffen nur mit kleinem Waffenschein.', '{901}', null, 1, 3, null, 'Weniger frei verfügbare gefährliche Waffen können Taten im öffentlichen Raum erschweren, und der Bund kann das Waffenrecht ändern. Schusswaffentaten mit legalen Waffen sind in Deutschland aber selten; die Wirkung ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=134', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7570, 9, 13, null, 'Angebote für Prävention, Therapie und Gesundheitsschutz bei Suchtmitteln ausbauen.', '{911}', null, 1, 2, null, 'Suchterkrankungen erhöhen das Gewaltrisiko, mehr Prävention und Therapie setzen dort an. Die Zusage ist allgemein und nennt keinen Bezug zu Gewalt. Die Angebote liegen überwiegend bei Ländern, Kommunen und Krankenkassen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=96', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7571, 9, 13, null, 'Einziehung von Vermögen aus kriminellen Machenschaften erleichtern und Vermögensabschöpfung stärker nutzbar machen.', '{902}', 7489, 1, 2, null, 'Eine leichtere Einziehung von Vermögen trifft kriminelle Strukturen finanziell. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum. Eine volle Beweislastumkehr steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=135', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7572, 9, 14, null, 'Keine flächendeckende Überwachung im öffentlichen Raum und keine automatisierte Gesichtserkennung dort.', '{901}', 7507, 0, 3, null, 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Videoüberwachung senkt laut Meta-Analyse vor allem Eigentums- und Fahrzeugdelikte, kaum Gewalt; der Verzicht kostet daher wenig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=24', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7573, 9, 14, null, 'Gerichte und Verfahrensrecht weiter digitalisieren, etwa mit Online-Gerichtsverfahren.', '{902}', 7483, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und IT-Projekte der Justiz brauchen viele Jahre und die Mitarbeit der Länder.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=23', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7574, 9, 14, null, 'Strafgesetzbuch überprüfen, überholte Straftatbestände streichen oder anpassen; Schwarzfahren nur noch als Ordnungswidrigkeit.', '{902}', 7490, 1, 3, null, 'Allein Fahren ohne Fahrschein macht rund 6 % der Verurteilungen und über die Hälfte der Ersatzfreiheitsstrafen aus. Eine Streichung entlastet Justiz und Haft spürbar. Die Aufklärung schwerer Taten verbessert sie nur indirekt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=23', null, 'belegt', '2026-10-02', false, true, 'blind'),
  (7575, 9, 14, null, 'Europol zu einem Europäischen Kriminalamt ausbauen, gegen Terrorismus, organisierte und Cyberkriminalität.', '{902,906,907}', 7488, 1, 1, null, 'Viele Online- und organisierte Taten kommen aus dem Ausland, deshalb setzt eine bessere Zusammenarbeit an einer Ursache an. Operative Befugnisse für Europol erfordern aber eine Änderung der EU-Verträge mit allen Mitgliedstaaten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=22', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7576, 9, 14, null, 'Clans und organisierte Kriminalität bekämpfen: Geldwäsche unterbinden, Vermögen aus Straftaten einziehen.', '{902}', 7489, 1, 2, null, 'Eine leichtere Einziehung von Vermögen trifft kriminelle Strukturen finanziell. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum. Eine volle Beweislastumkehr steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=23', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7577, 9, 14, null, 'Quick-Freeze statt Vorratsdatenspeicherung: Daten im Verdachtsfall auf richterliche Anordnung sichern.', '{906}', 7486, 1, 3, null, 'Quick Freeze ist grundrechtsschonend und schnell umsetzbar. Es greift aber nur bei Daten, die zum Zeitpunkt der Anordnung noch vorhanden sind. Bei IP-Adressen ist das oft nicht mehr der Fall, daher ist der Nutzen bei Onlinebetrug begrenzt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=24', 'https://heise.de/newsticker/meldung/Studie-Vorratsdatenspeicherung-verbessert-die-Aufklaerungsquote-nicht-1423035.html', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7578, 9, 14, null, 'Nachrichtendienste erhalten klarere Rechtsgrundlagen; zersplitterte Kontrolle neu ordnen, Lücken schließen.', '{907}', 7498, 2, 2, null, 'Eine frühe Aufklärung von Netzwerken und Gefährdern kann schwere Anschläge verhindern. Unabhängige Wirkungsstudien fehlen, und neue Befugnisse stoßen auf verfassungsrechtliche Grenzen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=22', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7579, 9, 14, null, 'Mehr Betätigungs- und Organisationsverbote für antisemitische Organisationen.', '{907}', 7500, 1, 3, null, 'Verbote zerschlagen Strukturen, Vermögen und Treffpunkte, und das Innenministerium kann sie selbst aussprechen. Mitglieder organisieren sich aber oft neu. Zur Wirkung auf Straftaten gibt es kaum Studien.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=51', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7580, 9, 14, null, 'Sicherheitsbehörden sollen gefährdete Gruppen und ihre Einrichtungen besser schützen.', '{907}', null, 1, 2, null, 'Der Schutz gefährdeter Einrichtungen kann Anschläge verhindern. Die Zusage nennt aber kein konkretes Instrument, und der Objektschutz liegt meist bei der Landespolizei.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=26', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7581, 9, 14, null, 'Gegen Radikalisierung durch islamistische Influencer im Internet neben Strafrecht auch ausländerrechtliche Maßnahmen einsetzen.', '{907}', null, 1, 2, null, 'Strafrecht und Ausweisung können einzelne radikalisierende Akteure stoppen. Viele Influencer wirken aber aus dem Ausland oder sind Deutsche, und die Wirkung ist unbelegt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=26', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7582, 9, 14, null, 'Frauenhausplätze bedarfsgerecht ausfinanzieren und freie Plätze über eine bundesweite Online-Plattform in Echtzeit anzeigen.', '{904}', 7494, 2, 2, null, 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=29', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'belegt', '2026-10-02', false, true, 'blind'),
  (7583, 9, 15, null, 'Ausweisung ausländischer Straftäter, besonders bei Gewalt-, Drogen- und Sexualdelikten sowie organisierter und Clankriminalität, deutlich erleichtern.', '{905}', 7497, 1, 2, null, 'Die Maßnahme verhindert weitere Taten der Abgeschobenen im Inland. Sie betrifft aber nur einen kleinen Teil der Tatverdächtigen und lässt die Ursachen laut Forschung unberührt. Ob sie gelingt, hängt von der Mitarbeit der Herkunftsstaaten ab.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=102', 'https://www.swp-berlin.org/10.18449/2021S12/', 'offen', '2026-10-02', false, true, 'blind'),
  (7584, 9, 15, null, 'Ausländische Gefährder, Extremisten und schwere Straftäter vorrangig zurückführen.', '{905,907}', 7497, 1, 2, null, 'Die Maßnahme verhindert weitere Taten der Abgeschobenen im Inland. Sie betrifft aber nur einen kleinen Teil der Tatverdächtigen und lässt die Ursachen laut Forschung unberührt. Ob sie gelingt, hängt von der Mitarbeit der Herkunftsstaaten ab.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=102', 'https://www.swp-berlin.org/10.18449/2021S12/', 'offen', '2026-10-02', false, true, 'blind'),
  (7585, 9, 15, null, 'Grenzen wieder selbst kontrollieren, Bundespolizei als Grenzbehörde einsetzen und Einreisende an der Grenze zurückweisen; auch zur Bekämpfung grenzüberschreitender Kriminalität.', '{905}', null, 1, 1, null, 'Grenzkontrollen können einzelne grenzüberschreitende Taten aufdecken. Auf die Ursachen der Überrepräsentation wirken sie kaum. Dauerhafte Kontrollen und Zurückweisungen sind nach Schengen- und EU-Asylrecht nur eng zulässig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=104', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7586, 9, 15, null, 'Ermittlungsbehörden erheblich bei Personal und Ausstattung aufstocken.', '{902}', 7482, 2, 2, null, 'Mehr und besser ausgestattete Ermittler können mehr Taten aufklären, und Studien aus den USA finden weniger Kriminalität bei mehr Polizei. Der Bund steuert aber nur BKA und Bundespolizei. Ohne konkreten Umfang ist die Wirkung unbestimmt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=118', null, 'gemischt', '2026-10-02', false, true, 'blind'),
  (7587, 9, 15, null, 'Justizpersonal aufstocken und Rechtssystem stärken.', '{902}', 7481, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten nach der Personalbedarfsberechnung als ein Hauptgrund für rund eine Million offene Verfahren. Mehr Personal setzt dort an. Der Bund kann über einen Pakt aber nur mitfinanzieren, und Nachwuchs ist knapp.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=120', 'https://www.drb.de/newsroom/presse-mediencenter/nachrichten-auf-einen-blick/nachricht/news/staatsanwaltschaften-am-limit-1', 'belegt', '2026-10-02', false, true, 'blind'),
  (7588, 9, 15, null, 'Strafverfolgungsbefugnisse und Fahndungsmöglichkeiten der Polizei an die Kriminalitätsentwicklung anpassen.', '{902}', 7484, 1, 2, null, 'Automatisierte Analysen und Online-Befugnisse können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=119', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7589, 9, 15, null, 'Strafaussetzung zur Bewährung bei Haftstrafen nur nach Mindestverbüßung.', '{902}', null, 1, 2, null, 'Eine Mindesthaft macht Strafen spürbarer. Mehr Strafaussetzung hat aber nach deutschen Daten den Rückfall nicht erhöht, und Haft wirkt nicht besser. Volle Gefängnisse der Länder sind eine Hürde.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=120', 'https://www.uni-konstanz.de/rtf/kis/heinz-sanktionen-jugendstrafrecht-12-thesen.htm', 'belegt', '2026-10-02', false, true, 'blind'),
  (7590, 9, 15, null, 'Durch Straftaten erworbenes Vermögen konsequent einziehen, mit Nachweispflicht zur Herkunft bei Straftätern und Familienmitgliedern.', '{902}', 7489, 1, 2, null, 'Eine leichtere Einziehung von Vermögen trifft kriminelle Strukturen finanziell. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum. Eine volle Beweislastumkehr steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=118', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7591, 9, 15, null, 'In sogenannten No-go-Areas Mittel bereitstellen und Razzien und Kontrollstellen durchführen, um den Rechtsstaat durchzusetzen.', '{901}', 7506, 2, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung in andere Gebiete. Die meisten Orte liegen aber in der Zuständigkeit der Landespolizei, und Personal fehlt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=123', 'https://nij.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-02', false, true, 'blind'),
  (7592, 9, 15, null, 'Flächendeckende Videoüberwachung ablehnen.', '{901}', 7507, 0, 3, null, 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Videoüberwachung senkt laut Meta-Analyse vor allem Eigentums- und Fahrzeugdelikte, kaum Gewalt; der Verzicht kostet daher wenig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=125', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7593, 9, 15, null, 'Waffenrecht neu fassen; statt Legalwaffenbesitzer zu belasten, illegalen Waffenbesitz und -handel bekämpfen.', '{901}', null, 1, 2, null, 'Viele Waffentaten werden mit illegalen Waffen begangen, daher setzt die Maßnahme an. Sie nennt aber kein konkretes Instrument, und illegale Märkte sind schwer zu kontrollieren.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=121', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7594, 9, 15, null, 'Strafmündigkeit auf 12 Jahre senken, Jugendstrafrecht nur bis 18, zeitnahe Haft für Mehrfach- und Intensivtäter.', '{903}', 7492, 1, 2, null, 'Dafür spricht, dass Intensivtäter früher gestoppt werden können. Rückfallstudien zeigen aber keinen Vorteil härterer Sanktionen bei jungen Menschen, eher höhere Rückfallraten. Für Kinder fehlen zudem geeignete Einrichtungen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=119', 'https://www.uni-konstanz.de/rtf/kis/heinz-sanktionen-jugendstrafrecht-12-thesen.htm', 'belegt', '2026-10-02', false, true, 'blind'),
  (7595, 9, 15, null, 'Organisationen des gewaltsamen Linksextremismus verbieten und ihre Symbole unter Strafe stellen.', '{907}', 7500, 1, 3, null, 'Verbote zerschlagen Strukturen, Vermögen und Treffpunkte, und das Innenministerium kann sie selbst aussprechen. Mitglieder organisieren sich aber oft neu. Zur Wirkung auf Straftaten gibt es kaum Studien.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=121', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7596, 9, 15, null, 'Vereine und Verbände, die Extremisten unterstützen, von staatlichen Mittelzuwendungen ausschließen.', '{907}', 7504, 1, 2, null, 'Die Maßnahme verhindert, dass extremistische Strukturen staatlich mitfinanziert werden. Auf Straftaten wirkt sie nur indirekt. Ein Ausschluss allein wegen einer Beobachtung oder wegen einzelner Mitglieder ist rechtlich angreifbar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=122', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7597, 9, 15, null, 'Öffentliche Forderung nach einem Kalifat unter Strafe stellen; ausländische Teilnehmer abschieben.', '{907}', 7503, 1, 2, null, 'Neue Straftatbestände können Werbung für Terror oder verfassungsfeindliche Ziele früher ahnden. Sie überschneiden sich teils mit geltendem Recht und müssen vor der Meinungsfreiheit bestehen. Zur Wirkung auf Gewalttaten gibt es keine Belege.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=122', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7598, 9, 15, null, 'Verfassungsschutz grundsätzlich reformieren; Terrorabwehr und Spionageabwehr bei Bundesnachrichtendienst und Polizei.', '{907}', 7499, 1, 2, null, 'Bekannte Fehler wie im V-Leute-System sprechen für eine Reform. Ein Umbau kann aber zunächst die Früherkennung schwächen. Belege, dass eine andere Organisationsform extremistische Taten besser verhindert, fehlen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=139', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7599, 9, 15, null, 'Angriffe auf Juden und antisemitische Beleidigungen konsequent strafrechtlich ahnden.', '{907}', null, 1, 2, null, 'Eine konsequente Verfolgung antisemitischer Taten kann Täter abschrecken und Betroffene ermutigen, Taten anzuzeigen. Die Zusage nennt aber kein Instrument wie Schwerpunktstaatsanwaltschaften, und die Strafverfolgung liegt bei den Ländern.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=124', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7600, 9, 16, null, 'Sicherheitskonzepte im öffentlichen Raum sollen nicht pauschal kontrollieren und anlasslos flächendeckend überwachen; Soziale Prävention statt Überwachung.', '{901}', 7507, 0, 3, null, 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Videoüberwachung senkt laut Meta-Analyse vor allem Eigentums- und Fahrzeugdelikte, kaum Gewalt; der Verzicht kostet daher wenig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=48', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7601, 9, 16, null, 'Obdachlose und Suchtabhängige nicht aus Innenstädten verdrängen, sondern bessere Hilfsangebote und mehr Sozialarbeit.', '{901}', null, 1, 2, null, 'Sozialarbeit und Hilfen vor Ort können Konflikte an Brennpunkten in Innenstädten entschärfen. Für das Sicherheitsgefühl ist die Wirkung kaum untersucht. Zuständig sind vor allem Kommunen, der Bund kann nur fördern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=48', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7602, 9, 16, null, 'Kriminalpolizei und Staatsanwaltschaft sollen in die Lage versetzt werden, mit neuen Kriminalitätsformen Schritt zu halten, auch bei Cyber-Attacken.', '{902,906}', 7482, 2, 2, null, 'Mehr und besser ausgestattete Ermittler können mehr Taten aufklären, und Studien aus den USA finden weniger Kriminalität bei mehr Polizei. Der Bund steuert aber nur BKA und Bundespolizei. Ohne konkreten Umfang ist die Wirkung unbestimmt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=48', null, 'gemischt', '2026-10-02', false, true, 'blind'),
  (7603, 9, 16, null, 'Ermittlungsbefugnisse nicht ausweiten: gegen Vorratsdatenspeicherung, Onlinedurchsuchungen, Rasterfahndung und allgegenwärtige Videoüberwachung.', '{902,901,906}', 7485, 0, 3, null, 'Das Ablehnen von Befugnissen schützt Grundrechte, bringt die Aufklärung aber nicht voran. Laut einer Studie des Max-Planck-Instituts brachte die Vorratsdatenspeicherung keine messbar höhere Aufklärung, der Verlust wäre also gering.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', 'https://heise.de/newsticker/meldung/Studie-Vorratsdatenspeicherung-verbessert-die-Aufklaerungsquote-nicht-1423035.html', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7604, 9, 16, null, 'Drogenkonsum vollständig entkriminalisieren und medizinische sowie sozialarbeiterische Interventionsprogramme schaffen.', '{902,911}', null, 1, 2, null, 'Weniger Konsumverfahren entlasten Polizei und Justiz, und Hilfsprogramme erreichen Abhängige. Auf die Aufklärung schwerer Taten wirkt das nur indirekt. Die Wirkung einer vollständigen Entkriminalisierung ist umstritten, internationale Abkommen setzen Grenzen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'gemischt', '2026-10-02', false, true, 'blind'),
  (7605, 9, 16, null, 'Verfassungsschutz durch unabhängige Beobachtungsstelle ersetzen; V-Leute-System aufdecken und beenden.', '{907}', 7499, 1, 2, null, 'Bekannte Fehler wie im V-Leute-System sprechen für eine Reform. Ein Umbau kann aber zunächst die Früherkennung schwächen. Belege, dass eine andere Organisationsform extremistische Taten besser verhindert, fehlen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7606, 9, 16, null, 'Demokratiefördergesetz mit dauerhafter Finanzierung für Beratung gegen Rechtsextremismus, Opferberatung und Demokratiebündnisse.', '{907}', 7502, 2, 2, null, 'Eine Auswertung eines Aussteigerprogramms fand bei 94 % der Betreuten keine neuen Straftaten, allerdings ohne Vergleichsgruppe. Belastbare Wirkungsstudien sind selten. Ob der Bund für ein Fördergesetz zuständig ist, ist umstritten.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=51', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/546159/ein-weg-aus-dem-rechtsextremismus/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7607, 9, 16, null, 'Verbot militanter, bewaffneter, neonazistischer Organisationen.', '{907}', 7500, 1, 3, null, 'Verbote zerschlagen Strukturen, Vermögen und Treffpunkte, und das Innenministerium kann sie selbst aussprechen. Mitglieder organisieren sich aber oft neu. Zur Wirkung auf Straftaten gibt es kaum Studien.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=51', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7608, 9, 16, null, 'Ausfinanzierter Aktionsplan gegen queerfeindliche Gewalt und Diskriminierung.', '{907}', null, 1, 2, null, 'Ein Aktionsplan kann Prävention und Erfassung queerfeindlicher Hasskriminalität bündeln. Er nennt aber kein konkretes Instrument gegen Straftaten, und die Wirkung solcher Pläne ist kaum untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7609, 9, 16, null, 'Istanbul-Konvention vollständig umsetzen; Frauenhäuser verlässlich finanzieren; Schutz und Beratung kostenfrei und überall verfügbar.', '{904}', 7494, 2, 2, null, 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'belegt', '2026-10-02', false, true, 'blind'),
  (7610, 9, 16, null, 'Gewaltschutz im Sorge- und Umgangsrecht verankern.', '{904}', null, 2, 3, null, 'Trennung und Umgangskontakte sind Hochrisikophasen; wenn Gewaltschutz im Sorgerecht Vorrang hat, sinken die Gelegenheiten für Taten. Der Bund kann das selbst regeln. Wirkungsstudien fehlen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7611, 9, 16, null, 'Prinzip „Nur Ja heißt Ja“ gesetzlich verankern und gezielt gegen Netzwerke sexualisierter Gewalt vorgehen.', '{908}', 7493, 1, 3, null, 'In Schweden stiegen die Verurteilungen nach der Reform deutlich. Deutschland erfasst seit 2016 aber schon Taten gegen den erkennbaren Willen, daher ist der Zusatznutzen kleiner. An der geringen Anzeigebereitschaft ändert die Reform wenig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', 'https://www.thelocal.se/20200616/how-swedens-new-consent-law-led-to-a-75-rise-in-rape-convictions/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7612, 9, 16, null, 'Awareness-Konzepte gegen sexualisierte Gewalt als Pflichtbestandteil von Sicherheitskonzepten bei Großveranstaltungen.', '{908}', null, 1, 2, null, 'Awareness-Konzepte bieten Betroffenen bei Großveranstaltungen schnelle Hilfe und können Übergriffe verhindern. Sie erreichen nur einen kleinen Teil der Taten, und die Auflagen für Veranstaltungen regeln vor allem Länder und Kommunen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=49', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7613, 9, 16, null, 'Straftäter ohne Abschiebung: reguläres Strafverfahren und Haftverbüßung im Inland unabhängig vom Aufenthaltsstatus.', '{905}', null, 0, 3, null, 'Die Maßnahme entspricht im Wesentlichen der geltenden Rechtslage und schützt rechtsstaatliche Gleichbehandlung. An den Ursachen der Überrepräsentation setzt sie aber nicht an.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7614, 9, 16, null, 'Haftung für Onlinemarktplätze und Onlineplattformen.', '{906}', null, 1, 1, null, 'Eine Haftung von Plattformen würde Anreize gegen Fake-Shops und Betrug setzen. Die Haftungsregeln legt aber der europäische Digital Services Act abschließend fest, Deutschland kann sie nicht allein ändern.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=56', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7615, 9, 17, null, 'Polizei so besetzen, dass sie sichtbar auf Straßen und öffentlichen Plätzen präsent ist; dafür ausreichend Personal.', '{901}', 7506, 2, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung in andere Gebiete. Die meisten Orte liegen aber in der Zuständigkeit der Landespolizei, und Personal fehlt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', 'https://nij.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-02', false, true, 'blind'),
  (7616, 9, 17, null, 'Polizei solide mit modernen Einsatzmitteln und IT ausstatten, auch gegen Cyberkriminalität und Terrorismus; Aus- und Fortbildung.', '{902,906,907}', 7482, 2, 2, null, 'Mehr und besser ausgestattete Ermittler können mehr Taten aufklären, und Studien aus den USA finden weniger Kriminalität bei mehr Polizei. Der Bund steuert aber nur BKA und Bundespolizei. Ohne konkreten Umfang ist die Wirkung unbestimmt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', null, 'gemischt', '2026-10-02', false, true, 'blind'),
  (7617, 9, 17, null, 'Deutlich mehr Personal in den Justizbehörden und weniger Verfahren durch Reformen, besonders im Strafrecht.', '{902}', 7481, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten nach der Personalbedarfsberechnung als ein Hauptgrund für rund eine Million offene Verfahren. Mehr Personal setzt dort an. Der Bund kann über einen Pakt aber nur mitfinanzieren, und Nachwuchs ist knapp.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', 'https://www.drb.de/newsroom/presse-mediencenter/nachrichten-auf-einen-blick/nachricht/news/staatsanwaltschaften-am-limit-1', 'belegt', '2026-10-02', false, true, 'blind'),
  (7618, 9, 17, null, 'Beleidigung von Politikern aus dem Strafgesetzbuch streichen, um Polizei und Ermittlungsbehörden zu entlasten.', '{902}', 7490, 1, 3, null, 'Allein Fahren ohne Fahrschein macht rund 6 % der Verurteilungen und über die Hälfte der Ersatzfreiheitsstrafen aus. Eine Streichung entlastet Justiz und Haft spürbar. Die Aufklärung schwerer Taten verbessert sie nur indirekt.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', null, 'belegt', '2026-10-02', false, true, 'blind'),
  (7619, 9, 17, null, 'Sammeln und Speichern individueller Verhaltensdaten verbieten und Vorratsdatenspeicherung stoppen.', '{902,906}', 7485, 0, 3, null, 'Das Ablehnen von Befugnissen schützt Grundrechte, bringt die Aufklärung aber nicht voran. Laut einer Studie des Max-Planck-Instituts brachte die Vorratsdatenspeicherung keine messbar höhere Aufklärung, der Verlust wäre also gering.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=43', 'https://heise.de/newsticker/meldung/Studie-Vorratsdatenspeicherung-verbessert-die-Aufklaerungsquote-nicht-1423035.html', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7620, 9, 17, null, 'Gewaltschutz- und Hilfesysteme ausbauen, mehr Frauenhausplätze und Schutzwohnungen, langfristige Finanzierung durch den Bund, kostenfreie Nutzung.', '{904}', 7494, 2, 2, null, 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=33', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'belegt', '2026-10-02', false, true, 'blind'),
  (7621, 9, 17, null, 'Angebote der Täterarbeit und Anti-Aggressionstrainings ausbauen.', '{904}', 7496, 2, 2, null, 'Eine Meta-Analyse findet bis zu zwei Jahre nach Täterprogrammen deutlich weniger Rückfälle, danach keinen gesicherten Effekt mehr. Die Angebote liegen überwiegend bei den Ländern, der Bund kann fördern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=34', 'https://pure.qub.ac.uk/en/publications/the-effectiveness-of-interventions-to-prevent-recidivism-in-perpe/', 'gemischt', '2026-10-02', false, true, 'blind'),
  (7622, 9, 17, null, 'Information und Sensibilisierung zum Gewaltschutz fester Bestandteil im Bildungscurriculum an Schulen und Hochschulen.', '{904,903}', null, 1, 1, null, 'Gewaltschutz im Unterricht kann junge Menschen früh für Grenzen und Hilfsangebote sensibilisieren. Die Wirkung schulischer Programme ist uneinheitlich belegt, und für Lehrpläne sind allein die Länder zuständig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=33', null, 'gemischt', '2026-10-02', false, true, 'blind'),
  (7623, 9, 17, null, 'Zuwanderer, die schwere Straftaten begehen, ausweisen und notfalls abschieben; Verfahren dazu vorrangig und zügig führen.', '{905}', 7497, 1, 2, null, 'Die Maßnahme verhindert weitere Taten der Abgeschobenen im Inland. Sie betrifft aber nur einen kleinen Teil der Tatverdächtigen und lässt die Ursachen laut Forschung unberührt. Ob sie gelingt, hängt von der Mitarbeit der Herkunftsstaaten ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', 'https://www.swp-berlin.org/10.18449/2021S12/', 'offen', '2026-10-02', false, true, 'blind'),
  (7624, 9, 17, null, 'Beobachtungsbereich „Delegitimierung des Staates“ beim Verfassungsschutz abschaffen.', '{907}', null, 0, 3, null, 'Die Abschaffung eines Beobachtungsbereichs ist leicht umsetzbar und kann Eingriffe in politische Meinungsäußerung verringern. Weniger politisch motivierte Straftaten sind davon aber nicht zu erwarten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7625, 9, 17, null, 'Finanzierung von Projekten und Organisationen, die den öffentlichen Diskurs beeinflussen sollen, beenden; Demokratiefördergesetz ablehnen.', '{907}', null, 0, 3, null, 'Das Ende der Förderung spart Geld und beendet den Vorwurf politischer Einflussnahme. Es streicht aber auch Prävention und Ausstiegsarbeit gegen Extremismus. Weniger Straftaten sind dadurch nicht zu erwarten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=39', null, 'offen', '2026-10-02', false, true, 'blind'),
  (7662, 9, 11, 'BE', 'Videoüberwachung an allen kriminalitätsbelasteten Orten ausbauen, auch mit intelligenten Systemen', '{901}', 7630, 1, 3, null, 'Videoüberwachung senkt Kriminalität laut Meta-Analyse moderat, vor allem Eigentumsdelikte auf Parkplätzen, kaum Gewalt. Aktiv beobachtete Kameras wirken stärker. Das Polizeirecht des Landes erlaubt den Ausbau an belasteten Orten.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=10', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'belegt', '2026-10-03', false, true, 'blind'),
  (7663, 9, 11, 'BE', 'Neue Polizeiwache am Leopoldplatz mit sichtbarer Präsenz, um Drogenkriminalität entgegenzutreten', '{901}', 7626, 3, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=8', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-03', false, true, 'blind'),
  (7664, 9, 11, 'BE', 'Verdachtsunabhängige Personenkontrollen ermöglichen; Räume kurzfristig zu kriminalitätsbelasteten Orten erklären', '{901}', 7632, 1, 3, null, 'Die Evaluation der Leipziger Waffenverbotszone fand weniger bewaffnete Angriffe, aber kaum Wirkung auf andere Taten. Anlasslose Kontrollen können Vertrauen kosten. Das Land kann sie im Polizeigesetz regeln.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=8', 'https://medienservice.sachsen.de/medien/news/252888', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7665, 9, 11, 'BE', 'Angsträume abbauen durch bessere Beleuchtung, übersichtliche Wegeführung und gepflegte Unterführungen', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=10', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7666, 9, 11, 'BE', 'Mehr sichtbares Sicherheitspersonal, mehr Videoüberwachung und Notrufsäulen im Nahverkehr', '{901}', 7628, 3, 2, null, 'Ein Zufallsexperiment an 41 Bahnhöfen fand bei Streifen durch Sicherheitspersonal 16 % weniger Taten, bei Gewalt 31 % weniger. Das Personal kostet dauerhaft und muss mit den Verkehrsunternehmen vereinbart werden.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=72', 'https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0187392', 'belegt', '2026-10-03', false, true, 'blind'),
  (7667, 9, 11, 'BE', 'Strafrechtliche Ahndung des unerlaubten Umgangs mit halbautomatischen Kurzwaffen durch eigenen Verbrechenstatbestand', '{901}', 7651, 1, 1, null, 'Höhere Strafen benennen Unrecht klarer. Die Forschung zeigt aber übereinstimmend, dass vor allem das Entdeckungsrisiko abschreckt, kaum die Strafhöhe. Das Strafrecht ändert der Bund, das Land kann nur werben.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=19', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7668, 9, 11, 'BE', 'Neue Wege bei der Personalgewinnung für die Polizei', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=7', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7669, 9, 11, 'BE', 'Strafverfolgungsbehörden personell und technisch deutlich stärken, am Bedarf ausrichten', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=19', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7670, 9, 11, 'BE', 'Polizei von Bürokratie entlasten, Dokumentationspflichten abbauen, Verfahren digitalisieren', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=7', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7671, 9, 11, 'BE', 'Technische Ermittlungsinstrumente ausbauen: KI-Datenanalyse, Auswertesoftware, Speicherung von IP-Adressen', '{902}', 7661, 1, 2, null, 'Automatisierte Analysen und Auswertesoftware können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=20', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7672, 9, 11, 'BE', 'Vermögensabschöpfung gegen organisierte Kriminalität und Clanstrukturen weiter stärken', '{902}', 7655, 1, 3, null, 'Vermögensabschöpfung trifft kriminelle Strukturen finanziell und ist eine spürbare Tatfolge. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum, Wirkungsstudien fehlen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=19', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7673, 9, 11, 'BE', 'Auf Bundesebene Haftgründe verschärfen, damit Wiederholungstäter schneller in Untersuchungshaft kommen', '{902}', null, 1, 1, null, 'Mehr Untersuchungshaft kann Wiederholungstaten bis zum Urteil verhindern. Die Haftgründe regelt der Bund, Haft verlangt Verhältnismäßigkeit, und Belege zur Wirkung fehlen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=9', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7674, 9, 11, 'BE', 'Strafmündigkeit auf Bundesebene von 14 auf 12 Jahre senken, gerichtliches Verantwortungsverfahren', '{903}', 7641, 1, 1, null, 'Fachverbände sehen keine Belege für eine abschreckende Wirkung, und nach Arrest und Jugendstrafe sind Rückfallquoten hoch. Dafür spricht ein früheres Eingreifen bei Intensivtätern. Das Land kann nur über den Bundesrat werben.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=24', 'https://jugendhilfeportal.de/artikel/stellungnahme-zur-forderung-der-senkung-des-strafmuendigkeitsalters-durch-cdu-generalsekretaer', 'belegt', '2026-10-03', false, true, 'blind'),
  (7675, 9, 11, 'BE', 'Schuldistanz- und Jugenddelinquenz-Teams flächendeckend in allen Jugendämtern ausbauen', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=12', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7676, 9, 11, 'BE', 'Elektronische Fußfessel bei Hochrisiko-Gefährdern ausweiten, um Kontakt- und Näherungsverbote zu überwachen', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=11', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7677, 9, 11, 'BE', 'Zusätzliche Schutzplätze, Beratungs- und Interventionsangebote und ein zehntes Frauenhaus', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=11', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7678, 9, 11, 'BE', 'Verpflichtende Täterarbeit und niedrigschwellige Beratung ausbauen', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=12', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7679, 9, 11, 'BE', 'Regelmäßige Dunkelfeldstudien als Teil der Prävention von Gewalt gegen Frauen', '{909}', 7654, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=12', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7680, 9, 11, 'MV', 'Mehr Polizei in Innenstädten und an Kriminalitätsschwerpunkten, höherer Kontrolldruck, wirksamere Platzverweise und Aufenthaltsverbote', '{901}', 7626, 3, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=31', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-03', false, true, 'blind'),
  (7681, 9, 11, 'MV', 'Angsträume verhindern, unter anderem durch ausgeweitete Videoüberwachung', '{901}', 7630, 1, 3, null, 'Videoüberwachung senkt Kriminalität laut Meta-Analyse moderat, vor allem Eigentumsdelikte auf Parkplätzen, kaum Gewalt. Aktiv beobachtete Kameras wirken stärker. Das Polizeirecht des Landes erlaubt den Ausbau an belasteten Orten.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=6', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'belegt', '2026-10-03', false, true, 'blind'),
  (7682, 9, 11, 'MV', 'Modernes Beleuchtungsmanagement und bauliche Maßnahmen für mehr Sicherheit in Städten', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=32', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7683, 9, 11, 'MV', 'Polizei-Soll-Stärke erreichen, Einstellungszahlen erhöhen', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=27', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7684, 9, 11, 'MV', '50 zusätzliche Stellen bei den Staatsanwaltschaften und angemessene Personalausstattung der Gerichte', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=33', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7685, 9, 11, 'MV', 'Mehrjähriges IT-Investitionsprogramm für die Landespolizei', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=30', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7686, 9, 11, 'MV', 'Digitalisierung der Justiz ausweiten, elektronische Akte in allen Rechtsgebieten', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=34', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7687, 9, 11, 'MV', 'Vorratsdatenspeicherung auf Bundesebene einfordern', '{902}', null, 1, 1, null, 'Laut einer Max-Planck-Studie brachte die Vorratsdatenspeicherung keine messbar höhere Aufklärung; andere sehen Nutzen bei Onlinetaten. Das Land kann nur auf Bundesebene werben, und das EU-Recht setzt enge Grenzen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=35', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7688, 9, 11, 'MV', 'Einziehung von Vermögen aus kriminellen Geschäften per Beweislastumkehr erleichtern', '{902}', 7656, 1, 1, null, 'Eine leichtere Einziehung trifft kriminelle Strukturen finanziell, wirkt aber kaum auf alltägliche Taten. Die Beweislastumkehr regelt der Bund, und sie steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=30', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7689, 9, 11, 'MV', 'Dauerhafte Ermittlungsgruppen gegen Organisierte und Clan-Kriminalität', '{902}', 7657, 1, 3, null, 'Dauerhafte Ermittlungsgruppen bündeln Wissen gegen organisierte Kriminalität. Auf die Aufklärung der vielen alltäglichen Taten wirken sie kaum, und Belege zur Wirkung fehlen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=30', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7690, 9, 11, 'MV', 'Beschleunigte Verfahren im Jugendstrafrecht', '{903}', 7639, 1, 3, null, 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=35', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7691, 9, 11, 'MV', 'Jugendlichen Mehrfach- und Intensivtätern durch bessere Kooperation und schnelleren Datenaustausch begegnen', '{903}', 7640, 2, 3, null, 'Evaluationen zeigen eine bessere Zusammenarbeit von Polizei, Justiz und Jugendhilfe, teils kürzere Verfahren und weniger Rückfälle; Vergleichsgruppen fehlen oft. Länder können solche Häuser selbst einrichten.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=35', 'https://www.iss-ffm.de/themen/armut-und-armutsfolgen/projekte/evaluation-der-haeuser-des-jugendrechts-in-niedersachsen', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7692, 9, 11, 'MV', 'Präventive Kontakt- und Näherungsverbote durch die Polizei ausweiten, Gewaltpräventionsberatung für Gefährder', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=31', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7693, 9, 11, 'MV', 'Vernetzung der Akteure im Gewaltschutz zur Beschleunigung von Verfahren bei häuslicher Gewalt', '{904}', 7645, 2, 3, null, 'Fallkonferenzen und standardisierte Risikoeinschätzung wie in Großbritannien und Spanien sollen Hochrisikofälle früh erkennen; Berichte melden weniger Wiederholungstaten, aber auch Fehleinschätzungen. Das Land kann es selbst einführen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=34', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7694, 9, 11, 'ST', 'Videoschutz im öffentlichen Raum ausweiten, um Straftaten aufzuklären und zu verhindern', '{901}', 7630, 1, 3, null, 'Videoüberwachung senkt Kriminalität laut Meta-Analyse moderat, vor allem Eigentumsdelikte auf Parkplätzen, kaum Gewalt. Aktiv beobachtete Kameras wirken stärker. Das Polizeirecht des Landes erlaubt den Ausbau an belasteten Orten.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=7', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'belegt', '2026-10-03', false, true, 'blind'),
  (7695, 9, 11, 'ST', 'Sichtbarkeit der Landespolizei in den Revieren vor Ort erhöhen', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=6', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7696, 9, 11, 'ST', 'Personalaufwuchs bei der Landespolizei fortsetzen, mit Zielgröße für Vollzug und Verwaltung', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=6', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7697, 9, 11, 'ST', 'KI-gestützten Videoschutz landesweit ermöglichen, um auffällige Verhaltensmuster zu erkennen und Fahndungserfolge zu erzielen', '{902}', 7661, 1, 2, null, 'Automatisierte Analysen und Auswertesoftware können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=7', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7698, 9, 11, 'ST', 'Gesetzliche Grundlage für biogeographische Analyse von DNA-Spuren schaffen', '{902}', null, 1, 1, null, 'Die biogeographische Analyse kann bei unbekannten Tätern Ermittlungshinweise geben. Die Strafprozessordnung regelt der Bund, das Land kann nur werben, und der Nutzen ist kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=7', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7699, 9, 11, 'ST', 'Bedrohungs- und Gefährdungsmanagement einrichten, zentrale Gefahrenanalyse und behördenübergreifendes Datenmanagement', '{902}', 7661, 1, 2, null, 'Automatisierte Analysen und Auswertesoftware können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=7', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7700, 9, 11, 'ST', 'Beschleunigte Verfahren mit Zielzeiten und digitaler Infrastruktur, damit Straftaten unmittelbar geahndet werden', '{902}', 7639, 1, 3, null, 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=58', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7701, 9, 11, 'ST', 'Nachwuchsgewinnung für die Justiz ausbauen und Justizberufe attraktiver machen', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=58', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7702, 9, 11, 'ST', 'Vollständige elektronische Aktenführung in der Justiz einführen', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=58', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7703, 9, 11, 'ST', 'Opferschutz ausbauen und Finanzierung ambulanter Beratungsstellen und Frauenhäuser sichern', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=59', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7704, 9, 11, 'ST', 'Jugendliche in Schülergremien stärken, die im Umfeld beginnender Jugendkriminalität die Rechtsordnung bei Gleichaltrigen vermitteln', '{903}', null, 1, 3, null, 'Gleichaltrige können Regeln glaubwürdig vermitteln. Wie Schülergremien gegen beginnende Jugendkriminalität wirken, ist kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=59', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7705, 9, 12, 'BE', 'Fuß- und Fahrradstreifen der Polizei stadtweit ausweiten', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7706, 9, 12, 'BE', 'U- und S-Bahnhöfe häufiger mit Sicherheitspersonal besetzen', '{901}', 7628, 3, 2, null, 'Ein Zufallsexperiment an 41 Bahnhöfen fand bei Streifen durch Sicherheitspersonal 16 % weniger Taten, bei Gewalt 31 % weniger. Das Personal kostet dauerhaft und muss mit den Verkehrsunternehmen vereinbart werden.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', 'https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0187392', 'belegt', '2026-10-03', false, true, 'blind'),
  (7707, 9, 12, 'BE', 'Sicherheit im öffentlichen Raum: Haltestellen überdachen und beleuchten, mehr BVG-Streifen, besetzte Bahnhöfe, Heimwegtelefon', '{901}', 7628, 3, 2, null, 'Ein Zufallsexperiment an 41 Bahnhöfen fand bei Streifen durch Sicherheitspersonal 16 % weniger Taten, bei Gewalt 31 % weniger. Das Personal kostet dauerhaft und muss mit den Verkehrsunternehmen vereinbart werden.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', 'https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0187392', 'belegt', '2026-10-03', false, true, 'blind'),
  (7708, 9, 12, 'BE', 'Drogenabhängige vor Ort unterstützen statt vertreiben, Drogen aus dem öffentlichen Raum holen, Drogenkonsumräume ausbauen', '{901}', 7634, 2, 3, null, 'Konsumräume und aufsuchende Hilfe verringern laut Evaluationen offenen Drogenkonsum und Szenebelastung; Diebstahl und Raub im Umfeld sinken aber nicht. Das Land kann solche Angebote mit den Kommunen rasch finanzieren.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=51', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7709, 9, 12, 'BE', 'Waffen- und Messerverbotszonen nur als Ausnahme (Einschränkung)', '{901}', 7633, 0, 3, null, 'Die Abschaffung beugt diskriminierenden Kontrollen vor, verzichtet aber auf ein Mittel, das in Leipzig bewaffnete Angriffe etwas senkte. Die Sicherheit an belasteten Orten verbessert sie nicht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7710, 9, 12, 'BE', 'Verdachtsunabhängige Kontrollen räumlich und im Anwendungsbereich auf das Notwendige beschränken', '{901}', 7633, 0, 3, null, 'Die Abschaffung beugt diskriminierenden Kontrollen vor, verzichtet aber auf ein Mittel, das in Leipzig bewaffnete Angriffe etwas senkte. Die Sicherheit an belasteten Orten verbessert sie nicht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7711, 9, 12, 'BE', 'Ausrüstung und Infrastruktur der Polizei modernisieren', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7712, 9, 12, 'BE', 'Verfahrensdauern in der Justiz durch bessere Abläufe, Digitalisierung und zusätzliche Stellen verkürzen', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7713, 9, 12, 'BE', 'Ersatzfreiheitsstrafen schrittweise durch soziale Arbeit ersetzen', '{902}', null, 1, 3, null, 'Gemeinnützige Arbeit statt Ersatzfreiheitsstrafe entlastet Justiz und Vollzug und lässt sich vom Land selbst ausbauen. Die Aufklärung schwerer Taten verbessert das nur indirekt.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7714, 9, 12, 'BE', 'Keine Palantir-Software für die Berliner Polizei (Verzicht auf Massendatenauswertung dieser Art)', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7715, 9, 12, 'BE', 'Kriminell erworbenes Vermögen konsequent abschöpfen', '{902}', 7655, 1, 3, null, 'Vermögensabschöpfung trifft kriminelle Strukturen finanziell und ist eine spürbare Tatfolge. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum, Wirkungsstudien fehlen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7716, 9, 12, 'BE', 'Spezialisierte Ermittlungsstrukturen bei Polizei und Staatsanwaltschaft gegen organisierte Kriminalität stärken', '{902}', 7657, 1, 3, null, 'Dauerhafte Ermittlungsgruppen bündeln Wissen gegen organisierte Kriminalität. Auf die Aufklärung der vielen alltäglichen Taten wirken sie kaum, und Belege zur Wirkung fehlen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7717, 9, 12, 'BE', 'Programme zur gewaltfreien Konfliktlösung und Prävention in den Kiezen fördern, Schwerpunkt häusliche Gewalt sowie Waffen- und Messergewalt', '{904}', null, 1, 2, null, 'Programme zur gewaltfreien Konfliktlösung in Stadtteilen können häuslicher Gewalt vorbeugen. Ihre Wirkung ist kaum untersucht, und der Umfang bleibt offen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=31', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7718, 9, 12, 'BE', 'Systematische Risikoanalysen der Polizei zur Früherkennung von Hochrisikofällen bei Gewalt gegen Frauen', '{904}', 7645, 2, 3, null, 'Fallkonferenzen und standardisierte Risikoeinschätzung wie in Großbritannien und Spanien sollen Hochrisikofälle früh erkennen; Berichte melden weniger Wiederholungstaten, aber auch Fehleinschätzungen. Das Land kann es selbst einführen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7719, 9, 12, 'BE', 'Istanbul-Konvention umsetzen, Frauenhäuser, Schutzwohnungen, Täterarbeit und Gewaltschutzambulanzen stadtweit ausbauen', '{904,908}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7720, 9, 12, 'BE', 'Einrichtungen zum Schutz von Frauen vor Gewalt per Trägerfinanzierung längerfristig sichern', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7721, 9, 12, 'BE', 'Auf Bundesebene Vorrang des Gewaltschutzes vor dem Umgangsrecht gewalttätiger Elternteile durchsetzen', '{904}', 7650, 1, 1, null, 'Gewalt setzt sich nach Trennungen oft bei Umgangskontakten fort; ein Vorrang des Schutzes setzt dort an. Das Familienrecht regelt der Bund, das Land kann nur werben, und zur Wirkung gibt es kaum Daten.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7722, 9, 12, 'BE', 'Spezialisierte Beratungsstellen gegen Gewalt gegen Frauen stärken und Aufklärungsquoten erhöhen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7723, 9, 12, 'BE', 'Kostenübernahme der Vertraulichen Spurensicherung durch Krankenkassen erreichen', '{908}', null, 1, 2, null, 'Die Kostenübernahme erleichtert Spurensicherung ohne Anzeige. Das Sozialrecht sieht sie seit 2020 grundsätzlich vor, offen sind vor allem Verträge vor Ort; der Zusatznutzen ist daher gering.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=32', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7724, 9, 12, 'BE', 'Regelmäßige Dunkelfeldforschung zu den wichtigsten Kriminalitätsphänomenen fördern', '{909}', 7654, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7725, 9, 12, 'MV', 'Sicherheit und Ordnung an Bahnhöfen, Haltestellen und in Bussen und Bahnen mit Kommunen, Verkehrsunternehmen, Polizei und Ordnungsbehörden stärken.', '{901}', null, 1, 3, null, 'Abgestimmtes Vorgehen von Polizei, Kommunen und Verkehrsunternehmen kann Bahnhöfe und Haltestellen sicherer machen. Ohne konkretes Instrument bleibt der Umfang offen.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=46', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7726, 9, 12, 'MV', 'Personalstand der Landespolizei auf Mindestniveau halten und Präsenz der Polizei in der Fläche sichern.', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=46', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7727, 9, 12, 'MV', 'Hohe Ausbildungskapazität der Polizeifachhochschule sichern, um Personalaufwuchs auf knapp 6.200 Polizeibeschäftigte zu erreichen.', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=47', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7728, 9, 12, 'MV', 'Polizeiarbeit durch Fortsetzung der Digitalisierungsstrategie modernisieren und von Mehrfacharbeiten entlasten.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=47', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7729, 9, 12, 'MV', 'Bei polizeilichen Analysesystemen auf Palantir verzichten und eine europäische Alternative einsetzen.', '{902}', 7661, 1, 2, null, 'Automatisierte Analysen und Auswertesoftware können Ermittlungen beschleunigen. Unabhängige Belege für höhere Aufklärungsquoten fehlen, und das Bundesverfassungsgericht hat enge Grenzen gesetzt.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=47', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7730, 9, 12, 'MV', 'Personalausstattung der Justiz mit Richterinnen, Staatsanwältinnen und Rechtspflegern auf hohem Niveau erhalten.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=59', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7731, 9, 12, 'MV', 'Digitalisierung der Justiz weiter vorantreiben, damit Verfahren einfacher und schneller werden.', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=59', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7732, 9, 12, 'MV', 'Situation von Frauenschutzhäusern, Beratungsstellen und Täterberatung verbessern; Frauenhäuser mit Investitionsmitteln modernisieren und bedarfsgerecht ausbauen.', '{904,908}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=38', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7733, 9, 12, 'MV', 'Freiwillige Schulungen für Richterinnen und Richter zu Femiziden und zur Istanbul-Konvention anbieten.', '{904}', null, 1, 3, null, 'Geschulte Richterinnen und Richter können Gefahren bei Partnerschaftsgewalt besser erkennen. Freiwillige Schulungen erreichen aber nicht alle, und zur Wirkung gibt es kaum Daten.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=38', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7734, 9, 12, 'MV', 'Auf Bundesebene erreichen, dass der Umgang mit Kindern zugunsten des Opferschutzes ausgesetzt werden kann, wenn ein Elternteil Opfer des anderen ist.', '{904}', 7650, 1, 1, null, 'Gewalt setzt sich nach Trennungen oft bei Umgangskontakten fort; ein Vorrang des Schutzes setzt dort an. Das Familienrecht regelt der Bund, das Land kann nur werben, und zur Wirkung gibt es kaum Daten.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=59', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7735, 9, 12, 'ST', 'Dienstposten der Landespolizei voll finanzieren und Besoldung der Polizeibeschäftigten verbessern', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=29', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7736, 9, 12, 'ST', 'Gerichte und Staatsanwaltschaften personell und technisch stärken, kein Einstellungsstopp in der Justiz', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=31', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7737, 9, 12, 'ST', 'Verbindliches Digitalisierungskonzept für die Justiz, abgesicherte IT-Migration und Einführung der E-Akte', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=31', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7738, 9, 12, 'ST', 'Häuser des Jugendrechts, in denen Polizei, Staatsanwaltschaft und Jugendhilfe Delikte Minderjähriger gemeinsam bearbeiten', '{903}', 7640, 2, 3, null, 'Evaluationen zeigen eine bessere Zusammenarbeit von Polizei, Justiz und Jugendhilfe, teils kürzere Verfahren und weniger Rückfälle; Vergleichsgruppen fehlen oft. Länder können solche Häuser selbst einrichten.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=27', 'https://www.iss-ffm.de/themen/armut-und-armutsfolgen/projekte/evaluation-der-haeuser-des-jugendrechts-in-niedersachsen', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7739, 9, 12, 'ST', 'Frauenhäuser und Schutzwohnungen landesweit ausbauen; Istanbul-Konvention und Gewalthilfegesetz umsetzen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=32', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7740, 9, 12, 'ST', 'Beratungsinfrastruktur gegen Gewalt an Frauen stärken, besonders im ländlichen Raum, mit mehrjährigen Förderverträgen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=32', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7741, 9, 13, 'BE', 'Community Policing: mehr Kontaktbereichsbeamte, mehr Fahrradstreifen und Präsenz an Hotspots, mobile Wachen und Kiezläufer', '{901}', 7626, 3, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=225', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-03', false, true, 'blind'),
  (7742, 9, 13, 'BE', 'Strategie „Sicherheit-Plus“: soziale Infrastruktur in Brennpunkten stärken, Aufenthaltsqualität des öffentlichen Raums verbessern, polizeiliche Präsenzmaßnahmen', '{901}', 7626, 3, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=232', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-03', false, true, 'blind'),
  (7743, 9, 13, 'BE', 'Ausreichende Beleuchtung auf den Wegen zu Haltestellen', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=82', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7744, 9, 13, 'BE', 'Mehr Sicherheit und Sauberkeit auf Bahnhöfen und in Bahnen; mehr geschulte Sicherheitsmitarbeitende der BVG, Frauenabteile in der U-Bahn erproben', '{901,908}', 7628, 3, 2, null, 'Ein Zufallsexperiment an 41 Bahnhöfen fand bei Streifen durch Sicherheitspersonal 16 % weniger Taten, bei Gewalt 31 % weniger. Das Personal kostet dauerhaft und muss mit den Verkehrsunternehmen vereinbart werden.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=82', 'https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0187392', 'belegt', '2026-10-03', false, true, 'blind'),
  (7745, 9, 13, 'BE', 'Videoüberwachung im öffentlichen Raum nicht flächendeckend, nur gezielt zum Schutz kritischer Infrastruktur ausbauen', '{901}', 7631, 0, 3, null, 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Da Videoüberwachung Gewalt laut Meta-Analyse kaum senkt, kostet der Verzicht wenig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=228', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7746, 9, 13, 'BE', 'Konsumräume und Streetwork-Teams ausbauen, um besonders junge und sozial benachteiligte Menschen zu erreichen', '{901}', 7634, 2, 3, null, 'Konsumräume und aufsuchende Hilfe verringern laut Evaluationen offenen Drogenkonsum und Szenebelastung; Diebstahl und Raub im Umfeld sinken aber nicht. Das Land kann solche Angebote mit den Kommunen rasch finanzieren.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=209', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7747, 9, 13, 'BE', 'Polizeiausbildung attraktiver machen und Arbeitsbedingungen verbessern, um das Personal zu sichern', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=225', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7748, 9, 13, 'BE', 'Sanierungsstau bei Liegenschaften und Fuhrpark der Polizei abbauen, Neubau für das Kriminaltechnische Institut anschieben', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=226', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7749, 9, 13, 'BE', 'Personaloffensive in der Justiz mit besseren Arbeitsbedingungen, Quereinstiegen und Aufstiegschancen', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=240', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7750, 9, 13, 'BE', 'Digitale Recherchetools und Assistenzsysteme in Rechtsprechung und Strafverfolgung unterstützen, um Gerichte und Staatsanwaltschaften zu entlasten', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=242', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7751, 9, 13, 'BE', 'Ersatzfreiheitsstrafe und Strafbarkeit von Bagatelldelikten wie Fahren ohne Fahrschein über den Bund abschaffen, Abarbeiten von Geldstrafen stärken', '{902}', 7658, 1, 1, null, 'Fahren ohne Fahrschein bindet viel Justizkapazität und führt oft zu Ersatzfreiheitsstrafen; eine Streichung entlastet. Schwere Taten werden dadurch nur indirekt schneller verfolgt, und das Land braucht den Bund.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=238', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'belegt', '2026-10-03', false, true, 'blind'),
  (7752, 9, 13, 'BE', 'Anlasslose Massenüberwachung wie biometrische Gesichtserkennung ablehnen; Absage an Vorratsdatenspeicherung im Bundesrat', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=227', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7753, 9, 13, 'BE', 'Immobilienregister mit wirtschaftlich Berechtigten, um kriminelle Strukturen aufzudecken und Immobilien einzuziehen', '{902}', null, 1, 1, null, 'Ein Register der wirtschaftlich Berechtigten erleichtert Ermittlungen gegen Geldwäsche mit Immobilien. Auf alltägliche Taten wirkt es kaum, und Grundbuch- und Registerrecht regelt weitgehend der Bund.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=232', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7754, 9, 13, 'BE', 'Organisierte Kriminalität priorisieren: Strukturermittlungen bei LKA und Staatsanwaltschaft, Schnittstellen zu Finanzämtern, Steuerfahndung und Zoll', '{902}', 7655, 1, 3, null, 'Vermögensabschöpfung trifft kriminelle Strukturen finanziell und ist eine spürbare Tatfolge. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum, Wirkungsstudien fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=232', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7755, 9, 13, 'BE', 'Angebote der Jugendsozial- und Jugendkulturarbeit in belasteten Kiezen absichern, vor allem für junge Männer, als Kriminalprävention', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=225', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7756, 9, 13, 'BE', 'Ressortübergreifender Sicherheitsgipfel von Land und Bezirken gegen die Zunahme rechtsextremer Jugendgewalt', '{903}', null, 1, 3, null, 'Ein ressortübergreifender Gipfel kann Maßnahmen gegen rechtsextreme Jugendgewalt bündeln. Ein Treffen allein ändert wenig, konkrete Instrumente fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=160', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7757, 9, 13, 'BE', 'Zwei neue Frauenhäuser, mehr Beratungsangebote, Zweite-Stufe-Wohnungen und Schutzwohnungen mit Bundesmitteln aus dem Gewalthilfegesetz', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=131', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7758, 9, 13, 'BE', 'Elektronische Fußfessel mit Benachrichtigungsmöglichkeit für Betroffene einführen', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=131', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7759, 9, 13, 'BE', 'Standardisierte, regelbasierte Verfahren der Polizei bei geschlechtsspezifischer und häuslicher Gewalt nach spanischem Vorbild', '{904}', 7645, 2, 3, null, 'Fallkonferenzen und standardisierte Risikoeinschätzung wie in Großbritannien und Spanien sollen Hochrisikofälle früh erkennen; Berichte melden weniger Wiederholungstaten, aber auch Fehleinschätzungen. Das Land kann es selbst einführen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=131', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7760, 9, 13, 'BE', 'Istanbul-Konvention umsetzen: Prävention in Schulen und Sozialämtern sowie Täterarbeit wie Anti-Aggressionstrainings stärken', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=132', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7761, 9, 13, 'BE', 'Sonderzuständigkeit für Sexualdelikte an den Strafgerichten schaffen', '{908}', 7649, 1, 3, null, 'Spezialisierte Staatsanwälte und Kammern können Verfahren beschleunigen und Betroffene schonen. Belege für mehr Anzeigen oder Verurteilungen fehlen weitgehend.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=132', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7762, 9, 13, 'BE', 'Über den Bund Catcalling unter Strafe stellen', '{908}', 7651, 1, 1, null, 'Höhere Strafen benennen Unrecht klarer. Die Forschung zeigt aber übereinstimmend, dass vor allem das Entdeckungsrisiko abschreckt, kaum die Strafhöhe. Das Strafrecht ändert der Bund, das Land kann nur werben.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=132', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7763, 9, 13, 'BE', 'Berliner Periodischer Sicherheitsbericht neben der Polizeilichen Kriminalstatistik, der auch Ursachen von Taten analysiert', '{909}', 7654, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=227', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7764, 9, 13, 'MV', 'Bürgernahe Polizei mit mehr Präsenz vor Ort, Beamte zu Fuß in den Quartieren', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://gruene-mv.de/?wpdmdl=33772#page=76', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7765, 9, 13, 'MV', 'Moratorium für biometrische Überwachung im öffentlichen Raum, stattdessen Prävention und Präsenz', '{901}', 7631, 0, 3, null, 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Da Videoüberwachung Gewalt laut Meta-Analyse kaum senkt, kostet der Verzicht wenig.', 'https://gruene-mv.de/?wpdmdl=33772#page=74', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7766, 9, 13, 'MV', 'Soziale Präventionsarbeit in Kommunen finanziell stärken: Streetwork, Jugendclubs, Suchtberatung, psychologische Betreuung', '{901,903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://gruene-mv.de/?wpdmdl=33772#page=76', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7767, 9, 13, 'MV', 'Stadt- und Dorfplanung gendersensibel gestalten, u. a. mit sicheren Übergängen und guter Beleuchtung', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://gruene-mv.de/?wpdmdl=33772#page=85', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7768, 9, 13, 'MV', 'Ausreichende Neueinstellungen bei der Landespolizei und Reform der Aus- und Fortbildung', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7769, 9, 13, 'MV', 'Deutlich mehr Richter, Staatsanwälte und Justizbedienstete einstellen und angemessen bezahlen', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://gruene-mv.de/?wpdmdl=33772#page=78', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7770, 9, 13, 'MV', 'Polizeigesetz mit hohen Hürden für Grundrechtseingriffe, ohne Online-Durchsuchung und Quellen-TKÜ', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7771, 9, 13, 'MV', 'Keine Zusammenarbeit der Sicherheitsbehörden mit Palantir', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://gruene-mv.de/?wpdmdl=33772#page=74', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7772, 9, 13, 'MV', 'Beratungs- und Hilfenetz gegen geschlechtsspezifische Gewalt dauerhaft finanzieren (Frauenhäuser, Beratung, Täterarbeit)', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://gruene-mv.de/?wpdmdl=33772#page=82', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7773, 9, 13, 'MV', 'Einheitliche Definition von Femiziden und systematische statistische Erfassung durch Polizei und Staatsanwaltschaften', '{904}', 7647, 1, 3, null, 'Eine einheitliche Erfassung verbessert das Lagebild und kann Prävention gezielter machen. Sie verhindert selbst keine Taten, und zur Wirkung gibt es kaum Daten.', 'https://gruene-mv.de/?wpdmdl=33772#page=82', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7774, 9, 13, 'MV', 'Beratungs- und Hilfenetz für Opfer sexueller und häuslicher Gewalt auskömmlich finanzieren', '{904,908}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://gruene-mv.de/?wpdmdl=33772#page=90', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7775, 9, 13, 'MV', 'Periodischer Sicherheitsbericht, der die Kriminalstatistik allgemeinverständlich ergänzt', '{909}', 7654, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7776, 9, 13, 'ST', 'Polizeifahrradstreifen als sichtbare, präventive Polizeipräsenz weiter fördern', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=41', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7777, 9, 13, 'ST', 'Mehr Sicherheit im Schienenverkehr durch Doppelbesetzung mit Zugbegleitung und Sicherheitsteams', '{901}', 7628, 3, 2, null, 'Ein Zufallsexperiment an 41 Bahnhöfen fand bei Streifen durch Sicherheitspersonal 16 % weniger Taten, bei Gewalt 31 % weniger. Das Personal kostet dauerhaft und muss mit den Verkehrsunternehmen vereinbart werden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=31', 'https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0187392', 'belegt', '2026-10-03', false, true, 'blind'),
  (7778, 9, 13, 'ST', 'Sichere Haltestellen schaffen und Angsträume beseitigen', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=32', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7779, 9, 13, 'ST', 'Personalausbau bei der Polizei bis zur Zielgröße fortsetzen', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=41', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7780, 9, 13, 'ST', 'Bessere Personalausstattung von Gerichten und Staatsanwaltschaften für zügigere Verfahren', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=46', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7781, 9, 13, 'ST', 'Digitalisierung der Justiz mit E-Akte und digitalen Verfahren vorantreiben', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=46', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7782, 9, 13, 'ST', 'Fahren ohne Fahrschein nicht mehr als Straftat behandeln', '{902}', 7658, 1, 1, null, 'Fahren ohne Fahrschein bindet viel Justizkapazität und führt oft zu Ersatzfreiheitsstrafen; eine Streichung entlastet. Schwere Taten werden dadurch nur indirekt schneller verfolgt, und das Land braucht den Bund.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=31', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'belegt', '2026-10-03', false, true, 'blind'),
  (7783, 9, 13, 'ST', 'Jugendarbeit und Schulsozialarbeit massiv stärken, um früh präventiv zu wirken', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=62', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7784, 9, 13, 'ST', 'Bedarfsgerechter Ausbau von Frauenhäusern und Schutzräumen in allen Regionen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=44', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7785, 9, 13, 'ST', 'Gewalthilfegesetz umsetzen und Frauenhaus-Finanzierung ohne Eigenanteil der Bewohnerinnen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=44', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7786, 9, 13, 'ST', 'Fachstellen für Täterarbeit auch im ländlichen Raum fördern', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=45', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7787, 9, 13, 'ST', 'Alle Kliniken ans Netzwerk für anonyme Spurensicherung nach sexueller Gewalt anbinden', '{908}', 7652, 2, 3, null, 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=83', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7788, 9, 13, 'ST', 'Polizeiliche Kriminalstatistik durch Studien ergänzen und einordnen', '{909}', 7654, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=42', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7789, 9, 14, 'BE', 'Dauerhafte, verstärkte Polizeipräsenz im öffentlichen Raum; Polizei von Verwaltungsaufgaben entlasten', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=66', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7790, 9, 14, 'BE', 'Sonderbefugnisse (anlasslose Identitätsfeststellung, Durchsuchung) der Polizei an kriminalitätsbelasteten Orten, mit klareren Kriterien für die Einstufung', '{901}', 7632, 1, 3, null, 'Die Evaluation der Leipziger Waffenverbotszone fand weniger bewaffnete Angriffe, aber kaum Wirkung auf andere Taten. Anlasslose Kontrollen können Vertrauen kosten. Das Land kann sie im Polizeigesetz regeln.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=67', 'https://medienservice.sachsen.de/medien/news/252888', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7791, 9, 14, 'BE', 'Security by Design: bauliche Sicherheit an Risikoorten wie Bahnhöfen durch Beleuchtung, Sichtachsen, keine dunklen Ecken, daneben temporäre Videoüberwachung', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=67', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7792, 9, 14, 'BE', 'Konsumräume und Streetwork-Teams ausbauen; Nachtcafés und Drogenkonsumräume im Kurfürstenkiez sichern', '{901}', 7634, 2, 3, null, 'Konsumräume und aufsuchende Hilfe verringern laut Evaluationen offenen Drogenkonsum und Szenebelastung; Diebstahl und Raub im Umfeld sinken aber nicht. Das Land kann solche Angebote mit den Kommunen rasch finanzieren.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=118', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7793, 9, 14, 'BE', 'Finanzierung des Parkläufer-Projekts verstetigen, um Konflikte in Grünanlagen zu deeskalieren und Parkordnungen durchzusetzen', '{901}', 7634, 2, 3, null, 'Konsumräume und aufsuchende Hilfe verringern laut Evaluationen offenen Drogenkonsum und Szenebelastung; Diebstahl und Raub im Umfeld sinken aber nicht. Das Land kann solche Angebote mit den Kommunen rasch finanzieren.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=70', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7794, 9, 14, 'BE', 'Personalsituation bei Polizei (und Justiz) verbessern: Bezahlung, Arbeitsplätze, Nachwuchsprogramm', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=72', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7795, 9, 14, 'BE', 'Statt anlassloser Datenspeicherung das Quick-Freeze-Verfahren nach richterlichem Beschluss einführen', '{902}', 7660, 1, 1, null, 'Quick Freeze ist grundrechtsschonend, greift aber nur bei Daten, die bei der Anordnung noch vorhanden sind. Die Strafprozessordnung regelt der Bund, das Land kann nur werben.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7796, 9, 14, 'BE', 'Clankriminalität bekämpfen, Vermögen aus Straftaten bei Tatverdacht auch per Beweislastumkehr abschöpfen', '{902}', 7656, 1, 1, null, 'Eine leichtere Einziehung trifft kriminelle Strukturen finanziell, wirkt aber kaum auf alltägliche Taten. Die Beweislastumkehr regelt der Bund, und sie steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=73', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7797, 9, 14, 'BE', 'Verfahren gegen straffällige Jugendliche unmittelbar nach der Tat (Neuköllner Modell) fortsetzen und verstetigen', '{903}', 7639, 1, 3, null, 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=73', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7798, 9, 14, 'BE', 'Gewaltpräventive Angebote der Polizei an Schulen verstärken, Polizei, Schulen und Jugendhilfe verzahnen, mehr Jugend- und Sozialarbeit sowie Streetwork', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7799, 9, 14, 'BE', 'Gewaltschutzambulanz stärken und ausbauen, mehr Zufluchtsorte, bessere Zusammenarbeit der Institutionen bei häuslicher und sexualisierter Gewalt', '{904,908}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=69', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7800, 9, 14, 'BE', 'Schutz- und Beratungseinrichtungen nach Gewalthilfegesetz ausbauen und regelfinanzieren, mehr Schutzplätze in Frauenhäusern', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=80', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7801, 9, 14, 'BE', 'Täterarbeit bei häuslicher Gewalt deutlich ausbauen', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=81', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7802, 9, 14, 'BE', 'Höhere Strafandrohung im Gewaltschutzgesetz und bessere Durchsetzung gegen Stalking und Hasskriminalität', '{904}', 7651, 1, 1, null, 'Höhere Strafen benennen Unrecht klarer. Die Forschung zeigt aber übereinstimmend, dass vor allem das Entdeckungsrisiko abschreckt, kaum die Strafhöhe. Das Strafrecht ändert der Bund, das Land kann nur werben.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=73', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7803, 9, 14, 'MV', 'Verlässliche Polizeipräsenz auch im ländlichen Raum sicherstellen', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7804, 9, 14, 'MV', 'Personalschlüssel der Landespolizei anpassen, mehr Beamte im operativen Dienst', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7805, 9, 14, 'MV', 'Zahl der Richter, Staatsanwälte und Justizmitarbeitenden bedarfsgerecht erhöhen', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=138', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7806, 9, 14, 'MV', 'Digitalisierung der Justiz vorantreiben, Medienbrüche zwischen Polizei, Staatsanwaltschaft und Gerichten beenden', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=138', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7807, 9, 14, 'MV', 'Vollständig digitale Abläufe bei der Polizei mit interaktiven Streifenwagen und mobilen Endgeräten', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7808, 9, 14, 'MV', 'Anlasslose Vorratsdatenspeicherung ablehnen, stattdessen Quick-Freeze bei konkretem Verdacht', '{902}', 7660, 1, 1, null, 'Quick Freeze ist grundrechtsschonend, greift aber nur bei Daten, die bei der Anordnung noch vorhanden sind. Die Strafprozessordnung regelt der Bund, das Land kann nur werben.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=134', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7809, 9, 14, 'MV', 'Flächendeckende Videoüberwachung und automatisierte Gesichtserkennung ablehnen', '{901}', 7631, 0, 3, null, 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Da Videoüberwachung Gewalt laut Meta-Analyse kaum senkt, kostet der Verzicht wenig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7810, 9, 14, 'MV', 'Femiziden entgegenwirken: Gefährdungsanalysen, Behördenabstimmung, elektronische Fußfessel bei häuslicher Gewalt per Landesrecht', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7811, 9, 14, 'MV', 'Finanzierung des Beratungs- und Hilfenetzes bei häuslicher und sexualisierter Gewalt stärken', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=53', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7812, 9, 14, 'MV', 'Straftaten ehrlich erfassen, einschließlich der Herkunft der Täter', '{909}', 7653, 1, 3, null, 'Mehr Angaben zur Staatsangehörigkeit sollen Transparenz schaffen. Ob das die verzerrte Wahrnehmung korrigiert oder verstärkt, ist offen; Medien nennen bei Gewalttaten schon heute fast nur ausländische Tatverdächtige.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=132', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7813, 9, 14, 'ST', 'Sichtbar mehr Polizei in Stadt und Land: Zielzahl von 7.000 Stellen im Polizeivollzugsdienst halten.', '{902,901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=47', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7814, 9, 14, 'ST', 'Sicherheitspartnerschaften von Polizei und Ordnungsämtern flächendeckend ausbauen, gemeinsame Einsätze zum Regelfall machen, um die Präsenz im öffentlichen Raum zu erhöhen.', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=47', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7815, 9, 14, 'ST', 'Alle Waffenverbotszonen im Land abschaffen, damit entfallen auch die anlasslosen Personenkontrollen dort.', '{901}', 7633, 0, 3, null, 'Die Abschaffung beugt diskriminierenden Kontrollen vor, verzichtet aber auf ein Mittel, das in Leipzig bewaffnete Angriffe etwas senkte. Die Sicherheit an belasteten Orten verbessert sie nicht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=48', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7816, 9, 14, 'ST', 'Elektronische Akte in allen Bereichen der Justiz bis spätestens 2030 landesweit einführen, ohne Medienbruch.', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=45', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7817, 9, 14, 'ST', 'Frauenhäuser stärken und Ursachen häuslicher Gewalt bekämpfen; Eigenanteile für Übernachtungen in Frauenhäusern abschaffen als geeigneter Weg.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=39', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7818, 9, 15, 'BE', 'Videoüberwachung in allen Brennpunktbereichen einführen', '{901}', 7630, 1, 3, null, 'Videoüberwachung senkt Kriminalität laut Meta-Analyse moderat, vor allem Eigentumsdelikte auf Parkplätzen, kaum Gewalt. Aktiv beobachtete Kameras wirken stärker. Das Polizeirecht des Landes erlaubt den Ausbau an belasteten Orten.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'belegt', '2026-10-03', false, true, 'blind'),
  (7819, 9, 15, 'BE', 'Mobile Polizeiwachen in Problemvierteln und dichteres Netz stationärer Wachen', '{901}', 7626, 3, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-03', false, true, 'blind'),
  (7820, 9, 15, 'BE', 'Strafrahmen und Schnellverfahren bei Messerdelikten, mehr anlasslose Kontrollen an kriminalitätsbelasteten Orten', '{901,902}', null, 1, 2, null, 'Kontrollen an belasteten Orten und Schnellverfahren setzen an, wirken laut Leipziger Evaluation aber nur begrenzt; höhere Strafen schrecken kaum ab. Den Strafrahmen ändert der Bund.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=15', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7821, 9, 15, 'BE', 'Mehr Personal bei Polizei und Justiz sowie ausreichende Ausbildung des Nachwuchses', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7822, 9, 15, 'BE', 'Bessere Ausrüstung und Arbeitsbedingungen für Polizei und Justiz, Sanierung von Gebäuden', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7823, 9, 15, 'BE', 'Digitale Infrastruktur für Polizei und Justiz, gegebenenfalls KI', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7824, 9, 15, 'BE', 'Bezirkspolizei bei den Ordnungsämtern mit Befugnissen zu Identitätsfeststellung, Platzverweis und unmittelbarem Zwang, zur Entlastung der Landespolizei', '{902}', null, 1, 2, null, 'Eine Ordnungspolizei der Bezirke kann die Landespolizei von einfachen Aufgaben entlasten und Zeit für Ermittlungen schaffen. Aufbau, Befugnisse und Personal brauchen Zeit, Belege fehlen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=12', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7825, 9, 15, 'BE', 'Verfahren gegen Mehrfachbeschuldigte beim selben Dezernenten bündeln, Staatsanwaltschaft neu strukturieren und enger mit Polizei verzahnen', '{902}', 7639, 1, 3, null, 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=15', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7826, 9, 15, 'BE', 'Tatverdächtige der organisierten Kriminalität binnen 48 Stunden dem Bereitschaftsrichter vorführen', '{902}', null, 1, 2, null, 'Eine schnelle Vorführung kann Verfahren gegen Tatverdächtige beschleunigen. Die Vorführung vor einen Richter ist ohnehin binnen eines Tages Pflicht, der Zusatznutzen ist unklar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=14', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7827, 9, 15, 'BE', 'Beschlagnahme und Einziehung kriminell erworbenen Vermögens konsequent bei Clans und organisierter Kriminalität anwenden', '{902}', 7655, 1, 3, null, 'Vermögensabschöpfung trifft kriminelle Strukturen finanziell und ist eine spürbare Tatfolge. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum, Wirkungsstudien fehlen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=14', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7828, 9, 15, 'BE', 'Rechtsgrundlage für nächtliche Ausgangssperren für jugendliche Intensivtäter', '{903}', null, 1, 1, null, 'Nächtliche Ausgangssperren könnten Intensivtäter von Taten abhalten. Sie greifen stark in Grundrechte ein, sind rechtlich unsicher, und Belege zur Wirkung fehlen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7829, 9, 15, 'BE', 'Strafmündigkeit auf 12 senken, beschleunigte Jugendverfahren ausweiten, Warnschussarrest und Jugendstrafe früher möglich', '{903}', 7641, 1, 1, null, 'Fachverbände sehen keine Belege für eine abschreckende Wirkung, und nach Arrest und Jugendstrafe sind Rückfallquoten hoch. Dafür spricht ein früheres Eingreifen bei Intensivtätern. Das Land kann nur über den Bundesrat werben.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=15', 'https://jugendhilfeportal.de/artikel/stellungnahme-zur-forderung-der-senkung-des-strafmuendigkeitsalters-durch-cdu-generalsekretaer', 'belegt', '2026-10-03', false, true, 'blind'),
  (7830, 9, 15, 'BE', 'Migrationshintergrund von Tatverdächtigen klar benennen und statistisch erfassen, auch bei Deutschen', '{909}', null, 1, 2, null, 'Mehr Angaben zur Herkunft sollen Transparenz schaffen; ob das verzerrte Wahrnehmung korrigiert oder verstärkt, ist offen. Die Kriminalstatistik ist bundeseinheitlich, ein Migrationshintergrund wird darin bisher nicht erfasst.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=13', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7831, 9, 15, 'MV', 'Sichtbare Polizeipräsenz auf den Straßen erhöhen und Polizei modern ausstatten, gegen gefährliche Plätze und Angst vor nächtlichen Spaziergängen.', '{901,902}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=11', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7832, 9, 15, 'MV', 'Polizeipersonal der Landespolizei auf dem Zielstand halten und genug Absolventen der Polizeifachhochschule ausbilden.', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=37', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7833, 9, 15, 'MV', 'Polizeivollzugsbeamte durch Prozessoptimierung, Digitalisierung und nichtpolizeiliches Personal von Verwaltungsarbeit entlasten.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=37', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7834, 9, 15, 'MV', 'Quick-Freeze-Verfahren statt Vorratsdatenspeicherung stärken und KI-gestützte Auswertung sichergestellter Daten einsetzen.', '{902}', 7660, 1, 1, null, 'Quick Freeze ist grundrechtsschonend, greift aber nur bei Daten, die bei der Anordnung noch vorhanden sind. Die Strafprozessordnung regelt der Bund, das Land kann nur werben.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=43', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7835, 9, 15, 'MV', 'Staatsanwaltschaften sollen in einfach gelagerten Fällen häufiger das beschleunigte Strafverfahren nutzen, in Jugendsachen das vereinfachte Verfahren.', '{902,903}', 7639, 1, 3, null, 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=44', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7836, 9, 15, 'MV', 'Bundesratsinitiative, die Strafmündigkeit von 14 auf 12 Jahre zu senken.', '{903}', 7641, 1, 1, null, 'Fachverbände sehen keine Belege für eine abschreckende Wirkung, und nach Arrest und Jugendstrafe sind Rückfallquoten hoch. Dafür spricht ein früheres Eingreifen bei Intensivtätern. Das Land kann nur über den Bundesrat werben.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=44', 'https://jugendhilfeportal.de/artikel/stellungnahme-zur-forderung-der-senkung-des-strafmuendigkeitsalters-durch-cdu-generalsekretaer', 'belegt', '2026-10-03', false, true, 'blind'),
  (7837, 9, 15, 'MV', 'Gewalt an Schulen unterbinden und Schulsozialarbeit als Landesaufgabe etablieren.', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7838, 9, 15, 'MV', 'Mehr Informationen zur Ausländerkriminalität in der Kriminalstatistik auch je Landkreis und kreisfreier Stadt veröffentlichen.', '{909}', 7653, 1, 3, null, 'Mehr Angaben zur Staatsangehörigkeit sollen Transparenz schaffen. Ob das die verzerrte Wahrnehmung korrigiert oder verstärkt, ist offen; Medien nennen bei Gewalttaten schon heute fast nur ausländische Tatverdächtige.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=39', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7839, 9, 15, 'MV', 'In Polizei-Presseinformationen auf doppelte Staatsangehörigkeiten von Tatverdächtigen und Opfern hinweisen.', '{909}', 7653, 1, 3, null, 'Mehr Angaben zur Staatsangehörigkeit sollen Transparenz schaffen. Ob das die verzerrte Wahrnehmung korrigiert oder verstärkt, ist offen; Medien nennen bei Gewalttaten schon heute fast nur ausländische Tatverdächtige.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=39', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7840, 9, 15, 'MV', 'Landeskriminalamt-Lagebild zu Kriminalität im Kontext von Zuwanderung mit Herkunftsstaaten und Täter-Opfer-Verhältnissen veröffentlichen.', '{909}', 7653, 1, 3, null, 'Mehr Angaben zur Staatsangehörigkeit sollen Transparenz schaffen. Ob das die verzerrte Wahrnehmung korrigiert oder verstärkt, ist offen; Medien nennen bei Gewalttaten schon heute fast nur ausländische Tatverdächtige.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=39', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7841, 9, 15, 'MV', 'Regelmäßige landesweite Dunkelfeldbefragungen zu erlebter Kriminalität und Meiden öffentlicher Plätze.', '{909}', 7654, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=39', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7842, 9, 15, 'ST', 'Landespolizei auf mindestens 7.500 Vollzugsbeamte aufstocken.', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=105', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7843, 9, 15, 'ST', 'Freiwillige Bürgerwacht unter dem Ordnungsamt als zusätzliche Säule der Sicherheit vor Ort aufbauen, die Ordnungsamt und Polizei unterstützt.', '{901}', null, 1, 2, null, 'Freiwillige Streifen können Präsenz erhöhen und Ordnungsämter unterstützen. Ohne Befugnisse und Ausbildung ist ihr Beitrag begrenzt, und Belege zur Wirkung fehlen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=112', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7844, 9, 15, 'ST', 'Beschleunigte Verfahren stärker nutzen, besonders bei Straftaten von Jugendlichen schnelles Aburteilen (Neuköllner Modell).', '{902,903}', 7639, 1, 3, null, 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=119', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7845, 9, 15, 'ST', 'Vorübergehender Stellenaufwuchs in der Justizverwaltung und Einstellungsoffensive im Justizvollzugsdienst.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=121', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7846, 9, 15, 'ST', 'Bei Gewaltverbrechen den Strafrahmen voll ausschöpfen; Richter sollen maximale Härte anwenden.', '{902,908}', null, 0, 1, null, 'Richter sind unabhängig, das Land kann ihnen keine Strafhöhe vorgeben. Zudem schreckt laut Forschung vor allem das Entdeckungsrisiko ab, kaum die Höhe der Strafe.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=119', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7847, 9, 15, 'ST', 'Strafmündigkeit auf Bundesebene von 14 auf 12 Jahre absenken.', '{903}', 7641, 1, 1, null, 'Fachverbände sehen keine Belege für eine abschreckende Wirkung, und nach Arrest und Jugendstrafe sind Rückfallquoten hoch. Dafür spricht ein früheres Eingreifen bei Intensivtätern. Das Land kann nur über den Bundesrat werben.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=124', 'https://jugendhilfeportal.de/artikel/stellungnahme-zur-forderung-der-senkung-des-strafmuendigkeitsalters-durch-cdu-generalsekretaer', 'belegt', '2026-10-03', false, true, 'blind'),
  (7848, 9, 15, 'ST', 'Warnschussarrest bei jeder Form der Jugendkriminalität konsequent verhängen.', '{903}', 7641, 1, 1, null, 'Fachverbände sehen keine Belege für eine abschreckende Wirkung, und nach Arrest und Jugendstrafe sind Rückfallquoten hoch. Dafür spricht ein früheres Eingreifen bei Intensivtätern. Das Land kann nur über den Bundesrat werben.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=109', 'https://jugendhilfeportal.de/artikel/stellungnahme-zur-forderung-der-senkung-des-strafmuendigkeitsalters-durch-cdu-generalsekretaer', 'belegt', '2026-10-03', false, true, 'blind'),
  (7849, 9, 15, 'ST', 'Rechtsfigur des Heranwachsenden im Jugendstrafrecht abschaffen, sodass diese Altersgruppe nach Erwachsenenstrafrecht behandelt wird.', '{903}', 7641, 1, 1, null, 'Fachverbände sehen keine Belege für eine abschreckende Wirkung, und nach Arrest und Jugendstrafe sind Rückfallquoten hoch. Dafür spricht ein früheres Eingreifen bei Intensivtätern. Das Land kann nur über den Bundesrat werben.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=125', 'https://jugendhilfeportal.de/artikel/stellungnahme-zur-forderung-der-senkung-des-strafmuendigkeitsalters-durch-cdu-generalsekretaer', 'belegt', '2026-10-03', false, true, 'blind'),
  (7850, 9, 15, 'ST', 'Bei Bedarf privaten Wachdienst an Schulen einrichten, der Gewalt auf dem Schulhof verhindert.', '{903}', null, 1, 2, null, 'Wachpersonal kann Gewalt auf dem Schulhof unterbinden. Private Dienste haben aber keine hoheitlichen Befugnisse, Belege zur Wirkung fehlen, und Präventionsprogramme gelten als besser belegt.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=88', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7851, 9, 15, 'ST', 'Schulen und Staatsanwaltschaften vernetzen, damit jede Straftat strafmündiger Schüler vor Gericht kommt; Gewalttäter schneller der Schule verweisen.', '{903}', null, 1, 2, null, 'Eine engere Verbindung von Schulen und Justiz setzt bei Jugendgewalt an. Jede Tat vor Gericht zu bringen widerspricht aber der Diversion, die laut Rückfallforschung nicht schlechter wirkt als formelle Verfahren.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=89', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7852, 9, 16, 'BE', 'Statt Zaun und nächtlicher Parkschließung Mittel für aufsuchende Sozialarbeit, Obdachlosen- und Suchthilfe sowie Parkläufer*innen einsetzen.', '{901}', 7634, 2, 3, null, 'Konsumräume und aufsuchende Hilfe verringern laut Evaluationen offenen Drogenkonsum und Szenebelastung; Diebstahl und Raub im Umfeld sinken aber nicht. Das Land kann solche Angebote mit den Kommunen rasch finanzieren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=288', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7853, 9, 16, 'BE', 'Kriminalitätsbelastete Orte und Waffenverbotszonen samt Videoüberwachung und anlasslosen Kontrollen abschaffen.', '{901}', 7633, 0, 3, null, 'Die Abschaffung beugt diskriminierenden Kontrollen vor, verzichtet aber auf ein Mittel, das in Leipzig bewaffnete Angriffe etwas senkte. Die Sicherheit an belasteten Orten verbessert sie nicht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7854, 9, 16, 'BE', 'Zusätzliche Polizeieinheiten wie die Brennpunkt- und Präsenzeinheit an diesen Orten abbauen, Mittel in soziale Infrastruktur umlenken.', '{901}', null, 1, 3, null, 'Mittel für soziale Infrastruktur können langfristig wirken. Der Abbau gezielter Präsenzeinheiten verzichtet aber auf ein Mittel, das an Brennpunkten laut Studien Kriminalität senkt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=290', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7855, 9, 16, 'BE', 'Konzept für ein Frauen*-Nachttaxi als Ergänzung des Nahverkehrs entwickeln.', '{901}', null, 1, 3, null, 'Ein Nachttaxi kann nächtliche Wege sicherer machen und das Sicherheitsgefühl stärken. Bisher ist nur ein Konzept vorgesehen, zur Wirkung gibt es kaum Daten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=68', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7856, 9, 16, 'BE', 'In Großsiedlungen Grünflächen aufwerten und für bessere Beleuchtung sorgen.', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=32', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7857, 9, 16, 'BE', 'Untersuchungshaft-Überbelegung durch Beschleunigung des Strafprozesses begegnen: richterliche Stellen und Personal zur kriminaltechnischen Auswertung bereitstellen.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=307', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7858, 9, 16, 'BE', 'Digitalisierung der Berliner Justiz vorantreiben und die justizielle IT standardisieren.', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=307', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7859, 9, 16, 'BE', 'Typische Armutsdelikte, insbesondere Schwarzfahren, ersatzlos entkriminalisieren; Vollstreckung von Geldstrafen über gemeinnützige Arbeit.', '{902}', 7658, 1, 1, null, 'Fahren ohne Fahrschein bindet viel Justizkapazität und führt oft zu Ersatzfreiheitsstrafen; eine Streichung entlastet. Schwere Taten werden dadurch nur indirekt schneller verfolgt, und das Land braucht den Bund.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=311', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'belegt', '2026-10-03', false, true, 'blind'),
  (7860, 9, 16, 'BE', 'Überwachungsbefugnisse von Polizei und Verfassungsschutz beschränken, keine neuen Befugnisse mittragen; Staatstrojaner und KI-Analyse in Polizeidatenbanken ablehnen.', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=291', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7861, 9, 16, 'BE', 'Ausbau kiezorientierter Gewalt- und Kriminalitätsprävention auf Bezirksebene und Projekte der Jugendsozialarbeit, verlässlich finanziert.', '{903,901}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=288', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7862, 9, 16, 'BE', 'Außerschulische Angebote zu Mobbing- und Gewaltprävention für Schulen absichern und verstetigen.', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=163', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7863, 9, 16, 'BE', 'Gewalthilfegesetz und Istanbul-Konvention in allen Senatsverwaltungen umsetzen; Landesanteil an der Finanzierung der Anti-Gewalt-Arbeit nicht durch Bundesmittel ersetzen.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=214', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7864, 9, 16, 'BE', 'Landeskoordinierungsstelle für die Umsetzung der Istanbul-Konvention einrichten.', '{904}', 7648, 1, 3, null, 'Ein Aktionsplan oder eine Koordinierungsstelle kann Zuständigkeiten klären und Lücken sichtbar machen. Ohne zusätzliche Mittel bleibt die Wirkung offen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=214', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7865, 9, 16, 'BE', 'Arbeit mit Täter*innen häuslicher Gewalt dauerhaft absichern; Täter*innenkurse verpflichtend anbieten.', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=214', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7866, 9, 16, 'BE', 'Fraueninfrastruktur wie Frauenhäuser und Beratungsstellen langfristig sichern, ausbauen und finanziell stärken.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=213', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7867, 9, 16, 'BE', 'Anonyme, vertrauliche Spurensicherung nach sexualisierter Gewalt flächendeckend, dezentral und rund um die Uhr verfügbar machen.', '{908}', 7652, 2, 3, null, 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=142', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7868, 9, 16, 'BE', 'Gewaltschutzambulanz ausbauen.', '{908}', 7652, 2, 3, null, 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=289', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7869, 9, 16, 'MV', 'Mehr Plätze in Frauenhäusern, barrierefreie Schutzorte sowie Ausbau und dauerhafte Absicherung von Beratungs- und Interventionsstellen und Täterarbeit.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=14', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7870, 9, 16, 'MV', 'Landesweites Hochrisikomanagement bei häuslicher Gewalt einführen, mit verbindlichen Verfahren zur Gefährdungseinschätzung besonders gefährdeter Frauen.', '{904}', 7645, 2, 3, null, 'Fallkonferenzen und standardisierte Risikoeinschätzung wie in Großbritannien und Spanien sollen Hochrisikofälle früh erkennen; Berichte melden weniger Wiederholungstaten, aber auch Fehleinschätzungen. Das Land kann es selbst einführen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=14', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7871, 9, 16, 'MV', 'Polizei durch ausreichende personelle und sachliche Ausstattung unterstützen.', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=20', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7872, 9, 16, 'MV', 'Kein Einsatz von Staatstrojanern, Vorratsdatenspeicherung oder automatisierter Gesichtserkennung (Verzicht auf diese Ermittlungsbefugnisse).', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=19', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7873, 9, 16, 'MV', 'Keine Nutzung von Palantir und keine allgegenwärtige Videoüberwachung.', '{901}', 7631, 0, 3, null, 'Die Ablehnung schützt Grundrechte, bringt die Sicherheit an unsicheren Orten aber nicht voran. Da Videoüberwachung Gewalt laut Meta-Analyse kaum senkt, kostet der Verzicht wenig.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=19', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7874, 9, 16, 'MV', 'E-Akte, Fachverfahren und Schnittstellen zu Polizei und anderen Institutionen interoperabel und zuverlässig gestalten.', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=24', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7875, 9, 16, 'MV', 'Arbeitsbedingungen in Gerichten, Staatsanwaltschaften und Justizvollzug verbessern, um die Berufe attraktiv zu machen.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=24', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7876, 9, 16, 'MV', 'Opferambulanzen dauerhaft absichern und personell wie sachlich stärken.', '{908}', 7652, 2, 3, null, 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=25', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7877, 9, 16, 'MV', 'Beratungs- und Interventionsstellen für queere Betroffene sexueller und körperlicher Gewalt ausbauen.', '{908}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=16', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7878, 9, 16, 'ST', '500 zusätzliche Polizeistellen bis 2030 für mehr Präsenz auf der Straße', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=128', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7879, 9, 16, 'ST', 'Flächendeckende E-Akte in der Justiz zur Beschleunigung der Verfahren', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=136', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7880, 9, 16, 'ST', 'Freie Stellen in der Justiz schnell besetzen und Fachpersonal durch Assistenz- und IT-Kräfte entlasten', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=136', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7881, 9, 16, 'ST', 'Fahren ohne Fahrschein nicht mehr strafbar machen, um Verfahren zu vermeiden', '{902}', 7658, 1, 1, null, 'Fahren ohne Fahrschein bindet viel Justizkapazität und führt oft zu Ersatzfreiheitsstrafen; eine Streichung entlastet. Schwere Taten werden dadurch nur indirekt schneller verfolgt, und das Land braucht den Bund.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=138', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'belegt', '2026-10-03', false, true, 'blind'),
  (7882, 9, 16, 'ST', 'Ersatzfreiheitsstrafen per Bundesratsinitiative abschaffen', '{902}', 7658, 1, 1, null, 'Fahren ohne Fahrschein bindet viel Justizkapazität und führt oft zu Ersatzfreiheitsstrafen; eine Streichung entlastet. Schwere Taten werden dadurch nur indirekt schneller verfolgt, und das Land braucht den Bund.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=140', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'belegt', '2026-10-03', false, true, 'blind'),
  (7883, 9, 16, 'ST', 'Keine automatisierte Datenanalysesoftware bei der Polizei einführen', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=129', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7884, 9, 16, 'ST', 'Mehr Streetwork, Jugendtreffs und Jugendzentren statt Jugendknast zur Kriminalitätsvorbeugung', '{903,901}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=134', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7885, 9, 16, 'ST', 'Häuser des Jugendrechts für schnelle, behördenübergreifende Reaktionen auf Jugendstraftaten einrichten', '{903}', 7640, 2, 3, null, 'Evaluationen zeigen eine bessere Zusammenarbeit von Polizei, Justiz und Jugendhilfe, teils kürzere Verfahren und weniger Rückfälle; Vergleichsgruppen fehlen oft. Länder können solche Häuser selbst einrichten.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=140', 'https://www.iss-ffm.de/themen/armut-und-armutsfolgen/projekte/evaluation-der-haeuser-des-jugendrechts-in-niedersachsen', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7886, 9, 16, 'ST', 'Im Jugendstrafrecht erzieherische Wirkung und alternative Maßnahmen statt Freiheitsentzug bevorzugen', '{903}', null, 1, 2, null, 'Erzieherische und ambulante Maßnahmen gehen nicht mit höheren Rückfallraten einher als Freiheitsentzug; Vergleiche sind aber durch Auswahl verzerrt. Das Jugendstrafrecht regelt der Bund, das Land kann ambulante Angebote fördern.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=140', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7887, 9, 16, 'ST', 'Frauenberatungsstellen stärken, Eigenanteil im Frauenschutzhaus abschaffen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=21', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7888, 9, 16, 'ST', 'Frauenhausplätze und Zufluchtswohnungen ausbauen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=24', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7889, 9, 16, 'ST', 'Bei hoher Risikoeinstufung Näherungsverbot digital überwachen, Sonderzuständigkeiten bei Justiz und Polizei', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=24', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7890, 9, 16, 'ST', 'Aufsuchende mobile Beratung für Betroffene häuslicher Gewalt schaffen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=23', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7891, 9, 16, 'ST', 'Anti-Gewalt-Programme für gewaltauffällige Personen als gerichtliche Auflage', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=24', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7892, 9, 16, 'ST', 'Schwerpunktstaatsanwaltschaften für geschlechtsspezifische Gewalt einrichten', '{904}', 7649, 1, 3, null, 'Spezialisierte Staatsanwälte und Kammern können Verfahren beschleunigen und Betroffene schonen. Belege für mehr Anzeigen oder Verurteilungen fehlen weitgehend.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=138', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7893, 9, 16, 'ST', 'Femizid als Mordmerkmal im Strafgesetzbuch per Bundesratsinitiative', '{904}', 7651, 1, 1, null, 'Höhere Strafen benennen Unrecht klarer. Die Forschung zeigt aber übereinstimmend, dass vor allem das Entdeckungsrisiko abschreckt, kaum die Strafhöhe. Das Strafrecht ändert der Bund, das Land kann nur werben.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=138', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7894, 9, 16, 'ST', 'Kostenlose Untersuchungen mit gerichtsverwertbarer Dokumentation in Opferschutzambulanzen, Erhalt und Ausbau', '{908}', 7652, 2, 3, null, 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=139', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7895, 9, 16, 'ST', 'Polizeistatistiken und Lagebilder veröffentlichen', '{909}', 7654, 1, 3, null, 'Wissenschaftlich eingeordnete Lagebilder und Dunkelfeldbefragungen machen das tatsächliche Geschehen sichtbar und sind leicht umsetzbar. Ob sie die öffentliche Wahrnehmung ändern, ist kaum untersucht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=128', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7896, 9, 17, 'BE', 'Intensivere Streifenpräsenz an Brennpunkten wie Bahnhöfen sowie in kriminalitätsbelasteten Parks und Plätzen.', '{901}', 7626, 3, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-03', false, true, 'blind'),
  (7897, 9, 17, 'BE', 'Beleuchtung und städtebauliche Kriminalprävention ausbauen, dunkle Ecken in Parks und auf Bahnhofsvorplätzen beseitigen.', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-03', false, true, 'blind'),
  (7898, 9, 17, 'BE', 'Videoüberwachung an besonders kriminalitätsbelasteten Orten, mit parlamentarischer Genehmigung, Echtzeit-Auswertung und längerer Speicherfrist bei BVG- und DB-Kameras.', '{901}', 7630, 1, 3, null, 'Videoüberwachung senkt Kriminalität laut Meta-Analyse moderat, vor allem Eigentumsdelikte auf Parkplätzen, kaum Gewalt. Aktiv beobachtete Kameras wirken stärker. Das Polizeirecht des Landes erlaubt den Ausbau an belasteten Orten.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', 'https://www.ojp.gov/library/publications/cctv-surveillance-crime-prevention-40-year-systematic-review-meta-analysis', 'belegt', '2026-10-03', false, true, 'blind'),
  (7899, 9, 17, 'BE', 'Zusätzliche gemeinsame Kontrollen von Ordnungsamt, Polizei und Zoll, auch im öffentlichen Raum.', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7900, 9, 17, 'BE', 'Öffentlichen Drogenkonsum im Umfeld von Schulen und Kitas ahnden, mit Platzverweisen und Sicherheitszonen.', '{901}', null, 1, 3, null, 'Platzverweise und Sicherheitszonen können Drogenkonsum vor Schulen und Kitas zurückdrängen, verlagern ihn aber oft nur. Das Land kann das im Ordnungsrecht regeln; Belege zur Wirkung fehlen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7901, 9, 17, 'BE', 'Einstellungsoffensive bei der Polizei mit Fokus auf qualitativ hochwertige Auswahl.', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=39', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7902, 9, 17, 'BE', 'Ausstattung der Polizei deutlich verbessern (Schutzkleidung, Fahrzeuge, IT, mobile Geräte) und Investitionsstau abbauen.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=39', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7903, 9, 17, 'BE', 'Digitalisierung bei Polizei und Feuerwehr vorantreiben für schnellere Vorgangsbearbeitung und weniger Bürokratie.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=39', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7904, 9, 17, 'BE', 'Deutlich mehr Richter- und Staatsanwaltsstellen.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7905, 9, 17, 'BE', 'Beschleunigte Verfahren bei Alltags- und Jugendkriminalität.', '{902,903}', 7639, 1, 3, null, 'Eine Evaluation des Neuköllner Modells zeigt schnellere Verfahren in geeigneten Fällen; eine Wirkung auf spätere Straftaten ist nicht belegt. Die Verfahren gibt es schon, Länder können sie organisatorisch stärken.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', 'https://jugendsozialarbeit.news/evaluation_beschleunigtes_jugendverfahren/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7906, 9, 17, 'BE', 'Konsequente Vermögensabschöpfung bei organisierter Kriminalität, Erlöse für Polizei und Feuerwehr.', '{902}', 7655, 1, 3, null, 'Vermögensabschöpfung trifft kriminelle Strukturen finanziell und ist eine spürbare Tatfolge. Auf die Aufklärung alltäglicher Straftaten wirkt sie kaum, Wirkungsstudien fehlen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7907, 9, 17, 'BE', 'Gemeinsame Ermittlungsgruppen ausbauen.', '{902}', 7657, 1, 3, null, 'Dauerhafte Ermittlungsgruppen bündeln Wissen gegen organisierte Kriminalität. Auf die Aufklärung der vielen alltäglichen Taten wirken sie kaum, und Belege zur Wirkung fehlen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=41', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7908, 9, 17, 'BE', 'Flächendeckende Präventions- und Anti-Gewaltprogramme an Schulen.', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7909, 9, 17, 'BE', 'Präventionsprojekte in stark betroffenen Communities, Ausbau der Jugendarbeit gegen Messerangriffe und schwere Gewalt.', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7910, 9, 17, 'BE', 'Elektronische Fußfessel bei Annäherungsverbot mit Warnsystem für Betroffene nach spanischem Modell.', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7911, 9, 17, 'BE', 'Angebot an Frauenhäusern ausbauen, mit mehrsprachigen Hinweisen auf Hilfsangebote.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7912, 9, 17, 'MV', 'Mehr Personal im Streifen- und Ermittlungsdienst, um Präsenz in Problem- und Brennpunktbereichen zu stärken.', '{901,902}', 7626, 3, 2, null, 'Studien zur gezielten Polizeipräsenz an Brennpunkten zeigen weniger Kriminalität ohne Verdrängung, teils mit Nutzen für das Umfeld. Die Landespolizei ist zuständig, doch Personal für dauerhafte Präsenz ist knapp.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=67', 'https://www.ojp.gov/library/publications/hot-spots-policing-and-crime-reduction-update-ongoing-systematic-review-and', 'belegt', '2026-10-03', false, true, 'blind'),
  (7913, 9, 17, 'MV', 'Mehr Einsatzkräfte statt Ausweitung der Videoüberwachung im öffentlichen Raum.', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=67', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7914, 9, 17, 'MV', 'Zeitgemäße Ausstattung, Technik sowie Aus- und Fortbildung der Polizei.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=67', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7915, 9, 17, 'MV', 'Polizeibesoldung und Zulagen an westliche Länder und den Bund angleichen, bessere Aufstiegschancen.', '{902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=68', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7916, 9, 17, 'MV', 'Mehr Richter, Staatsanwälte und Servicekräfte in der Justiz.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=69', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7917, 9, 17, 'MV', 'Schulen mit multiprofessionellen Teams (u. a. Sozialarbeit) ausstatten, um Gewalt vorzubeugen.', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7918, 9, 17, 'MV', 'Ausbau von Täterarbeit zur Verhinderung von Wiederholungstaten bei Gewalt gegen Frauen.', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=71', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7919, 9, 17, 'MV', 'Mehr Frauenhausplätze und Schutzwohnungen im ganzen Land, besonders im ländlichen Raum.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=72', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7920, 9, 17, 'MV', 'Konsequente Wegweisungen und Annäherungsverbote zum schnellen Schutz Betroffener.', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=72', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7921, 9, 17, 'MV', 'Landesaktionsplan gegen Gewalt mit klaren Zuständigkeiten.', '{904}', 7648, 1, 3, null, 'Ein Aktionsplan oder eine Koordinierungsstelle kann Zuständigkeiten klären und Lücken sichtbar machen. Ohne zusätzliche Mittel bleibt die Wirkung offen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=72', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7922, 9, 17, 'ST', 'Mehr sichtbare Polizeipräsenz in Städten, Vierteln und Dörfern sowie mehr Mittel für attraktive Innenstädte und Quartiere.', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=67', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7923, 9, 17, 'ST', 'Landespolizei bis 2028 auf rund 7.000 Beamte aufstocken, auch für Präsenz und Ermittlungsarbeit.', '{901,902}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=68', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7924, 9, 17, 'ST', 'Polizei und Ermittlungsbehörden so ausstatten, dass sie gegen organisierte Kriminalität handlungsfähig sind.', '{902}', 7657, 1, 3, null, 'Dauerhafte Ermittlungsgruppen bündeln Wissen gegen organisierte Kriminalität. Auf die Aufklärung der vielen alltäglichen Taten wirken sie kaum, und Belege zur Wirkung fehlen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=67', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7925, 9, 17, 'ST', 'Keine Palantir-Software und vergleichbare Systeme zur automatisierten Datenverknüpfung bei der Polizei.', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=67', null, 'gemischt', '2026-10-03', false, true, 'blind'),
  (7926, 9, 17, 'ST', 'Richter- und Staatsanwaltsbesoldung verbessern, mehr Planungssicherheit bei Einstellungen, Einstellungsstopp im Justizdienst aufheben.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=71', null, 'belegt', '2026-10-03', false, true, 'blind'),
  (7927, 9, 17, 'ST', 'Frauenhäuser, Beratungsstellen und Schutzwohnungen dauerhaft und auskömmlich finanzieren, unabhängig von kommunaler Haushaltslage.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=37', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-03', false, true, 'blind'),
  (7928, 9, 17, 'ST', 'Gewaltambulanzen langfristig absichern und landesweit ausbauen, auch telemedizinisch.', '{908}', 7652, 2, 3, null, 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=38', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7929, 9, 17, 'ST', 'Femizide systematisch erfassen; Landeskriminalamt richtet ein eigenes Monitoring ein.', '{904}', 7647, 1, 3, null, 'Eine einheitliche Erfassung verbessert das Lagebild und kann Prävention gezielter machen. Sie verhindert selbst keine Taten, und zur Wirkung gibt es kaum Daten.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=38', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7930, 9, 17, 'ST', 'Verbindlichen Landesaktionsplan zur Umsetzung der Istanbul-Konvention verabschieden.', '{904}', 7648, 1, 3, null, 'Ein Aktionsplan oder eine Koordinierungsstelle kann Zuständigkeiten klären und Lücken sichtbar machen. Ohne zusätzliche Mittel bleibt die Wirkung offen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=38', null, 'offen', '2026-10-03', false, true, 'blind'),
  (7931, 9, 17, 'ST', 'Mehr Sozialarbeiter in der Jugendarbeit; Gewalt- und Extremismuspräventionsprojekte weiter vom Land fördern.', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=65', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-03', false, true, 'blind'),
  (7943, 18, 11, null, 'Flächendeckende Pflichtversicherung für Elementarschäden einführen', '{1806}', null, 3, 2, null, 'Setzt direkt an der Versicherungslücke an: Frankreich erreicht mit verpflichtender Deckung rund 98 %, Deutschland rund 50 %. Verfassungsrechtlich laut Justizministerkonferenz möglich; Prämien in Risikogebieten bleiben strittig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=25', 'https://www.bundestag.de/dokumente/textarchiv/2024/kw11-pa-recht-elementarschadenversicherung-991898', 'belegt', '2026-10-04', false, true, 'blind'),
  (7944, 18, 11, null, 'Küsten- und Hochwasserschutz priorisieren und von der Ausgleichspflicht für solche Maßnahmen wegkommen', '{1805}', null, 1, 2, null, 'Weniger Ausgleichspflichten können Hochwasserschutzbauten beschleunigen. Dagegen: Kein zusätzliches Geld oder Vorhaben, Bauen in Überschwemmungsgebieten bleibt unberührt, EU-Naturschutzrecht begrenzt den Spielraum.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=25', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7945, 18, 11, null, 'Flächenversiegelung reduzieren und Flächen klüger nutzen', '{1804}', 7941, 1, 2, null, 'Begrünung und Entsiegelung wirken nachweislich gegen Hitze und Abfluss; die Zusage nennt aber weder Instrument noch Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=26', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7946, 18, 11, null, 'Städte und Gemeinden bei Wassermanagement und verstärkter Begrünung unterstützen', '{1803}', 7941, 1, 2, null, 'Begrünung und Entsiegelung wirken nachweislich gegen Hitze und Abfluss; die Zusage nennt aber weder Instrument noch Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=77', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7947, 18, 11, null, 'CO2-Bepreisung zum Leitinstrument ausbauen, Einnahmen zurückgeben', '{1801,1802}', 7932, 1, 2, null, 'CO2-Preise senken Emissionen nachweislich (Metaanalyse: im Mittel rund 10 %). Auf Hitze in Deutschland wirkt nationaler Klimaschutz aber nur als kleiner Beitrag zum globalen Klimaschutz und mit großer Verzögerung.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11099057/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7948, 18, 11, null, 'Heizungsgesetz abschaffen, stattdessen technologieoffen emissionsarme Wärme fördern', '{1801,1802}', 7939, 0, 2, null, 'Lockert eine Vorgabe zur Emissionsminderung bei Heizungen und hilft nicht gegen Hitze oder Unwetterschäden. Per Bundesgesetz änderbar, EU-Gebäuderichtlinie setzt aber Grenzen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=22', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7949, 18, 11, null, 'Verbrenner-Verbot rückgängig machen', '{1801,1802}', 7938, 0, 1, null, 'Lockert eine Emissionsvorgabe und setzt an keiner Ursache im Sinne des Ziels an. Die Vorgabe ist EU-Recht; Deutschland kann sie nicht allein aufheben, sondern nur im EU-Verfahren darauf hinwirken.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=74', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7950, 18, 11, null, 'Kein weiteres endgültiges Abschalten von Kohlekraftwerken, bevor Ersatz gebaut ist', '{1801,1802}', 7936, 0, 2, null, 'Längerer Kohlebetrieb erhöht die Emissionen gegenüber einem Ausstieg (Studien: deutliche Minderung durch Ausstieg) und hilft nicht gegen Hitze; per Gesetz änderbar, aber durch CO2-Preise im EU-Emissionshandel wirtschaftlich fraglich.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=21', 'https://www.ewi.uni-koeln.de/en/news/neue-ewi-studie-kohleausstieg-ermoeglicht-erreichung-der-klimaziele-2030/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7951, 18, 11, null, 'Moorschutz intensivieren und Anreize für Wiedervernässung geben', '{1801,1802}', null, 1, 2, null, 'Entwässerte Moore verursachen rund 7,5 % der deutschen Emissionen; Wiedervernässung senkt sie deutlich. Dagegen: Umsetzung braucht Einigung mit Eigentümern und Zeit; die Wirkung auf Hitze bleibt gering.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=25', 'https://www.bundesumweltministerium.de/faq/warum-ist-die-wiedervernaessung-von-mooren-so-wichtig', 'belegt', '2026-10-04', false, true, 'blind'),
  (7952, 18, 11, null, 'Rahmenbedingungen für Kohlenstoffabscheidung, -nutzung und -speicherung samt Transportinfrastruktur schaffen', '{1801,1802}', 7935, 1, 3, null, 'Seit Ende 2025 ist kommerzielles CCS rechtlich möglich; es kann schwer vermeidbare Industrieemissionen senken. Dagegen: Infrastruktur braucht 7 bis 10 Jahre, Kosten und Umfang sind unsicher; Wirkung auf Hitze gering.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=24', 'https://www.bundesregierung.de/breg-de/aktuelles/speicherung-von-kohlendioxid-2376946', 'gemischt', '2026-10-04', false, true, 'blind'),
  (7953, 18, 12, null, 'Städtebauförderung zur Klimaanpassung: Begrünung, Entsiegelung (Schwammstadt) und kühlende öffentliche Räume in Städten.', '{1803}', 7940, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C im Umfeld); der Bund fördert Städtebau bereits. Dagegen: Wirkung bleibt lokal und hängt von Umsetzung in den Kommunen ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7954, 18, 12, null, 'Vorsorge gegen Klimafolgen wie Hitzewellen im Bevölkerungsschutz stärken.', '{1801}', null, 1, 3, null, 'Vorsorge gegen Hitzewellen im Bevölkerungsschutz ist sinnvoll und umsetzbar. Dagegen: Die Zusage nennt kein konkretes Instrument, daher ist die Wirkung kaum abschätzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=46', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7955, 18, 12, null, 'Kommunale Wärmepläne für klimaneutrale Wärmeversorgung fördern.', '{1801,1802}', 7934, 1, 3, null, 'Erneuerbare vermieden 2024 laut UBA rund 259 Mio. t CO2-Äquivalente; Förderprogramme bestehen. Auf Hitzetage in Deutschland wirkt das nur als kleiner Teil des globalen Klimaschutzes und mit Verzögerung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=33', 'https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024', 'belegt', '2026-10-04', false, true, 'blind'),
  (7956, 18, 12, null, 'Mittel aus Aktionsprogramm Natürlicher Klimaschutz flächendeckend einsetzen, um Wälder, Moore, Flussauen und Stadtgrün zu schützen.', '{1801,1802,1803}', null, 1, 3, null, 'Das bestehende Förderprogramm stärkt Senken und Stadtgrün und ist finanziert. Dagegen: Die Mittel verteilen sich breit, der Beitrag zur Kühlung von Städten und zur Hitzevermeidung bleibt gering.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=53', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7957, 18, 12, null, 'Windkraft und Fotovoltaik konsequent ausbauen und mit Speichern einbinden.', '{1801,1802}', 7934, 1, 3, null, 'Erneuerbare vermieden 2024 laut UBA rund 259 Mio. t CO2-Äquivalente; Förderprogramme bestehen. Auf Hitzetage in Deutschland wirkt das nur als kleiner Teil des globalen Klimaschutzes und mit Verzögerung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=34', 'https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024', 'belegt', '2026-10-04', false, true, 'blind'),
  (7958, 18, 13, null, 'Europäischen Emissionshandel für Verkehr und Gebäude unterstützen und den CO₂-Preis als zentralen Hebel stärken', '{1801,1802}', 7932, 1, 2, null, 'CO2-Preise senken Emissionen nachweislich (Metaanalyse: im Mittel rund 10 %). Auf Hitze in Deutschland wirkt nationaler Klimaschutz aber nur als kleiner Beitrag zum globalen Klimaschutz und mit großer Verzögerung.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=38', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11099057/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7959, 18, 13, null, 'Sektorverantwortung im Klimaschutzgesetz stärken, bei Zielverfehlung verbindlich nachsteuern', '{1801,1802}', 7933, 1, 3, null, 'Verbindliche Sektorziele erhöhen den Druck zum Nachsteuern und sind per Gesetzesänderung umsetzbar; ihre eigene Wirkung ist kaum belegt, und auf die Hitze in Deutschland wirkt nationaler Klimaschutz nur langfristig und gering.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=39', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7960, 18, 13, null, 'Alle verbliebenen Kohlekraftwerke ab 2030 nicht mehr befeuern, Kohleförderung beenden, fossiles Gas schrittweise reduzieren', '{1801,1802}', null, 1, 2, null, 'Ein Kohleausstieg senkt die Emissionen des Stromsektors deutlich (Studien). Dagegen: Ersatzkraftwerke und Versorgungssicherheit bis 2030 sind ungeklärt, und die Wirkung auf Hitze in Deutschland ist gering und verzögert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=43', 'https://www.ewi.uni-koeln.de/en/news/neue-ewi-studie-kohleausstieg-ermoeglicht-erreichung-der-klimaziele-2030/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7961, 18, 13, null, 'Förderung für fossilfreie Heizungen und Wärmenetze ausbauen, Energieberatung ausbauen', '{1801,1802}', 7934, 1, 3, null, 'Erneuerbare vermieden 2024 laut UBA rund 259 Mio. t CO2-Äquivalente; Förderprogramme bestehen. Auf Hitzetage in Deutschland wirkt das nur als kleiner Teil des globalen Klimaschutzes und mit Verzögerung.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=44', 'https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024', 'belegt', '2026-10-04', false, true, 'blind'),
  (7962, 18, 13, null, 'Hochwasserschutz mit den Ländern verbessern: natürliche Überschwemmungsräume, Auen mehr Raum, Deiche und Rückhaltesysteme, beschleunigte Umsetzung', '{1805}', 7942, 2, 3, null, 'Rückhalteräume und Auen dämpfen Hochwasserscheitel nachweislich, der Bund fördert Hochwasserschutz bereits mit. Dagegen: Deiche verlagern Risiken teils flussabwärts und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=46', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-04', false, true, 'blind'),
  (7963, 18, 13, null, 'Städte gegen Hitzewellen und Starkregen schützen: mehr Entsiegelung, Frischluftschneisen, Gebäude- und Stadtgrün, Trinkbrunnen, Schwammstadt', '{1802,1803,1804}', 7940, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C im Umfeld); der Bund fördert Städtebau bereits. Dagegen: Wirkung bleibt lokal und hängt von Umsetzung in den Kommunen ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=46', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7964, 18, 13, null, 'Versicherungsschutz gegen Elementarschäden sozialverträglich ausweiten', '{1806}', null, 2, 2, null, 'Setzt an der Versicherungslücke an; Erfahrungen anderswo zeigen, dass verbindliche Modelle die Deckung stark erhöhen. Dagegen: Ohne bestimmtes Instrument (Pflicht oder Angebotsmodell) ist der Umfang der Verbesserung offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=46', 'https://www.bundestag.de/dokumente/textarchiv/2024/kw11-pa-recht-elementarschadenversicherung-991898', 'belegt', '2026-10-04', false, true, 'blind'),
  (7965, 18, 13, null, 'Nationalen Hitzeschutzplan ausbauen und Hitzeaktionspläne in allen Kommunen', '{1802}', null, 3, 2, null, 'Hitzeschutzpläne senkten die hitzebedingte Übersterblichkeit in Europa um rund 25 %. Dagegen: Pläne in allen Kommunen kann der Bund nicht vorschreiben, nur fördern und mit Ländern vereinbaren.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=96', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC12724396/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7966, 18, 13, null, 'Flächenverbrauch mit neuen Instrumenten (Flächenzertifikatehandel, Baulandabgabemodell) bis 2030 auf 30 Hektar pro Tag senken', '{1804}', null, 2, 2, null, 'Ein Planspiel mit 87 Kommunen zeigte, dass Flächenzertifikate Neuversiegelung wirksam begrenzen können. Dagegen: Reale Erfahrungen fehlen, und die Einführung braucht neue Bundesregeln und Akzeptanz der Kommunen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=73', 'https://www.umweltbundesamt.de/themen/flaechenzertifikatehandel-flaechenverbauchsziele', 'offen', '2026-10-04', false, true, 'blind'),
  (7967, 18, 14, null, 'Einheitlicher europäischer Emissionshandel als Leitinstrument der Klimapolitik, mit global angestrebtem Preis für Treibhausgase', '{1801,1802}', null, 1, 1, null, 'Emissionshandel senkt Emissionen nachweislich. Dagegen: Ein einheitlicher EU-Handel hängt von EU-Entscheidungen ab, ein globaler Preis von anderen Staaten; die Wirkung auf Hitze in Deutschland ist gering.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11099057/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7968, 18, 14, null, 'Nationales Klimaneutralitätsziel 2045 im Klimaschutzgesetz durch das europäische Ziel 2050 ersetzen', '{1801,1802}', null, 0, 1, null, 'Ein späteres Klimaneutralitätsziel bremst Emissionsminderung und hilft nicht gegen Hitze. Rechtlich heikel, weil das Bundesverfassungsgericht einen ausreichenden Reduktionspfad verlangt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7969, 18, 14, null, 'Abscheidung und Speicherung von Treibhausgasen (CCS/CCU) diskriminierungsfrei als Klimaschutz-Option ermöglichen', '{1801,1802}', 7935, 1, 3, null, 'Seit Ende 2025 ist kommerzielles CCS rechtlich möglich; es kann schwer vermeidbare Industrieemissionen senken. Dagegen: Infrastruktur braucht 7 bis 10 Jahre, Kosten und Umfang sind unsicher; Wirkung auf Hitze gering.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', 'https://www.bundesregierung.de/breg-de/aktuelles/speicherung-von-kohlendioxid-2376946', 'gemischt', '2026-10-04', false, true, 'blind'),
  (7970, 18, 14, null, 'Heizungsgesetz vollständig auslaufen lassen; stattdessen Zertifikatehandel', '{1801,1802}', 7939, 0, 2, null, 'Lockert eine Vorgabe zur Emissionsminderung bei Heizungen und hilft nicht gegen Hitze oder Unwetterschäden. Per Bundesgesetz änderbar, EU-Gebäuderichtlinie setzt aber Grenzen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=45', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7971, 18, 14, null, 'Faktisches Verbrenner-Verbot ab 2035 umgehend aufheben', '{1801,1802}', 7938, 0, 1, null, 'Lockert eine Emissionsvorgabe und setzt an keiner Ursache im Sinne des Ziels an. Die Vorgabe ist EU-Recht; Deutschland kann sie nicht allein aufheben, sondern nur im EU-Verfahren darauf hinwirken.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=40', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7972, 18, 14, null, 'Erneuerbare Energien ohne EEG-Subventionen für neue Anlagen vollständig in den Markt überführen', '{1801,1802}', null, 0, 2, null, 'Marktintegration kann Förderkosten senken; ohne Absicherung droht aber ein langsamerer Ausbau, der Emissionen weniger senkt. Ein Beitrag gegen Hitze ist nicht zu erwarten; EEG-Änderung möglich.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', null, 'gemischt', '2026-10-04', false, true, 'blind'),
  (7973, 18, 14, null, 'Bau neuer Kernkraftwerke und Wiederinbetriebnahme vorhandener rechtlich ermöglichen, ohne Subventionen', '{1801,1802}', null, 0, 1, null, 'Kernkraft ist emissionsarm, ohne Subventionen ist ein Neubau aber nicht absehbar; ob vorhandene Anlagen reaktiviert werden können, ist umstritten. In einer Wahlperiode ist keine Wirkung auf Emissionen zu erwarten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', null, 'gemischt', '2026-10-04', false, true, 'blind'),
  (7974, 18, 15, null, 'Geplanten Ausstieg aus der Braunkohleverstromung nicht umsetzen, Kohlekraftwerke ausbauen.', '{1801,1802}', 7936, 0, 2, null, 'Längerer Kohlebetrieb erhöht die Emissionen gegenüber einem Ausstieg (Studien: deutliche Minderung durch Ausstieg) und hilft nicht gegen Hitze; per Gesetz änderbar, aber durch CO2-Preise im EU-Emissionshandel wirtschaftlich fraglich.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=42', 'https://www.ewi.uni-koeln.de/en/news/neue-ewi-studie-kohleausstieg-ermoeglicht-erreichung-der-klimaziele-2030/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7975, 18, 15, null, 'Wiedereinstieg in die Kernenergie, bestehende Kraftwerke so schnell wie möglich wieder in Betrieb nehmen.', '{1801,1802}', null, 0, 1, null, 'Der zugleich geplante Ausbau von Kohlekraftwerken erhöht Emissionen. Eine Rückkehr zur Kernenergie wäre in einer Wahlperiode kaum wirksam, weil der Rückbau fortgeschritten ist und Betreiber eine Reaktivierung ablehnen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=42', null, 'gemischt', '2026-10-04', false, true, 'blind'),
  (7976, 18, 15, null, 'Abgabe auf CO₂ abschaffen.', '{1801,1802}', 7937, 0, 2, null, 'Entfernt ein nachweislich emissionsmindernd wirkendes Instrument und hilft nicht gegen Hitze. National möglich, ab 2028 greift für Verkehr und Gebäude aber ohnehin der EU-Emissionshandel.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11099057/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7977, 18, 15, null, 'Verbot von Gas- und Ölheizungen aufheben.', '{1801,1802}', 7939, 0, 2, null, 'Lockert eine Vorgabe zur Emissionsminderung bei Heizungen und hilft nicht gegen Hitze oder Unwetterschäden. Per Bundesgesetz änderbar, EU-Gebäuderichtlinie setzt aber Grenzen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=14', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7978, 18, 15, null, 'Verbot des Verbrennungsmotors aufheben.', '{1801,1802}', 7938, 0, 1, null, 'Lockert eine Emissionsvorgabe und setzt an keiner Ursache im Sinne des Ziels an. Die Vorgabe ist EU-Recht; Deutschland kann sie nicht allein aufheben, sondern nur im EU-Verfahren darauf hinwirken.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=42', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7979, 18, 15, null, 'Weiteren Ausbau der Windenergie ablehnen.', '{1801,1802}', null, 0, 2, null, 'Ein Stopp des Windausbaus bremst die Verdrängung fossiler Stromerzeugung, die nachweislich Emissionen vermeidet, und hilft nicht gegen Hitze. Erfordert Änderungen an EEG und Planungsrecht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=81', 'https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024', 'belegt', '2026-10-04', false, true, 'blind'),
  (7980, 18, 15, null, 'Aus dem Pariser Klimaabkommen aussteigen.', '{1801,1802}', null, 0, 2, null, 'Der Austritt schwächt internationale Klimaschutzverpflichtungen und hilft nicht gegen Hitze. Rechtlich per Kündigung möglich; EU-Klimarecht bliebe bindend.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=80', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7981, 18, 16, null, 'Kitas und Schulen besser vor Hitzewellen schützen, Investitionsmittel dafür bereitstellen', '{1802}', null, 1, 2, null, 'Kinder leiden bei Hitze häufig gesundheitlich, Investitionen in Kitas und Schulen helfen ihnen. Dagegen: Die meisten Hitzetoten sind über 75; Kitas und Schulen sind Sache von Ländern und Kommunen, der Bund kann nur mitfinanzieren.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7982, 18, 16, null, 'Mehr öffentliche Parks und Grünflächen gegen die Hitze sowie öffentliche Wasserspender; Gebäude- und Flächenbegrünung ausweiten', '{1803,1802}', 7940, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C im Umfeld); der Bund fördert Städtebau bereits. Dagegen: Wirkung bleibt lokal und hängt von Umsetzung in den Kommunen ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7983, 18, 16, null, 'Flächenentsiegelung vorantreiben, Städte zu Schwammstädten machen und vor Flutkatastrophen schützen', '{1804}', 7941, 1, 2, null, 'Begrünung und Entsiegelung wirken nachweislich gegen Hitze und Abfluss; die Zusage nennt aber weder Instrument noch Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7984, 18, 16, null, 'Luftaustausch zwischen Stadt und Umland durch bessere Raumplanung verbessern', '{1803}', null, 2, 2, null, 'Kaltluftbahnen aus dem Umland verbessern die nächtliche Abkühlung von Städten. Dagegen: Die Planung liegt überwiegend bei Ländern und Kommunen, der Bund kann nur über Raumordnung und Baurecht beitragen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', 'https://www.vdi.de/news/detail/lokale-kaltluft-in-staedten-ein-wichtiger-baustein-im-zuge-der-klimaanpassung', 'belegt', '2026-10-04', false, true, 'blind'),
  (7985, 18, 16, null, 'Klimaanpassung als Gemeinschaftsaufgabe von Bund, Ländern und Kommunen definieren, Katastrophenschutz massiv aufwerten', '{1801}', null, 2, 1, null, 'Eine Gemeinschaftsaufgabe würde dauerhafte Mischfinanzierung von Anpassung durch Bund und Länder ermöglichen. Dagegen: Grundgesetzänderung mit Zweidrittelmehrheiten nötig, Wirkung hängt von späteren Mitteln ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=33', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7986, 18, 16, null, 'Sektorziele im Klimaschutzgesetz wiederherstellen, verbindliche Ziele und Emissionsgrenzen', '{1801,1802}', 7933, 1, 3, null, 'Verbindliche Sektorziele erhöhen den Druck zum Nachsteuern und sind per Gesetzesänderung umsetzbar; ihre eigene Wirkung ist kaum belegt, und auf die Hitze in Deutschland wirkt nationaler Klimaschutz nur langfristig und gering.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=33', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7987, 18, 16, null, 'Emissionshandel für Wärme und Verkehr (ETS-2) ablehnen, stattdessen verbindliche Klimaziele und Emissionsgrenzen', '{1801,1802}', null, 1, 1, null, 'Verbindliche Ziele und Grenzen können Emissionen senken. Dagegen: Der EU-Emissionshandel für Wärme und Verkehr ist beschlossenes EU-Recht, das Deutschland nicht allein abwählen kann; Wirkung auf Hitze gering.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=33', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7988, 18, 17, null, 'Nationalen CO2-Preis abschaffen.', '{1801,1802}', 7937, 0, 2, null, 'Entfernt ein nachweislich emissionsmindernd wirkendes Instrument und hilft nicht gegen Hitze. National möglich, ab 2028 greift für Verkehr und Gebäude aber ohnehin der EU-Emissionshandel.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11099057/', 'belegt', '2026-10-04', false, true, 'blind'),
  (7989, 18, 17, null, 'Verbrenner-Verbot zurücknehmen.', '{1801,1802}', 7938, 0, 1, null, 'Lockert eine Emissionsvorgabe und setzt an keiner Ursache im Sinne des Ziels an. Die Vorgabe ist EU-Recht; Deutschland kann sie nicht allein aufheben, sondern nur im EU-Verfahren darauf hinwirken.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=29', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7990, 18, 17, null, 'Heizungsgesetz sofort abschaffen und durch andere Regelungen ersetzen.', '{1801,1802}', 7939, 0, 2, null, 'Lockert eine Vorgabe zur Emissionsminderung bei Heizungen und hilft nicht gegen Hitze oder Unwetterschäden. Per Bundesgesetz änderbar, EU-Gebäuderichtlinie setzt aber Grenzen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'offen', '2026-10-04', false, true, 'blind'),
  (7991, 18, 17, null, 'Bau von CCS- und CCU-Anlagen durch Superabschreibungen oder öffentliche Kredite fördern.', '{1801,1802}', 7935, 1, 3, null, 'Seit Ende 2025 ist kommerzielles CCS rechtlich möglich; es kann schwer vermeidbare Industrieemissionen senken. Dagegen: Infrastruktur braucht 7 bis 10 Jahre, Kosten und Umfang sind unsicher; Wirkung auf Hitze gering.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=12', 'https://www.bundesregierung.de/breg-de/aktuelles/speicherung-von-kohlendioxid-2376946', 'gemischt', '2026-10-04', false, true, 'blind'),
  (7992, 18, 17, null, 'Repowering-Programm: alte Windanlagen durch neue ersetzen.', '{1801,1802}', 7934, 1, 3, null, 'Erneuerbare vermieden 2024 laut UBA rund 259 Mio. t CO2-Äquivalente; Förderprogramme bestehen. Auf Hitzetage in Deutschland wirkt das nur als kleiner Teil des globalen Klimaschutzes und mit Verzögerung.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=11', 'https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024', 'belegt', '2026-10-04', false, true, 'blind'),
  (7993, 18, 17, null, 'Fernwärme ausbauen und auf erneuerbare Quellen umstellen, Geothermie-Ausbauziele anheben.', '{1801,1802}', 7934, 1, 3, null, 'Erneuerbare vermieden 2024 laut UBA rund 259 Mio. t CO2-Äquivalente; Förderprogramme bestehen. Auf Hitzetage in Deutschland wirkt das nur als kleiner Teil des globalen Klimaschutzes und mit Verzögerung.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=12', 'https://www.umweltbundesamt.de/publikationen/emissionsbilanz-erneuerbarer-energietrager-2024', 'belegt', '2026-10-04', false, true, 'blind'),
  (7994, 18, 17, null, 'Mittel für Auf- und Ausbau von Deichen und Dämmen bereitstellen, Folgen von Hochwasser abmildern.', '{1805}', 7942, 2, 3, null, 'Rückhalteräume und Auen dämpfen Hochwasserscheitel nachweislich, der Bund fördert Hochwasserschutz bereits mit. Dagegen: Deiche verlagern Risiken teils flussabwärts und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=20', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-04', false, true, 'blind'),
  (7995, 6, 14, null, 'Kein Anspruch auf Sozialleistungen für Personen, die Identitätsfeststellungsverfahren aktiv behindern', '{604}', null, 1, 2, null, 'Leistungskürzung bei Verweigerung der Mitwirkung kann Anreiz zur Identitätsklärung setzen; Wirkung auf Rückführungen ist kaum untersucht, die Hauptursache liegt oft bei Herkunftsstaaten. Das Existenzminimum begrenzt Kürzungen, Bundesgesetz möglich.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'offen', '2026-10-05', false, true, 'blind'),
  (7996, 6, 15, null, 'Asylantragstellung nur bei nachgewiesener Identität und Staatsangehörigkeit', '{604}', null, 1, 0, null, 'Identitätsklärung ist ein Hauptproblem bei Rückführungen, aber wer ohne Papiere flieht, könnte gar keinen Antrag mehr stellen; das widerspricht dem Zugang zum Asylverfahren (Grundgesetz, EU-Recht, Genfer Konvention). Wirkung auf Rückführungen kaum untersucht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=104', null, 'offen', '2026-10-05', false, true, 'blind'),
  (7997, 6, 15, null, 'Asylrecht entfällt bei Falschangaben zur Identität im Asylverfahren', '{604}', null, 1, 1, null, 'Sanktion für Täuschung kann Anreize zu korrekten Angaben setzen, klärt aber keine Identität und löst nicht das Papierproblem. Der Wegfall des Asylrechts berührt Art. 16a GG und Flüchtlingsschutz nach EU-Recht; nur mit großen Hürden.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=105', null, 'offen', '2026-10-05', false, true, 'blind'),
  (7998, 9, 12, 'ST', 'Bürokratische Belastungen der Polizei werden reduziert, damit sich Beschäftigte auf Kernaufgaben konzentrieren können.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=29', null, 'offen', '2026-10-05', false, true, 'blind'),
  (7999, 9, 14, 'MV', 'Polizei von Bürokratie entlasten: Dokumentationspflichten und interne Verwaltungsaufgaben deutlich reduzieren und auf Verwaltungsangestellte übertragen.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=133', null, 'offen', '2026-10-05', false, true, 'blind'),
  (8000, 9, 15, 'MV', 'Die im Landespolizeigesetz (SOG) beschlossenen Dokumentationspflichten für die Polizei sollen sofort zurückgenommen werden.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=38', null, 'offen', '2026-10-05', false, true, 'blind'),
  (8001, 15, 16, null, 'Ablehnung des europäischen Emissionshandels für Wärme und Verkehr (ETS-2); stattdessen verbindliche Klimaziele und Emissionsgrenzen, damit kein CO₂-Preis auf Kraftstoffe entsteht.', '{1502}', 7011, 2, 1, null, 'Senkt den Spritpreis 2026 um rund 15 bis 18 Cent je Liter; ab 2028 gilt aber der europäische Emissionshandel für Verkehr, den Deutschland nicht allein abschaffen kann. Die Einnahmen fehlen für Entlastungen an anderer Stelle.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=33', null, 'belegt', '2026-10-05', false, true, null),
  (8002, 9, 11, 'BE', 'Berichts- und Dokumentationspflichten der Polizei stark zurückfahren und überarbeiten', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=8', null, 'offen', '2026-10-05', false, true, 'blind'),
  (8003, 9, 11, 'MV', 'Durch Technik, Automatisierung und KI den Zeitanteil bürokratischer Routineprozesse im Polizeidienst deutlich verringern, damit mehr Zeit für Prävention und Strafverfolgung bleibt.', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=28', null, 'offen', '2026-10-05', false, true, 'blind'),
  (8059, 27, 11, null, 'Springerpools puffern Belastungsspitzen ab und planbare Einsatzzeiten verbessern die Arbeitsbedingungen.', '{2701,2702}', 8023, 2, 2, null, 'Pools können kurzfristige Ausfälle auffangen und planbare Einsatzzeiten fördern. Modellierungen zeigen, dass flexible Kräfte eine ausreichende Grundbesetzung nicht ersetzen und bei knapper Verfügbarkeit wenig verlässlich sind.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', 'https://europepmc.org/article/MED/33677251', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8060, 27, 11, null, 'Dokumentationsprozesse mit hohem Zeitaufwand vereinfachen.', '{2703}', 8015, 2, 2, null, 'Weniger unnötige Dokumentation kann unmittelbar Arbeitszeit freisetzen. Forschung misst die Belastung uneinheitlich und untersucht die Wirkung konkreter Vereinfachungen bislang nur begrenzt; notwendige Qualitäts- und Sicherheitsnachweise bleiben erforderlich.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=72', 'https://europepmc.org/article/MED/33434273', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8061, 27, 11, null, 'Durch Änderungen im Tarifvertragsgesetz die Bereitschaft zur Tarifbindung stützen.', '{2704}', 8019, 2, 3, null, 'Erleichterte Tarifbindung und Allgemeinverbindlichkeit können die Reichweite ausgehandelter Entlohnung verbessern. Der Effekt auf die Belastung hängt von den vereinbarten Inhalten und der tatsächlichen Abdeckung ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=33', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8062, 27, 11, null, 'Online-Betriebsratssitzungen und -versammlungen als gleichwertige Alternative zu Präsenzformaten ermöglichen.', '{2705}', 8005, 1, 3, null, 'Digitale Zugänge können Beteiligung erleichtern, ändern aber weder die Reichweite der Mitbestimmung noch unmittelbar Personal, Arbeitszeit oder Unterstützung.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=33', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8063, 27, 11, null, 'Digitale Zugangsrechte bei der betrieblichen Mitbestimmung klarstellen.', '{2705}', 8005, 1, 3, null, 'Digitale Zugänge können Beteiligung erleichtern, ändern aber weder die Reichweite der Mitbestimmung noch unmittelbar Personal, Arbeitszeit oder Unterstützung.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=33', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8064, 27, 11, 'BE', 'Einrichtung einer Pflegekammer zur Weiterentwicklung des Pflegeberufs und Vertretung der Pflegeinteressen', '{2705}', 8018, 1, 2, null, 'Eine Kammer kann berufliche Interessen und Selbstverwaltung stärken, wirkt aber nur mittelbar auf tägliche Arbeitslast, Dienstpläne oder Unterstützung am Arbeitsplatz.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=100', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8065, 27, 11, 'ST', 'Pflegefachkräften mehr Kompetenzen und Verantwortung übertragen.', '{2705}', 8054, 2, 2, null, 'Mehr fachlicher Spielraum kann Einfluss auf die eigene Arbeit stärken. Zusätzliche Verantwortung kann zugleich Anforderungen erhöhen; Zuständigkeiten und Qualifikationen müssen klar geregelt sein.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=28', 'https://www.nationalacademies.org/publications/25982', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8066, 27, 12, null, 'Bedarfsgerechte Personalausstattung für alle Beschäftigtengruppen bundesweit einführen.', '{2701}', 8010, 2, 2, null, 'Höhere und bedarfsgerechte Besetzung kann Arbeitslast senken; Studien zu Personalstärke und Ergebnissen stützen den Ansatz, zeigen aber auch Kosten-, Mess- und Umsetzungsprobleme sowie weniger klare Befunde für andere Berufsgruppen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', 'https://europepmc.org/article/MED/35780608', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8067, 27, 12, null, 'Zusammenarbeit aller Gesundheitsberufe und Durchlässigkeit stärken sowie Befugnisse von Pflegefachpersonen erweitern.', '{2701}', 8057, 1, 2, null, 'Bessere Zusammenarbeit und erweiterte Befugnisse können Aufgaben verteilen und den Arbeitsablauf erleichtern. Ohne konkrete Zuständigkeiten oder Bezug zur Personalbemessung bleibt die Entlastung unsicher.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', 'https://www.nationalacademies.org/publications/25982', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8068, 27, 12, null, 'Weltweite Anwerbung und Integration von Fachkräften ausbauen.', '{2701}', 8009, 2, 2, null, 'Zusätzliche Pflegekräfte können knappe Besetzung und Zeitdruck mindern. Anwerbung und Rückkehr sind jedoch nicht automatisch zusätzliche verfügbare Vollzeitkräfte und erfordern Zeit sowie geeignete Arbeitsbedingungen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8069, 27, 12, null, 'Praxisnahe und kostenfreie Ausbildungen in Gesundheitsfachberufen fördern.', '{2701}', 8027, 1, 2, null, 'Kostenfreie und praxisnahe Ausbildung kann Zugang und Nachwuchs fördern, führt aber erst nach Abschluss zu zusätzlicher Besetzung. Ausbildungs- und Finanzierungskapazitäten begrenzen das Tempo.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8070, 27, 12, null, 'Mehr Freizeitausgleich schaffen, etwa durch eine verkürzte Wochenarbeitszeit.', '{2702}', 8022, 2, 1, null, 'Kürzere Arbeitszeiten können Erholung verbessern, wenn die Arbeitsmenge nicht auf weniger Zeit verdichtet wird. Voller Lohnausgleich und zusätzlicher Personalausgleich sind kosten- und personalintensiv.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', 'https://europepmc.org/article/MED/30737987', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8071, 27, 12, null, 'Vergütung und Dienstzeiten während des praktischen Jahres verlässlich regeln.', '{2702,2704}', 8004, 2, 2, null, 'Verlässliche Vergütung und Dienstzeiten verbessern die Bedingungen angehender Ärztinnen und Ärzte. Umfang, Finanzierung und tatsächliche Wirkung auf die Belastung hängen von der konkreten Regelung ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8072, 27, 12, null, 'KI-gestützte Dokumentation ausbauen, um den Dokumentationsaufwand im Gesundheitswesen zu verringern.', '{2703}', 8038, 2, 2, null, 'Automatisierung kann Dokumentationszeit senken, kann aber durch Prüfung, Korrekturen und Integration neue Arbeit erzeugen. Reviews finden wenige, heterogene Interventionsstudien und keine verlässliche allgemeine Wirkung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', 'https://europepmc.org/article/MED/39366661', 'offen', '2026-10-06', false, true, 'blind'),
  (8073, 27, 12, null, 'Ordentliche Tarifverträge in Gesundheit und Pflege unterstützen.', '{2704}', 8031, 1, 3, null, 'Tarifverträge können Bezahlung und Bedingungen regeln; die bloße Unterstützung enthält aber keine konkrete Vorgabe zu Lohn, Arbeitszeit oder Entlastung.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8074, 27, 12, null, 'Tarifgebundene Bezahlung bei Unternehmen mit Bundesaufträgen durchsetzen.', '{2704}', 8012, 2, 3, null, 'Tarifbindung kann Entlohnung und Arbeitsbedingungen bei erfassten Auftragnehmenden verbessern. Die Reichweite hängt von Vergabeumfang, Kontrollen und der tatsächlichen Tarifabdeckung ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=23', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8075, 27, 12, null, 'Mitbestimmungsrechte der Betriebsräte bei Personalplanung, KI, Gesundheitsschutz und Weiterbildung ausbauen.', '{2705}', 8043, 2, 2, null, 'Erzwingbare Beteiligung bei Personalbemessung, Gesundheitsschutz und Weiterbildung stärkt den Einfluss auf Arbeitsbedingungen. Ob sie Belastungen reduziert, hängt von Durchsetzung und verfügbaren Ressourcen ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=13', 'https://www.who.int/publications/i/item/9789240053052', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8076, 27, 12, null, 'Zugang zu Weiterbildung und gesundheitsfördernden Maßnahmen für Beschäftigte in Gesundheitsberufen erleichtern.', '{2705}', 8011, 1, 3, null, 'Gesundheitsförderung kann Beschäftigte unterstützen, verändert aber nicht zwingend hohe emotionale Anforderungen, geringe Mitsprache oder fehlende soziale Unterstützung am Arbeitsplatz.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', 'https://europepmc.org/article/MED/37893584', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8077, 27, 12, 'BE', 'Eine Konferenz für Betriebs- und Personalräte als Dialogforum schaffen.', '{2705}', 8045, 1, 3, null, 'Austausch kann Probleme sichtbar machen, verleiht aber ohne verbindliche Rechte oder Umsetzungspflichten keinen zusätzlichen Einfluss auf Arbeitsbedingungen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8078, 27, 12, 'BE', 'Die Verfolgung von Angriffen auf Mitbestimmung durch die Staatsanwaltschaft stärken.', '{2705}', 8042, 1, 3, null, 'Spezialisierte Ermittlungen können bestehende Rechte besser durchsetzen und abschrecken. Sie schaffen selbst keine neuen Beteiligungsrechte und hängen von Fällen, Personal und Verfahrensdauer ab.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8079, 27, 12, 'BE', 'Die Behinderung von Betriebsratsarbeit zu einem Offizialdelikt machen.', '{2705}', 8021, 2, 1, null, 'Wirksame Sanktionen können Mitsprache schützen und abschrecken. Die Schaffung neuer Straftatbestände oder Sanktionen liegt nicht ohne Weiteres in Landeshand; die Maßnahme braucht bundesrechtliche Schritte.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8080, 27, 12, 'BE', 'Eine unabhängige Arbeitnehmervertretung durch die Netzwerkstelle Gute Arbeit fördern.', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8081, 27, 12, 'BE', 'Landesförderungen an Tarifbindung und Mitbestimmung koppeln.', '{2705}', 8037, 1, 2, null, 'Förderbedingungen können Mitsprache bei geförderten Einrichtungen anreizen, erfassen aber nur einen Teil der Arbeitgeber und nennen keine konkreten Mitbestimmungsstandards.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8082, 27, 12, 'BE', 'Ausgründungen rückgängig machen, die Mitbestimmung einschränken.', '{2705}', 8048, 1, 1, null, 'Rückgängigmachung von Ausgründungen kann Mitbestimmungswege wiederherstellen, betrifft aber nur bestimmte Einrichtungen und erfordert erhebliche organisatorische sowie finanzielle Schritte.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=10', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8083, 27, 12, 'MV', 'Betriebsratsgründungen besser schützen und betriebliche Mitbestimmung stärken.', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=23', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8084, 27, 12, 'ST', 'Das Land unterstützt die Gründung von Betriebsräten und informiert über Arbeitnehmerrechte.', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=8', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8085, 27, 12, 'ST', 'Professionelle Sprachmittlung im Gesundheitswesen wird verlässlich finanziert.', '{2706}', 8020, 2, 2, null, 'Reviews zeigen bessere Kommunikation und Versorgungsqualität mit professioneller Sprachmittlung; eine direkte Entlastung der Beschäftigten ist weniger gut untersucht. Verfügbarkeit und Finanzierung bestimmen die Wirkung.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=36', 'https://europepmc.org/article/MED/17362215', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8086, 27, 13, null, 'Höhere Personalschlüssel für Pflegekräfte umsetzen.', '{2701}', 8010, 2, 2, null, 'Höhere und bedarfsgerechte Besetzung kann Arbeitslast senken; Studien zu Personalstärke und Ergebnissen stützen den Ansatz, zeigen aber auch Kosten-, Mess- und Umsetzungsprobleme sowie weniger klare Befunde für andere Berufsgruppen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', 'https://europepmc.org/article/MED/35780608', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8087, 27, 13, null, 'Wegen Überlastung ausgeschiedene Pflegefachkräfte mit einer Rückkehroffensive zurückgewinnen.', '{2701}', 8009, 2, 2, null, 'Zusätzliche Pflegekräfte können knappe Besetzung und Zeitdruck mindern. Anwerbung und Rückkehr sind jedoch nicht automatisch zusätzliche verfügbare Vollzeitkräfte und erfordern Zeit sowie geeignete Arbeitsbedingungen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8088, 27, 13, null, 'Dokumentationspflichten und Bürokratie in der Pflege auf ein Mindestmaß reduzieren.', '{2703}', 8015, 2, 2, null, 'Weniger unnötige Dokumentation kann unmittelbar Arbeitszeit freisetzen. Forschung misst die Belastung uneinheitlich und untersucht die Wirkung konkreter Vereinfachungen bislang nur begrenzt; notwendige Qualitäts- und Sicherheitsnachweise bleiben erforderlich.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=93', 'https://europepmc.org/article/MED/33434273', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8089, 27, 13, null, 'Durchlässige Weiterentwicklungswege und neue fachliche Rollen bis zum Masterniveau schaffen.', '{2704}', 8014, 2, 2, null, 'Durchlässige Laufbahnen und neue Rollen können berufliche Anerkennung und Entwicklungsperspektiven verbessern. Sie brauchen Ausbildungsplätze, klare Befugnisse und passende Finanzierung und ersetzen keine ausreichende Besetzung.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8090, 27, 13, null, 'Gründung betrieblicher Interessenvertretungen unterstützen und Online-Wahlen ermöglichen.', '{2705}', 8016, 2, 3, null, 'Schutz von Initiierenden und leichtere Wahlen können betriebliche Mitsprache ermöglichen. Ob daraus spürbar mehr Einfluss auf Arbeitsbelastung folgt, hängt von tatsächlicher Gründung und Durchsetzung ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=68', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8091, 27, 13, 'BE', 'Betriebliche Gesundheitsförderung und Präventionsprogramme für gesundheitsfördernde Arbeitsbedingungen in Gesundheitsfachberufen ausbauen.', '{2705}', 8046, 1, 3, null, 'Förderprogramme können Prävention und gesundheitsfördernde Arbeitsbedingungen unterstützen. Ohne konkrete Vorgaben zu Personal, Arbeitszeit oder Einfluss bleibt die Wirkung auf die benannten Belastungsursachen begrenzt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=208', 'https://www.who.int/publications/i/item/9789240053052', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8092, 27, 13, 'BE', 'Aufbau einer Pflegekammer fördern und evaluieren, um die Interessenvertretung und Beteiligung der Pflegeberufe zu stärken.', '{2705}', 8018, 1, 2, null, 'Eine Kammer kann berufliche Interessen und Selbstverwaltung stärken, wirkt aber nur mittelbar auf tägliche Arbeitslast, Dienstpläne oder Unterstützung am Arbeitsplatz.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=214', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8093, 27, 13, 'BE', 'Ausreichende Sprachangebote für angeworbene Pflegefachkräfte bereitstellen.', '{2706}', 8007, 2, 2, null, 'Berufsbezogene Sprachförderung kann Verständigungsprobleme im Arbeitsalltag mindern. Für ihre direkte Wirkung auf die Belastung von Beschäftigten und die nötigen Kapazitäten ist die Evidenz begrenzt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=213', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8094, 27, 13, 'MV', 'Beschäftigte in Gesundheits- und Pflegeberufen vor Gewalt und Belästigung schützen.', '{2705}', 8024, 2, 2, null, 'Schutzmaßnahmen können emotionale Belastungen und Gefährdungen mindern. Reviews betonen, dass Schulungen Teil eines umfassenden Schutzkonzepts mit Unterstützung und passenden Bedingungen sein müssen.', 'https://gruene-mv.de/?wpdmdl=33772#page=58', 'https://europepmc.org/article/MED/33802868', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8095, 27, 13, 'ST', 'Beschäftigte durch Betriebsräte stärker an Entscheidungen beteiligen.', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=76', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8096, 27, 13, 'ST', 'Eine Pflegeselbstvertretung schaffen, über die Pflegekräfte Berufsordnung und Interessen selbst mitgestalten.', '{2705}', 8018, 1, 2, null, 'Eine Kammer kann berufliche Interessen und Selbstverwaltung stärken, wirkt aber nur mittelbar auf tägliche Arbeitslast, Dienstpläne oder Unterstützung am Arbeitsplatz.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=87', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8097, 27, 13, 'ST', 'Genossenschaften und Belegschaftsmodelle als Formen betrieblicher Mitbestimmung fördern.', '{2705}', 8053, 1, 2, null, 'Solche Modelle können Beschäftigten mehr Mitsprache eröffnen, sind aber kein allgemeiner Hebel für Arbeitsbedingungen und erfordern freiwillige Gründungen sowie tragfähige Finanzierung.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=89', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8098, 27, 14, null, 'Wöchentliche statt tägliche Höchstarbeitszeit einführen und Arbeitszeit- sowie Ruhezeitvorgaben flexibilisieren.', '{2702}', 8041, 0, 3, null, 'Flexiblere Grenzen können individuelle Modelle ermöglichen, garantieren aber weder Pausen noch Erholung und können längere Einsätze erleichtern. Die Forschung verbindet kurze Ruhezeiten mit Müdigkeit, während Gesamtergebnisse gemischt sind.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', 'https://europepmc.org/article/MED/30737987', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8099, 27, 14, null, 'Pflegeanbieter von unnötigen Nachweis- und Dokumentationspflichten befreien.', '{2703}', 8015, 2, 2, null, 'Weniger unnötige Dokumentation kann unmittelbar Arbeitszeit freisetzen. Forschung misst die Belastung uneinheitlich und untersucht die Wirkung konkreter Vereinfachungen bislang nur begrenzt; notwendige Qualitäts- und Sicherheitsnachweise bleiben erforderlich.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', 'https://europepmc.org/article/MED/33434273', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8100, 27, 14, null, 'Mehr Pflegefachkräfte im In- und Ausland gewinnen.', '{2701}', 8009, 2, 2, null, 'Zusätzliche Pflegekräfte können knappe Besetzung und Zeitdruck mindern. Anwerbung und Rückkehr sind jedoch nicht automatisch zusätzliche verfügbare Vollzeitkräfte und erfordern Zeit sowie geeignete Arbeitsbedingungen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8101, 27, 14, null, 'Digitale Anwendungen, Automatisierung und Robotik zur Entlastung des Pflegepersonals einsetzen.', '{2701}', 8047, 1, 2, null, 'Technik kann einzelne Aufgaben erleichtern, aber die Maßnahme benennt weder Anwendungen noch Einsatzbedingungen. Einführungs-, Wartungs- und Kontrollaufwand kann einen Teil der erhofften Entlastung aufzehren.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=35', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8102, 27, 14, null, 'Eine ungekürzte, leistungsgerechte Vergütung für Gesundheitsberufe vorsehen.', '{2704}', 8049, 1, 2, null, 'Angemessene Bezahlung kann das Verhältnis von Einsatz und Belohnung verbessern. Ohne Maßstab, Betrag und Finanzierungsweg bleibt der Umfang unbestimmt; leistungsbezogene Anreize können zusätzliche Belastung erzeugen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=33', null, 'gemischt', '2026-10-06', false, true, 'blind'),
  (8103, 27, 14, 'BE', 'Freiwilligen Zusammenschluss von Pflegekraeften zur Interessenvertretung unterstuetzen', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=116', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8104, 27, 14, 'MV', 'Handlungs- und Ermessensspielraum von Pflegekräften erweitern', '{2705}', 8054, 2, 2, null, 'Mehr fachlicher Spielraum kann Einfluss auf die eigene Arbeit stärken. Zusätzliche Verantwortung kann zugleich Anforderungen erhöhen; Zuständigkeiten und Qualifikationen müssen klar geregelt sein.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=50', 'https://www.nationalacademies.org/publications/25982', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8105, 27, 15, null, 'Bundeseinheitliche gesetzliche Personalbemessung für alle pflegesensitiven Bereiche vorsehen.', '{2701}', 8010, 2, 2, null, 'Höhere und bedarfsgerechte Besetzung kann Arbeitslast senken; Studien zu Personalstärke und Ergebnissen stützen den Ansatz, zeigen aber auch Kosten-, Mess- und Umsetzungsprobleme sowie weniger klare Befunde für andere Berufsgruppen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=28', 'https://europepmc.org/article/MED/35780608', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8106, 27, 15, null, 'Die Finanzierung des notwendigen Personalaufwuchses sicherstellen.', '{2701}', 8036, 2, 1, null, 'Finanzierung ist Voraussetzung für zusätzliche Stellen, schafft diese aber ohne konkrete Mittel, Verteilung und Einstellungsplan nicht selbst. Umfang und dauerhafte Finanzierung sind offen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=29', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8107, 27, 15, null, 'Für medizinisches Fachpersonal eine fachliche und sprachliche Qualifikation auf Niveau C1 verlangen.', '{2706}', 8032, 1, 2, null, 'Gute Sprachkenntnisse können Verständigungsprobleme begrenzen, ersetzen aber keine verfügbare Sprachmittlung in komplexen Fällen. Höhere Zugangshürden können zudem die Personalgewinnung erschweren.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=34', 'https://europepmc.org/article/MED/17362215', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8108, 27, 15, 'MV', 'Besseren gesetzlichen Schutz des medizinischen und pflegerischen Personals vor Gewalt umsetzen.', '{2705}', 8024, 2, 2, null, 'Schutzmaßnahmen können emotionale Belastungen und Gefährdungen mindern. Reviews betonen, dass Schulungen Teil eines umfassenden Schutzkonzepts mit Unterstützung und passenden Bedingungen sein müssen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=64', 'https://europepmc.org/article/MED/33802868', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8109, 27, 15, 'MV', 'Berufsbegleitende Sprachförderangebote für medizinisches Personal verankern und einheitliche Approbationsstandards konsequent anwenden.', '{2706}', 8007, 2, 2, null, 'Berufsbezogene Sprachförderung kann Verständigungsprobleme im Arbeitsalltag mindern. Für ihre direkte Wirkung auf die Belastung von Beschäftigten und die nötigen Kapazitäten ist die Evidenz begrenzt.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=63', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8110, 27, 15, 'ST', 'Pflegekräfte sollen über die Einrichtung einer Pflegekammer abstimmen.', '{2705}', 8058, 1, 3, null, 'Eine Abstimmung gibt Pflegekräften Einfluss auf die Einrichtung einer Selbstvertretung, ändert aber für sich genommen weder Arbeitsbedingungen noch Mitsprache am Arbeitsplatz.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=244', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8111, 27, 16, null, 'Verbindliche Personalbemessung mit PPR 2.0, mehr Pflegepersonal und stressfreien Schichtplänen einführen.', '{2701,2702}', 8034, 2, 2, null, 'Personalbemessung und planbare Schichten setzen direkt an Besetzung und Erholung an. Die geforderte Größenordnung, Refinanzierung und Umsetzung über mehrere Berufsgruppen erfordern erhebliche Ressourcen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', 'https://europepmc.org/article/MED/35780608', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8112, 27, 16, null, 'Ehemalige Pflegekräfte und andere Gesundheitsbeschäftigte bundesweit zurückgewinnen und eine Ausbildungsoffensive starten.', '{2701}', 8009, 2, 2, null, 'Zusätzliche Pflegekräfte können knappe Besetzung und Zeitdruck mindern. Anwerbung und Rückkehr sind jedoch nicht automatisch zusätzliche verfügbare Vollzeitkräfte und erfordern Zeit sowie geeignete Arbeitsbedingungen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8113, 27, 16, null, 'Entlastungstarifverträge unterstützen, refinanzieren und leichter allgemeinverbindlich machen.', '{2704}', 8025, 2, 2, null, 'Entlastungstarifverträge können Arbeitsbedingungen verbindlicher verbessern. Reichweite, Finanzierung und Durchsetzung sind offen; Tarifregeln allein schaffen keine zusätzlichen Arbeitskräfte.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8114, 27, 16, null, 'Niedrigschwellige Beratung und Unterstützung für Pflegekräfte, Rettungssanitäter*innen und andere belastende Gesundheitsberufe bereitstellen.', '{2705}', 8030, 1, 3, null, 'Beratung kann bei Stress und psychischer Belastung helfen, beseitigt aber keine Ursachen wie Unterbesetzung oder ungünstige Dienstpläne. Reviews finden Nutzen individueller Ansätze, bei heterogenen Studien.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=18', 'https://europepmc.org/article/MED/37893584', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8115, 27, 16, null, 'Öffentliche Arbeitgeber sollen mit Gewerkschaften Entlastung und gute Arbeit vereinbaren, um Personalmangel zu beheben.', '{2701}', 8029, 2, 2, null, 'Verbindliche Schritte können Personalengpässe und Arbeitsbedingungen adressieren. Die Zusage nennt weder Mindeststandards noch Finanzierung oder Sanktionen bei Nichteinhaltung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8116, 27, 16, null, 'Arbeitsschutz stärken und Betriebsräten erzwingbare Mitbestimmung bei Personalbemessung und Belastungsvermeidung geben.', '{2705}', 8050, 2, 2, null, 'Arbeitsschutz und verbindliche Beteiligung können Belastungen vorbeugen und Mitsprache stärken. Die konkrete Entlastung hängt von Standards, Kontrolle und tatsächlicher Personalverfügbarkeit ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', 'https://www.who.int/publications/i/item/9789240053052', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8117, 27, 16, null, 'Kürzere Arbeitszeiten mit vollem Lohnausgleich und notwendigem Personalausgleich unterstützen.', '{2701,2702}', 8025, 2, 2, null, 'Entlastungstarifverträge können Arbeitsbedingungen verbindlicher verbessern. Reichweite, Finanzierung und Durchsetzung sind offen; Tarifregeln allein schaffen keine zusätzlichen Arbeitskräfte.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8118, 27, 16, null, 'Acht-Stunden-Tag, mindestens elf Stunden Ruhezeit zwischen Schichten und höchstens 40 Wochenstunden sichern.', '{2702}', 8055, 2, 3, null, 'Begrenzte Arbeitszeiten und ausreichende Ruhe können Müdigkeit reduzieren; Reviews stützen den Zusammenhang, zeigen aber teils gemischte Ergebnisse. Ohne Ausgleich kann die Arbeitsmenge pro Schicht steigen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', 'https://europepmc.org/article/MED/30737987', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8119, 27, 16, null, 'Einen Rechtsanspruch auf familienfreundliche Schichten schaffen.', '{2702}', 8040, 2, 2, null, 'Planbarere und passende Dienstzeiten können Erholung erleichtern. Reviews verbinden ungünstige Schichtmerkmale mit Müdigkeit, finden aber gemischte Befunde und belegen diesen konkreten Rechtsanspruch nicht direkt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', 'https://europepmc.org/article/MED/30737987', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8120, 27, 16, null, 'Einen gesetzlichen Urlaubsanspruch von sechs Wochen pro Jahr einführen.', '{2702}', 8028, 1, 2, null, 'Mehr Urlaub ermöglicht zusätzliche Erholungszeit, verändert aber nicht unmittelbar Pausen und Belastung zwischen den Urlaubstagen. Personalvertretung während Abwesenheiten muss mitgedacht werden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8121, 27, 16, null, 'Beschäftigten zweimal im Berufsleben ein Sabbatjahr mit Rückkehrrecht ermöglichen.', '{2702}', 8035, 1, 1, null, 'Ein Sabbatjahr kann einzelnen Beschäftigten Erholung ermöglichen, löst aber nicht die regelmäßigen Pausen- und Schichtprobleme. Vertretung, Anspruchsumfang und Finanzierung sind ungeklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8122, 27, 16, null, 'Die Lohnlücke in der Kranken- und Altenpflege schließen und Pflegekräfte angemessen entlohnen.', '{2704}', 8051, 2, 2, null, 'Eine konkrete Lohnanhebung verbessert unmittelbar die finanzielle Belohnung für Pflegearbeit. Höhe, betroffene Beschäftigte und Refinanzierung sind nicht ausgeführt; höhere Bezahlung allein löst Überlastung nicht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8123, 27, 16, null, 'Den gesetzlichen Mindestlohn auf mindestens 60 Prozent des Medianlohns erhöhen und an dessen Entwicklung anpassen.', '{2704}', 8056, 1, 3, null, 'Ein höherer Mindestlohn verbessert die Entlohnung der davon erfassten Beschäftigten, erreicht aber viele qualifizierte Gesundheitsberufe nicht direkt und verändert Arbeitsbelastung oder Personalbesetzung nicht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=26', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8124, 27, 16, null, 'Die Mitbestimmung in öffentlichen und kirchlichen Einrichtungen an das Betriebsverfassungsgesetz anpassen.', '{2705}', 8039, 2, 2, null, 'Einheitlichere Beteiligungsrechte können den Einfluss Beschäftigter stärken. Die nötigen Änderungen betreffen unterschiedliche Rechts- und Trägerstrukturen; ihre Wirkung auf Belastung ist nicht direkt belegt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=28', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8125, 27, 16, null, 'Betriebsratswahlen erleichtern, ihre Behinderung konsequenter verfolgen und Initiator*innen besser schützen.', '{2705}', 8016, 2, 3, null, 'Schutz von Initiierenden und leichtere Wahlen können betriebliche Mitsprache ermöglichen. Ob daraus spürbar mehr Einfluss auf Arbeitsbelastung folgt, hängt von tatsächlicher Gründung und Durchsetzung ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=28', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8126, 27, 16, null, 'Nicht-duale Ausbildungen in Gesundheitsberufen besser entlohnen.', '{2704}', 8052, 1, 2, null, 'Vergütung kann die finanzielle Belastung während der Ausbildung senken, betrifft aber Auszubildende und nicht unmittelbar die Arbeitslast der bereits Beschäftigten. Finanzierungszuständigkeiten sind zu klären.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=40', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8127, 27, 16, 'BE', 'Beschäftigte in öffentlichen Krankenhäusern sollen in Planungs- und Leitungsgremien mitentscheiden.', '{2705}', 8017, 2, 2, null, 'Mitwirkung in Planungs- und Leitungsgremien erhöht die Möglichkeit, Arbeitsbedingungen zu beeinflussen. Die Wirkung ist unklar, solange Aufgaben, Stimmrechte und Umsetzung der Beschlüsse nicht feststehen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=136', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8128, 27, 16, 'BE', 'Psychische Belastungen sollen kontrolliert und Gesundheitsförderung sowie die Beteiligung der Beschäftigten an Verbesserungen verbindlich verankert werden.', '{2705}', 8044, 2, 2, null, 'Kontrollen und Beteiligung können psychosoziale Risiken sichtbar machen und Verbesserungen anstoßen. Wirkung setzt wirksame Standards und Abhilfe voraus; Zuständigkeiten für Arbeitsschutzregeln sind zwischen Bund und Ländern verteilt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=138', 'https://www.who.int/publications/i/item/9789240053052', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8129, 27, 16, 'MV', 'Betriebs- und Personalräte stärken und das Personalvertretungsgesetz evaluieren.', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8130, 27, 16, 'MV', 'Betriebliche Gesundheitsprävention fördern.', '{2705}', 8033, 1, 3, null, 'Prävention kann Gesundheit und Aufmerksamkeit für Arbeitsbedingungen fördern, greift aber ohne konkrete organisatorische Änderungen die genannten Ursachen nur begrenzt an.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8131, 27, 16, 'ST', 'Mitentscheidungsrechte der Betriebsräte bei Investitionen, Standortfragen und Digitalisierung ausweiten.', '{2705}', 8008, 2, 2, null, 'Verbindliche Beteiligung kann den Einfluss auf Arbeitsbedingungen und Veränderungsprozesse erhöhen. Ohne nähere Zuständigkeiten und Durchsetzungsrechte bleibt die erwartbare Wirkung unsicher.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=87', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8132, 27, 16, 'ST', 'Sanktionen gegen Union Busting und die Behinderung von Betriebsratsarbeit einführen.', '{2705}', 8021, 2, 1, null, 'Wirksame Sanktionen können Mitsprache schützen und abschrecken. Die Schaffung neuer Straftatbestände oder Sanktionen liegt nicht ohne Weiteres in Landeshand; die Maßnahme braucht bundesrechtliche Schritte.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=87', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8133, 27, 16, 'ST', 'Betriebsräte durch Bildung, Gesundheitsangebote und Weiterbildung fördern.', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=87', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8134, 27, 16, 'ST', 'Ein Landesprogramm zur betrieblichen Mitbestimmung in kleinen und mittleren Unternehmen einrichten.', '{2705}', 8013, 2, 2, null, 'Unterstützung und Schutz von Interessenvertretungen können Mitsprache und soziale Unterstützung fördern. Die Wirkungsforschung zur konkreten Entlastung im Gesundheitswesen ist begrenzt; private Arbeitsrechtsregeln liegen zudem teilweise beim Bund.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=87', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8135, 27, 16, 'ST', 'Einen landesweiten Sprachmittlerservice als Standard für den öffentlichen Dienst und die medizinische Versorgung einführen.', '{2706}', 8020, 2, 2, null, 'Reviews zeigen bessere Kommunikation und Versorgungsqualität mit professioneller Sprachmittlung; eine direkte Entlastung der Beschäftigten ist weniger gut untersucht. Verfügbarkeit und Finanzierung bestimmen die Wirkung.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=99', 'https://europepmc.org/article/MED/17362215', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8136, 27, 17, null, 'Öffentliche Aufträge und Subventionen an die Zahlung von Tariflöhnen knüpfen.', '{2704}', 8012, 2, 3, null, 'Tarifbindung kann Entlohnung und Arbeitsbedingungen bei erfassten Auftragnehmenden verbessern. Die Reichweite hängt von Vergabeumfang, Kontrollen und der tatsächlichen Tarifabdeckung ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8137, 27, 17, null, 'Die Allgemeinverbindlichkeit von Tarifverträgen erleichtern.', '{2704}', 8019, 2, 3, null, 'Erleichterte Tarifbindung und Allgemeinverbindlichkeit können die Reichweite ausgehandelter Entlohnung verbessern. Der Effekt auf die Belastung hängt von den vereinbarten Inhalten und der tatsächlichen Abdeckung ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=21', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8138, 27, 17, null, 'Mehr Pflegepersonal ausbilden und besser bezahlen.', '{2704,2701}', 8026, 2, 2, null, 'Mehr ausgebildetes Personal kann Besetzungsengpässe mindern, bessere Bezahlung kann die Anerkennung stärken. Ausbildung wirkt zeitverzögert und beide Zusagen lassen Umfang und Finanzierung offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', 'https://www.who.int/publications/i/item/9789240003279', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8139, 27, 17, 'MV', 'Mitbestimmung als Teil verbesserter Arbeitsbedingungen zur Fachkräftebindung stärken', '{2705}', 8006, 2, 2, null, 'Verlässlichere Arbeitszeiten und mehr Beteiligung setzen an Erholung und Einflussmöglichkeiten an. Die Zusage bleibt breit und lässt Umfang, Umsetzung und Finanzierung offen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=19', 'https://www.who.int/publications/i/item/9789240053052', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8140, 27, 17, 'ST', 'Betriebsräte und Gewerkschaften an Investitions-, Standort- und Transformationsentscheidungen beteiligen.', '{2705}', 8008, 2, 2, null, 'Verbindliche Beteiligung kann den Einfluss auf Arbeitsbedingungen und Veränderungsprozesse erhöhen. Ohne nähere Zuständigkeiten und Durchsetzungsrechte bleibt die erwartbare Wirkung unsicher.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=22', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8141, 27, 17, 'ST', 'Behinderungen betrieblicher Mitbestimmung sanktionieren.', '{2705}', 8021, 2, 1, null, 'Wirksame Sanktionen können Mitsprache schützen und abschrecken. Die Schaffung neuer Straftatbestände oder Sanktionen liegt nicht ohne Weiteres in Landeshand; die Maßnahme braucht bundesrechtliche Schritte.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=22', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8171, 29, 11, null, 'Bestehende Netzwerke gegen Einsamkeit mit Nachbarschaftshilfen und Beratungsangeboten weiter unterstützen', '{2901,2903}', null, 1, 2, null, 'Bloße Weiterförderung bestehender Netzwerke schafft kaum neue Angebote. Zuständig sind Länder und Kommunen; der Bund kann nur mit Programmen und Geld beitragen. Wirkung kaum untersucht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=63', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8172, 29, 11, null, 'Ambulante und stationäre Angebote für psychische Erkrankungen bedarfsgerecht verbessern', '{2905}', 8169, 1, 3, null, 'Ohne benannten Weg bleibt unklar, wie Plätze entstehen; die Versorgung gilt als unzureichend. Zusage lässt sich rechtlich leicht fassen, die Wirkung hängt von der Umsetzung ab.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=70', 'https://europepmc.org/article/MED/40034167', 'offen', '2026-10-06', false, true, 'blind'),
  (8173, 29, 11, 'BE', 'Lokale Kiez- und Nachbarschaftstreffen sowie wöchentliche Einsamkeitssprechstunden in Stadtteilzentren fördern.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=110', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8174, 29, 11, 'BE', 'Plauderbänke als Orte für Austausch und offene Gespräche fördern.', '{2901}', 8149, 1, 3, null, 'Niedrigschwellige Gesprächsgelegenheit mit sehr geringem Aufwand, aber nur flüchtige Kontakte und kaum Wirkung auf bestehende Einsamkeit. Wirkung kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=110', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8175, 29, 11, 'BE', 'Ein Landesprogramm für psychische Gesundheit und schulpsychologische Angebote ausbauen sowie Prävention und frühe Hilfen im Schulalltag verankern.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=61', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8176, 29, 11, 'BE', 'Niedrigschwellige Hilfen für junge Menschen in Krisen und mit psychischen Problemen an weiteren Standorten anbieten.', '{2903}', 8156, 2, 3, null, 'Anlaufstellen ohne Termin und Diagnose erleichtern jungen Menschen den ersten Schritt zur Hilfe. Wirkung kaum vergleichend untersucht; Länder und Kommunen können Standorte rasch fördern.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=98', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8177, 29, 11, 'MV', 'Netzwerke, ehrenamtliches Engagement und generationenübergreifende Wohnformen zur Stärkung des gesellschaftlichen Zusammenhalts fördern.', '{2901}', null, 1, 3, null, 'Allgemeine Absicht, Netzwerke, Ehrenamt und Wohnformen zu fördern, ohne konkreten Weg oder Zielgruppe. Wirkung auf Einsamkeit kaum untersucht, leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=79', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8178, 29, 11, 'MV', 'Einen Beauftragten für sozialen Zusammenhalt zur Koordination des Vorgehens gegen Einsamkeit einsetzen.', '{2901}', 8143, 1, 3, null, 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=79', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8179, 29, 11, 'MV', 'Landesmittel als Kofinanzierung für die Förderung von Mehrgenerationenhäusern bereitstellen.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=97', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8180, 29, 11, 'MV', 'Generationenmanager und Generationenwerker erproben und etablieren.', '{2901}', 8143, 1, 3, null, 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=97', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8181, 29, 11, 'MV', 'Die Vermittlung generationsübergreifender Wohnpartnerschaften im Konzept „Wohnen für Hilfe“ ausbauen.', '{2901}', 8146, 1, 3, null, 'Bietet Alltagskontakt im selben Haushalt, erreicht aber nur wenige Menschen und setzt passende Wohnungen voraus. Wirkung auf Einsamkeit kaum untersucht; Vermittlung ist schnell aufzubauen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=98', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8182, 29, 11, 'MV', 'Konzepte zur Vermittlung von Wunschgroßeltern zwischen Familien und älteren Menschen stärker unterstützen.', '{2901}', 8148, 1, 3, null, 'Persönliche Kontakte können Alleinstehende erreichen, die Reichweite kleiner Modellprojekte ist aber gering. Einzelangebote wirkten in Übersichten seltener als Gruppenangebote; leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=98', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8183, 29, 11, 'MV', 'Den Sozialpsychiatrischen Dienst zu einer Notfallnummer mit telemedizinischem Bereitschaftsdienst und schneller ärztlicher Beratung weiterentwickeln.', '{2903}', 8155, 2, 2, null, 'Krisenmodelle sind laut Cochrane-Übersicht gangbar und werden gut angenommen, die Studienlage ist aber klein und von geringer bis mäßiger Qualität. Flächendeckender Aufbau braucht Personal und Zeit.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=75', 'https://europepmc.org/article/MED/26633650', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8184, 29, 11, 'ST', 'Orte der Begegnung für ältere Menschen stärken, Vereinsamung entgegenwirken und alternative Wohnformen fördern.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=32', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8185, 29, 11, 'ST', 'Ehrenamtlich getragene Anlaufstellen im ländlichen Raum unterstützen, die das soziale Miteinander sichern.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=70', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8186, 29, 11, 'ST', 'Psychische Gesundheit und Suizidprävention in der Präventionsarbeit stärker berücksichtigen.', '{2903}', 8159, 1, 3, null, 'Eine Übersicht sieht keine Einzelstrategie klar im Vorteil; schulische Aufklärung senkte Suizidversuche, Telefon- und Internethilfen sind noch zu wenig untersucht. Rechtlich und finanziell gut umsetzbar.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=28', 'https://europepmc.org/article/MED/27289303', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8187, 29, 12, null, 'Das Taschengeld im Freiwilligendienst so gestalten, dass Jugendliche aus einkommensärmeren Haushalten teilnehmen können.', '{2902}', 8164, 1, 3, null, 'Senkt finanzielle und soziale Hürden zur Teilnahme, erreicht aber nur wenige und wirkt eher auf Teilhabe als auf bestehende Einsamkeit. Wirkung kaum untersucht; Bund finanziert Freiwilligendienste bereits.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=28', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8188, 29, 12, null, 'Antragsverfahren für Sozialleistungen vereinfachen und zentrale, niedrigschwellige Anlaufstellen entwickeln.', '{2902}', null, 1, 2, null, 'Einfachere Anträge und zentrale Anlaufstellen können die Inanspruchnahme von Leistungen erhöhen, ändern aber kaum die Einkommenshöhe. Anlaufstellen sind kommunal, der Bund kann nur gesetzlich vereinfachen und fördern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=37', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8189, 29, 12, 'BE', 'Senior*innen mit ungenutzten Zimmern und junge Menschen werden für gegenseitige Alltagshilfe und gemeinsames Wohnen vermittelt.', '{2901}', 8146, 1, 3, null, 'Bietet Alltagskontakt im selben Haushalt, erreicht aber nur wenige Menschen und setzt passende Wohnungen voraus. Wirkung auf Einsamkeit kaum untersucht; Vermittlung ist schnell aufzubauen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=20', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8190, 29, 12, 'BE', 'Barrierefreie, bezahlbare Alters-WGs und generationenübergreifende Wohngruppen schaffen.', '{2901}', 8147, 1, 2, null, 'Gemeinschaftliches Wohnen kann Alltagskontakt bieten, entsteht aber nur durch Neubau oder Umbau und erreicht wenige Menschen. Wirkung kaum untersucht; Umsetzung dauert mehrere Jahre.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=17', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8191, 29, 12, 'BE', 'Ein regelmäßiger stadtweiter Aktionstag soll Gemeinschaft in den Kiezen fördern und Großstadtanonymität aufbrechen.', '{2901}', null, 1, 3, null, 'Ein einzelner Aktionstag schafft Kontaktgelegenheiten, aber keine dauerhaften Beziehungen und erreicht Zurückgezogene kaum. Wirkung kaum untersucht, leicht umsetzbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=47', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8192, 29, 12, 'BE', 'In jedem Bezirk neue Orte der Begegnung schaffen.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=47', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8193, 29, 12, 'BE', 'Psychische Kontakt- und Beratungsstellen ausbauen und eine niedrigschwellige, wohnortnahe Versorgung ermöglichen.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=34', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8194, 29, 12, 'BE', 'Niedrigschwellige Anlaufstellen für Jugendliche in seelischen Krisen ausbauen.', '{2903}', 8156, 2, 3, null, 'Anlaufstellen ohne Termin und Diagnose erleichtern jungen Menschen den ersten Schritt zur Hilfe. Wirkung kaum vergleichend untersucht; Länder und Kommunen können Standorte rasch fördern.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=38', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8195, 29, 12, 'BE', 'Psychosoziale Beratung für wohnungslose Menschen als Teil ausgebauter und verstetigter Beratungs- und Versorgungsangebote.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=51', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8196, 29, 12, 'BE', 'Die mentale Gesundheit in Schulen durch mehr multiprofessionelles Personal, insbesondere Schulpsychologie und Gesundheitsfachkräfte, stärken.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8197, 29, 12, 'MV', 'Landesprogramm zur Schaffung von Begegnungsorten weiter unterstützen', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=33', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8198, 29, 12, 'MV', 'Jugendclubs, soziokulturelle Zentren und Dritte Orte stärken und neu schaffen', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=36', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8199, 29, 12, 'MV', 'Stigmatisierung psychischer Erkrankungen entgegenwirken und Diagnostik und Therapie verbessern', '{2903}', 8152, 1, 3, null, 'Aufklärung und Kontaktprogramme verbessern kurzfristig Einstellungen und Wissen; langfristige Effekte und Wirkung auf die Hilfesuche sind kaum belegt. Gut umsetzbar.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=31', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8200, 29, 12, 'ST', 'Wohnortnahe Versorgungsnetzwerke und organisierte Nachbarschaftshilfe stärken', '{2901}', 8144, 2, 3, null, 'Erreicht auch Menschen, die nicht von sich aus Treffpunkte aufsuchen. Besuchsangebote wirkten in Übersichten seltener als Gruppenangebote (60 % gegenüber 79 % der Studien mit Verbesserung). Gut umsetzbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=14', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8201, 29, 12, 'ST', 'Eine landesweite Strategie gegen Einsamkeit entwickeln', '{2901}', 8143, 1, 3, null, 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=34', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8202, 29, 12, 'ST', 'Die Engagementstrategie finanziell stärken und weiterentwickeln', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=34', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8203, 29, 12, 'ST', 'Den Engagementfonds niedrigschwellig ausbauen und Initiativen unterstützen', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=34', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8204, 29, 12, 'ST', 'Freiwilligenagenturen und Engagementzentren strukturell fördern', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=34', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8205, 29, 12, 'ST', 'Stadtteilfeste, Begegnungsformate und Vernetzung vor Ort finanziell unterstützen', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=34', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8206, 29, 12, 'ST', 'Prävention und Beratung zu psychischer Gesundheit ausbauen', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=15', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8207, 29, 12, 'ST', 'Gemeindepsychiatrische Verbünde stärken', '{2903}', 8158, 2, 3, null, 'Bestehende kommunale Dienste erreichen auch Menschen, die von sich aus keine Hilfe suchen. Wirkung der Ausbaustufen kaum untersucht; Land kann Mittel und Aufgaben zügig anpassen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=15', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8208, 29, 12, 'ST', 'Passgenaue Beratung bei psychischen Belastungen queerer Menschen anbieten', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=15', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8209, 29, 12, 'ST', 'Die Jungenarbeit im Land strukturell stärken', '{2904}', 8161, 1, 3, null, 'Setzt früh an Rollenbildern an, die später die Hilfesuche hemmen, wirkt aber erst nach Jahren und erreicht nur Teilgruppen. Wirkung auf spätere Hilfesuche kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=27', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8210, 29, 13, null, 'Eine Garantierente für mehr Menschen mit geringem Einkommen weiterentwickeln.', '{2902}', 8163, 2, 2, null, 'Hebt Alterseinkommen direkt an; Studien zu Geldleistungen und psychischer Gesundheit sind uneinheitlich, der Einfluss auf Einsamkeit ist kaum untersucht. Kosten erfordern Finanzierung und Vorlauf.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=97', null, 'gemischt', '2026-10-06', false, true, 'blind'),
  (8211, 29, 13, null, 'Ein bundesweit vergünstigtes Nahverkehrsangebot für Menschen mit geringem Einkommen entwickeln.', '{2902}', null, 1, 2, null, 'Ein günstiges Ticket erleichtert Teilhabe finanziell, wirkt aber nur mittelbar auf Einsamkeit; Wirkung kaum untersucht. Nahverkehr ist Ländersache, der Bund braucht eine Vereinbarung und muss Mittel bereitstellen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=49', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8212, 29, 13, null, 'Den Zugang zum freiwilligen Engagement für Menschen mit geringem Einkommen verbessern.', '{2902}', 8164, 1, 3, null, 'Senkt finanzielle und soziale Hürden zur Teilnahme, erreicht aber nur wenige und wirkt eher auf Teilhabe als auf bestehende Einsamkeit. Wirkung kaum untersucht; Bund finanziert Freiwilligendienste bereits.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=111', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8213, 29, 13, null, 'Sozial gestaffelte Unterstützungsmöglichkeiten für Freiwilligendienste schaffen.', '{2902}', 8164, 1, 3, null, 'Senkt finanzielle und soziale Hürden zur Teilnahme, erreicht aber nur wenige und wirkt eher auf Teilhabe als auf bestehende Einsamkeit. Wirkung kaum untersucht; Bund finanziert Freiwilligendienste bereits.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=112', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8214, 29, 13, null, 'Engagementstrukturen für ältere Menschen ausbauen, damit auch bisher schwer erreichbare Personen teilnehmen können.', '{2902}', 8164, 1, 3, null, 'Senkt finanzielle und soziale Hürden zur Teilnahme, erreicht aber nur wenige und wirkt eher auf Teilhabe als auf bestehende Einsamkeit. Wirkung kaum untersucht; Bund finanziert Freiwilligendienste bereits.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=86', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8215, 29, 13, null, 'Die Angebote der Mental Health Coaches an Schulen ausbauen.', '{2903}', 8170, 2, 2, null, 'Fachkräfte an Schulen erleichtern das Erkennen von Belastungen und die Hilfesuche. Schulen sind Ländersache, der Bund kann nur über Förderprogramme oder Vereinbarungen beitragen. Wirkung kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8216, 29, 13, null, 'Mehr Stellen für Schulsozialarbeit und Schulpsychologie in multiprofessionellen Teams schaffen.', '{2903}', 8170, 2, 2, null, 'Fachkräfte an Schulen erleichtern das Erkennen von Belastungen und die Hilfesuche. Schulen sind Ländersache, der Bund kann nur über Förderprogramme oder Vereinbarungen beitragen. Wirkung kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8217, 29, 13, null, 'Therapieplätze bedarfsgerecht ausbauen.', '{2905}', 8169, 1, 3, null, 'Ohne benannten Weg bleibt unklar, wie Plätze entstehen; die Versorgung gilt als unzureichend. Zusage lässt sich rechtlich leicht fassen, die Wirkung hängt von der Umsetzung ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=95', 'https://europepmc.org/article/MED/40034167', 'offen', '2026-10-06', false, true, 'blind'),
  (8218, 29, 13, null, 'Psychiatrisch-psychosoziale Krisendienste bedarfsgerecht ausbauen.', '{2903}', null, 2, 2, null, 'Krisenmodelle sind laut Cochrane-Übersicht gangbar, die Studienlage ist klein. Zuständig sind die Länder; der Bund kann nur mit Geld oder Vereinbarungen beitragen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=95', 'https://europepmc.org/article/MED/26633650', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8219, 29, 13, null, 'Psychosoziale Zentren für Geflüchtete stärken.', '{2903}', null, 2, 3, null, 'Spezialisierte, niedrigschwellige Beratung mit Sprachmittlung hilft Geflüchteten bei der Hilfesuche, erreicht aber nur diese Gruppe. Wirkung kaum untersucht; der Bund fördert die Zentren bereits.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=95', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8220, 29, 13, null, 'Die Bedarfsplanung für psychotherapeutische Angebote modernisieren.', '{2905}', 8167, 2, 3, null, 'Mehr Kassensitze setzen direkt an der Kapazität an; Befragungen sehen fehlende Termine als Hauptengpass. Wirkung bisheriger Reformen nur teils belegt. Bund und Selbstverwaltung können es regeln.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=95', 'https://europepmc.org/articles/PMC13288593', 'offen', '2026-10-06', false, true, 'blind'),
  (8221, 29, 13, null, 'Die angemessene Finanzierung der psychotherapeutischen Weiterbildung sicherstellen.', '{2905}', 8166, 1, 2, null, 'Sichert den Nachwuchs, wirkt aber erst nach Jahren und ändert nicht die Zahl der Kassensitze, die die Wartezeit begrenzt. Bund kann die Finanzierung regeln, braucht aber Einigung mit den Kassen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=95', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8222, 29, 13, 'BE', 'Begegnungsräume durch generationenübergreifende Treffpunkte und bestehende Begegnungsstätten in allen Bezirken schaffen und weiterentwickeln.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=218', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8223, 29, 13, 'BE', 'Gemeinschaftliche Flächen in Quartieren so gestalten, dass sie Nachbarschaft und Begegnung fördern.', '{2901}', null, 1, 3, null, 'Gemeinsam gestaltete Flächen können zufällige Begegnungen fördern, schaffen aber kein Angebot für Alleinstehende. Wirkung auf Einsamkeit kaum untersucht, leicht umsetzbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=63', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8224, 29, 13, 'BE', 'Eine Landesstrategie gegen Einsamkeit mit gezielten Maßnahmen für sozial isolierte Menschen entwickeln.', '{2901}', 8143, 1, 3, null, 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=74', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8225, 29, 13, 'BE', 'Mit mobiler Stadtteilarbeit Menschen erreichen, für die ein Nachbarschaftszentrum zu schwer zugänglich ist.', '{2901}', 8144, 2, 3, null, 'Erreicht auch Menschen, die nicht von sich aus Treffpunkte aufsuchen. Besuchsangebote wirkten in Übersichten seltener als Gruppenangebote (60 % gegenüber 79 % der Studien mit Verbesserung). Gut umsetzbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=74', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8226, 29, 13, 'BE', 'Gemeinschaftliche Wohnformen unterstützen, die Vereinsamung vorbeugen und gegenseitige Hilfe fördern.', '{2901}', 8147, 1, 2, null, 'Gemeinschaftliches Wohnen kann Alltagskontakt bieten, entsteht aber nur durch Neubau oder Umbau und erreicht wenige Menschen. Wirkung kaum untersucht; Umsetzung dauert mehrere Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=219', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8227, 29, 13, 'BE', 'Das Projekt der Plauderbänke in den Bezirken fördern.', '{2901}', 8149, 1, 3, null, 'Niedrigschwellige Gesprächsgelegenheit mit sehr geringem Aufwand, aber nur flüchtige Kontakte und kaum Wirkung auf bestehende Einsamkeit. Wirkung kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=219', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8228, 29, 13, 'BE', 'Psychische Gesundheit durch Entstigmatisierung, Prävention und Früherkennung stärken.', '{2903,2904}', 8152, 1, 3, null, 'Aufklärung und Kontaktprogramme verbessern kurzfristig Einstellungen und Wissen; langfristige Effekte und Wirkung auf die Hilfesuche sind kaum belegt. Gut umsetzbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=204', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8229, 29, 13, 'BE', 'Psychiatrische Einrichtungen fördern und niedrigschwellige Lotsen- und Vermittlungsangebote für passende Psychotherapie ausbauen.', '{2903}', 8157, 1, 3, null, 'Lotsen helfen, vorhandene Angebote zu finden, schaffen aber keine zusätzlichen Behandlungsplätze. Wirkung auf Wartezeiten und Hilfesuche kaum untersucht; gut umsetzbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=204', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8230, 29, 13, 'BE', 'Integrierte, niedrigschwellige, aufsuchende und multiprofessionelle Hilfs- und Krisenangebote in allen Bezirken ausbauen.', '{2903}', 8155, 2, 2, null, 'Krisenmodelle sind laut Cochrane-Übersicht gangbar und werden gut angenommen, die Studienlage ist aber klein und von geringer bis mäßiger Qualität. Flächendeckender Aufbau braucht Personal und Zeit.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=204', 'https://europepmc.org/article/MED/26633650', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8231, 29, 13, 'BE', 'Präventions- und Unterstützungsangebote für Kinder und Jugendliche mit Schulpsychologie, Jugendpsychiatrie-Teams und früher Hilfe im sozialen Umfeld ausbauen.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=204', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8232, 29, 13, 'BE', 'Die anonyme Telefonsorge der „Nummer gegen Kummer“ für Kinder und Jugendliche dauerhaft erhalten.', '{2903}', 8155, 2, 2, null, 'Krisenmodelle sind laut Cochrane-Übersicht gangbar und werden gut angenommen, die Studienlage ist aber klein und von geringer bis mäßiger Qualität. Flächendeckender Aufbau braucht Personal und Zeit.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=204', 'https://europepmc.org/article/MED/26633650', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8233, 29, 13, 'BE', 'Suizidprävention systematisch verankern und Hilfsangebote stärker vernetzen und gezielt ausbauen.', '{2903}', 8159, 1, 3, null, 'Eine Übersicht sieht keine Einzelstrategie klar im Vorteil; schulische Aufklärung senkte Suizidversuche, Telefon- und Internethilfen sind noch zu wenig untersucht. Rechtlich und finanziell gut umsetzbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=204', 'https://europepmc.org/article/MED/27289303', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8234, 29, 13, 'BE', 'Psychosoziale und psychotherapeutische Versorgung für Geflüchtete stärken und niedrigschwelligen, bedarfsgerechten Zugang ermöglichen.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=143', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8235, 29, 13, 'BE', 'Flächendeckende integrierte Gesundheitszentren mit therapeutischen, psychosozialen und präventiven Angeboten aufbauen.', '{2903}', null, 1, 2, null, 'Gesundheitszentren bündeln Angebote und können Hürden senken, der Zusammenhang mit dem Erkennen psychischer Symptome ist aber indirekt. Wirkung kaum untersucht; flächendeckender Aufbau dauert Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=202', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8236, 29, 13, 'BE', 'Gesundheitsförderung mit Schwerpunkt psychische Gesundheit verbindlich in Kitas, Schulen, Betrieben und Senior*inneneinrichtungen integrieren.', '{2903}', 8151, 1, 3, null, 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=208', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8237, 29, 13, 'BE', 'Psychosoziale Versorgung durch Zusammenarbeit von Straßensozialarbeit und psychosozialen Diensten direkt in den Kiezen stärken.', '{2903}', 8158, 2, 3, null, 'Bestehende kommunale Dienste erreichen auch Menschen, die von sich aus keine Hilfe suchen. Wirkung der Ausbaustufen kaum untersucht; Land kann Mittel und Aufgaben zügig anpassen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=73', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8238, 29, 13, 'MV', 'Kommunale Nachbarschaftstreffs als Orte der Geselligkeit und des gemeinsamen Arbeitens schaffen; Veranstaltungen für Menschen über 65 kostenlos anbieten.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://gruene-mv.de/?wpdmdl=33772#page=63', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8239, 29, 13, 'MV', 'Mentale Gesundheit an Schulen durch Aufklärung, geschultes Personal und verlässliche Unterstützung fördern.', '{2903}', 8151, 1, 3, null, 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'https://gruene-mv.de/?wpdmdl=33772#page=59', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8240, 29, 13, 'MV', 'Flächendeckende Krisendienste für schnelle und niedrigschwellige Hilfe in akuten Situationen aufbauen.', '{2903}', 8155, 2, 2, null, 'Krisenmodelle sind laut Cochrane-Übersicht gangbar und werden gut angenommen, die Studienlage ist aber klein und von geringer bis mäßiger Qualität. Flächendeckender Aufbau braucht Personal und Zeit.', 'https://gruene-mv.de/?wpdmdl=33772#page=59', 'https://europepmc.org/article/MED/26633650', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8241, 29, 13, 'MV', 'Psychosoziale Beratung flächendeckend und auskömmlich finanzieren und digitale Angebote ermöglichen.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://gruene-mv.de/?wpdmdl=33772#page=64', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8242, 29, 13, 'MV', 'Stigmatisierung psychisch erkrankter Menschen abbauen.', '{2904}', 8152, 1, 3, null, 'Aufklärung und Kontaktprogramme verbessern kurzfristig Einstellungen und Wissen; langfristige Effekte und Wirkung auf die Hilfesuche sind kaum belegt. Gut umsetzbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=60', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8243, 29, 13, 'ST', 'Bestehende Treffpunkte sichern und moderne Dorfzentren mit gebündelten Alltagsangeboten ermöglichen.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=39', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8244, 29, 13, 'ST', 'Quartiersansätze gegen Einsamkeit bündeln, unterstützen und finanzieren.', '{2901}', 8143, 1, 3, null, 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=39', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8245, 29, 13, 'ST', 'Jugendorte für freie Treffen und Austausch in kleineren Städten und Gemeinden schaffen und ausbauen.', '{2901}', null, 1, 3, null, 'Jugendorte bieten freie Treffen, erreichen aber vor allem junge Menschen und nicht die Gruppe der Verwitweten. Wirkung auf Einsamkeit kaum untersucht, leicht umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=56', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8246, 29, 13, 'ST', 'Kitas als soziale Treffpunkte und offene Familienzentren weiterentwickeln.', '{2901}', null, 1, 3, null, 'Familienzentren bieten Kontakt für Familien, erreichen aber kaum Verwitwete oder Ältere. Wirkung auf Einsamkeit kaum untersucht, Ausbau ist gut umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=58', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8247, 29, 13, 'ST', 'Selbsthilfegruppen unterstützen, um Engagement und soziale Teilhabe zu fördern.', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=74', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8248, 29, 13, 'ST', 'Patenschaften und Leihgroßeltern als generationenübergreifende Gemeinschaftsprojekte unterstützen.', '{2901}', 8148, 1, 3, null, 'Persönliche Kontakte können Alleinstehende erreichen, die Reichweite kleiner Modellprojekte ist aber gering. Einzelangebote wirkten in Übersichten seltener als Gruppenangebote; leicht umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=86', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8249, 29, 13, 'ST', 'Niedrigschwellige Beratung und Krisenintervention zur psychischen Gesundheit für Jugendliche ausbauen.', '{2903}', 8156, 2, 3, null, 'Anlaufstellen ohne Termin und Diagnose erleichtern jungen Menschen den ersten Schritt zur Hilfe. Wirkung kaum vergleichend untersucht; Länder und Kommunen können Standorte rasch fördern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=56', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8250, 29, 13, 'ST', 'Beratung, Prävention und Aufklärung zu psychischen Erkrankungen fördern und Stigmatisierungen abbauen.', '{2903,2904}', 8152, 1, 3, null, 'Aufklärung und Kontaktprogramme verbessern kurzfristig Einstellungen und Wissen; langfristige Effekte und Wirkung auf die Hilfesuche sind kaum belegt. Gut umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=84', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8251, 29, 13, 'ST', 'Geschlechtersensible Forschung zu Männergesundheit in Ausbildung und Klinikalltag verankern.', '{2904}', null, 1, 3, null, 'Forschung in Ausbildung und Klinikalltag kann Behandler für Männer sensibilisieren, ändert aber kaum die Scham, die Männer von der Hilfesuche abhält. Wirkung kaum untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=82', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8252, 29, 14, null, 'Babyboomer-Engagement gezielt für Sportangebote und Vereinsarbeit einbinden.', '{2901}', null, 1, 2, null, 'Einbindung der Babyboomer stärkt Vereine, erreicht Verwitwete aber nur mittelbar. Vereinsförderung ist überwiegend Ländersache, der Bund kann über Engagementprogramme beitragen. Wirkung kaum untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=32', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8253, 29, 14, null, 'Psychische Gesundheit durch Entstigmatisierung und niedrigschwellige digitale Angebote stärken.', '{2903}', null, 1, 3, null, 'Entstigmatisierung und digitale Angebote können Hürden senken, die Maßnahme nennt aber keinen konkreten Weg. Digitale Angebote wirken auf Symptome, Entstigmatisierung meist nur kurzfristig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8254, 29, 14, null, 'Suizidprävention spürbar ausbauen und Menschen mit Suizidgedanken Unterstützung zusichern.', '{2903}', null, 1, 2, null, 'Eine Übersicht sieht keine Einzelstrategie klar im Vorteil; ohne konkrete Bausteine bleibt die Wirkung offen. Suizidprävention ist überwiegend Länder- und Kassenaufgabe, der Bund kann mit Strategie und Geld beitragen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', 'https://europepmc.org/article/MED/27289303', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8255, 29, 14, null, 'Das Kostenerstattungsverfahren während der Wartezeit vereinfachen und standardisieren.', '{2905}', 8168, 1, 3, null, 'Überbrückt Wartezeit über Privatpraxen, solange es dort freie Plätze gibt; das Gesamtangebot wächst nicht. Wirkung kaum untersucht, rechtlich leicht änderbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8256, 29, 14, 'BE', 'Den generationsübergreifenden Dialog vertiefen.', '{2901}', 8148, 1, 3, null, 'Persönliche Kontakte können Alleinstehende erreichen, die Reichweite kleiner Modellprojekte ist aber gering. Einzelangebote wirkten in Übersichten seltener als Gruppenangebote; leicht umsetzbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=119', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8257, 29, 14, 'BE', 'Eltern für traditionelle Rollenbilder sensibilisieren und geschlechtersensible Erziehung fördern.', '{2904}', 8161, 1, 3, null, 'Setzt früh an Rollenbildern an, die später die Hilfesuche hemmen, wirkt aber erst nach Jahren und erreicht nur Teilgruppen. Wirkung auf spätere Hilfesuche kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=81', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8258, 29, 14, 'MV', 'Senioren- und Mehrgenerationenbegegnungsstätten mit generationsübergreifenden Freizeitprogrammen gegen Vereinsamung fördern.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=39', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8259, 29, 14, 'MV', 'Digitale Mental-Health-Angebote und Online-Interventionen in die Regelversorgung an Hochschulen integrieren.', '{2903}', 8160, 2, 3, null, 'Eine Meta-Analyse von 21 Studien findet mittlere Effekte digitaler Angebote bei Depression und Angst von Studierenden. Sie senken die Hürde zur Hilfe, wirken aber auf Symptome, nicht auf das Erkennen. Gut umsetzbar.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=115', 'https://europepmc.org/article/MED/40033658', 'belegt', '2026-10-06', false, true, 'blind'),
  (8260, 29, 14, 'MV', 'Online-Interventionen in den ersten vier bis sechs Wochen bis zur Regelversorgung ohne Verzögerung ermöglichen.', '{2903}', 8160, 2, 3, null, 'Eine Meta-Analyse von 21 Studien findet mittlere Effekte digitaler Angebote bei Depression und Angst von Studierenden. Sie senken die Hürde zur Hilfe, wirken aber auf Symptome, nicht auf das Erkennen. Gut umsetzbar.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=115', 'https://europepmc.org/article/MED/40033658', 'belegt', '2026-10-06', false, true, 'blind'),
  (8261, 29, 14, 'ST', 'Orte der Begegnung für zivilgesellschaftliche Initiativen fördern.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=35', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8262, 29, 15, null, 'Erhöhung des einkommensteuerlichen Grundfreibetrags zur Entlastung niedriger Einkommen', '{2902}', 8162, 1, 3, null, 'Entlastet über die Steuer, erreicht aber Armutsgefährdete ohne Steuerlast kaum; der Zusammenhang zwischen mehr Einkommen und weniger Einsamkeit ist nicht kausal belegt. Bund kann es kurzfristig regeln.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=59', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8263, 29, 15, 'BE', 'Einsamkeit im Alter durch gezielte Förderung von Teilhabe und ehrenamtlichem Engagement bekämpfen.', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=51', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8264, 29, 15, 'MV', 'Heimatvereine gezielt fördern.', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=67', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8265, 29, 15, 'MV', 'Die Zahl der Schulpsychologen am gestiegenen Bedarf ausrichten.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8266, 29, 16, null, 'Eine sanktionsfreie Mindestsicherung am Armutsrisiko ausrichten und für Menschen ohne ausreichendes Einkommen oder Vermögen öffnen.', '{2902}', null, 2, 1, null, 'Hebt das Mindesteinkommen direkt auf die Armutsschwelle; Studien zu Geldleistungen und psychischer Gesundheit sind uneinheitlich, zu Einsamkeit kaum vorhanden. Die Kosten sind hoch, die Finanzierung ungeklärt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=15', null, 'gemischt', '2026-10-06', false, true, 'blind'),
  (8267, 29, 16, null, 'Niedrige und mittlere Einkommen steuerlich entlasten.', '{2902}', 8162, 1, 3, null, 'Entlastet über die Steuer, erreicht aber Armutsgefährdete ohne Steuerlast kaum; der Zusammenhang zwischen mehr Einkommen und weniger Einsamkeit ist nicht kausal belegt. Bund kann es kurzfristig regeln.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=11', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8268, 29, 16, null, 'Kinder- und Jugendangebote wohnortnah, barrierefrei und gebührenfrei zugänglich machen und kommunal finanzieren.', '{2902}', 8165, 1, 2, null, 'Freizeit- und Bildungsangebote ermöglichen Teilhabe unabhängig vom Einkommen, wirken aber nur mittelbar auf Einsamkeit. Zuständig sind Länder und Kommunen, der Bund kann nur mit Geld beitragen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8269, 29, 16, null, 'Ein kostenloses bundesweites Senior*innen-Ticket für Mobilität und soziale Teilhabe einführen.', '{2902}', null, 1, 1, null, 'Ein kostenloses Ticket erleichtert Teilhabe finanziell, wirkt aber nur mittelbar auf Einsamkeit; Wirkung kaum untersucht. Nahverkehr ist Ländersache, die Kosten für alle Älteren sind sehr hoch und ungeklärt finanziert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=17', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8270, 29, 16, null, 'Psychotherapien bis zu ausreichender Kassenzulassung unbürokratisch über Kostenerstattung ermöglichen.', '{2905}', 8168, 1, 3, null, 'Überbrückt Wartezeit über Privatpraxen, solange es dort freie Plätze gibt; das Gesamtangebot wächst nicht. Wirkung kaum untersucht, rechtlich leicht änderbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8271, 29, 16, null, 'Die Bedarfsplanung für psychotherapeutische Kassensitze am tatsächlichen Bedarf ausrichten.', '{2905}', 8167, 2, 3, null, 'Mehr Kassensitze setzen direkt an der Kapazität an; Befragungen sehen fehlende Termine als Hauptengpass. Wirkung bisheriger Reformen nur teils belegt. Bund und Selbstverwaltung können es regeln.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', 'https://europepmc.org/articles/PMC13288593', 'offen', '2026-10-06', false, true, 'blind'),
  (8272, 29, 16, null, 'Ausbildungskosten künftiger Psychotherapeut*innen deckeln.', '{2905}', 8166, 1, 2, null, 'Sichert den Nachwuchs, wirkt aber erst nach Jahren und ändert nicht die Zahl der Kassensitze, die die Wartezeit begrenzt. Bund kann die Finanzierung regeln, braucht aber Einigung mit den Kassen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8273, 29, 16, null, 'Psychotherapeut*innen in Ausbildung einen Beschäftigungsstatus mit Zugang zu Tarifstrukturen geben.', '{2905}', 8166, 1, 2, null, 'Sichert den Nachwuchs, wirkt aber erst nach Jahren und ändert nicht die Zahl der Kassensitze, die die Wartezeit begrenzt. Bund kann die Finanzierung regeln, braucht aber Einigung mit den Kassen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8274, 29, 16, null, 'Die Finanzierung der Psychotherapieausbildung durch Weiterbildungsstätten gesetzlich regeln.', '{2905}', 8166, 1, 2, null, 'Sichert den Nachwuchs, wirkt aber erst nach Jahren und ändert nicht die Zahl der Kassensitze, die die Wartezeit begrenzt. Bund kann die Finanzierung regeln, braucht aber Einigung mit den Kassen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=19', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8275, 29, 16, 'BE', 'Einsamkeitsbeauftragte bei landeseigenen Wohnungsunternehmen sollen ältere Mieter*innen besuchen und nachbarschaftliche Aktivitäten organisieren.', '{2901}', 8144, 2, 3, null, 'Erreicht auch Menschen, die nicht von sich aus Treffpunkte aufsuchen. Besuchsangebote wirkten in Übersichten seltener als Gruppenangebote (60 % gegenüber 79 % der Studien mit Verbesserung). Gut umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=30', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8276, 29, 16, 'BE', 'Ein Aktionsprogramm soll nachbarschaftliche Angebote in Großsiedlungen fördern und Beteiligungsformate für das Miteinander ausbauen.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=32', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8277, 29, 16, 'BE', 'Kiezkantinen sollen bezahlbare Mahlzeiten und soziale Begegnungsorte in der Nachbarschaft schaffen.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=32', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8278, 29, 16, 'BE', 'Pilotprojekte für Sorgezentren sollen Nachbarschaft, gemeinsame Sorgearbeit und Selbstorganisation vor Ort ermöglichen.', '{2901}', null, 1, 3, null, 'Pilotprojekte schaffen Orte für Nachbarschaft, erreichen aber nur wenige Standorte und liefern erst später Erkenntnisse. Wirkung kaum untersucht, leicht umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=43', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8279, 29, 16, 'BE', 'Ein verbindliches Landesprogramm soll Einsamkeit durch aufsuchende Maßnahmen und bezirkliche Link-Worker bekämpfen.', '{2901}', null, 2, 2, null, 'Link-Worker vermitteln Isolierte in Angebote vor Ort; alle neun ausgewerteten Studien berichten positive Effekte, sie sind aber klein und uneinheitlich. Neue Stellen und Strukturen brauchen Aufbauzeit.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=113', 'https://europepmc.org/article/MED/34159848', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8280, 29, 16, 'BE', 'In jedem Bezirk soll eine Einsamkeitsbeauftragte oder ein Einsamkeitsbeauftragter eingesetzt werden.', '{2901}', 8143, 1, 3, null, 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=137', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8281, 29, 16, 'BE', 'Ein Altenhilfestrukturgesetz soll soziale Infrastruktur für ältere Menschen bezirksübergreifend sichern und finanzieren.', '{2901}', null, 2, 2, null, 'Ein Gesetz mit gesicherter Finanzierung gibt Begegnungs- und Unterstützungsangeboten für Ältere Dauer und Verbindlichkeit. Wirkung kaum untersucht; Gesetzgebung und Aufbau brauchen mehrere Jahre.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=148', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8282, 29, 16, 'BE', 'Aufsuchende Nachbarschaftshilfe für allein lebende ältere Menschen soll ausgebaut werden.', '{2901}', 8144, 2, 3, null, 'Erreicht auch Menschen, die nicht von sich aus Treffpunkte aufsuchen. Besuchsangebote wirkten in Übersichten seltener als Gruppenangebote (60 % gegenüber 79 % der Studien mit Verbesserung). Gut umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=151', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8283, 29, 16, 'BE', 'Wohnortnahe soziale Treffpunkte und aufsuchende Stadtteilarbeit sollen erhalten und ausgebaut werden.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=243', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8284, 29, 16, 'BE', 'Ein zusätzlicher Fonds soll Personal und Infrastruktur im Breitensport stärken, dessen Vereine Schutzräume gegen soziale Isolation bieten.', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=313', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8285, 29, 16, 'BE', 'Psychische Gesundheit soll im Unterricht und in Projektwochen thematisiert werden, um Wissen zu Erkrankungen und Hilfen zu vermitteln und Stigmatisierung abzubauen.', '{2903,2904}', 8151, 1, 3, null, 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=137', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8286, 29, 16, 'BE', 'Bezirkliche Kriseninterventionszentren mit Chats und aufsuchenden Hilfen sowie der Berliner Krisendienst sollen gestärkt werden.', '{2903}', 8155, 2, 2, null, 'Krisenmodelle sind laut Cochrane-Übersicht gangbar und werden gut angenommen, die Studienlage ist aber klein und von geringer bis mäßiger Qualität. Flächendeckender Aufbau braucht Personal und Zeit.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=137', 'https://europepmc.org/article/MED/26633650', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8287, 29, 16, 'BE', 'Psychosoziale Kontakt- und Beratungsstellen mit Einzel- und Gruppenberatung sowie alltagsnaher Unterstützung sollen in jedem Bezirk bestehen.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=137', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8288, 29, 16, 'BE', 'Die psychosoziale Unterstützung junger Menschen soll vernetzt und durch Lotsen, niedrigschwellige Krisenkontakte und Anlaufstellen erreichbar werden.', '{2903}', 8156, 2, 3, null, 'Anlaufstellen ohne Termin und Diagnose erleichtern jungen Menschen den ersten Schritt zur Hilfe. Wirkung kaum vergleichend untersucht; Länder und Kommunen können Standorte rasch fördern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=179', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8289, 29, 16, 'MV', 'Begegnungsorte und Nachbarschaftsnetzwerke gegen Einsamkeit im Alter unterstützen.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=12', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8290, 29, 16, 'MV', 'Resilienzförderung und Lerntrainings in schulischen Rahmenplänen verankern.', '{2903}', 8151, 1, 3, null, 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8291, 29, 16, 'MV', 'Digitale Hilfsangebote und flächendeckende Schulpsychologie für Kinder und Jugendliche ausbauen.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=11', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8292, 29, 16, 'MV', 'Gesundheitsförderndes Verhalten, Emotionsregulation und den Umgang mit Stress im Schulalltag verankern.', '{2903}', 8151, 1, 3, null, 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=11', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8293, 29, 16, 'MV', 'Die psychosoziale Beratung durch Studierendenwerke dauerhaft sichern und erweitern.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=17', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8294, 29, 16, 'ST', 'Barrierefreie Begegnungsstätten und offene Treffpunkte fördern und erweitern.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=58', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8295, 29, 16, 'ST', 'Nachbarschaftshilfe und Senior:innenassistenz mit Beratungsangeboten unterstützen.', '{2901}', 8144, 2, 3, null, 'Erreicht auch Menschen, die nicht von sich aus Treffpunkte aufsuchen. Besuchsangebote wirkten in Übersichten seltener als Gruppenangebote (60 % gegenüber 79 % der Studien mit Verbesserung). Gut umsetzbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=59', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8296, 29, 16, 'ST', 'Patenschaften für Alleinstehende fördern.', '{2901}', 8148, 1, 3, null, 'Persönliche Kontakte können Alleinstehende erreichen, die Reichweite kleiner Modellprojekte ist aber gering. Einzelangebote wirkten in Übersichten seltener als Gruppenangebote; leicht umsetzbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=59', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8297, 29, 16, 'ST', 'Präventions-, Beratungs- und Behandlungsangebote für Betroffene ausbauen und bestehende Angebote unterstützen.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=52', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8298, 29, 16, 'ST', 'Medizinisches Fachpersonal durch Aufklärung für Stigmata sensibilisieren und diese abbauen.', '{2904}', 8153, 1, 3, null, 'Schulungen können Vorurteile im Umfeld von Betroffenen mindern; Studien zeigen vor allem kurzfristige Einstellungsänderungen, kaum Verhaltens- oder Langzeitwirkung. Leicht umsetzbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=52', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8299, 29, 16, 'ST', 'Psychisches Leiden infolge medizinischer Stigmata verhindern, behandeln und rechtlich ahnden.', '{2904}', null, 1, 2, null, 'Weniger Stigmatisierung durch Behandelnde kann die Hilfesuche erleichtern, erreicht aber nur einen Teil der Scham. Rechtliche Ahndung ist schwer zu fassen; Wirkung kaum untersucht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=52', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8300, 29, 16, 'ST', 'Lotsenstellen in die psychische Versorgung und frühe Hilfen mit Familienhebammen landesweit stärken.', '{2903}', 8157, 1, 3, null, 'Lotsen helfen, vorhandene Angebote zu finden, schaffen aber keine zusätzlichen Behandlungsplätze. Wirkung auf Wartezeiten und Hilfesuche kaum untersucht; gut umsetzbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=60', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8301, 29, 17, null, 'Mindestrenten nach Versicherungsdauer sichern und stufenweise erhöhen', '{2902}', 8163, 2, 2, null, 'Hebt Alterseinkommen direkt an; Studien zu Geldleistungen und psychischer Gesundheit sind uneinheitlich, der Einfluss auf Einsamkeit ist kaum untersucht. Kosten erfordern Finanzierung und Vorlauf.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=22', null, 'gemischt', '2026-10-06', false, true, 'blind'),
  (8302, 29, 17, null, 'Wohnortnahe Freizeit- und Bildungsangebote für Kinder und Familien zugänglich machen', '{2902}', 8165, 1, 2, null, 'Freizeit- und Bildungsangebote ermöglichen Teilhabe unabhängig vom Einkommen, wirken aber nur mittelbar auf Einsamkeit. Zuständig sind Länder und Kommunen, der Bund kann nur mit Geld beitragen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=32', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8303, 29, 17, null, 'Ausbildungsplätze für Psychotherapeutinnen und -therapeuten schaffen', '{2905}', null, 1, 2, null, 'Mehr Ausbildungsplätze erhöhen langfristig die Zahl der Fachkräfte, ändern aber nicht die Kassensitze und wirken erst nach Jahren. Studienplätze sind Ländersache, der Bund kann nur beitragen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=27', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8304, 29, 17, 'BE', 'Stadtteilzentren ausbauen und dauerhaft sichern, Nachbarschafts- und Begegnungsprojekte fördern, gezielte Maßnahmen gegen Vereinsamung.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=12', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8305, 29, 17, 'BE', 'Schulpsychologinnen und Schulpsychologen flächendeckend an Schulen einsetzen.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=16', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8306, 29, 17, 'MV', 'Sportvereine, Kulturangebote und Ehrenamt als Orte der Begegnung und sozialen Teilhabe stärken.', '{2901}', 8145, 1, 3, null, 'Vereine und Engagement bieten Kontaktgelegenheiten, die Förderung wirkt aber nur indirekt und erreicht Verwitwete nicht gezielt. Wirkung auf Einsamkeit kaum untersucht; leicht umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=15', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8307, 29, 17, 'MV', 'Soziale Orte und Unterstützungsstrukturen im ländlichen Raum fördern, mit Mobilitätsprogrammen und niedrigschwelligen Treffpunkten.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=15', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8308, 29, 17, 'MV', 'Die Landesstrategie gegen Einsamkeit mit konkreten Maßnahmen, klaren Zuständigkeiten und ausreichender Finanzierung ausbauen.', '{2901}', 8143, 1, 3, null, 'Strategie und Koordination schaffen selbst kein Angebot; die Wirkung hängt von den Maßnahmen ab, die daraus folgen. Wirkung solcher Strukturen kaum untersucht, rechtlich und finanziell leicht umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=15', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8309, 29, 17, 'MV', 'Krisentelefone und ambulante Hilfen für Menschen mit psychischen Erkrankungen und in akuten Belastungssituationen sichern und ausbauen.', '{2903}', 8155, 2, 2, null, 'Krisenmodelle sind laut Cochrane-Übersicht gangbar und werden gut angenommen, die Studienlage ist aber klein und von geringer bis mäßiger Qualität. Flächendeckender Aufbau braucht Personal und Zeit.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=15', 'https://europepmc.org/article/MED/26633650', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8310, 29, 17, 'MV', 'Jugendsozialarbeit verlässlich finanzieren und Präventionsangebote für Kinder und Jugendliche zur Stärkung sozialer und mentaler Gesundheit ausbauen.', '{2903}', 8156, 2, 3, null, 'Anlaufstellen ohne Termin und Diagnose erleichtern jungen Menschen den ersten Schritt zur Hilfe. Wirkung kaum vergleichend untersucht; Länder und Kommunen können Standorte rasch fördern.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=15', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8311, 29, 17, 'MV', 'Schulen mit multiprofessionellen Teams zur Prävention psychischer Probleme ausstatten.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8312, 29, 17, 'MV', 'Mehr Schulpsychologen und dauerhaft finanzierte Schulsozialarbeit bereitstellen.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=61', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8313, 29, 17, 'MV', 'Erziehungs- und Familienberatung mit kurzen Wartezeiten und niedrigschwelligen Zugängen stärken.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=61', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8314, 29, 17, 'MV', 'Präventionsangebote zu psychischer Gesundheit, Resilienz, Medienkompetenz und Konfliktbewältigung ausbauen.', '{2903}', 8151, 1, 3, null, 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=61', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8315, 29, 17, 'ST', 'Einen landesweiten Personalschlüssel für Schulsozialarbeit und Schulpsychologie einführen.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=47', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8316, 29, 17, 'ST', 'Schulpsychologen präventiv einsetzen und für Lernende sowie Lehrkräfte niedrigschwellig erreichbar machen.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=48', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8317, 29, 17, 'ST', 'Multiprofessionelle Teams mit Schulpsychologie als Regelangebot an Schulen etablieren.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=48', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-06', false, true, 'blind'),
  (8318, 29, 17, 'ST', 'Den sozialpsychiatrischen Dienst ausbauen und stärker in Jugend-, Schul- und Integrationsarbeit einbinden.', '{2903}', 8158, 2, 3, null, 'Bestehende kommunale Dienste erreichen auch Menschen, die von sich aus keine Hilfe suchen. Wirkung der Ausbaustufen kaum untersucht; Land kann Mittel und Aufgaben zügig anpassen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=59', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8331, 30, 11, null, 'Die Teillegalisierung von Cannabis wird rückgängig gemacht.', '{3005}', 8330, 1, 3, null, 'Kann den legalen Konsum senken, setzt aber nicht an unbekannten Wirkstoffen am Schwarzmarkt an; Studien zur Legalisierung sind gemischt. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', 'https://europepmc.org/articles/PMC10176789', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8332, 30, 11, 'MV', 'Sucht- und Drogenberatung dauerhaft stärken; Perspektivplan sichert Finanzierung und Organisation der Beratungsstellen.', '{3006}', 8321, 1, 3, null, 'Sichert vorhandene Angebote, schafft aber kaum zusätzlichen Zugang und senkt die Scham-Hürde nicht. Rechtlich und finanziell leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=80', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8333, 30, 11, 'MV', 'Polizei und Aufsichtsbehörden personell, technisch und rechtlich so ausstatten, dass illegales Glücksspiel online und vor Ort verfolgt wird.', '{3004}', 8327, 2, 2, null, 'Verfolgung kann illegale Angebote eindämmen; Wirkung auf Spielschäden kaum untersucht, Online-Anbieter sind schwer zu fassen. Braucht Personal und Länderabstimmung.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=81', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8334, 30, 11, 'MV', 'Mehr Mittel aus den Erträgen der staatlichen Toto-Lotto GmbH für Suchtprävention beim Glücksspiel bereitstellen.', '{3004}', 8326, 1, 3, null, 'Aufklärung wirkte in weniger als der Hälfte der Studien zu Jugendprogrammen; Angebot und Werbung bleiben unverändert. Mit Landesmitteln leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=82', 'https://doi.org/10.1016/j.addbeh.2018.11.048', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8335, 30, 11, 'ST', 'Regeln für Glücksspiel so ausgestalten, dass Jugend- und Spielerschutz gestärkt und illegales Glücksspiel bekämpft wird.', '{3004}', null, 1, 2, null, 'Nennt Ziele für das Regelwerk ohne konkrete Mittel; Wirkung hängt von der Ausgestaltung ab. Änderungen brauchen alle Länder.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8336, 30, 12, null, 'Strengere Regulierung, Werbebeschränkungen und Altersgrenzen für Alkohol, Einweg-Zigaretten und neuartige Nikotinprodukte.', '{3003}', 8328, 2, 3, null, 'Wer mehr Werbung wahrnimmt, raucht später häufiger; Beschränkungen verringern die Reichweite, aber nicht vollständig. Bundesrecht, EU-Spielraum vorhanden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=28', 'https://www.cochrane.org/evidence/CD003439_does-advertising-and-promotion-tobacco-products-make-children-more-likely-smoke', 'belegt', '2026-10-06', false, true, 'blind'),
  (8337, 30, 12, null, 'Schritte einleiten, um eine europarechtskonforme Legalisierung von Cannabis zu ermöglichen.', '{3005}', 8329, 2, 1, null, 'Geprüfte Qualität kann Verunreinigungen senken; Studien zeigen gemischte Folgen für Konsum und Gesundheit. Hängt von EU- und UN-Recht ab, das Deutschland nicht allein ändert.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=46', 'https://europepmc.org/articles/PMC10176789', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8338, 30, 12, 'BE', 'Beratungs- und Versorgungsangebote für wohnungslose Menschen, darunter Suchtberatung, ausbauen und dauerhaft sichern.', '{3006}', 8323, 2, 3, null, 'Erreicht eine Gruppe, die Behandlung häufig meidet; Wirkung kaum untersucht. Landesmittel und Träger vorhanden.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=51', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8339, 30, 12, 'BE', 'Therapieangebote für suchtkranke Menschen ausbauen.', '{3006}', null, 2, 3, null, 'Mehr Therapie erweitert den Zugang, Drugchecking macht Inhalte erkennbar; beides in Deutschland erst in Teilen untersucht. Landesmittel und rechtliche Grundlage vorhanden.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=51', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8340, 30, 12, 'BE', 'Abschaffung des begleiteten Trinkens für Jugendliche unter 16 Jahren unterstützen.', '{3001}', null, 1, 2, null, 'Schließt einen legalen Zugang für unter 16-Jährige, betrifft aber nur eine kleine Gruppe. Regelung liegt im Bundesrecht, das Land kann nur im Bundesrat unterstützen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=51', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8341, 30, 12, 'MV', 'Auf Bundesebene ein Suchtpräventionsprogramm für Kommunen anstoßen, das Prävention vor Ort bei Alkohol, Nikotin, Cannabis und Drogen finanziert.', '{3001}', null, 1, 2, null, 'Kommunale Prävention zeigt in Studien gemischte Wirkung auf Konsum. Hängt von einem Bundesprogramm ab, das das Land nur anstoßen kann.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=31', 'https://www.cochrane.org/evidence/CD003020_do-school-based-programmes-prevent-illicit-drug-use', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8342, 30, 12, 'MV', 'Landesfachstelle für Kinder aus psychisch und suchtbelasteten Familien über 2027 hinaus finanzieren, um Hilfe zu bieten und Sucht vorzubeugen.', '{3006}', 8321, 1, 3, null, 'Sichert vorhandene Angebote, schafft aber kaum zusätzlichen Zugang und senkt die Scham-Hürde nicht. Rechtlich und finanziell leicht umsetzbar.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=35', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8343, 30, 12, 'ST', 'Soziale Beratungsangebote einschließlich Suchtberatung landesweit stärken und besser vernetzen.', '{3006}', 8320, 2, 3, null, 'Behandlung wirkt gut belegt, erreicht aber zu wenige Menschen; mehr Angebot beseitigt Scham als Hürde nur indirekt. Landesmittel und Träger vorhanden.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=15', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8344, 30, 13, null, 'Werbung für Tabak und Alkohol stärker regulieren.', '{3003}', 8328, 2, 3, null, 'Wer mehr Werbung wahrnimmt, raucht später häufiger; Beschränkungen verringern die Reichweite, aber nicht vollständig. Bundesrecht, EU-Spielraum vorhanden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=94', 'https://www.cochrane.org/evidence/CD003439_does-advertising-and-promotion-tobacco-products-make-children-more-likely-smoke', 'belegt', '2026-10-06', false, true, 'blind'),
  (8345, 30, 13, null, 'Einheitliche, neutrale Verpackungen ohne Markenlogos für Tabakprodukte einführen.', '{3003}', null, 1, 3, null, 'Neutrale Packungen machen Tabak weniger attraktiv, der Rückgang des Konsums ist klein. EU-Recht erlaubt es, Bundesgesetz genügt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=94', 'https://www.cochrane.org/evidence/CD011244_do-plain-tobacco-packaging-reduce-smoking', 'belegt', '2026-10-06', false, true, 'blind'),
  (8346, 30, 13, null, 'Cannabis in lizenzierten Fachgeschäften verkaufen, um Schwarzmarkt und organisierte Kriminalität einzudämmen.', '{3005}', 8329, 2, 1, null, 'Geprüfte Qualität kann Verunreinigungen senken; Studien zeigen gemischte Folgen für Konsum und Gesundheit. Hängt von EU- und UN-Recht ab, das Deutschland nicht allein ändert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=96', 'https://europepmc.org/articles/PMC10176789', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8347, 30, 13, null, 'Drogenkriminalität auf organisierten Handel konzentrieren und dafür Kriminalpolizei und Zoll stärken.', '{3005}', null, 1, 2, null, 'Verfolgung des organisierten Handels macht den Markt nicht sicherer; Wirkung auf Verfügbarkeit und Reinheit ist kaum belegt. Personalaufbau bei Polizei und Zoll dauert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=96', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8348, 30, 13, null, 'Angebote für Prävention, Therapie und Gesundheitsschutz auch bei legalen Suchtmitteln ausbauen.', '{3006}', 8325, 2, 2, null, 'Behandlung ist belegt wirksam, die Versorgung liegt aber vor allem bei Ländern, Kommunen und Kassen; der Bund kann Programme und Rahmen setzen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=96', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8349, 30, 13, 'BE', 'Werbung für Sportwetten und Glücksspiel einschränken, Warnhinweise in der Werbung vorschreiben, Werbung gemeinnütziger Vereine verbieten.', '{3004}', null, 2, 2, null, 'Weniger Werbung und Warnhinweise können Spielen mindern; Warnhinweise wirken in Studien gemischt. Änderungen am Glücksspielstaatsvertrag brauchen alle Länder.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=38', null, 'gemischt', '2026-10-06', false, true, 'blind'),
  (8350, 30, 13, 'BE', 'Spielersperrdatei „Oasis“ ausbauen, auch für glücksspielartige Elemente digital; im Online-Glücksspiel Vermögensprüfungen und feste Einzahlungslimits als Standard.', '{3004}', null, 2, 2, null, 'Sperren und Limits helfen vor allem bei Pflicht statt Freiwilligkeit; Reviews zeigen begrenzte Wirkung wegen Umgehung. Änderungen brauchen alle Länder.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=210', 'https://doi.org/10.1016/j.addbeh.2018.11.048', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8351, 30, 13, 'BE', 'Verhaltensbezogene Süchte wie Glücksspiel- oder Medienspielsucht systematisch in die Hilfestrukturen einbinden.', '{3006}', 8320, 2, 3, null, 'Behandlung wirkt gut belegt, erreicht aber zu wenige Menschen; mehr Angebot beseitigt Scham als Hürde nur indirekt. Landesmittel und Träger vorhanden.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=210', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8352, 30, 13, 'BE', 'Wartezeiten auf Therapieplätze verkürzen und niedrigschwellige Hilfsangebote ausbauen, besonders für junge und sozial benachteiligte Menschen.', '{3006}', 8322, 2, 2, null, 'Konsumräume erreichen Randgruppen und senken Überdosierungen ohne mehr Konsum; Substitution ist gut belegt. Räume brauchen Landesrecht, Therapieplätze Personal.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=209', 'https://doi.org/10.1016/j.drugalcdep.2014.10.012', 'belegt', '2026-10-06', false, true, 'blind'),
  (8353, 30, 13, 'BE', 'Sucht- und Präventionsarbeit im Strafvollzug absichern, Zugang zu Substitution und Therapie sowie Anschlussversorgung nach der Haft.', '{3006}', 8324, 2, 3, null, 'Substitutionsbehandlung ist gut belegt, auch in Haft; senkt Rückfall und Todesfälle. Setzt an Behandlungszugang an, nicht an Scham allgemein. Länderzuständigkeit.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=210', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8354, 30, 13, 'MV', 'Beratungsangebote zu Suchterkrankungen ausbauen und unabhängige Ansprechpersonen in allen Regionen stärken.', '{3006}', 8320, 2, 3, null, 'Behandlung wirkt gut belegt, erreicht aber zu wenige Menschen; mehr Angebot beseitigt Scham als Hürde nur indirekt. Landesmittel und Träger vorhanden.', 'https://gruene-mv.de/?wpdmdl=33772#page=60', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8355, 30, 13, 'ST', 'Kommunale Suchtberatungsstellen verlässlich fördern und Beratung zu Online-, Medien- und Gamingsucht stärken.', '{3006}', 8320, 2, 3, null, 'Behandlung wirkt gut belegt, erreicht aber zu wenige Menschen; mehr Angebot beseitigt Scham als Hürde nur indirekt. Landesmittel und Träger vorhanden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=85', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8356, 30, 13, 'ST', 'Anonyme, rund um die Uhr erreichbare digitale Suchtberatung dauerhaft aus Landesmitteln finanzieren.', '{3006}', 8319, 2, 3, null, 'Anonymität und kurze Wege senken die Hemmschwelle durch Scham; Wirkung auf die Inanspruchnahme ist kaum untersucht. Finanzierbar und kurzfristig umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=85', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8357, 30, 14, null, 'Cannabis-Legalisierung beibehalten, um den Schwarzmarkt einzudämmen sowie Qualität und Jugendschutz zu sichern.', '{3005}', null, 2, 3, null, 'Kontrollierte Qualität senkt Verunreinigungen bei Cannabis; Studien zeigen gemischte Folgen für Konsum und Gesundheit. Rechtsrahmen besteht bereits.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', 'https://europepmc.org/articles/PMC10176789', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8358, 30, 14, 'BE', 'Spielerschutz im Glücksspiel stärken: konsequent gegen illegale Angebote vorgehen und regulierten Anbietern sichere Rahmenbedingungen schaffen.', '{3004}', 8327, 2, 2, null, 'Verfolgung kann illegale Angebote eindämmen; Wirkung auf Spielschäden kaum untersucht, Online-Anbieter sind schwer zu fassen. Braucht Personal und Länderabstimmung.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8359, 30, 14, 'BE', 'Wartezeiten auf Therapieplätze verkürzen und niedrigschwellige Angebote ausbauen, besonders für junge Menschen und sozial Benachteiligte.', '{3006}', 8322, 2, 2, null, 'Konsumräume erreichen Randgruppen und senken Überdosierungen ohne mehr Konsum; Substitution ist gut belegt. Räume brauchen Landesrecht, Therapieplätze Personal.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=117', 'https://doi.org/10.1016/j.drugalcdep.2014.10.012', 'belegt', '2026-10-06', false, true, 'blind'),
  (8360, 30, 14, 'BE', 'Alkohol- und Medikamentenberatung in den Bezirken landesweit steuern, damit sie flächendeckend und verlässlich verfügbar ist.', '{3006}', 8321, 1, 3, null, 'Sichert vorhandene Angebote, schafft aber kaum zusätzlichen Zugang und senkt die Scham-Hürde nicht. Rechtlich und finanziell leicht umsetzbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=118', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8361, 30, 14, 'BE', 'Suchtprävention mit Fokus auf junge Menschen ausbauen (Schule, Jugendarbeit, digitale Beratung) und den Zugang zu Beratung und Therapie verbessern.', '{3006}', 8320, 2, 3, null, 'Behandlung wirkt gut belegt, erreicht aber zu wenige Menschen; mehr Angebot beseitigt Scham als Hürde nur indirekt. Landesmittel und Träger vorhanden.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=118', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8362, 30, 14, 'BE', 'Sucht- und Präventionsarbeit im Strafvollzug absichern, mit Zugang zu Substitution und Therapie sowie Anschlussversorgung nach der Haft.', '{3006}', 8324, 2, 3, null, 'Substitutionsbehandlung ist gut belegt, auch in Haft; senkt Rückfall und Todesfälle. Setzt an Behandlungszugang an, nicht an Scham allgemein. Länderzuständigkeit.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=118', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8363, 30, 15, null, 'Die Freigabe des Cannabiskonsums außerhalb medizinischer Indikationen soll umgehend zurückgenommen werden.', '{3005}', 8330, 1, 3, null, 'Kann den legalen Konsum senken, setzt aber nicht an unbekannten Wirkstoffen am Schwarzmarkt an; Studien zur Legalisierung sind gemischt. Per Bundesgesetz umsetzbar.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=32', 'https://europepmc.org/articles/PMC10176789', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8364, 30, 15, null, 'Suchtpsychiatrische Versorgung ausbauen, damit Drogenkranke dauerhaft abstinent werden.', '{3006}', 8325, 2, 2, null, 'Behandlung ist belegt wirksam, die Versorgung liegt aber vor allem bei Ländern, Kommunen und Kassen; der Bund kann Programme und Rahmen setzen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=32', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8365, 30, 15, 'MV', 'Alkohol- und Drogenprävention im Land finanziell und strukturell absichern.', '{3001}', null, 1, 3, null, 'Prävention sichert vorhandene Arbeit, Programme zeigen gemischte Wirkung auf Konsum. Mit Landesmitteln leicht umsetzbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=63', 'https://www.cochrane.org/evidence/CD003020_do-school-based-programmes-prevent-illicit-drug-use', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8366, 30, 16, null, 'Werbe- und Sponsoringverbot für Tabak, Alkohol, andere Drogen und Glücksspielangebote, begleitet von Aufklärungskampagnen zu Alkohol-, Drogen- und Spielsucht.', '{3003}', null, 3, 2, null, 'Werbung erhöht die Konsumbereitschaft, ein Verbot entfernt die Ursache direkt. Glücksspielwerbung ist Ländersache, Alkohol-Verbot hat verfassungs- und EU-rechtliche Hürden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', 'https://www.cochrane.org/evidence/CD003439_does-advertising-and-promotion-tobacco-products-make-children-more-likely-smoke', 'belegt', '2026-10-06', false, true, 'blind'),
  (8367, 30, 16, null, 'Drogenkonsum vollständig entkriminalisieren und stattdessen medizinische und sozialarbeiterische Interventionsprogramme schaffen.', '{3005}', null, 2, 2, null, 'Strafandrohung hängt mit schlechterem Zugang zu Prävention und Behandlung zusammen; Studien meist beobachtend. Braucht Gesetzesänderung und Aufbau der Hilfsprogramme.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', 'https://europepmc.org/articles/PMC6005363', 'belegt', '2026-10-06', false, true, 'blind'),
  (8368, 30, 16, null, 'Cannabis vollständig legalisieren und dafür die nötigen Änderungen auf EU- und UN-Ebene durchsetzen.', '{3005}', 8329, 2, 1, null, 'Geprüfte Qualität kann Verunreinigungen senken; Studien zeigen gemischte Folgen für Konsum und Gesundheit. Hängt von EU- und UN-Recht ab, das Deutschland nicht allein ändert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', 'https://europepmc.org/articles/PMC10176789', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8369, 30, 16, null, 'Flächendeckend Drogenkonsumräume, sterile Konsumutensilien, Medikamente gegen Überdosierung und Drugchecking verfügbar machen.', '{3005}', null, 2, 2, null, 'Konsumräume senken Überdosierungen ohne mehr Konsum oder Kriminalität; Drugchecking ist weniger untersucht. Räume sind Ländersache, der Bund kann Rahmen und Mittel setzen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', 'https://doi.org/10.1016/j.drugalcdep.2014.10.012', 'belegt', '2026-10-06', false, true, 'blind'),
  (8370, 30, 16, null, 'Präventions-, Beratungs- und Hilfsangebote im Bereich Drogen und Sucht stärken.', '{3006}', 8325, 2, 2, null, 'Behandlung ist belegt wirksam, die Versorgung liegt aber vor allem bei Ländern, Kommunen und Kassen; der Bund kann Programme und Rahmen setzen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8371, 30, 16, 'BE', 'Land soll sich auf Bundesebene für ein weitgehendes Werbeverbot für Sportwetten einsetzen.', '{3004}', null, 2, 1, null, 'Weniger Werbung hängt mit weniger Wetten zusammen; das Land kann nur auf Bundesebene werben, Zustimmung anderer Länder und des Bundes fehlt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=324', null, 'gemischt', '2026-10-06', false, true, 'blind'),
  (8372, 30, 16, 'BE', 'Präventions- und Aufklärungsmaßnahmen zu Sportwetten auf Landesebene deutlich verstärken, besonders für junge Männer in Sportvereinen.', '{3004}', 8326, 1, 3, null, 'Aufklärung wirkte in weniger als der Hälfte der Studien zu Jugendprogrammen; Angebot und Werbung bleiben unverändert. Mit Landesmitteln leicht umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=324', 'https://doi.org/10.1016/j.addbeh.2018.11.048', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8373, 30, 16, 'BE', 'Äußeres Erscheinungsbild von Wettbüros regeln, etwa getönte Außenfenster.', '{3004}', null, 1, 3, null, 'Weniger Sichtbarkeit kann Anreize senken, ändert aber Zugang und Einsatzhöhe nicht. Per Landesrecht rasch umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=324', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8374, 30, 16, 'BE', 'Angebote der Sucht- und Drogenhilfe verstetigen und ausbauen, ebenso bedarfsorientierte ambulante Therapieangebote.', '{3006}', 8320, 2, 3, null, 'Behandlung wirkt gut belegt, erreicht aber zu wenige Menschen; mehr Angebot beseitigt Scham als Hürde nur indirekt. Landesmittel und Träger vorhanden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=145', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8375, 30, 16, 'BE', 'Psychosoziale Betreuung für Abhängige weiterentwickeln und niedrigschwelligen Zugang zur Substitutionsbehandlung vorantreiben.', '{3006}', 8322, 2, 2, null, 'Konsumräume erreichen Randgruppen und senken Überdosierungen ohne mehr Konsum; Substitution ist gut belegt. Räume brauchen Landesrecht, Therapieplätze Personal.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=145', 'https://doi.org/10.1016/j.drugalcdep.2014.10.012', 'belegt', '2026-10-06', false, true, 'blind'),
  (8376, 30, 16, 'BE', 'Suchthilfe und psychiatrische Versorgung über das Gesundheitsdienstgesetz ausweiten, auch mit Diagnostik und Therapie zulasten der Krankenkassen.', '{3006}', null, 2, 2, null, 'Mehr Suchthilfe und Therapie erweitert den Zugang; Kassenleistungen hängen an Bundesrecht und Selbstverwaltung. Wirkung auf die Scham-Hürde ist indirekt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=130', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8377, 30, 16, 'BE', 'Zwei Versorgungszentren für obdach- und wohnungslose Menschen finanzieren, unter anderem mit Beratung bei Suchterkrankungen.', '{3006}', 8323, 2, 3, null, 'Erreicht eine Gruppe, die Behandlung häufig meidet; Wirkung kaum untersucht. Landesmittel und Träger vorhanden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=130', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8378, 30, 16, 'ST', 'Mobile Beratungsstellen für Sucht-, Schulden- und Familienprobleme sowie Sozialarbeit und Familienhilfe im ländlichen Raum verfügbar machen.', '{3006}', 8319, 2, 3, null, 'Anonymität und kurze Wege senken die Hemmschwelle durch Scham; Wirkung auf die Inanspruchnahme ist kaum untersucht. Finanzierbar und kurzfristig umsetzbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=134', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8379, 30, 17, 'BE', 'Hilfsangebote für Drogenkranke wie medizinische Betreuung und Unterstützung bei Substitutionstherapien ausweiten.', '{3006}', 8322, 2, 2, null, 'Konsumräume erreichen Randgruppen und senken Überdosierungen ohne mehr Konsum; Substitution ist gut belegt. Räume brauchen Landesrecht, Therapieplätze Personal.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=12', 'https://doi.org/10.1016/j.drugalcdep.2014.10.012', 'belegt', '2026-10-06', false, true, 'blind'),
  (8380, 30, 17, 'MV', 'Mindestens ein Prozent der Glücksspielerlöse des Vorjahres verbindlich für Suchtprävention bei Glücksspiel einsetzen.', '{3004}', 8326, 1, 3, null, 'Aufklärung wirkte in weniger als der Hälfte der Studien zu Jugendprogrammen; Angebot und Werbung bleiben unverändert. Mit Landesmitteln leicht umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=64', 'https://doi.org/10.1016/j.addbeh.2018.11.048', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8381, 30, 17, 'MV', 'Schwerpunktberatungsstellen und Landesfachstelle Glücksspielsucht personell und sachlich deutlich stärker ausstatten.', '{3006}', 8320, 2, 3, null, 'Behandlung wirkt gut belegt, erreicht aber zu wenige Menschen; mehr Angebot beseitigt Scham als Hürde nur indirekt. Landesmittel und Träger vorhanden.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=64', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8382, 30, 17, 'MV', 'Flächendeckende Präventionsangebote gegen Glücksspielsucht, auch mobil und digital, vor allem im ländlichen Raum.', '{3004}', 8326, 1, 3, null, 'Aufklärung wirkte in weniger als der Hälfte der Studien zu Jugendprogrammen; Angebot und Werbung bleiben unverändert. Mit Landesmitteln leicht umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=64', 'https://doi.org/10.1016/j.addbeh.2018.11.048', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8383, 30, 17, 'MV', 'Initiativen zur Regulierung suchtfördernder Mechanismen wie Lootboxen fortführen und unterstützen.', '{3004}', null, 1, 1, null, 'Lootboxen ähneln Glücksspiel, Wirkung von Regulierung ist kaum untersucht. Zuständig sind Bund und EU, das Land kann nur Initiativen unterstützen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=64', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8384, 30, 17, 'MV', 'Eigenständige Förderrichtlinie für Sucht- und Drogenberatung mit ausreichenden, verlässlichen Landesmitteln wieder einführen.', '{3006}', 8321, 1, 3, null, 'Sichert vorhandene Angebote, schafft aber kaum zusätzlichen Zugang und senkt die Scham-Hürde nicht. Rechtlich und finanziell leicht umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=62', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8385, 30, 17, 'MV', 'Suchtprävention und Suchtberatung als Pflichtaufgabe der Gesundheitsämter verankern.', '{3006}', 8321, 1, 3, null, 'Sichert vorhandene Angebote, schafft aber kaum zusätzlichen Zugang und senkt die Scham-Hürde nicht. Rechtlich und finanziell leicht umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=62', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8386, 30, 17, 'MV', 'Niedrigschwellige, anonyme Beratungsangebote ausbauen.', '{3006}', 8319, 2, 3, null, 'Anonymität und kurze Wege senken die Hemmschwelle durch Scham; Wirkung auf die Inanspruchnahme ist kaum untersucht. Finanzierbar und kurzfristig umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=64', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8396, 33, 11, null, 'Kinder- und Jugendschutz im Netz einschließlich sozialer Medien gewährleisten; bei der Umsetzung des Digital Services Act Jugend- und Medienschutz betonen.', '{3301}', 8394, 1, 3, null, 'Der DSA verpflichtet Plattformen zu Risikoprüfungen auch zu Minderjährigen; die Wirkung auf Likes- und Belohnungsdesign ist bisher kaum untersucht. Umsetzung durch den Bund ist möglich.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=41', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8397, 33, 11, 'BE', 'Medienkompetenz wird an allen Schulen verbindlicher Bestandteil des Unterrichts; Schülerinnen und Schüler lernen kritischen und verantwortungsvollen Umgang mit Medien.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=63', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8398, 33, 11, 'BE', 'Lehrkräfte werden im Bereich Digitalisierung und Medienbildung verbindlich und systematisch qualifiziert.', '{3303}', 8391, 1, 3, null, 'Geschulte Fachkräfte und Zentren können Medienbildung tragen; die Wirkung auf die Mediennutzung der Kinder läuft nur über den Unterricht und ist kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=60', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8399, 33, 11, 'MV', 'Landeseinheitliches Verbot privater Smartphone-Nutzung im Unterricht und auf dem Schulgelände bis Klasse zehn.', '{3302}', 8387, 2, 3, null, 'Dafür: In England, Florida und Indien stiegen die Noten leicht bis moderat, Ablenkung sank. Dagegen: In Florida, Schweden und England fanden Studien keine Effekte auf Noten oder Wohlbefinden; Abendnutzung bleibt unberührt.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=53', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8400, 33, 11, 'MV', 'Altersgerechte Mediensensibilisierung über die Gefahren digitaler und sozialer Medien in Kindergarten und Grundschule.', '{3303}', 8390, 2, 3, null, 'Gezielte schulische Prävention senkte problematische Nutzung deutlich (d = 1,47), Bildschirmzeit kaum (d = 0,15); Publikationsverzerrung möglich. Setzt bei den Kindern an, nicht direkt bei der Begleitung durch Eltern.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=53', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8401, 33, 11, 'ST', 'Medienpädagogische Angebote ausbauen und mit Schulen, Landesmedienanstalt und Trägern neue Bildungsformate für alle Generationen entwickeln.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=36', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8402, 33, 11, 'ST', 'Medienbildung in der Kita altersgerecht und mit pädagogischer Begleitung einführen.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=49', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8403, 33, 11, 'ST', 'In Schulen Projekte und Unterrichtseinheiten, die die kritische Reflexionsfähigkeit im Umgang mit digitalen Medien stärken.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=22', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8404, 33, 12, null, 'Jugendschutz im Netz stärken, unter anderem durch wirksame Möglichkeiten zur Altersverifikation.', '{3301}', null, 1, 2, null, 'Verifikation kann Altersgrenzen durchsetzen, ersetzt aber keine Designregeln; technische Umsetzung hängt an EU-Lösungen und Datenschutz.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8405, 33, 12, null, 'Plattformen müssen ihre Algorithmen zur Inhaltsdarstellung offenlegen und auf manipulative Praktiken prüfen lassen.', '{3301}', null, 1, 1, null, 'Transparenz und Prüfung machen Empfehlungsdesign sichtbar, verbieten es aber nicht; Wirkung auf Kinder kaum untersucht. Plattformregeln setzt weitgehend die EU (DSA).', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=50', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8406, 33, 12, 'BE', 'Handyverbot an allen Grundschulen durchsetzen, begründet mit Gesundheits- und Kinderschutz.', '{3302}', 8388, 1, 3, null, 'Weniger Ablenkung möglich, doch Effekte zeigten sich vor allem an weiterführenden Schulen mit hohem Smartphone-Besitz; in der Grundschule ist die Nutzung ohnehin geringer. Studien zu Handyregeln uneinheitlich.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8407, 33, 12, 'BE', 'Medienkompetenz, kritischen Umgang mit sozialen Medien und digitale Verantwortung fest in der schulischen Bildung verankern.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8408, 33, 12, 'MV', 'Medienkompetenz altersgerecht in allen Schularten stärken; Lehrkräfte durch Fortbildung und praxisnahe Materialien unterstützen.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=67', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8409, 33, 12, 'MV', 'Lehrkräfte, Erziehende und Bildungsstätten stärken, damit Medienkompetenz von Beginn an vermittelt wird; außerschulische Angebote für alle Altersgruppen ergänzen.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=44', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8410, 33, 12, 'ST', 'Medienbildung wird in allen Schulfächern fest verankert und weiter ausgebaut.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=19', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8411, 33, 13, null, 'Manipulative Algorithmen sozialer Plattformen strenger regulieren; Algorithmen, die Kinder gezielt süchtig machen, nicht dulden.', '{3301}', null, 2, 1, null, 'Regeln gegen suchtfördernde Algorithmen setzen direkt am Belohnungsdesign an, bleiben aber unbestimmt; Wirkung kaum untersucht, nationale Alleingänge begrenzt das EU-Recht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=85', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8412, 33, 13, null, 'Eltern mit sicheren Voreinstellungen für Dienste und Geräte sowie Datenschutzregeln für Kinder und Jugendliche unterstützen.', '{3303,3301}', null, 1, 2, null, 'Sichere Voreinstellungen entlasten Eltern und begrenzen riskante Funktionen von Beginn an; Wirkung auf die Nutzungsdauer kaum untersucht, Geräte- und Dienstregeln sind EU-geprägt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=85', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8413, 33, 13, null, 'In den Schulen digitale Fähigkeiten und Medienkompetenz aufbauen.', '{3303}', 8395, 1, 1, null, 'Schulische Medienbildung wirkt gegen problematische Nutzung, aber kaum auf die Bildschirmzeit; Schulen und Lehrpläne sind Ländersache, der Bund kann nur Anreize setzen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8414, 33, 13, 'BE', 'Medienbildung als verbindlichen Teil des Unterrichts ab der 1. Klasse in allen Schulformen verankern.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=190', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8415, 33, 13, 'BE', 'Medienkompetenzzentren ausbauen und an jeder Schule Medienteams einrichten.', '{3303}', 8391, 1, 3, null, 'Geschulte Fachkräfte und Zentren können Medienbildung tragen; die Wirkung auf die Mediennutzung der Kinder läuft nur über den Unterricht und ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=190', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8416, 33, 13, 'BE', 'Einschränkungen der privaten Handynutzung unterstützen, wenn die Schule sie für die beste Lösung hält.', '{3302}', null, 1, 3, null, 'Unterstützt nur freiwillige Entscheidungen der Schulen; ohne Verpflichtung geringere Wirkung als ein verbindliches Verbot. Studien zu Handyregeln uneinheitlich.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=190', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8417, 33, 13, 'BE', 'Medienkompetenz-Angebote für Jugendliche und Erwachsene fördern, um Sucht- und Extremismusgefahren durch Games vorzubeugen.', '{3303}', 8390, 2, 3, null, 'Gezielte schulische Prävention senkte problematische Nutzung deutlich (d = 1,47), Bildschirmzeit kaum (d = 0,15); Publikationsverzerrung möglich. Setzt bei den Kindern an, nicht direkt bei der Begleitung durch Eltern.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=103', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8418, 33, 13, 'MV', 'Medienkompetenz, auch zu Desinformation und digitaler Mündigkeit, verbindlich in Lehrerausbildung und Lehrplänen verankern.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://gruene-mv.de/?wpdmdl=33772#page=44', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8419, 33, 13, 'MV', 'Bibliotheken als Orte für Kinder und Jugendliche stärken und ihre Angebote zur Medienkompetenz ausweiten.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://gruene-mv.de/?wpdmdl=33772#page=98', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8420, 33, 13, 'ST', 'Pflichtfach Informatik und Medienbildung von Klasse 5 bis 10/11 an allen allgemeinbildenden Schulen, u. a. kritischer Umgang mit Inhalten in sozialen Medien.', '{3303}', null, 1, 2, null, 'Ein Pflichtfach verankert Medienbildung dauerhaft; Wirkung auf das Nutzungsverhalten wie bei Schulprogrammen gemischt, Lehrkräfte für ein neues Fach fehlen absehbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8421, 33, 13, 'ST', 'Digital- und Medienkompetenz fest in Bildung verankern, auch in Familienbildungsstätten, Jugendhilfe und Erwachsenenbildung.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=53', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8422, 33, 13, 'ST', 'Computer- und Videospiele als Thema an weiterführenden Schulen fächerübergreifend stärker behandeln und analysieren.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=85', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8423, 33, 14, null, 'Lehrpläne modernisieren und dabei mehr Raum für Medienkompetenz schaffen.', '{3303}', 8395, 1, 1, null, 'Schulische Medienbildung wirkt gegen problematische Nutzung, aber kaum auf die Bildschirmzeit; Schulen und Lehrpläne sind Ländersache, der Bund kann nur Anreize setzen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8424, 33, 14, 'BE', 'Medienkompetenz im Schulunterricht stärken, dazu Lehrkräfte und Schulsozialarbeitende aus- und weiterbilden.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=16', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8425, 33, 14, 'BE', 'Elternarbeit zur Aufklärung der Kinder über Medienkonsum und Gefahren im Netz stärken.', '{3303}', 8392, 2, 3, null, 'Setzt direkt bei den Eltern an; Programme mit Elternbeteiligung senkten problematische Nutzung stärker. Belastbare Daten zu reinen Elternangeboten fehlen, und es erreichen vor allem interessierte Eltern.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=17', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8426, 33, 14, 'BE', 'Eltern und Fachkräfte mit mehr Informationen zur Mediennutzung von Kindern und Jugendlichen versorgen.', '{3303}', 8393, 1, 3, null, 'Leicht und schnell umsetzbar; Information erreicht aber nur, wer sie nutzt, und die Wirkung auf die Begleitung durch Eltern ist kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=17', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8427, 33, 14, 'MV', 'Eltern durch verständliche, freiwillige, wissenschaftsbasierte Informationen zu Mediennutzung, Bildschirmzeiten und digitaler Sicherheit stärken.', '{3303}', 8393, 1, 3, null, 'Leicht und schnell umsetzbar; Information erreicht aber nur, wer sie nutzt, und die Wirkung auf die Begleitung durch Eltern ist kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=84', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8428, 33, 14, 'MV', 'Medienbildung und kritischen, selbstbestimmten Umgang mit neuen Medien für alle Kinder und Jugendlichen als verbindlichen Lerninhalt festlegen.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=98', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8429, 33, 14, 'ST', 'Angebote der Medienbildung weiter ausbauen und Eltern bei der digitalen Erziehung durch Unterstützungsangebote helfen.', '{3303}', 8392, 2, 3, null, 'Setzt direkt bei den Eltern an; Programme mit Elternbeteiligung senkten problematische Nutzung stärker. Belastbare Daten zu reinen Elternangeboten fehlen, und es erreichen vor allem interessierte Eltern.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=26', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8430, 33, 15, 'BE', 'Grundschulen bildschirmfrei halten und dort Smartphones verbieten; an weiterführenden Schulen das Mitführen von Smartphones restriktiver handhaben.', '{3302}', 8388, 1, 3, null, 'Weniger Ablenkung möglich, doch Effekte zeigten sich vor allem an weiterführenden Schulen mit hohem Smartphone-Besitz; in der Grundschule ist die Nutzung ohnehin geringer. Studien zu Handyregeln uneinheitlich.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=30', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8431, 33, 15, 'MV', 'Private Handynutzung im Schulalltag bis zur 7. Klasse per Verordnung unterbinden, Ausnahmen nur bei Notfällen oder nach Rücksprache mit der Lehrkraft.', '{3302}', 8387, 2, 3, null, 'Dafür: In England, Florida und Indien stiegen die Noten leicht bis moderat, Ablenkung sank. Dagegen: In Florida, Schweden und England fanden Studien keine Effekte auf Noten oder Wohlbefinden; Abendnutzung bleibt unberührt.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=31', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8432, 33, 15, 'ST', 'Smartphone-Nutzung an Schulen bis einschließlich Klasse 10 untersagen.', '{3302}', 8387, 2, 3, null, 'Dafür: In England, Florida und Indien stiegen die Noten leicht bis moderat, Ablenkung sank. Dagegen: In Florida, Schweden und England fanden Studien keine Effekte auf Noten oder Wohlbefinden; Abendnutzung bleibt unberührt.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=79', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8433, 33, 16, null, 'Medien- und Datenschutzkompetenz von Kindern und Jugendlichen möglichst früh fördern.', '{3303}', null, 1, 2, null, 'Frühe Förderung ist sinnvoll, nennt aber keinen Weg; Schulen sind Ländersache, der Bund kann mit Programmen und Geld beitragen. Wirkung auf die Bildschirmzeit gering.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8434, 33, 16, null, 'EU-Gesetz über digitale Dienste zügig in nationales Recht überführen.', '{3301}', 8394, 1, 3, null, 'Der DSA verpflichtet Plattformen zu Risikoprüfungen auch zu Minderjährigen; die Wirkung auf Likes- und Belohnungsdesign ist bisher kaum untersucht. Umsetzung durch den Bund ist möglich.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=57', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8435, 33, 16, 'BE', 'Medienbildung inklusive Mediensuchtprävention ab der Grundschule verbindlich in Rahmenlehrplänen und schulinternen Curricula verankern.', '{3303}', 8390, 2, 3, null, 'Gezielte schulische Prävention senkte problematische Nutzung deutlich (d = 1,47), Bildschirmzeit kaum (d = 0,15); Publikationsverzerrung möglich. Setzt bei den Kindern an, nicht direkt bei der Begleitung durch Eltern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=165', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8436, 33, 16, 'BE', 'Schulgemeinschaften in Medienbildung schulen und Ressourcen für Elternarbeit ausbauen, um Eltern früh einzubeziehen.', '{3303}', 8392, 2, 3, null, 'Setzt direkt bei den Eltern an; Programme mit Elternbeteiligung senkten problematische Nutzung stärker. Belastbare Daten zu reinen Elternangeboten fehlen, und es erreichen vor allem interessierte Eltern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=165', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8437, 33, 16, 'BE', 'Medienkompetenzzentren in allen Bezirken gut ausstatten, kostenfreie begleitete Angebote und regelmäßige Schulungen für Fachkräfte schaffen, für junge Menschen, Eltern und Fachkräfte.', '{3303}', 8392, 2, 3, null, 'Setzt direkt bei den Eltern an; Programme mit Elternbeteiligung senkten problematische Nutzung stärker. Belastbare Daten zu reinen Elternangeboten fehlen, und es erreichen vor allem interessierte Eltern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=178', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8438, 33, 16, 'BE', 'Haushaltsmittel für Medienkompetenzbildung durch Freie Träger bereitstellen, entwickelt mit jungen Menschen für junge Menschen.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=247', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8439, 33, 16, 'BE', 'Verbindliche Fort- und Weiterbildungsangebote für Schulbeschäftigte zu Medienbildung.', '{3303}', 8391, 1, 3, null, 'Geschulte Fachkräfte und Zentren können Medienbildung tragen; die Wirkung auf die Mediennutzung der Kinder läuft nur über den Unterricht und ist kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=229', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8440, 33, 16, 'BE', 'Handyfreier Schultag bis Jahrgangsstufe 9 als Grundsatz, solange die Schulgemeinschaft keine andere Regelung beschließt.', '{3302}', 8387, 2, 3, null, 'Dafür: In England, Florida und Indien stiegen die Noten leicht bis moderat, Ablenkung sank. Dagegen: In Florida, Schweden und England fanden Studien keine Effekte auf Noten oder Wohlbefinden; Abendnutzung bleibt unberührt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=167', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8441, 33, 16, 'MV', 'Medienbildung auf allen Ebenen ausbauen: in der Schule, außerschulisch und für Erwachsene.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=27', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8442, 33, 16, 'MV', 'Das medienpädagogische Zentrum personell ausbauen, um Unterrichtsangebote zur Medienbildung zu stärken.', '{3303}', 8391, 1, 3, null, 'Geschulte Fachkräfte und Zentren können Medienbildung tragen; die Wirkung auf die Mediennutzung der Kinder läuft nur über den Unterricht und ist kaum untersucht.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8443, 33, 16, 'ST', 'Landesprogramm zur Stärkung der Medienkompetenz und digitalen Bildung an Schulen.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=74', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8444, 33, 17, null, 'Gesetz für soziale Medien nach australischem Vorbild, damit Kinder weniger in der virtuellen Welt verschwinden.', '{3301}', null, 2, 1, null, 'Altersgrenze setzt direkt am Zugang zu Likes- und Belohnungssystemen an; Erfahrungen aus Australien sind sehr jung, Umgehung möglich. Nationale Regelung stößt an EU-Recht und Länder-Jugendmedienschutz.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8445, 33, 17, null, 'Handys und Tablets mindestens bis zum Ende der Grundschule aus den Klassenzimmern verbannen, danach möglichst wenig im Unterricht einsetzen.', '{3302}', null, 1, 1, null, 'Weniger Ablenkung im Unterricht, Abendnutzung und Schlaf bleiben unberührt; Studien uneinheitlich. Schulrecht ist Ländersache, der Bund kann nur Anreize setzen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8446, 33, 17, 'BE', 'Grundschulklassen ohne Bildschirme einrichten, um Aufmerksamkeit, Gedächtnis und Lesekompetenz zu fördern.', '{3302}', 8388, 1, 3, null, 'Weniger Ablenkung möglich, doch Effekte zeigten sich vor allem an weiterführenden Schulen mit hohem Smartphone-Besitz; in der Grundschule ist die Nutzung ohnehin geringer. Studien zu Handyregeln uneinheitlich.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=16', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8447, 33, 17, 'BE', 'Smartphones im Unterricht grundsätzlich nicht nutzen und vor dem Unterricht wegschließen.', '{3302}', null, 1, 3, null, 'Wegschließen verringert Ablenkung in den Stunden, nicht aber die Nutzung in Pausen oder abends. Studien zu Handyregeln uneinheitlich.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=16', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8448, 33, 17, 'BE', 'Verbindlichen digitalen Führerschein mit Nachweis von Medien-, Datenschutz- und Informationskenntnissen bis Ende Klasse 10 einführen.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=16', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8449, 33, 17, 'MV', 'Familienbildungs- und Beratungsangebote ausbauen, die Eltern in der Medienerziehung stärken und Orientierung im digitalen Alltag geben.', '{3303}', 8392, 2, 3, null, 'Setzt direkt bei den Eltern an; Programme mit Elternbeteiligung senkten problematische Nutzung stärker. Belastbare Daten zu reinen Elternangeboten fehlen, und es erreichen vor allem interessierte Eltern.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=12', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8450, 33, 17, 'MV', 'Präventionsangebote für Kinder und Jugendliche ausbauen, die auch Medienkompetenz stärken.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=61', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8451, 33, 17, 'MV', 'Medienkompetenz an weiterführenden Schulen vermitteln, in der Grundschule ohne digitale Endgeräte lernen.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=47', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8452, 33, 17, 'ST', 'Verbindliches Smartphone-Verbot im Schulalltag, um Ablenkung und digitale Abhängigkeiten zu verringern.', '{3302}', 8387, 2, 3, null, 'Dafür: In England, Florida und Indien stiegen die Noten leicht bis moderat, Ablenkung sank. Dagegen: In Florida, Schweden und England fanden Studien keine Effekte auf Noten oder Wohlbefinden; Abendnutzung bleibt unberührt.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=45', 'https://world-education-blog.org/2025/12/15/are-phone-bans-working/', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8453, 1, 18, null, 'Für Fachpraxisbesuche ohne Überweisung wird eine Selbstbeteiligung eingeführt (Hausarztzentrierung), um Fachpraxen zu entlasten.', '{102}', null, 1, 3, null, 'Hausarztsteuerung kann Facharztbesuche verringern (Studien zum Gatekeeping); die Praxisgebühr mit Ausnahme bei Überweisung zeigte aber kaum Steuerungswirkung und schreckte eher Ärmere ab. Per Bundesgesetz rasch umsetzbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=125', 'https://ideas.repec.org/p/zbw/rwipos/16.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8454, 1, 18, null, 'Multiprofessionelle regionale Versorgungszentren mit Gesundheitsfachberufen werden eingerichtet.', '{101}', 6679, 2, 2, null, 'Angestelltenverhältnisse und Teamarbeit entsprechen den Wünschen vieler junger Ärztinnen und Ärzte und können Praxissitze in unterversorgten Regionen besetzen; wie viele Zentren tatsächlich entstehen, hängt von Kommunen und Finanzierung ab.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=125', null, 'gemischt', '2026-10-07', false, true, null),
  (8455, 1, 18, null, 'Mobile Gesundheitseinheiten mit regelmäßigen Sprechstunden kommen in entlegene Gebiete.', '{101}', null, 1, 2, null, 'Bringt Sprechstunden zu wenig mobilen Menschen in entlegenen Orten; Studien und Pilotprojekte zeigen gute Auslastung. Ersetzt aber keine fehlenden Praxen, braucht selbst ärztliches Personal und ist teuer; die Sicherstellung liegt bei den KVen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=126', 'https://nnphi.org/resources/the-scope-and-impact-of-mobile-health-clinics-in-the-united-states-a-literature-review/', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8456, 2, 18, null, 'Fördersystem für klimafreundlichen Wohnbau im bezahlbaren Preissegment', '{201,202}', null, 1, 3, null, 'Ein Bundesprogramm mit zinsverbilligten Krediten für günstigen klimafreundlichen Neubau besteht bereits; ohne Mietbindung ist nicht gesichert, dass die Wohnungen günstig vermietet werden, Mitnahmeeffekte sind möglich, eine Wirkungsauswertung fehlt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=96', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8457, 2, 18, null, 'Steuerliche Begünstigungen und günstige Kredite für Genossenschaften und Baugemeinschaften', '{201}', null, 1, 2, null, 'Genossenschaften vermieten meist unter Marktniveau, Steuervorteile und günstige Kredite erleichtern ihren Neubau; ihr Anteil am Neubau ist aber klein, Engpass ist oft Bauland, und Steuerermäßigungen nur für eine Rechtsform werfen EU- und beihilferechtliche Fragen auf.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=96', null, 'gemischt', '2026-10-07', false, true, 'blind'),
  (8458, 2, 18, null, 'Rückkauf und Neubau von Wohnungen durch Kommunen', '{201,202}', null, 2, 2, null, 'Kommunale Wohnungen werden deutlich unter Marktniveau vermietet (etwa Wien); Rückkäufe schaffen aber keine zusätzlichen Wohnungen und binden viel Geld, Neubauziele kommunaler Unternehmen wurden oft verfehlt, und der Bund kann Kommunen nur über die Länder fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=95', 'https://www.lpb-bw.de/wohnen-vorbild-wien', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8459, 2, 18, null, 'Sozialbindung bei Wohnbauprojekten verlängern, durch niedrigere Baukosten ausgeglichen', '{206}', null, 2, 2, null, 'Längere Bindungen bremsen den Verlust von Sozialwohnungen, die heute oft nach 15 bis 30 Jahren herausfallen; die Wohnraumförderung regeln die Länder, der Bund kann Bindungen nur über Finanzhilfen vorgeben, und wie niedrigere Baukosten den Ausgleich schaffen, bleibt offen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=96', 'https://mieterbund.de/aktuelles/meldungen/historischer-tiefstand-bei-sozialwohnungen/', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8460, 2, 18, null, 'Umnutzung leerstehender Gewerbegebäude zu Wohnraum, Leerstandsmanagement und Baugebote', '{201}', null, 1, 2, null, 'Umnutzung und Leerstandsaktivierung schaffen Wohnraum ohne Neubau; laut ifo ist nur ein Teil leerer Büros umbaubar und weniger als die Hälfte davon wirtschaftlich, in Großstädten ist der Wohnungsleerstand gering, Baugebote sind rechtlich aufwendig.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=94', 'https://www.baulinks.de/webplugin/2024/1277.php4', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8461, 2, 18, null, 'Umbau-, Nachverdichtungs- und Aufstockungsverfahren vereinfachen und beschleunigen', '{201}', null, 2, 2, null, 'Aufstockung und Nachverdichtung schaffen Wohnungen ohne neues Bauland, Studien sehen über eine Million mögliche Wohnungen; das reale Potenzial ist wegen Statik, Brandschutz, Stellplätzen und Kosten deutlich kleiner, und Bauordnungsrecht ist Ländersache.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=94', 'https://www.baulinks.de/webplugin/2016/0333.php4', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8462, 2, 18, null, 'Weniger nachzuweisende Pkw-Stellplätze bei nachhaltigen Mobilitätslösungen', '{203}', null, 2, 1, null, 'Stellplatzpflichten verteuern den Neubau nachweislich (Tiefgaragenplatz 15.000–30.000 €, Aufschlag im Neubau rund 10 %); die Entlastung greift nur bei Mobilitätskonzepten, und Stellplatzvorgaben regeln Länder und Kommunen, nicht der Bund.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=97', 'https://vdiv.de/news-details/iw-koeln-stellplatzverordnungen-machen-bauen-unnoetig-teuer', 'belegt', '2026-10-07', false, true, 'blind'),
  (8463, 2, 18, null, 'Landesbauordnungen angleichen, Genehmigungen digitalisieren und verschlanken', '{201}', null, 1, 1, null, 'Unterschiedliche Landesbauordnungen gelten als Hemmnis für serielles Bauen und Typengenehmigungen; wie stark eine Angleichung den Neubau steigert, ist kaum untersucht, und der Bund kann sie nicht anordnen, das können nur die Länder.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=97', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8464, 2, 18, null, 'Serieller Modulbau mit nachhaltigen Baustoffen, wo Neubau nötig ist', '{203}', null, 1, 2, null, 'Serieller Modulbau kann Bauzeit und Kosten senken, wenn genug gleiche Gebäude entstehen; Holz, Lehm und Recyclate sind oft teurer als übliche Baustoffe, und der Kostenvorteil hängt stark von Stückzahl und Grundstück ab.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=96', null, 'gemischt', '2026-10-07', false, true, 'blind'),
  (8466, 3, 18, null, 'Teile der Netzentgelte aus dem Bundeshaushalt decken', '{301}', 6703, 2, 2, null, 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=53', null, 'belegt', '2026-10-07', false, true, null),
  (8467, 3, 18, null, 'Netzentgelte verursachungsgerecht gestalten, Investitionen nicht mehr allein darüber finanzieren', '{301}', 6703, 2, 2, null, 'Senkt einen großen Teil des Strompreises direkt und spürbar; die Kosten des Netzausbaus trägt dann der Bundeshaushalt, und die Finanzierung muss auf Dauer gesichert werden.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=67', null, 'belegt', '2026-10-07', false, true, null),
  (8468, 3, 18, null, 'Stromsteuer auf das europäische Minimum senken', '{302}', 6704, 2, 2, null, 'Senkt den Strompreis für Haushalte um gut 2 Cent je Kilowattstunde; kostet den Bundeshaushalt mehrere Milliarden Euro im Jahr.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=67', null, 'belegt', '2026-10-07', false, true, null),
  (8469, 3, 18, null, 'Einen Teil der CO₂-Einnahmen als direkte Zahlungen an die Menschen zurückgeben', '{302}', 6705, 1, 2, null, 'Gleicht höhere Heizkosten durch den CO₂-Preis vor allem für Haushalte mit geringem Einkommen aus, senkt die Preise selbst aber nicht; ein Auszahlungsweg muss erst aufgebaut werden.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=60', null, 'belegt', '2026-10-07', false, true, null),
  (8470, 3, 18, null, 'Strombedarf bis 2035 durchgehend vollständig aus erneuerbaren Energien decken', '{304}', 6707, 2, 2, null, 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=66', null, 'gemischt', '2026-10-07', false, true, null),
  (8471, 3, 18, null, 'Hemmnisse für Energiespeicher abbauen, damit Speicher wirtschaftlich attraktiv werden', '{304}', 6707, 2, 2, null, 'Mehr Wind- und Solarstrom verdrängt teure Gaskraftwerke an der Börse und senkt dort die Preise; zugleich kostet der dafür nötige Netzausbau Geld, das über die Netzentgelte bezahlt wird.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=66', null, 'gemischt', '2026-10-07', false, true, null),
  (8472, 3, 18, null, 'Fernwärmeausbau und kommunale Wärmeplanung durch Förderprogramme und Duldungspflichten fördern', '{305}', 8465, 1, 3, null, 'Kann langfristig die Abhängigkeit von Gas- und Ölpreisen senken, wenn Netze erneuerbare Wärme oder Abwärme nutzen; Fernwärme wird heute aber noch stark mit Gas erzeugt, und in den Monopolnetzen sind die Preise oft hoch.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=68', 'https://www.vzbv.de/pressemitteilungen/teure-fernwaermepreise-verbraucherzentrale-fordert-preisdeckel', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8473, 4, 18, null, 'Duales Lehramtsstudium, das auch ausländische Abschlüsse und pädagogische Praxis anerkennt.', '{401}', null, 2, 2, null, 'Ein praxisintegriertes Lehramtsstudium mit Anrechnung ausländischer Abschlüsse kann zusätzliche Lehrkräfte gewinnen; zu dualen Lehramtsmodellen gibt es erst wenige Befunde. Lehrerbildung ist Ländersache, der Bund kann nur über Förderprogramme beitragen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=115', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8474, 4, 18, null, 'Lehrkräfte durch Verwaltungsfachkräfte und multiprofessionelle Teams entlasten.', '{401}', null, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zeigen Entlastung, Lerneffekte aber nur bei gezieltem Einsatz. Schulpersonal ist Ländersache, der Bund kann nur über Programme mitfinanzieren.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=107', 'https://evidenceforlearning.org.au/toolkit/teaching-assistants', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8475, 4, 18, null, 'Bundesweiter Bildungskanon für das Vorschuljahr, der Deutsch als Schulsprache und bilinguale Betreuung fördert.', '{404}', null, 1, 2, null, 'Ein gemeinsamer Bildungsrahmen für das Vorschuljahr kann Sprachförderung vereinheitlichen; ohne Sprachstandsfeststellung und Förderpflicht erreicht er nicht sicher alle Kinder mit Bedarf, Sprachförderprogramme wirken unterschiedlich. Der Bund braucht die Länder.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=108', null, 'gemischt', '2026-10-07', false, true, 'blind'),
  (8476, 4, 18, null, 'Längeres gemeinsames Lernen: Dreigliedriges Schulsystem wird aufgehoben.', '{405}', null, 2, 1, null, 'Längeres gemeinsames Lernen setzt an der frühen Trennung an; eine Studie zu deutschen Ländern findet Gewinne für Leistungsschwächere, die Forschung zur Schulstruktur ist insgesamt aber uneinheitlich. Für die Schulstruktur ist der Bund nicht zuständig (Grundgesetzänderung).', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=110', 'https://www.diw.de/de/diw_01.c.610091.de/publikationen/diskussionspapiere/2018_1775/better_together__heterogeneous_effects_of_tracking_on_student_achievement.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8477, 4, 18, null, 'Lernmaterialien für schulpflichtige Kinder bundesweit kostenfrei, vom Bund finanziert.', '{405}', null, 1, 2, null, 'Kostenfreie Lernmittel entlasten vor allem einkommensschwache Familien; Studien zu kostenlosen Schulbüchern finden im Durchschnitt kaum Effekte auf Leistungen. Schulen sind Ländersache, der Bund kann nur über Vereinbarung und Finanztransfers beitragen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=105', 'https://www.povertyactionlab.org/node/1436', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8478, 4, 18, null, 'Psychologie, Schulsozialarbeit, Schulgesundheit und Sonderpädagogik als fester Teil der Schulen.', '{405}', null, 1, 2, null, 'Fachkräfte für Psychologie, Sozialarbeit und Sonderpädagogik unterstützen Kinder in schwierigen Lagen; Studien finden kleine positive Effekte von Schulberatung, sonst sind Wirkungen auf Leistungen kaum belegt. Schulpersonal ist Ländersache, der Bund kann nur mitfinanzieren.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=111', 'https://ideas.repec.org/p/pit/wpaper/396.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8479, 5, 18, null, 'Effektive Unternehmenssteuerbelastung auf den OECD-Durchschnitt senken', '{501}', 6090, 1, 2, null, 'Niedrigere Unternehmenssteuern können Investitionen anregen, setzen aber nicht an den vom Sachverständigenrat genannten Gründen (Energiepreise, Lohnstückkosten) an; Studien zur Wirkung sind gemischt. Die Gegenfinanzierung ist offen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=54', null, 'gemischt', '2026-10-07', false, true, null),
  (8480, 5, 18, null, 'Energiesteuer auf das EU-rechtliche Minimum senken', '{501}', null, 1, 2, null, 'Senkt Kosten für Gas und Kraftstoffe; das Produzierende Gewerbe erhält aber schon Ermäßigungen, der Großteil der Entlastung ginge an Verkehr und Haushalte. Steuer ist im EU-Rahmen national gestaltbar, die Einnahmeausfälle sind hoch und ungedeckt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=53', null, 'gemischt', '2026-10-07', false, true, 'blind'),
  (8481, 5, 18, null, 'Teil der Netzentgelte aus dem Bundeshaushalt finanzieren', '{501}', 6089, 2, 2, null, 'Niedrigere Stromsteuer und Netzentgelte senken direkt die Energiekosten, die der Sachverständigenrat als Grund der Industrieschwäche nennt; allein gleichen sie den Kostenabstand aber nicht aus. Die Gegenfinanzierung ist offen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=53', null, 'belegt', '2026-10-07', false, true, null),
  (8482, 5, 18, null, 'Pflicht für Großunternehmen, bei betriebsbedingten Kündigungen Weiterbildung in zukunftsfähigen Berufen zu finanzieren', '{502}', null, 2, 2, null, 'Weiterbildung nach Entlassung erleichtert den Wechsel in wachsende Branchen; das IAB fand für Transfergesellschaften höhere Beschäftigung nach fünf Jahren, aber keinen Lohneffekt. Per Bundesgesetz möglich, belastet aber Unternehmen im Abbau zusätzlich.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=52', 'https://iab.de/publication/?id=1410534', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8483, 5, 18, null, 'Recht auf Freistellung für Weiterbildung in zukunftsorientierten Berufen', '{502}', null, 1, 2, null, 'Freistellung erleichtert Weiterbildung, doch Bildungsurlaub wird in den Ländern nur von etwa 1-3 % genutzt; die WIFO-Evaluation der österreichischen Bildungskarenz fand gemischte Beschäftigungseffekte. Bundesgesetz möglich, Kostenträger offen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=52', 'https://ideas.repec.org/b/wfo/wstudy/71089.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8484, 5, 18, null, 'Umschulungsprogramme für den Wechsel in Berufe mit Fachkräftemangel', '{502}', 6096, 2, 2, null, 'Geförderte Weiterbildung hilft Beschäftigten beim Wechsel in neue Branchen; Studien zeigen positive, aber je nach Maßnahme sehr unterschiedliche Effekte. Umsetzbar über die Arbeitsförderung, Finanzierung offen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=120', null, 'gemischt', '2026-10-07', false, true, null),
  (8485, 5, 18, null, 'Investitionen aus der Schuldenbremse ausnehmen (Goldene Regel Plus)', '{504}', 6098, 2, 1, null, 'Mehr Spielraum für öffentliche Investitionen setzt direkt an der Investitionslücke an. Eine Änderung der Schuldenbremse erfordert eine Grundgesetzänderung mit Zweidrittelmehrheit.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=22', null, 'belegt', '2026-10-07', false, true, null),
  (8486, 5, 18, null, 'Infrastrukturfonds für private Investitionen und massive Infrastrukturinvestitionen', '{504}', null, 1, 2, null, 'Ein Fonds kann privates Kapital für Infrastruktur mobilisieren, ersetzt aber kaum fehlende öffentliche Investitionen; der Bundesrechnungshof fand privat finanzierte Autobahnprojekte teurer als Haushaltsfinanzierung. Ausgestaltung und Volumen offen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=65', null, 'gemischt', '2026-10-07', false, true, 'blind'),
  (8487, 5, 18, null, 'Berichtspflichten des Lieferkettengesetzes streichen und an EU-Recht angleichen', '{505}', null, 1, 3, null, 'Streichung setzt an Berichtspflichten an, laut Gesetzentwurf der Bundesregierung entlastet sie aber nur um rund 4 Mio. Euro jährlich, gemessen an rund 64 Mrd. Euro Bürokratiekosten sehr wenig. Nationales Recht, per Bundesgesetz rasch umsetzbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=53', null, 'belegt', '2026-10-07', false, true, 'blind'),
  (8488, 5, 18, null, 'Genehmigungsverfahren für Industrieanlagen vereinfachen und auf drei Monate begrenzen', '{505}', null, 2, 1, null, 'Einfachere Verfahren senken Aufwand für Unternehmen; laut Normenkontrollrat bremsen Prüfumfang, Personalmangel und fehlende Digitalisierung. Eine Frist von drei Monaten ist bei EU-Vorgaben zu UVP und Beteiligung und knappem Personal kaum erreichbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=53', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Kurzmeldungen/DE/Presse/2025-07-bimsch-projekt.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8489, 5, 18, null, 'Tarifbindung stärken', '{507}', null, 1, 2, null, 'Setzt an der geringen Tarifbindung an, nennt aber keinen Weg (etwa Allgemeinverbindlichkeit, Tariftreue); ohne Instrument ist keine deutliche Wirkung abschätzbar. Umsetzbarkeit hängt vom gewählten Weg ab.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=89', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8490, 6, 18, null, 'Spezialisierte Kammern an den Verwaltungsgerichten für Asylprozesse, um Verfahren zu beschleunigen', '{602}', null, 1, 2, null, 'Spezialisierte Asylkammern können Verfahren beschleunigen (NRW meldet kürzere Dauer, zusammen mit mehr Personal); § 83 AsylG sieht sie aber schon vor, viele Gerichte haben sie. Einrichtung und Richterstellen liegen bei den Ländern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=136', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8491, 6, 18, null, 'Bundesweite kostenlose Asylberatung zur Begleitung der Asylsuchenden und Beschleunigung der Verfahren', '{602}', null, 1, 3, null, 'Beratung kann Anhörungen vorbereiten und Fehlentscheidungen vermeiden; die BAMF-Evaluation 2026 konnte eine Wirkung auf Verfahrensdauer und Klagen mangels Daten nicht messen. Der Bund fördert die Beratung seit 2023 (§ 12a AsylG).', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=136', 'https://www.asyl.net/view/evaluation-der-behoerdenunabhaengigen-asylverfahrensberatung', 'offen', '2026-10-07', false, true, 'blind'),
  (8492, 6, 18, null, 'Arbeitserlaubnis vom ersten Tag an, unabhängig vom Aufenthaltsstatus und vom einzelnen Arbeitgeber', '{603}', 6110, 2, 3, null, 'Ein früher Zugang zum Arbeitsmarkt setzt direkt an; Studien zeigen, dass Beschäftigungsverbote die Integration in Arbeit noch Jahre später verzögern. Sprachkurse und Anerkennung bleiben davon unberührt. Per Bundesgesetz umsetzbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=51', null, 'belegt', '2026-10-07', false, true, null),
  (8493, 6, 18, null, 'Abschlüsse werden nach Gleichwertigkeit des Berufsbildes im Ausbildungsland anerkannt statt individuell geprüft', '{603}', 6101, 2, 2, null, 'Einfachere und schnellere Anerkennungsverfahren setzen an einer Hürde an, die das IAB nennt; wie viel schneller es wird, hängt von der Ausgestaltung ab. Für viele reglementierte Berufe sind die Länder zuständig.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=51', null, 'gemischt', '2026-10-07', false, true, null),
  (8494, 6, 18, null, 'Kostenlose Deutschkurse für alle Zielgruppen unabhängig vom Aufenthaltsstatus', '{603}', 6107, 2, 3, null, 'Mehr und früher zugängliche Sprach- und Integrationskurse verkürzen Wartezeiten; Studien des IAB zeigen, dass Integrationskurse Sprachkenntnisse und Beschäftigung verbessern. Anerkennung und Arbeitsmarktzugang bleiben davon unberührt. Der Bund finanziert die Kurse bereits.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=138', null, 'belegt', '2026-10-07', false, true, null),
  (8495, 6, 18, null, 'Dublin-Verordnung abschaffen und Asylsuchende nach BIP, Bevölkerungsdichte und Größe auf die Länder verteilen', '{605}', 6109, 1, 1, null, 'Eine verbindliche Verteilung in der EU würde die Zuständigkeitsfrage anders lösen; ob Asylsuchende dann im zugewiesenen Staat bleiben, ist offen. Umsetzbar nur mit einer Mehrheit der EU-Staaten, die bisher nicht in Sicht ist.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=135', null, 'offen', '2026-10-07', false, true, null),
  (8496, 6, 18, null, 'Chancenjahr: Menschen mit abgelehntem Asylantrag können sich durch ein Jahr Arbeit einen Aufenthaltstitel erarbeiten', '{606}', 6108, 2, 3, null, 'Ein Bleiberecht für gut integrierte Geduldete beendet die Kettenduldung direkt; mit dem Chancen-Aufenthaltsrecht von 2022 haben viele Geduldete einen Aufenthaltstitel bekommen. Wer die Bedingungen nicht erfüllt, bleibt geduldet. Per Bundesgesetz umsetzbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=138', null, 'belegt', '2026-10-07', false, true, null),
  (8497, 6, 18, null, 'Dauerhafter Aufenthaltsstatus, wenn eine Abschiebung drei Jahre lang nicht vollzogen wurde und Integrationsbereitschaft gezeigt wurde', '{606}', 6108, 2, 3, null, 'Ein Bleiberecht für gut integrierte Geduldete beendet die Kettenduldung direkt; mit dem Chancen-Aufenthaltsrecht von 2022 haben viele Geduldete einen Aufenthaltstitel bekommen. Wer die Bedingungen nicht erfüllt, bleibt geduldet. Per Bundesgesetz umsetzbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=139', null, 'belegt', '2026-10-07', false, true, null),
  (8498, 7, 18, null, 'Renteneintrittsalter an die durchschnittliche Lebenserwartung koppeln', '{701}', null, 2, 3, null, 'Simulationen zeigen, dass die Kopplung den Beitragsanstieg spürbar dämpft und die Beschäftigung erhöht; Menschen mit geringerer Lebenserwartung (oft Geringverdienende) verlieren überproportional Rentenjahre. Per Bundesgesetz ohne Mehrkosten umsetzbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=92', 'https://www.bundesbank.de/de/aufgaben/themen/monatsbericht-wie-rentenreformen-wirken-koennten--892950', 'belegt', '2026-10-07', false, true, 'blind'),
  (8499, 7, 18, null, 'Beamte, Selbstständige und Freischaffende schrittweise in die gesetzliche Rentenversicherung einbeziehen', '{701}', 6176, 1, 2, null, 'Mehr Einzahlende verbessern das Verhältnis zu den Rentnern zunächst, später entstehen aus den Beiträgen aber auch Ansprüche; für Beamte kostet der Übergang Bund und Länder anfangs viel Geld. Per Bundesgesetz möglich, mit langen Übergangszeiten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=92', null, 'gemischt', '2026-10-07', false, true, null),
  (8500, 7, 18, null, 'Einkommen oberhalb der Armutsgrenze unabhängig von der Erwerbsbiografie garantieren, ergänzend zu Rentenansprüchen', '{702}', null, 2, 1, null, 'Eine Mindestsicherung über der Armutsgrenze unabhängig von der Biografie senkt Altersarmut, wie Länder mit Mindest- oder Grundrente zeigen; sie gleicht Folgen niedriger Löhne aus, ohne die Ursache zu ändern. Höhe offen, Kosten hoch, Finanzierung ungeklärt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=92', 'https://www.diw.de/de/diw_01.c.824031.de/publikationen/diw_aktuell/2021_0072/mindestrente__absicherung_gegen_altersarmut_und_notwendiger_baustein_fuer_weitere_reformen.html', 'belegt', '2026-10-07', false, true, 'blind'),
  (8501, 7, 18, null, 'Care-Arbeit, Freiwilligendienste und gesellschaftlich wertvolle Aufgaben bei der Rentenberechnung stärker berücksichtigen', '{702}', null, 2, 2, null, 'Anrechnung von Sorgezeiten senkt nachweislich Altersarmut von Frauen; sie wirkt aber wenig zielgenau und ist teuer (Mütterrente rund 14 Mrd. Euro jährlich). Umfang hier unbestimmt, Finanzierung offen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=92', 'https://www.diw.de/de/diw_01.c.909964.de/publikationen/wochenberichte/2024_31_1/abschaffung_der_muetterrente_wuerde_altersarmut_erhoehen.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8502, 7, 18, null, 'Mindestlohn auf 60 % des Medianbruttolohns anheben und regelmäßig anpassen', '{702}', 6181, 1, 3, null, 'Ein höherer Mindestlohn erhöht die Rentenansprüche von Geringverdienenden; auch mit 15 Euro liegt die Rente nach Lücken im Erwerbsleben oft nahe der Grundsicherung. Per Bundesgesetz umsetzbar, bisher entscheidet die Mindestlohnkommission.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=89', null, 'gemischt', '2026-10-07', false, true, null),
  (8503, 7, 18, null, 'Geringfügig Beschäftigte in die Sozialversicherung einbinden', '{702}', null, 1, 3, null, 'Volle Versicherungspflicht schließt Lücken bei Minijobs, die meist von der Rentenpflicht befreit sind; die Ansprüche aus kleinen Verdiensten bleiben aber gering. Per Bundesgesetz umsetzbar, eine Expertenkommission empfiehlt es.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=89', 'https://www.bertelsmann-stiftung.de/de/presse/pressemitteilungen/pressemitteilung/pid/reformen-bei-minijobs-und-ehegattensplitting-koennten-60000-neue-vollzeitstellen-schaffen', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8504, 7, 18, null, 'Staatlich gefördertes Renten-Depot zur Geburt mit Startbudget und jährlichen Staatseinzahlungen bis zur Volljährigkeit', '{703}', null, 2, 2, null, 'Ein staatlich befülltes Depot ab Geburt erreicht alle Kinder, auch aus armen Familien, und baut über Jahrzehnte Vermögen auf; britische Erfahrungen zeigen kleine Effekte auf das Sparverhalten. Wirkt erst sehr spät, rund 2 Mrd. Euro jährlich ohne Finanzierung.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=93', 'https://publications.aston.ac.uk/id/eprint/45231', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8505, 7, 18, null, 'Arbeitgeberbeiträge zur betrieblichen Altersvorsorge ins persönliche Depot', '{703}', 6177, 2, 3, null, 'Setzt direkt an der geringen Verbreitung von Betriebsrenten an; mehr Förderung und weniger Haftungsrisiken haben die Verbreitung bisher aber nur langsam erhöht, vor allem in kleinen Betrieben und bei Geringverdienenden. Per Bundesgesetz umsetzbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=93', null, 'gemischt', '2026-10-07', false, true, null),
  (8506, 8, 18, null, 'Öffentlichen Nahverkehr zuverlässig, barrierefrei und dicht getaktet ausbauen', '{801}', null, 2, 2, null, 'Dichtere Takte gewinnen laut Metaanalyse mehr Fahrgäste als Preissenkungen; ohne Betrag bleibt offen, wie viel ankommt. Zuständig sind die Länder, der Bund kann über Geld beitragen, Fahrpersonal fehlt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=69', 'https://worldtransitresearch.info/research/6475', 'belegt', '2026-10-07', false, true, 'blind'),
  (8507, 8, 18, null, 'Bedarfsgesteuerte Rufbusse und Verzahnung von Nahverkehr und Individualverkehr im ländlichen Raum', '{801}', null, 1, 2, null, 'Rufbusse erreichen auf dem Land mehr Menschen, vor allem abends und am Wochenende; sie kosten je Fahrgast aber ein Vielfaches eines Linienbusses. Zuständig sind die Länder, der Bund kann nur fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=70', 'https://kommunal.de/on-demand-verkehr-kommunen-aus-finanzierung', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8508, 8, 18, null, 'Deutschlandtakt sowie Ausbau und Modernisierung des Schienennetzes vorantreiben', '{802}', 6744, 2, 2, null, 'Setzt direkt am maroden Netz an, wirkt wegen Bauzeiten aber erst nach Jahren; der Bundesrechnungshof bezweifelt, dass mehr Mittel ohne bessere Steuerung den Zustand verbessern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=70', null, 'gemischt', '2026-10-07', false, true, null),
  (8509, 8, 18, null, 'Netz und Betrieb der Bahn entflechten; Bundeskompetenzzentrum steuert die Netzentwicklung', '{802}', 6741, 1, 2, null, 'Soll Wettbewerb und klare Verantwortung für das Netz schaffen; in anderen Ländern hat die Trennung nicht einheitlich zu einem besseren Netz geführt, und die Umstrukturierung bindet Jahre.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=70', null, 'gemischt', '2026-10-07', false, true, null),
  (8510, 8, 18, null, 'Deutschlandticket sichern und weiterentwickeln', '{804}', null, 1, 3, null, 'Die Evaluation zeigt, dass das Ticket genutzt wird und Fahrten vom Auto verlagert; reines Sichern verhindert aber weitere Preiserhöhungen nicht. Der Bund zahlt seinen Anteil bereits.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=70', 'https://www.bmv.de/SharedDocs/DE/Pressemitteilungen/2026/027-schnieder-evaluation-deutschlandticket.html', 'belegt', '2026-10-07', false, true, 'blind'),
  (8511, 8, 18, null, 'Kosten für Semestertickets übernehmen', '{804}', 6838, 1, 2, null, 'Entlastet Gruppen mit wenig Geld wie Auszubildende, Studierende oder Menschen mit geringem Einkommen gezielt; für alle anderen ändert sich nichts. Der Bund kann es nur gemeinsam mit den Ländern einführen und mitfinanzieren.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=106', null, 'belegt', '2026-10-07', false, true, null),
  (8512, 9, 18, null, 'Länder und Kommunen beim Gewinnen von Personal für Polizei und Ordnungsbehörden unterstützen, Ausbildungen attraktiver machen.', '{902}', 7482, 2, 2, null, 'Mehr und besser ausgestattete Ermittler können mehr Taten aufklären, und Studien aus den USA finden weniger Kriminalität bei mehr Polizei. Der Bund steuert aber nur BKA und Bundespolizei. Ohne konkreten Umfang ist die Wirkung unbestimmt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=33', null, 'gemischt', '2026-10-07', false, true, 'blind'),
  (8513, 9, 18, null, 'Anzeigenaufnahme bis Staatsanwaltschaft vollständig digitalisieren.', '{902}', 7483, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und IT-Projekte der Justiz brauchen viele Jahre und die Mitarbeit der Länder.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=35', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8514, 9, 18, null, 'Opportunitätsprinzip ausweiten, damit Polizeiressourcen gezielter eingesetzt werden.', '{902}', null, 1, 2, null, 'Ein weiteres Opportunitätsprinzip kann Ressourcen auf schwere Taten lenken. Zugleich bleiben mehr kleine Taten ohne Folgen, und zur Wirkung auf die Aufklärung gibt es kaum Daten; die Abkehr vom Legalitätsprinzip ist rechtlich umstritten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=35', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8515, 9, 18, null, 'Bodycams, Berichterstattungssysteme und Analysewerkzeuge stärker in den Polizeidienst integrieren.', '{902}', null, 1, 2, null, 'Bessere Technik kann Dokumentation und Auswertung erleichtern. Eine Übersichtsstudie fand bei Bodycams aber keine Wirkung auf Festnahmen, nur weniger Beschwerden; der Bund steuert nur die Bundespolizei.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=34', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8516, 9, 18, null, 'Schwarzfahren zur Ordnungswidrigkeit herabstufen, keine Ersatzfreiheitsstrafen mehr.', '{902}', 7490, 1, 3, null, 'Allein Fahren ohne Fahrschein macht rund 6 % der Verurteilungen und über die Hälfte der Ersatzfreiheitsstrafen aus. Eine Streichung entlastet Justiz und Haft spürbar. Die Aufklärung schwerer Taten verbessert sie nur indirekt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=70', null, 'belegt', '2026-10-07', false, true, 'blind'),
  (8517, 9, 18, null, 'Besitz und Gebrauch aller psychoaktiven Substanzen sanktionsfrei stellen.', '{902}', null, 1, 2, null, 'In Portugal entlastete die Entkriminalisierung des Konsums Justiz und Gefängnisse ohne starken Anstieg des Konsums. Eine völlig sanktionsfreie Regel geht weiter und steht in Spannung zu UN-Drogenkonventionen; schwere Taten werden nur indirekt schneller verfolgt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=154', 'https://kar.kent.ac.uk/29910/', 'belegt', '2026-10-07', false, true, 'blind'),
  (8518, 9, 18, null, 'Spezialeinheiten gegen organisierte Kriminalität bei BKA, Zoll und in den Ländern personell verstärken.', '{902}', null, 1, 2, null, 'Mehr Personal für Spezialeinheiten stärkt Ermittlungen gegen organisierte Kriminalität. Auf die Aufklärung alltäglicher Straftaten wirkt es kaum; der Bund steuert nur BKA und Zoll, Wirkungsstudien fehlen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=35', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8519, 9, 18, null, 'Cybercrime-Einheiten von Polizei und Justiz stärken.', '{906}', null, 2, 2, null, 'Mehr spezialisierte Ermittler können mehr Online-Taten aufklären. Viele Taten kommen aber aus dem Ausland, wo die Aufklärung gering bleibt; der Umfang ist offen, und die meisten Einheiten unterstehen den Ländern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=34', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8520, 9, 18, null, 'Europol zu einer europäischen Polizei mit Exekutivrechten ausbauen, gegen grenzüberschreitende Kriminalität.', '{906,907}', 7488, 1, 1, null, 'Viele Online- und organisierte Taten kommen aus dem Ausland, deshalb setzt eine bessere Zusammenarbeit an einer Ursache an. Operative Befugnisse für Europol erfordern aber eine Änderung der EU-Verträge mit allen Mitgliedstaaten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=31', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8521, 9, 18, null, 'Strafrahmen für Hasskriminalität und Unterstützung extremistischer Ideologien, besonders online, verschärfen.', '{907}', 7491, 1, 3, null, 'Höhere Strafen sind rechtlich leicht umsetzbar und benennen das Unrecht klarer. Die Forschung zeigt aber übereinstimmend: Abschreckend wirkt vor allem das Risiko, erwischt zu werden, kaum die Höhe der Strafe.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=18', 'https://prohic.nl/wp-content/uploads/2020/11/2020-06-02-DeterrenceMetaNagin.2013.pdf', 'belegt', '2026-10-07', false, true, 'blind'),
  (8522, 9, 18, null, 'Bildungsprogramme und zivilgesellschaftliche Initiativen gegen extremistische Ideologien fördern.', '{907}', 7502, 2, 2, null, 'Eine Auswertung eines Aussteigerprogramms fand bei 94 % der Betreuten keine neuen Straftaten, allerdings ohne Vergleichsgruppe. Belastbare Wirkungsstudien sind selten. Ob der Bund für ein Fördergesetz zuständig ist, ist umstritten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=19', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/546159/ein-weg-aus-dem-rechtsextremismus/', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8523, 9, 18, null, 'Deradikalisierungsprogramme und Ausstiegshilfen fördern.', '{907}', 7502, 2, 2, null, 'Eine Auswertung eines Aussteigerprogramms fand bei 94 % der Betreuten keine neuen Straftaten, allerdings ohne Vergleichsgruppe. Belastbare Wirkungsstudien sind selten. Ob der Bund für ein Fördergesetz zuständig ist, ist umstritten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=19', 'https://www.bpb.de/themen/rechtsextremismus/infopool-rechtsextremismus/546159/ein-weg-aus-dem-rechtsextremismus/', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8524, 9, 18, null, 'Zusammenarbeit mit internationalen Partnern intensivieren, um extremistische Netzwerke und Online-Plattformen zu zerschlagen.', '{907}', null, 1, 2, null, 'Extremistische Netzwerke und Plattformen agieren oft grenzüberschreitend, engere Zusammenarbeit setzt dort an. Ohne konkretes Instrument bleibt die Wirkung unbestimmt, und sie hängt von der Mitwirkung anderer Staaten ab.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=19', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8525, 9, 18, null, 'Schutzkonzepte für jüdische Gemeinden entwickeln, Antisemitismusbeauftragte und Meldestellen ausbauen.', '{907}', null, 2, 2, null, 'Bauliche Sicherung und Schutzkonzepte können Anschläge abwehren, wie die gesicherte Tür in Halle 2019 zeigte; Meldestellen machen Taten sichtbar. Objektschutz liegt bei den Ländern, und Wirkungsstudien fehlen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=145', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8526, 9, 18, null, 'Keine Abschiebung von Personen mit Arbeits-, Ausbildungs- oder Studienplatz, die nicht straffällig wurden.', '{905}', null, 1, 3, null, 'Eine Studie aus Italien zeigt, dass ein gesicherter Aufenthalt mit legaler Arbeit die Straffälligkeit von Zugewanderten etwa halbiert. Die Maßnahme betrifft aber nur Menschen, die schon arbeiten und nicht straffällig sind.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=139', 'https://swlb1.aeaweb.org/research/legalizing-immigrants-impact-crime-rate', 'belegt', '2026-10-07', false, true, 'blind'),
  (8527, 9, 18, null, 'Straffällige Jugendliche durch Präventionsmaßnahmen frühzeitig unterstützen.', '{903}', null, 2, 2, null, 'Eine Meta-Analyse zeigt weniger Rückfälle bei therapeutisch ausgerichteten, gut umgesetzten Programmen für straffällige Jugendliche. Welche Maßnahmen gemeint sind, bleibt offen; Jugendhilfe liegt bei Ländern und Kommunen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=38', 'https://ojp.gov/ncjrs/virtual-library/abstracts/primary-factors-characterize-effective-interventions-juvenile', 'belegt', '2026-10-07', false, true, 'blind'),
  (8528, 9, 18, null, 'Plätze in Frauenhäusern ausbauen, kostenloser Zugang für Schutzbedürftige.', '{904}', 7494, 2, 2, null, 'Es fehlen tausende Schutzplätze; Schutz und Beratung helfen Betroffenen direkt, aus der Gewalt herauszukommen. Die Gewalt selbst wird dadurch weniger verhindert. Der Bund beteiligt sich bereits, der Ausbau braucht aber Jahre und Personal.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=152', 'https://www.institut-fuer-menschenrechte.de/aktuelles/detail/gewalt-gegen-frauen-beratungs-und-unterstuetzungsstrukturen-in-stadt-und-land-sichern', 'belegt', '2026-10-07', false, true, 'blind'),
  (8529, 9, 18, null, 'Tatpersonen geschlechtsspezifischer Gewalt müssen Kurse in gewaltfreier Kommunikation absolvieren.', '{904}', 7496, 2, 2, null, 'Eine Meta-Analyse findet bis zu zwei Jahre nach Täterprogrammen deutlich weniger Rückfälle, danach keinen gesicherten Effekt mehr. Die Angebote liegen überwiegend bei den Ländern, der Bund kann fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=152', 'https://pure.qub.ac.uk/en/publications/the-effectiveness-of-interventions-to-prevent-recidivism-in-perpe/', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8530, 9, 18, null, 'Strafbarkeit auf neue Formen von Belästigung und Gewalt gegen Frauen erweitern, konsequente Verfolgung.', '{904}', 7491, 1, 3, null, 'Höhere Strafen sind rechtlich leicht umsetzbar und benennen das Unrecht klarer. Die Forschung zeigt aber übereinstimmend: Abschreckend wirkt vor allem das Risiko, erwischt zu werden, kaum die Höhe der Strafe.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=152', 'https://prohic.nl/wp-content/uploads/2020/11/2020-06-02-DeterrenceMetaNagin.2013.pdf', 'belegt', '2026-10-07', false, true, 'blind'),
  (8531, 9, 18, null, 'Vergewaltigung als medizinischen Notfall behandeln, bundesweit anonyme 24/7-Gewalt- und Forensik-Notdienste einführen.', '{908}', null, 2, 2, null, 'Spezialisierte forensische Notdienste (SANE) gingen in US-Studien mit häufigeren Verurteilungen einher, einzelne Standorte zeigten aber keinen Effekt. Ein bundesweiter 24/7-Dienst braucht Länder, Kliniken und Personal.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=152', 'https://crimesolutions.ojp.gov/ratedprograms/sexual-assault-nurse-examiner-sane-program-multisite', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8532, 10, 18, null, 'Betreuungsangebot für Pflegebedürftige deutlich ausbauen, damit niemand zu unbezahlter Sorgearbeit gezwungen ist', '{1004}', 6228, 2, 2, null, 'Mehr erreichbare Entlastungsangebote und Beratung setzen daran an, dass Angehörige die Hauptlast tragen; die Plätze fehlen aber oft auch wegen fehlender Pflegekräfte. Der Bund kann Leistungen und Förderung erhöhen, Planung und Bau liegen bei Ländern und Trägern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=52', null, 'gemischt', '2026-10-07', false, true, null),
  (8533, 11, 18, null, 'Energiesteuer auf das nach EU-Recht zulässige Minimum senken, langfristig auf EU-Ebene abschaffen', '{1101}', null, 1, 1, null, 'Steuersenkungen auf Kraftstoff wurden 2022 zu knapp 90 % weitergegeben; auf Lebensmittelpreise wirkt Energiesteuer nur indirekt und gering. Der Steuerausfall läge im zweistelligen Milliardenbereich ohne Finanzierung, die Abschaffung hängt an der EU.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=53', 'https://www.leuphana.de/institute/ivwl/aktuell/ansicht/2024/08/27/neue-publikation-von-mats-kahl-in-energy-economics.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8534, 11, 18, null, 'Grundnahrungsmittel wie Brot, Obst und Gemüse von der Mehrwertsteuer befreien, gegenfinanziert über die Erbschaftsteuer', '{1101}', 6880, 2, 2, null, 'Senkt die Preise für Grundnahrungsmittel um bis zu 6,5 % und entlastet vor allem Haushalte mit wenig Geld, wenn die Senkung weitergegeben wird; seit 2022 erlaubt das EU-Recht einen Nullsatz. Dagegen spricht der hohe Steuerausfall, und ob der Handel die Senkung vollständig weitergibt, ist umstritten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=101', null, 'gemischt', '2026-10-07', false, true, null),
  (8535, 11, 18, null, 'Mindestlohn auf 60 % des Medianbruttolohns anheben und regelmäßig anpassen', '{1103,1105}', 6889, 2, 3, null, 'Erhöht die Löhne im Niedriglohnbereich direkt; Studien zur Einführung 2015 und zur Erhöhung 2022 fanden kaum Jobverluste. Der Bundestag kann die Höhe per Gesetz festlegen, wie 2022 geschehen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=89', null, 'belegt', '2026-10-07', false, true, null),
  (8536, 11, 18, null, 'Tarifbindung stärken', '{1103,1105}', 6890, 1, 3, null, 'Wer nach Tarif arbeitet, verdient im Schnitt mehr; Tariftreue greift aber nur bei öffentlichen Aufträgen, und wie stark die Tarifbindung dadurch steigt, ist offen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=89', null, 'gemischt', '2026-10-07', false, true, null),
  (8537, 11, 18, null, 'Grundfreibetrag moderat anheben, um kleine und mittlere Einkommen zu entlasten', '{1104}', null, 1, 3, null, 'Erhöht das Nettoeinkommen aller Steuerpflichtigen, die Entlastung bleibt bei moderater Anhebung aber klein (eher zweistellige Euro im Monat). Der Grundfreibetrag wird regelmäßig per Gesetz angehoben, die Kosten von einigen Milliarden Euro sind tragbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=99', null, 'belegt', '2026-10-07', false, true, 'blind'),
  (8538, 11, 18, null, 'Umschulungen und maßgeschneiderte Weiterbildung mit Lohnkostenzuschüssen für Langzeitarbeitslose', '{1105}', 7228, 1, 2, null, 'Ein Berufsabschluss führt oft aus dem Niedriglohnbereich heraus, weil Fachkräfte deutlich mehr verdienen als Helfer; die Wirkung stellt sich erst über Jahre ein, und die Programme nennen kaum konkrete Instrumente.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=120', null, 'gemischt', '2026-10-07', false, true, null),
  (8539, 12, 18, null, 'Elektronische, streckenabhängige Autobahnmaut, deren Einnahmen Unterhalt und Ausbau der Autobahnen finanzieren sollen', '{1201}', 6932, 2, 2, null, 'Macht die Finanzierung der Autobahnen planbarer und unabhängiger vom Haushalt; öffentlich-private Partnerschaften waren laut Bundesrechnungshof bisher oft teurer als konventionelle Vergabe.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=71', null, 'gemischt', '2026-10-07', false, true, null),
  (8540, 12, 18, null, 'Schuldenbremse reformieren: Nettoinvestitionen unter anderem in Infrastruktur werden ausgenommen, Defizitgrenze steigt', '{1201}', 6931, 2, 2, null, 'Mehr Geld für Bund, Länder und Kommunen kann Sanierungsstau abbauen; ob es bei Straßen und Brücken ankommt und verbaut werden kann, hängt von Personal und Verfahren ab. Braucht eine Grundgesetzänderung, wie sie 2025 für das Sondervermögen beschlossen wurde.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=22', null, 'gemischt', '2026-10-07', false, true, null),
  (8541, 12, 18, null, 'Planungs- und Genehmigungsverfahren für Infrastrukturprojekte vereinfachen und auf höchstens drei Monate begrenzen', '{1201,1203}', null, 2, 1, null, 'Schnellere Verfahren verkürzen den Weg zu Ersatzbauten; laut KfW und Fachleuten bremsen aber vor allem Personal und Geld. Eine Frist von drei Monaten für alle Infrastrukturprojekte ist mit EU-Vorgaben zu Umweltprüfung und Beteiligung kaum vereinbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=53', 'https://www.kfw.de/Über-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8542, 12, 18, null, 'Gewerbesteuer ersetzen und Konzessionsabgabenverordnung reformieren, um Kommunalfinanzen zu stärken', '{1202}', null, 1, 1, null, 'Stabilere Einnahmen erleichtern Kommunen die Planung von Investitionen; aufkommensneutral entsteht aber kein zusätzliches Geld für Straßen. Ein Ersatz der Gewerbesteuer berührt Art. 28 und 106 GG und scheiterte bisher an Bund und Ländern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=15', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8543, 12, 18, null, 'Sichere Radwege und Fahrradstraßen ausbauen', '{1204}', 6936, 2, 2, null, 'Getrennte, durchgehende Radwege senken das Unfallrisiko nach vielen Studien; an Kreuzungen, wo die meisten schweren Unfälle passieren, hängt es von der Gestaltung ab. Bauen müssen Länder und Kommunen, der Bund kann fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=69', null, 'gemischt', '2026-10-07', false, true, null),
  (8544, 12, 18, null, 'Bundesweit Tempo 30 innerorts sowie Tempo 80 auf Landstraßen', '{1204}', null, 3, 3, null, 'Niedrigere Tempolimits senken Zahl und Schwere von Unfällen; Frankreich verzeichnete nach Tempo 80 auf Landstraßen 12 % weniger Getötete. Anders als Tempo 30 allein deckt es auch Landstraßen ab. Der Bund kann die StVO mit Zustimmung des Bundesrats ändern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=69', 'https://www.cerema.fr/en/node/7630', 'belegt', '2026-10-07', false, true, 'blind'),
  (8545, 13, 18, null, 'Gezielte Förderung und Subventionen für den Internetausbau in ländlichen Regionen.', '{1301}', 6967, 2, 3, null, 'Schließt Lücken, die der Markt nicht schließt; laut WIK ist die heutige Förderung aber teuer, anfällig für Überförderung und verdrängt teils privaten Ausbau – es kommt auf die Ausgestaltung an.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=72', 'https://www.wik.org/fileadmin/user_upload/Unternehmen/Veroeffentlichungen/Kurzstudien/2026/WIK_Kurzstudie_Anreizwirkung_der_derzeitigen_Gigabitfoerderung_auf_den_eigenwirtschaftlichen_Glasfaserausbau_in_Deutschland.pdf', 'gemischt', '2026-10-07', false, true, null),
  (8546, 13, 18, null, 'Glasfaserausbau beschleunigen: Hürden und Genehmigungsverfahren abbauen, Koordination von Bund, Ländern und Kommunen verbessern.', '{1301}', 6966, 1, 3, null, 'Verkürzt Genehmigungen für Masten und Leitungen und senkt Tiefbaukosten; wo sich der Ausbau wirtschaftlich nicht lohnt oder das Gelände schwierig ist, ändert das allein wenig.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=72', null, 'gemischt', '2026-10-07', false, true, null),
  (8547, 13, 18, null, 'Anbieter sollen Netzinfrastruktur stärker gemeinsam nutzen.', '{1302}', null, 1, 3, null, 'Gemeinsam genutzte Masten senken Kosten und können Funklöcher schließen (Großbritannien: Shared Rural Network); dort wirkte Sharing aber mit Versorgungsauflagen und Staatsgeld zusammen, hier bleibt es unverbindlich und zielt auf Nachhaltigkeit.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=72', 'https://www.gov.uk/government/publications/shared-rural-network-srn-progress-update-september-2024/shared-rural-network-srn-progress-update-september-2024', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8548, 14, 18, null, 'Zentrales Digitalministerium mit Richtlinienkompetenz für alle Verwaltungsebenen und bundeseinheitlichen Standards für durchgängige Digitalisierung der Verwaltung.', '{1401}', null, 2, 1, null, 'Verbindliche einheitliche Standards setzen an der Zersplitterung der IT von Bund und Ländern an, die Fachleute als Hauptbremse nennen. Eine Richtlinienkompetenz für alle Ebenen braucht aber eine Grundgesetzänderung (Art. 91c), Erfahrungen damit fehlen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=28', null, 'gemischt', '2026-10-07', false, true, 'blind'),
  (8549, 14, 18, null, 'Verwaltungsleistungen proaktiv, automatisiert, mobil und mit E-Identifikation und E-Payment bereitstellen.', '{1401}', 6986, 2, 2, null, 'Kann den Personalmangel abfedern und Bearbeitungszeiten senken, wie der Normenkontrollrat empfiehlt; Voraussetzung sind digitale Akten und vernetzte Daten, die vielerorts fehlen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=29', null, 'gemischt', '2026-10-07', false, true, null),
  (8550, 14, 18, null, 'Once-Only-Prinzip konsequent umsetzen: Daten werden nur einmal übermittelt und von Behörden gemeinsam genutzt, bei gewährleistetem Datenschutz.', '{1403}', 6984, 2, 2, null, 'Setzt direkt daran an, dass Nachweise immer wieder eingereicht werden müssen; Länder wie Österreich und Estland zeigen, dass es funktioniert. Die Registermodernisierung ist aber ein Vorhaben über viele Jahre, und die Länder können nicht zur Anbindung verpflichtet werden.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=29', 'https://www.normenkontrollrat.bund.de/Webs/NKR/SharedDocs/Downloads/DE/Jahresberichte/2025-jahresbericht.pdf?__blob=publicationFile&v=5', 'belegt', '2026-10-07', false, true, null),
  (8551, 14, 18, null, 'Zentrale Anlaufstellen, automatische Genehmigung bei verspäteter Bearbeitung und regelmäßige Überprüfung von Vorschriften.', '{1404}', null, 2, 2, null, 'Regelmäßige Überprüfung von Vorschriften und Genehmigungsfiktion können Verfahren straffen; Behörden könnten aber vorsorglich ablehnen, die Fiktion ersetzt keine Prüfung, und ihre Wirkung ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=17', null, 'gemischt', '2026-10-07', false, true, 'blind'),
  (8552, 14, 18, null, 'Zuständigkeiten zwischen Bund, Ländern und Kommunen neu ordnen.', '{1404}', null, 1, 1, null, 'Klarere Zuständigkeiten könnten Doppelarbeit und Aufgabenlast verringern; die Zusage bleibt unbestimmt, braucht Grundgesetzänderungen mit Zustimmung der Länder, und die Bilanz früherer Föderalismusreformen ist umstritten.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=15', null, 'gemischt', '2026-10-07', false, true, 'blind'),
  (8553, 14, 18, null, 'Angepasste Gehaltsstrukturen, Beamtentum auf Zeit und Personalrotation für die Verwaltung.', '{1402}', 6987, 2, 1, null, 'Setzt am Personalmangel an; der Bund regelt aber nur die Bedingungen seiner eigenen Beschäftigten, die meisten Stellen mit Bürgerkontakt liegen bei Ländern und Kommunen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=17', null, 'gemischt', '2026-10-07', false, true, null),
  (8555, 15, 18, null, 'Energiesteuer auf das nach EU-Recht zulässige Minimum senken, langfristig auf EU-Ebene ganz abschaffen.', '{1502}', 8554, 2, 2, null, 'Senkt Benzin um rund 30 Cent, Diesel um 14 Cent je Liter vor Mehrwertsteuer; 2022 kam die Senkung bei Benzin voll, bei Diesel nur teilweise an. Dauerhaft fehlen rund 12 Mrd. Euro im Jahr; die Abschaffung auf EU-Ebene braucht Einstimmigkeit.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=53', 'https://www.zew.de/PU84325', 'belegt', '2026-10-07', false, true, 'blind'),
  (8556, 15, 18, null, 'Dieselsteuer schrittweise an die Benzinsteuer angleichen.', '{1502}', null, 0, 3, null, 'Die Angleichung verteuert Diesel um gut 18 Cent je Liter (mit Mehrwertsteuer rund 22 Cent) und macht das Fahren für Dieselfahrende teurer statt günstiger; rechtlich mit einfachem Gesetz möglich und bringt dem Bund Einnahmen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=62', 'https://www.umweltbundesamt.de/en/press/pressinformation/environmentally-harmful-subsidies-in-transport', 'belegt', '2026-10-07', false, true, 'blind'),
  (8557, 15, 18, null, 'Ausbau der Ladeinfrastruktur für E-Fahrzeuge.', '{1505}', 7015, 1, 3, null, 'Hilft, wer nicht zu Hause laden kann, vor allem in Mehrparteienhäusern; öffentliches Laden bleibt aber meist teurer und aufwendiger als eine eigene Wallbox.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=70', null, 'gemischt', '2026-10-07', false, true, null),
  (8558, 16, 18, null, 'Finanzielle Unterstützung für klimaneutrale Maßnahmen bei Neubau und Sanierung.', '{1601}', 7034, 2, 3, null, 'Senkt die Investition, die viele Haushalte scheuen oder nicht aufbringen können, und setzt damit an den laut KfW größten Hindernissen an. Ob sie Haushalte mit wenig Geld erreicht, hängt von der Staffelung ab.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=96', 'https://www.kfw.de/PDF/Download-Center/Konzernthemen/Research/PDF-Dokumente-KfW-Energiewendebarometer/KfW-Energiewendebarometer-2026.pdf', 'gemischt', '2026-10-07', false, true, null),
  (8559, 16, 18, null, 'Kommunale Wärmeplanung dauerhaft finanzieren, Fernwärmeausbau über Duldungspflichten und Förderprogramme voranbringen.', '{1603}', 7038, 2, 2, null, 'Beschleunigt die Wärmepläne, auf die viele Eigentümer warten, und den Bau von Wärmenetzen; planen und bauen müssen die Kommunen, der Bund kann nur Geld und Beratung geben.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=68', 'https://www.bbsr.bund.de/BBSR/DE/veroeffentlichungen/analysen-kompakt/2026/ak-09-2026.html', 'gemischt', '2026-10-07', false, true, null),
  (8564, 17, 18, null, 'Betreuungsangebot für Kinder deutlich ausbauen, damit niemand wegen fehlender Plätze auf Erwerbsarbeit verzichten muss', '{1701}', 7280, 2, 2, null, 'Investitionshilfen können zusätzliche Plätze und erreichbare Angebote ermöglichen. Die Wirkung hängt von kommunaler Planung, Kofinanzierung und verfügbarem Personal ab.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=52', 'https://www.dji.de/themen/kinderbetreuung/kita-personalbedarf.html', 'belegt', '2026-10-07', false, true, 'blind'),
  (8565, 17, 18, null, 'Bundesweite digitale Plattform zur Vergabe von Kita-Plätzen, die auch private Einrichtungen und Tageseltern einbindet und freie Plätze zeigt', '{1701}', 8563, 1, 2, null, 'Zentrale digitale Vergabe beschleunigt das Verfahren, macht es fairer und zeigt den tatsächlichen Bedarf. Sie schafft keine zusätzlichen Plätze; die Vergabe liegt bei Kommunen und Trägern, deren Anbindung der Bund nicht allein regelt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=108', 'https://www.bertelsmann-stiftung.de/de/themen/aktuelle-meldungen/2023/juni/schneller-fairer-und-transparenter-zum-kita-platz-wie-ein-algorithmus-kommunen-helfen-kann', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8566, 17, 18, null, 'Tagespflege stärken durch geförderte gemeinsame Betreuungsräume für Tageseltern', '{1701}', 7301, 2, 2, null, 'Bundesunterstützung kann die Länder beim Erhalt und Ausbau ergänzender Betreuungsplätze unterstützen. Die konkrete Wirkung hängt von Umsetzung und dauerhafter Finanzierung vor Ort ab.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=108', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8567, 17, 18, null, 'Flexible Arbeitsplätze mit Kinderbetreuung durch Fachpersonal für Eltern ohne Kita-Platz oder bei kurzfristigem Betreuungsausfall', '{1704,1701}', null, 1, 2, null, 'Arbeitsplätze mit Betreuung können bei Ausfällen oder fehlendem Platz kurzfristig überbrücken; es gibt Praxisbeispiele, aber kaum Auswertungen. Sie ersetzen keinen regulären Platz, brauchen selbst Fachpersonal, Träger und Finanzierung sind offen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=108', 'https://www.uni-heidelberg.de/presse/news07/2709backu.html', 'offen', '2026-10-07', false, true, 'blind'),
  (8568, 17, 18, null, 'Bundesweit einheitliche Betreuungsschlüssel und Höchstgrößen der Gruppen in Krippen und Kitas', '{1703}', 8560, 3, 1, null, 'Die Zielwerte entsprechen den fachlichen Empfehlungen und setzen direkt an der Personalausstattung an. Für eine bundesweite Umsetzung fehlen absehbar sehr viele Fachkräfte; Umsetzung durch die Länder und Finanzierung sind ungeklärt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=108', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-07', false, true, 'blind'),
  (8569, 17, 18, null, 'Pädagogische Fachkräfte werden gleich wie Lehrkräfte bezahlt', '{1702}', 8561, 2, 1, null, 'Die meisten Fachkräfte halten ihr Gehalt für unangemessen; höhere Löhne können Berufswahl und Verbleib stärken. Frühere Lohnzuwächse schlossen die Lücke aber nicht; der Bund ist nicht Tarifpartei, die Kosten sind sehr hoch.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=109', 'https://www.diw.de/de/diw_01.c.817992.de/publikationen/wochenberichte/2021_19_1/erzieherinnen_empfinden_vielfache_belastungen_und_wenig_anerkennung.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8570, 17, 18, null, 'Finanzielle Unterstützung für pädagogische Fachkräfte während der Ausbildung', '{1702}', 7295, 2, 2, null, 'Bundesmittel für vergütete Ausbildung, Kapazitäten und Qualifizierung können den Ländern beim Aufbau des Personals helfen. Wirkung und Zeitbedarf hängen von Länderumsetzung und Ausbildungserfolg ab.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=109', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8571, 17, 18, null, 'Multiprofessionelle Teams entlasten pädagogische Fachkräfte in Kitas', '{1702}', 8562, 2, 2, null, 'Zusätzliche Kräfte für Sprache, Verwaltung und Unterstützung können Fachkräfte entlasten; Entlastung durch Verwaltungskräfte wird empfohlen. Die Wirkung ist kaum untersucht, Ehrenamtliche ersetzen keine Fachkräfte, der Bund kann nur fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=108', 'https://www.bertelsmann-stiftung.de/en/themen/aktuelle-meldungen/2023/november/mehr-plaetze-und-bessere-qualitaet-in-kitas-bis-2030-wenn-jetzt-entschlossen-gehandelt-wird', 'offen', '2026-10-07', false, true, 'blind'),
  (8572, 17, 18, null, 'Tagespflege, Krippen- und Kita-Plätze ab der Geburt bundesweit gebührenfrei', '{1705}', 7303, 2, 2, null, 'Geringere Beiträge entlasten Familien und können den Zugang erleichtern, beseitigen aber nicht alle Zusatzkosten. Mehr Nachfrage kann bei knappen Plätzen den Zugang erschweren, wenn der Ausbau nicht Schritt hält.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=105', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8573, 18, 18, null, 'Naturbasierte Lösungen: Gebäudebegrünung, Entsiegelung, Schwammstadt als zentrales Konzept.', '{1804,1803}', 7941, 1, 2, null, 'Begrünung und Entsiegelung wirken nachweislich gegen Hitze und Abfluss; die Zusage nennt aber weder Instrument noch Mittel, daher ist kaum eine Verbesserung absehbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=76', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-07', false, true, 'blind'),
  (8574, 18, 18, null, 'Ausbau von Hochwasserschutzanlagen und Renaturierung von Uferbereichen.', '{1805}', 7942, 2, 3, null, 'Rückhalteräume und Auen dämpfen Hochwasserscheitel nachweislich, der Bund fördert Hochwasserschutz bereits mit. Dagegen: Deiche verlagern Risiken teils flussabwärts und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=77', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-07', false, true, 'blind'),
  (8575, 18, 18, null, 'Datengestützte Hitzestrategie mit Hitzeaktionsplänen und Förderprogrammen, gemeinsam mit den Ländern.', '{1802}', null, 2, 2, null, 'Hitzeschutzpläne gingen in 14 europäischen Ländern mit rund 25 % weniger hitzebedingten Todesfällen einher. Dagegen: Zusage ohne Mittel und Ziele; Umsetzung liegt bei Ländern und Kommunen, der Bund kann nur fördern und koordinieren.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=129', 'https://www.cmcc.it/article/heat-prevention-plans-help-save-lives', 'belegt', '2026-10-07', false, true, 'blind'),
  (8576, 18, 18, null, 'Stärkere Förderung von Projekten zur Senkung innerstädtischer Temperaturen, etwa Begrünung.', '{1803}', 7940, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C im Umfeld); der Bund fördert Städtebau bereits. Dagegen: Wirkung bleibt lokal und hängt von Umsetzung in den Kommunen ab.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=129', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-07', false, true, 'blind'),
  (8577, 18, 18, null, 'Europäischen Emissionshandel (ETS-2) wie geplant 2027 ausweiten.', '{1801,1802}', null, 1, 1, null, 'CO2-Preise senken Emissionen nachweislich, auf Hitze wirkt das aber nur gering und verzögert. Der Start 2027 ist durch EU-Recht (2026) bereits auf 2028 verschoben; Deutschland kann das nicht allein ändern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=60', 'https://www.roedl.com/insights/ets-2-verzoegert-klimakosten-bleiben-warum-sie-nicht-auf-die-politik-warten-sollten-2/', 'belegt', '2026-10-07', false, true, 'blind'),
  (8578, 18, 18, null, 'Fossile Energieträger in Industrieanlagen bis 2035 befristen; neue Anlagen mit Strom oder Wasserstoff.', '{1801,1802}', null, 1, 1, null, 'Eine Frist für fossile Energie in der Industrie würde Emissionen senken. Dagegen: Laut UBA ist die Umstellung der Prozesswärme bis 2045 machbar, 2035 ist sehr knapp, Wasserstoff und Strom fehlen, Bestandsschutz wirft Rechtsfragen auf; Wirkung auf Hitze gering.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=61', 'https://www.umweltbundesamt.de/themen/industrielle-prozesswaerme-kann-bis-2045-co2', 'offen', '2026-10-07', false, true, 'blind'),
  (8579, 18, 18, null, 'CCS für unvermeidbare Industrieemissionen.', '{1801,1802}', 7935, 1, 3, null, 'Seit Ende 2025 ist kommerzielles CCS rechtlich möglich; es kann schwer vermeidbare Industrieemissionen senken. Dagegen: Infrastruktur braucht 7 bis 10 Jahre, Kosten und Umfang sind unsicher; Wirkung auf Hitze gering.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=62', 'https://www.bundesregierung.de/breg-de/aktuelles/speicherung-von-kohlendioxid-2376946', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8580, 18, 18, null, 'Nationales Sanierungsprogramm für klimaneutrales Bauen und Sanieren öffentlicher Gebäude.', '{1801,1802}', null, 1, 2, null, 'Sanierung öffentlicher Gebäude senkt Energiebedarf und Emissionen (dena: rund 120 Mrd. Euro bis 2045 nötig, meist kommunale Gebäude). Auf Hitze in Deutschland wirkt das nur als kleiner Beitrag zum globalen Klimaschutz; Finanzierung offen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=96', 'https://www.pv-magazine.de/?p=23862', 'belegt', '2026-10-07', false, true, 'blind'),
  (8581, 18, 18, null, 'Renaturierung und Wiedervernässung von Mooren massiv ausbauen.', '{1801,1802}', null, 1, 2, null, 'Entwässerte Moore verursachen laut UBA rund 7,5 % der deutschen Emissionen, Wiedervernässung senkt sie deutlich. Dagegen: Flächen meist privat, Wasser fehlt teils, Umsetzung über Länder; auf Hitze wirkt nationaler Klimaschutz nur gering und langfristig.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=79', 'https://www.umweltbundesamt.de/node/102188', 'belegt', '2026-10-07', false, true, 'blind'),
  (8582, 18, 18, null, 'Subventionen für fossile Energieträger in der Industrie vollständig abbauen.', '{1801,1802}', null, 1, 2, null, 'Steuervergünstigungen für fossile Energie mindern Sparanreize, ihr Abbau stützt Klimaschutz und entlastet den Haushalt. Dagegen: Abwanderungsrisiko energieintensiver Industrie, Wirkung kaum beziffert; auf Hitze in Deutschland nur geringer, verzögerter Effekt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=62', 'https://www.umweltbundesamt.de/themen/umweltschaedliche-subventionen-klettern-auf-ueber', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8583, 27, 18, null, 'Modellstudiengänge für Rettungsfachpersonal ausbauen und dauerhaft etablieren, weitere berufliche und akademische Weiterbildungsmöglichkeiten schaffen.', '{2704}', null, 1, 2, null, 'Fehlende Entwicklungsperspektiven gelten in einer Befragung von 814 Rettungskräften als Ausstiegsgrund; Studiengänge und Weiterbildung verbessern aber weder Pausen, Überstunden noch Besetzung. Hochschulen sind Ländersache, der Bund kann über Berufsrecht und Förderung beitragen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=128', 'https://www.frontiersin.org/journals/health-services/articles/10.3389/frhs.2025.1548525/full', 'offen', '2026-10-07', false, true, 'blind'),
  (8584, 27, 18, null, 'Heilberufe erhalten Antrags- und Stimmrechte im Gemeinsamen Bundesausschuss.', '{2705}', null, 1, 2, null, 'Stimmrechte im G-BA geben Heilberufen Einfluss auf Richtlinien, die ihre Arbeit mitprägen, wirken aber nur mittelbar auf Mitsprache am Arbeitsplatz. Rechtlich per Bundesgesetz möglich, doch Fragen der demokratischen Legitimation und Vertretung sind ungeklärt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=128', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8586, 29, 18, null, 'Bedarfsplanung für Psychotherapie anpassen, mehr Kassensitze und gerechtere Verteilung', '{2905}', 8167, 2, 3, null, 'Mehr Kassensitze setzen direkt an der Kapazität an; Befragungen sehen fehlende Termine als Hauptengpass. Wirkung bisheriger Reformen nur teils belegt. Bund und Selbstverwaltung können es regeln.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=132', 'https://europepmc.org/articles/PMC13288593', 'offen', '2026-10-07', false, true, 'blind'),
  (8587, 29, 18, null, 'Flächendeckende Gesundheitskioske für individuelle, niedrigschwellige Beratung', '{2903}', null, 1, 2, null, 'Im Hamburger Modell gut angenommen und mit weniger vermeidbaren Klinikfällen, aber ohne messbare Verbesserung der Gesundheitskompetenz; Beratung ist allgemein, nicht auf psychische Gesundheit ausgerichtet. Flächendeckender Aufbau braucht Finanzierungseinigung mit Kassen und Kommunen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=130', 'https://www.uni-hamburg.de/newsroom/presse/2021/pm17.html', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8588, 29, 18, null, 'Resilienzförderung schon im Kita-Alter, Weiterbildung für Fach- und Lehrkräfte', '{2903}', 8585, 1, 2, null, 'Früh ansetzende Förderung und geschulte Fachkräfte können Belastungen eher erkennen; Übersichten finden aber wenig Beleg, dass Präventionsprogramme in Bildungseinrichtungen Angst oder Depression senken. Kita und Schule sind Ländersache, der Bund kann nur fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=132', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8589, 30, 18, null, 'Drug-Checking, Konsumräume und Substitutionsangebote stärker fördern.', '{3005}', null, 2, 2, null, 'Konsumräume senken Überdosierungen ohne mehr Konsum, Substitution ist gut belegt; Drug-Checking ändert Konsumabsichten, Gesundheitsfolgen sind weniger untersucht. Der Bund kann fördern, Betrieb und Konsumräume regeln die Länder.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=133', 'https://doi.org/10.1016/j.drugalcdep.2014.10.012', 'belegt', '2026-10-07', false, true, 'blind'),
  (8590, 30, 18, null, 'Besitz und Gebrauch aller psychoaktiven Substanzen sanktionsfrei entkriminalisieren.', '{3005}', null, 1, 2, null, 'Entkriminalisierung senkt Hürden zu Hilfe und erhöht den Konsum laut Studien meist nicht, ändert aber nichts an unbekannten Wirkstoffen am Schwarzmarkt; Erfahrungen (Portugal, Oregon) gemischt. Per Bundesgesetz möglich, Spannungen mit UN-Recht.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=154', 'https://doi.org/10.1136/bmjopen-2019-035148', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8591, 30, 18, null, 'Regulierten Verkauf einzelner noch illegaler Substanzen an Erwachsene in Modellprojekten erproben.', '{3005}', null, 1, 1, null, 'Regulierter Verkauf macht Wirkstoff und Dosis bekannt, Modellprojekte erreichen aber nur wenige; Wirkung kaum untersucht. Verkauf widerspricht UN-Konventionen und EU-Rahmenbeschluss, die Deutschland nicht allein ändert.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=155', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8592, 30, 18, null, 'Teillegalisierung von Cannabis beibehalten und durch Verkauf und Beratung in Fachgeschäften ausbauen.', '{3005}', 8329, 2, 1, null, 'Geprüfte Qualität kann Verunreinigungen senken; Studien zeigen gemischte Folgen für Konsum und Gesundheit. Hängt von EU- und UN-Recht ab, das Deutschland nicht allein ändert.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=155', 'https://europepmc.org/articles/PMC10176789', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8593, 30, 18, null, 'Aufklärung, Konsumkompetenz und Entstigmatisierung des Substanzgebrauchs sowie gemeindebasierte Prävention fördern.', '{3006}', null, 2, 3, null, 'Kontakt- und Aufklärungsangebote verringerten Stigma in fast allen untersuchten Studien; ob mehr Betroffene Hilfe suchen, ist kaum belegt, Umfang der Förderung offen. Bundesprogramme dafür bestehen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=133', 'https://europepmc.org/articles/PMC3272222', 'belegt', '2026-10-07', false, true, 'blind'),
  (8594, 30, 18, null, 'Glücksspiel in der Suchtprävention verstärkt berücksichtigen.', '{3004}', null, 1, 3, null, 'Präventionsprogramme zu Glücksspiel zeigten in weniger als der Hälfte der Studien Verhaltenseffekte; Angebot und Werbung bleiben unverändert. Bundesweite Präventionsarbeit ist bereits etabliert und leicht ausbaubar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=133', 'https://doi.org/10.1016/j.addbeh.2018.11.048', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8595, 33, 18, null, 'Manipulative Gestaltung digitaler Angebote (Dark Patterns) und algorithmische Beeinflussung werden gesetzlich geregelt.', '{3301}', null, 2, 1, null, 'Setzt direkt an belohnungs- und suchtfördernden Designs an, die eine Prüfung trotz DSA auf allen großen Plattformen fand. Dagegen: Wirkung auf die Nutzung kaum untersucht; DSA und Verbraucherrecht sind EU-weit harmonisiert, nationale Regeln kaum möglich.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=27', 'https://www.vzbv.de/en/social-media-platforms-failing-adequately-protect-minors', 'offen', '2026-10-07', false, true, 'blind'),
  (8596, 33, 18, null, 'Aufsicht über digitale Dienste einschließlich des digitalen Jugendschutzes wird bei der Bundesnetzagentur gebündelt.', '{3301}', 8394, 1, 3, null, 'Der DSA verpflichtet Plattformen zu Risikoprüfungen auch zu Minderjährigen; die Wirkung auf Likes- und Belohnungsdesign ist bisher kaum untersucht. Umsetzung durch den Bund ist möglich.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=25', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8597, 33, 18, null, 'Schulungen für Eltern zu Chancen und Risiken der Digitalisierung.', '{3303}', null, 2, 2, null, 'Setzt direkt bei der Begleitung durch Eltern an; Programme mit Elternbeteiligung senkten problematische Nutzung stärker. Dagegen: reine Elternangebote kaum belegt, sie erreichen vor allem Interessierte; Elternbildung tragen Länder und Kommunen, der Bund kann fördern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=113', 'https://real.mtak.hu/222946', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8598, 30, 18, 'BE', 'Diamorphin-Substitution ausbauen und drogenabhängigen Menschen Zugang zu psychotherapeutischer Hilfe ermöglichen', '{3006}', 8322, 2, 2, null, 'Konsumräume erreichen Randgruppen und senken Überdosierungen ohne mehr Konsum; Substitution ist gut belegt. Räume brauchen Landesrecht, Therapieplätze Personal.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=84', 'https://doi.org/10.1016/j.drugalcdep.2014.10.012', 'belegt', '2026-10-08', false, true, 'blind'),
  (8599, 33, 18, 'BE', 'Medienkompetenz, reflektierter Umgang mit digitalen Technologien und Algorithmusverständnis werden fester Teil des Unterrichts.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=48', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8600, 33, 18, 'MV', 'Medien- und Demokratiebildung altersgerecht und fächerübergreifend ab der ersten Klasse im Unterricht verankern.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=7', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8601, 33, 18, 'ST', 'Medien- und Demokratiebildung ab Klasse 1 fächerübergreifend verankern, mit Vermittlung von Plattformlogiken und kritischer Medienkompetenz.', '{3303}', 8389, 1, 3, null, 'Schulische Programme senkten problematische Nutzung deutlich, Bildschirmzeit kaum (Metaanalyse, 34 Studien, Verzerrung möglich). Allgemeine Medienbildung setzt nur indirekt an der Begleitung durch Eltern an.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=30', 'https://europepmc.org/article/MED/40549948', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8602, 6, 18, 'BE', 'Einheitlicher Rahmenvertrag mit Qualitätskriterien und verlässlicher Refinanzierung für Anbieter, die den Bezirken Unterbringungsplätze bereitstellen.', '{601}', null, 1, 3, null, 'Ein Rahmenvertrag mit verlässlicher Refinanzierung macht die Bereitstellung von Plätzen planbarer und kann teure Notbeschaffung vermeiden; zusätzliche Plätze schafft er nicht direkt, und höhere Qualitätsvorgaben können Kosten erhöhen. Das Land kann ihn selbst regeln.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=107', 'https://www.bpb.de/themen/migration-integration/kurzdossiers/kommunale-migrations-und-fluechtlingspolitik/577376/kommunale-unterbringung-von-gefluechteten-in-deutschland/', 'offen', '2026-10-08', false, true, 'blind'),
  (8603, 6, 18, 'BE', 'Feste Stellen für die Belange Zugewanderter in Ämtern, darunter Landesamt für Einwanderung und Landesamt für Flüchtlingsangelegenheiten.', '{601}', null, 1, 2, null, 'Zusätzliche feste Stellen, auch in Einwanderungs- und Flüchtlingsbehörden, können Anliegen bündeln und Behörden etwas entlasten; die Überlastung entsteht laut Studien aber auch durch komplexes Recht und schleppende Digitalisierung, und Zahl und Wirkung der Stellen bleiben offen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=105', 'https://www.bertelsmann-stiftung.de/de/unsere-projekte/migration-fair-gestalten/projektnachrichten/studie-auslaenderbehoerden-zwischen-anspruch-und-alltag', 'offen', '2026-10-08', false, true, 'blind'),
  (8604, 6, 18, 'ST', 'Geflüchtete dezentral statt in großen Sammelunterkünften unterbringen, um Kosten zu senken und Teilhabe früh zu ermöglichen.', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=135', null, 'gemischt', '2026-10-08', false, true, null),
  (8605, 16, 18, 'BE', 'Ausgewiesene Wärmenetzgebiete zügig ans Fernwärmenetz anschließen und außerhalb davon Nahwärmelösungen schaffen, wo technisch und wirtschaftlich sinnvoll.', '{1603}', null, 2, 2, null, 'Schafft Klarheit, wo ein Wärmenetz kommt, und setzt den Wärmeplan um; Netzausbau ist teuer, dauert Jahre und rechnet sich nur bei hoher Anschlussquote, die im Bestand unsicher ist.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=92', 'https://www.roedl.com/insights/investitionsunsicherheit-ausbaugebiet-foerderung/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8606, 16, 18, 'ST', 'Zentrale Kompetenzstelle im Land, die Kommunen und Unternehmen bei Wärmeplanung und Wärmenetzprojekten berät und begleitet.', '{1603}', 7158, 2, 3, null, 'Beschleunigt die Wärmepläne und den Bau von Wärmenetzen, auf die viele Eigentümer warten; das Land kann Kommunen mit Geld und Fachleuten helfen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=69', null, 'gemischt', '2026-10-08', false, true, null),
  (8607, 17, 18, 'BE', 'Gesetzliche Zielgrößen für den Betreuungsschlüssel in Krippe und Kita', '{1703}', 7286, 3, 2, null, 'Die konkreten Zielwerte setzen direkt an der Personalausstattung an, die pädagogische Interaktionen ermöglicht. Die Verbesserung ist wirksam, erfordert angesichts des Fachkräftemangels aber zusätzliche Personal- und Finanzressourcen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=44', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8608, 17, 18, 'BE', 'Ausbildung und Qualifizierungswege ausbauen, Quereinstieg besser strukturieren, ausländische Abschlüsse schneller anerkennen', '{1702}', 7293, 2, 2, null, 'Mehr Ausbildungsplätze, Praxisanteile und Quereinstiege können mittelfristig den Personalzugang verbessern. Fehlende Lehrkräfte, Räume und Ausbildungserfolg begrenzen den Zuwachs.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=44', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8609, 17, 18, 'BE', 'Multiprofessionelle Teams in Kitas stärken, um Fachkräfte zu entlasten', '{1702}', 7298, 2, 2, null, 'Zusätzliche spezialisierte Kräfte können Kinder mit besonderem Förderbedarf gezielter unterstützen. Fachkräftemangel und die Finanzierung dauerhafter Stellen begrenzen die Umsetzung.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=44', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8610, 17, 18, 'BE', 'Vorrang beim Kita-Platzausbau für Quartiere mit hohem Bedarf', '{1701}', 7276, 2, 3, null, 'Kleinräumige Planung kann Plätze besser an Bedarf und Bevölkerungsentwicklung anpassen. Sie behebt einen landesweiten Personal- oder Finanzmangel nicht allein.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=45', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/fruehe-bildung-bedarfsgerechte-angebote-fehlen-weiterhin.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8611, 17, 18, 'MV', 'Beitragsfreiheit der Kitas langfristig absichern, unabhängig vom Einkommen der Eltern.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=9', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8612, 17, 18, 'MV', 'Besserer Betreuungsschlüssel mit mehr pädagogischem Personal pro Gruppe sowie bessere Arbeitsbedingungen und angemessene Vergütung.', '{1702,1703}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=9', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8613, 17, 18, 'ST', 'Mehr pädagogisches Personal und Objekt- statt Subjektfinanzierung, um den Betreuungsschlüssel zu verbessern.', '{1703,1702}', 7287, 2, 2, null, 'Mehr anrechenbare Personalzeit und die Berücksichtigung von Ausfällen können die Betreuung spürbar verbessern. Der Effekt bleibt begrenzt, wenn zusätzliche Fachkräfte nicht verfügbar sind.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=14', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/1756-verbesserte-personalschluessel-aber-belastung-durch-ausfaelle.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8614, 17, 18, 'ST', 'Erzieherinnen und Erzieher höher und verlässlicher bezahlen.', '{1702}', 7291, 2, 2, null, 'Bessere Bezahlung und Arbeitsbedingungen können die Attraktivität und Bindung von Fachkräften erhöhen. Der Fachkräftemangel und die Tarif- und Haushaltskosten begrenzen Geschwindigkeit und Reichweite.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=14', 'https://www.dji.de/veroeffentlichungen/aktuelles/news/article/personalkrise-in-der-kindertagesbetreuung-spitzt-sich-zu.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8615, 17, 18, 'ST', 'Sechs Stunden tägliche Kita-Betreuung landesweit kostenfrei; darüber hinaus Beiträge nach Elterneinkommen gestaffelt.', '{1705}', 7302, 2, 2, null, 'Beitragsfreiheit entlastet Familien und kann die Nutzung besonders bei jüngeren Kindern erhöhen. Sie schafft zusätzliche Nachfrage und kann Mittel binden, die sonst für Qualität oder Plätze verfügbar wären.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=14', 'https://www.dji.de/themen/kinderbetreuung/gebuehrenfreie-kitas-verstaerken-ungleiche-belastung-von-familien.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8616, 10, 18, 'MV', 'Gezielte Förderung kommunaler, genossenschaftlicher und quartiersnaher Pflegeeinrichtungen, um die Versorgung vor Ort zu sichern und Pflege bezahlbar zu halten.', '{1005}', null, 1, 3, null, 'Landesförderung für bestimmte Träger kann Kosten dämpfen, die Heime an Bewohner weitergeben; Art und Umfang der Förderung bleiben offen, und kommunale oder gemeinnützige Heime sind laut Daten nicht günstiger als private. Das Land kann ein Programm selbst auflegen.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=33', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8617, 10, 18, 'ST', 'Investitionskostenförderung des Landes für Pflegeeinrichtungen ausbauen, damit Bewohner weniger zahlen.', '{1005}', 6448, 1, 3, null, 'Eine Landesbeteiligung an den Investitionskosten senkt den Eigenanteil; ohne Angabe, wie viel das Land übernimmt, bleibt die Entlastung offen. Das Land kann es selbst regeln.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=41', null, 'gemischt', '2026-10-08', false, true, null),
  (8618, 29, 18, 'BE', 'Mental Health Coaches an Schulen und Jugendzentren und Mental Health im Lehrplan verankern; Mental Health Days vor Ort einführen.', '{2903}', 8150, 2, 2, null, 'Fachkräfte vor Ort erleichtern das Erkennen von Belastungen und die Hilfesuche; Angebot und Bedarf klaffen bislang auseinander. Wirkung kaum untersucht, Personalgewinnung dauert Jahre.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=83', 'https://europepmc.org/articles/PMC13341547', 'offen', '2026-10-08', false, true, 'blind'),
  (8619, 29, 18, 'BE', 'Pflichtfach Lebenskompetenz mit Schwerpunkt psychische Gesundheit, Empathie und sozial-emotionalem Lernen, zunächst an Pilotschulen.', '{2903}', 8151, 1, 3, null, 'Unterricht kann Wissen vermitteln, doch Übersichten finden wenig Beleg, dass schulische Präventionsprogramme Angst oder Depression senken; einzelne Ansätze zeigen Effekte. Land kann Lehrpläne anpassen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=48', 'https://europepmc.org/article/MED/31734106', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8620, 29, 18, 'BE', 'Gesundheitskioske und Gesundheitslots*innen für niedrigschwellige, mehrsprachige Beratung in benachteiligten Stadtteilen.', '{2903}', null, 1, 2, null, 'Mehrsprachige Gesundheitskioske wurden in einer Evaluation gut angenommen, Gesundheitskompetenz stieg aber nicht messbar; psychische Gesundheit ist nur ein Thema unter vielen. Dauerfinanzierung mit Kassen ungeklärt.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=80', 'https://www.aerzteblatt.de/archiv/223895', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8621, 29, 18, 'BE', 'Betroffene in Anti-Stigma-Kampagnen und Programme zur psychischen Gesundheit einbeziehen.', '{2904}', 8152, 1, 3, null, 'Aufklärung und Kontaktprogramme verbessern kurzfristig Einstellungen und Wissen; langfristige Effekte und Wirkung auf die Hilfesuche sind kaum belegt. Gut umsetzbar.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=83', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8622, 29, 18, 'BE', 'Begegnungsorte gegen Einsamkeit wie Mehrgenerationencafés und Nachbarschaftszentren schaffen.', '{2901}', 8142, 2, 3, null, 'Gruppen- und Aktivitätsangebote lindern Isolation häufiger als Einzelangebote (Übersicht, überwiegend schwache Studien); Wirkung bei Verwitweten nicht gesondert belegt. Land und Kommunen können Orte rasch fördern.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=83', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8623, 29, 18, 'ST', 'Niedrigschwellige Angebote zur psychischen Gesundheit wie Mental-Health-Cafés, Gruppen und digitale Formate ausbauen.', '{2903}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=39', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8624, 29, 18, 'ST', 'Männerberatungsstellen und psychosoziale Beratung ausbauen und regional besser verfügbar machen.', '{2904}', 8154, 2, 3, null, 'Wohnortnahe, niedrigschwellige Beratung senkt Hürden bei der Hilfesuche und hilft beim Einordnen von Beschwerden. Wirkung einzelner Modelle kaum vergleichend untersucht; Land kann Förderung zügig ausweiten.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=128', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8625, 29, 18, 'ST', 'Öffentlichkeitsarbeit, die das Holen von Hilfe als normale Stärke vermittelt.', '{2904}', 8152, 1, 3, null, 'Aufklärung und Kontaktprogramme verbessern kurzfristig Einstellungen und Wissen; langfristige Effekte und Wirkung auf die Hilfesuche sind kaum belegt. Gut umsetzbar.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=128', 'https://europepmc.org/article/MED/26410341', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8626, 29, 18, 'ST', 'Soziale Gesundheit stärken durch Programme gegen Einsamkeit und Förderung stabiler Beziehungen.', '{2901}', null, 1, 3, null, 'Gruppenangebote gegen Isolation zeigen in Übersichten häufig Verbesserungen, die Studien sind aber oft schwach; ohne benannte Programme bleibt offen, was entsteht. Land kann Programme leicht auflegen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=40', 'https://europepmc.org/article/MED/21843337', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8627, 8, 18, 'BE', 'Angebot in Außenbezirken und Randlagen durch digitale Rufbusse und autonome Shuttles verbessern; langfristige Finanzierung des Deutschlandtickets unterstützen.', '{801}', 6750, 1, 3, null, 'Schließt Lücken dort, wo Linienbusse fast leer fahren würden; Rufbusse befördern wenige Menschen je Fahrt und sind teuer, ersetzen also keinen dichten Takt.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=31', null, 'gemischt', '2026-10-08', false, true, null),
  (8628, 8, 18, 'BE', 'Modernen Nahverkehrsplan zeitnah umsetzen: Investitionen bündeln, Takte verbessern, neue Tangentialverbindungen mit Tram und Expressbus schaffen.', '{801}', 6749, 2, 2, null, 'Häufigere Fahrten und direkte Verbindungen verbessern das Angebot spürbar und ziehen mehr Fahrgäste an; das Land muss die zusätzlichen Fahrten dauerhaft bezahlen und braucht Fahrpersonal.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=32', null, 'belegt', '2026-10-08', false, true, null),
  (8629, 8, 18, 'BE', 'U-Bahnen vollautomatisieren und bei Tram und Bus digitale Unterstützungssysteme für Fahrpersonal einsetzen, um den Betrieb unabhängiger vom Fachkräftemangel zu machen.', '{803}', null, 1, 2, null, 'Fahrerlose U-Bahnen laufen etwa in Nürnberg und Paris und sparen Fahrpersonal; der Mangel betrifft aber vor allem Bus und Tram, wo Assistenzsysteme niemanden ersetzen. Die Umrüstung dauert Jahre und ist teuer.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=32', 'https://www.trackopedia.com/en/news/all-countries/automated-metro-lines-could-double-in-length-by-2030', 'belegt', '2026-10-08', false, true, 'blind'),
  (8630, 8, 18, 'MV', 'Dichtere Taktung auf stark nachgefragten Hauptachsen, durchgehender Stundentakt auf wichtigen Strecken', '{801}', 6749, 2, 2, null, 'Häufigere Fahrten und direkte Verbindungen verbessern das Angebot spürbar und ziehen mehr Fahrgäste an; das Land muss die zusätzlichen Fahrten dauerhaft bezahlen und braucht Fahrpersonal.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=53', null, 'belegt', '2026-10-08', false, true, null),
  (8631, 8, 18, 'MV', 'Landesweite Mindeststandards für Taktung und Anschlusssicherheit im Nahverkehr', '{801}', 6751, 2, 2, null, 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und braucht Fahrpersonal, das derzeit fehlt.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=54', null, 'offen', '2026-10-08', false, true, null),
  (8632, 8, 18, 'MV', 'Rufbus- und On-Demand-Systeme ausbauen, um ländliche Regionen besser anzubinden', '{801}', 6750, 1, 3, null, 'Schließt Lücken dort, wo Linienbusse fast leer fahren würden; Rufbusse befördern wenige Menschen je Fahrt und sind teuer, ersetzen also keinen dichten Takt.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=54', null, 'gemischt', '2026-10-08', false, true, null),
  (8633, 8, 18, 'MV', 'Kostenloser ÖPNV für Schüler, Auszubildende, Studierende und Freiwilligendienst-Leistende', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=54', null, 'belegt', '2026-10-08', false, true, null),
  (8634, 8, 18, 'ST', 'Landesweite Mindeststandards für Taktung, Anschlusssicherheit und Erreichbarkeit im Nahverkehr', '{801}', 6751, 2, 2, null, 'Setzt direkt am fehlenden Grundangebot an; ein flächendeckender Takt ist teuer und braucht Fahrpersonal, das derzeit fehlt.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=90', null, 'offen', '2026-10-08', false, true, null),
  (8635, 8, 18, 'ST', 'Landesweiter Ausbau von Rufbus- und On-Demand-Systemen im ländlichen Raum', '{801}', 6750, 1, 3, null, 'Schließt Lücken dort, wo Linienbusse fast leer fahren würden; Rufbusse befördern wenige Menschen je Fahrt und sind teuer, ersetzen also keinen dichten Takt.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=91', null, 'gemischt', '2026-10-08', false, true, null),
  (8636, 8, 18, 'ST', 'Ausreichend Fahrzeuge und Fahrpersonal für Rufbusse durch Förderung und Qualifizierung sichern', '{803}', 6754, 2, 3, null, 'Schnellere Qualifizierung, Anerkennung ausländischer Abschlüsse und eigene Ausbildung setzen direkt am Mangel an; ohne bessere Bedingungen verlassen viele den Beruf wieder.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=91', null, 'gemischt', '2026-10-08', false, true, null),
  (8637, 8, 18, 'ST', 'Landesweit koordiniertes, einkommensabhängig bezuschusstes Sozialticket für das Deutschlandticket', '{804}', 6840, 2, 2, null, 'Entlastet die Gruppen spürbar, für die der Preis am ehesten eine Hürde ist; das Land muss die Rabatte dauerhaft bezahlen, und für alle anderen bleibt der Preis gleich.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=96', null, 'belegt', '2026-10-08', false, true, null),
  (8638, 8, 18, 'ST', 'Kostenfreier ÖPNV für Schülerinnen und Schüler landesweit', '{804}', 6841, 2, 2, null, 'Nimmt jungen Menschen die Kosten ganz ab; kostenlose Schülertickets gibt es in mehreren Ländern bereits. Das Land muss die Einnahmeausfälle dauerhaft ausgleichen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=96', null, 'belegt', '2026-10-08', false, true, null),
  (8639, 8, 18, 'ST', 'Gesetzliche Grundlage für eine kommunale Nahverkehrsabgabe, zweckgebunden für Ausbau, Angebot und stabile Preise', '{801}', null, 2, 2, null, 'Eine kommunale Abgabe schafft eigenes Geld für mehr Angebot, wie die Arbeitgeberabgabe in Frankreich zeigt; laut Difu löst sie die Finanzierungsprobleme nicht allein, und es hängt von den Kommunen ab, ob sie sie einführen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=93', 'https://www.zfk.de/mobilitaet/oepnv/mobil-nahverkehr-studie-difu-finanzierung', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8643, 9, 18, 'BE', 'Konzept für sichere Grün-, Bewegungs- und öffentliche Räume, etwa mit besserer Beleuchtung und Begrünung', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=78', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-08', false, true, 'blind'),
  (8644, 9, 18, 'BE', 'Digitale Meldesysteme, über die Bürger unsichere Orte anonym markieren können', '{901}', null, 1, 3, null, 'Anonyme Meldungen zeigen, wo sich Menschen unsicher fühlen, und können Beleuchtung oder Streifen gezielter lenken, wie Projekte in Australien versuchen. Ob das die Sicherheit verbessert, ist nicht untersucht und hängt von den Folgemaßnahmen ab.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=78', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8645, 9, 18, 'BE', 'Aufsuchende Sozialarbeit und Präsenz statt Repression im Umgang mit Drogenkonsum', '{901}', 7634, 2, 3, null, 'Konsumräume und aufsuchende Hilfe verringern laut Evaluationen offenen Drogenkonsum und Szenebelastung; Diebstahl und Raub im Umfeld sinken aber nicht. Das Land kann solche Angebote mit den Kommunen rasch finanzieren.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=84', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8646, 9, 18, 'BE', 'Bessere Personalausstattung von Polizei und Justiz für höhere Streifendichte und konsequente Strafverfolgung', '{901,902}', 7635, 2, 2, null, 'Studien aus den USA finden weniger Gewalt bei mehr Polizei, und mehr Ermittler können mehr Taten aufklären. Die Ausbildung dauert aber Jahre, Pensionierungen zehren Zuwächse auf, und ohne Zielgröße bleibt der Umfang offen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=76', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8647, 9, 18, 'BE', 'Aufgabenverteilung zwischen Polizei und Ordnungsdiensten, damit sich die Polizei auf Kernaufgaben konzentriert', '{902}', null, 1, 2, null, 'Eine klarere Aufgabenteilung kann Polizeikräfte für Ermittlungen und Einsätze frei machen. Wie viel Zeit das bringt und ob mehr Taten aufgeklärt werden, ist kaum untersucht; die kommunalen Ordnungsdienste brauchen dafür selbst Personal.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=76', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8648, 9, 18, 'BE', 'Polizei mit digitalen Tools modernisieren (E-Akte, KI bei Einsatzberichten) mit Datenschutzregeln', '{902}', 7636, 1, 2, null, 'Bessere Technik und weniger Schreibarbeit verschaffen Zeit für Ermittlungen. Belege für höhere Aufklärungsquoten fehlen, und IT-Projekte der Polizei dauern oft Jahre.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=77', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8649, 9, 18, 'BE', 'Bodycams verpflichtend einschalten, alle Kräfte ausstatten, Löschen durch Beamte verhindern', '{902}', 8640, 1, 3, null, 'Laut Campbell-Übersichtsstudie senken Bodycams Beschwerden etwas, Gewaltanwendung und Festnahmen aber nicht verlässlich; Folgen für Aufklärung und Verurteilungen sind kaum untersucht. Das Land kann Einsatz und Pflichten im Polizeigesetz regeln.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=78', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8650, 9, 18, 'BE', 'Bürger- und Polizeibeauftragten mit Aktenzugang und Ermittlungskompetenzen ausstatten', '{902}', 8641, 1, 3, null, 'Polizeigewalt wird laut einer Opferbefragung (KviAPol) nur selten angezeigt und verfolgt; eine unabhängige Stelle setzt dort an. Ob solche Stellen mehr Taten aufklären, ist kaum untersucht, und sie betreffen nur einen kleinen Teil der Straftaten.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=77', 'https://www.lto.de/recht/nachrichten/n/studie-polizeigewalt-singelnstein-zwischenbericht', 'offen', '2026-10-08', false, true, 'blind'),
  (8651, 9, 18, 'BE', 'Strafverfahren wegen Besitzes geringer Mengen zum Eigenbedarf einstellen, Grenzwerte anheben', '{902}', 8642, 1, 3, null, 'Allein Fahren ohne Fahrschein führte 2021 zu über 38.000 Verurteilungen und fast einem Viertel der Ersatzfreiheitsstrafen; Einstellungsrichtlinien des Landes entlasten die Justiz rasch. Schwerere Taten werden dadurch nur indirekt schneller verfolgt.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=84', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'belegt', '2026-10-08', false, true, 'blind'),
  (8652, 9, 18, 'BE', 'Auf Bundesebene Beweislastumkehr für Vermögen organisierter Kriminalität einführen', '{902}', 7656, 1, 1, null, 'Eine leichtere Einziehung trifft kriminelle Strukturen finanziell, wirkt aber kaum auf alltägliche Taten. Die Beweislastumkehr regelt der Bund, und sie steht im Konflikt mit Unschuldsvermutung und Eigentumsschutz.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=78', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8653, 9, 18, 'BE', 'Gefährdete oder straffällige Jugendliche früh unterstützen: Schulen, Streetwork, Jugendhilfe stärken', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=74', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8654, 9, 18, 'BE', 'Fußfessel für Täter häuslicher Gewalt, damit sie sich Opfern nicht unbemerkt nähern können', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=75', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8655, 9, 18, 'BE', 'Frauenhausplätze ausbauen, um Vorgaben der Istanbul-Konvention zu erfüllen', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=75', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-08', false, true, 'blind'),
  (8656, 9, 18, 'BE', 'Rahmenkonzept zum Gefährdungsmanagement und multiinstitutionelle Fallkonferenzen gegen Stalking und Gewalt umsetzen', '{904}', 7645, 2, 3, null, 'Fallkonferenzen und standardisierte Risikoeinschätzung wie in Großbritannien und Spanien sollen Hochrisikofälle früh erkennen; Berichte melden weniger Wiederholungstaten, aber auch Fehleinschätzungen. Das Land kann es selbst einführen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=75', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8657, 9, 18, 'MV', 'Landeskoordinierungsstelle gegen häusliche und sexualisierte Gewalt wieder einrichten und elektronische Fußfessel gegen Wiederholungstaten einführen.', '{904,908}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=14', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8658, 9, 18, 'MV', 'Schutzhäuser deutlich ausbauen und dauerhaft finanzieren, inklusive anonymer Spurensicherung; mindestens eine Beratungsstelle je Landkreis.', '{904,908}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=15', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-08', false, true, 'blind'),
  (8659, 9, 18, 'MV', 'Kommunale Lichtkonzepte und Bildungskampagnen zur Prävention von Femiziden unterstützen.', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=15', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-08', false, true, 'blind'),
  (8660, 9, 18, 'MV', 'Beamte zum Einsatz von Bodycams zur Einsatzdokumentation verpflichten.', '{902}', 8640, 1, 3, null, 'Laut Campbell-Übersichtsstudie senken Bodycams Beschwerden etwas, Gewaltanwendung und Festnahmen aber nicht verlässlich; Folgen für Aufklärung und Verurteilungen sind kaum untersucht. Das Land kann Einsatz und Pflichten im Polizeigesetz regeln.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=15', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8661, 9, 18, 'MV', 'Unabhängige Ermittlungsstelle für mutmaßliche Polizeigewalt beim Justizministerium einrichten.', '{902}', 8641, 1, 3, null, 'Polizeigewalt wird laut einer Opferbefragung (KviAPol) nur selten angezeigt und verfolgt; eine unabhängige Stelle setzt dort an. Ob solche Stellen mehr Taten aufklären, ist kaum untersucht, und sie betreffen nur einen kleinen Teil der Straftaten.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=15', 'https://www.lto.de/recht/nachrichten/n/studie-polizeigewalt-singelnstein-zwischenbericht', 'offen', '2026-10-08', false, true, 'blind'),
  (8662, 9, 18, 'MV', 'Auf Palantir und vergleichbare intransparente Analyseplattformen bei der Polizei verzichten.', '{902}', 7659, 0, 3, null, 'Die Begrenzung schützt Grundrechte, bringt die Aufklärung aber nicht voran. Belege, dass automatisierte Analysen oder Staatstrojaner die Aufklärung messbar erhöhen, fehlen, der Verlust wäre also gering.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=45', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8663, 9, 18, 'MV', 'Schul- und Jugendsozialarbeit dauerhaft mit Landesmitteln fördern, auch zur Präventionsarbeit.', '{903}', 7642, 2, 2, null, 'Eine Meta-Analyse von 219 Studien findet weniger Aggression durch Programme an Schulen. Für allgemeine Jugend- und Schulsozialarbeit ist die Wirkung auf Gewalt schwerer nachzuweisen, und Fachkräfte fehlen.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=14', 'https://www.ojp.gov/library/publications/effectiveness-school-based-violence-prevention-programs-reducing-disruptive', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8664, 9, 18, 'ST', 'Polizei im ländlichen Raum sichtbarer machen: mobile Wachen und regelmäßige Präsenzpunkte in Gemeinden.', '{901}', 7627, 2, 2, null, 'Mehr sichtbare Polizei kann abschrecken und Vertrauen stärken. Ohne Ausrichtung auf Brennpunkte sind die Effekte bürgernaher Polizeiarbeit auf Kriminalität und Furcht laut Übersichtsstudie aber gering, und Personal ist knapp.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=167', 'https://asu.elsevierpure.com/en/publications/community-oriented-policing-to-reduce-crime-disorder-and-fear-and/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8665, 9, 18, 'ST', 'Kommunale Präventionsmaßnahmen wie Licht- und Raumkonzepte verstärkt unterstützen.', '{901}', 7629, 3, 2, null, 'Eine Übersichtsstudie und ein Zufallsexperiment in New York zeigen weniger Kriminalität nach besserer Beleuchtung, dort nachts im Freien rund ein Drittel weniger schwere Taten. Umsetzen müssen meist die Kommunen, das Land kann fördern.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=170', 'https://www.ojp.gov/ncjrs/virtual-library/abstracts/effects-improved-street-lighting-crime', 'belegt', '2026-10-08', false, true, 'blind'),
  (8666, 9, 18, 'ST', 'Kampagne „Ist Luisa hier?“ landesweit in Clubs, Bars und bei Veranstaltungen umsetzen.', '{908}', null, 1, 3, null, 'Ein Codewort in Clubs und Bars verschafft Betroffenen von Belästigung schnelle Hilfe vor Ort und ist günstig umzusetzen. Ob es Übergriffe verhindert oder Anzeigen erhöht, ist nicht untersucht; es erreicht nur das Nachtleben.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=173', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8667, 9, 18, 'ST', 'Einstellungsverfahren der Landespolizei durch parallele Prüfabläufe beschleunigen, um Personal zu gewinnen.', '{902}', null, 1, 3, null, 'Schnellere Einstellungsverfahren verringern den Verlust von Bewerbern an andere Arbeitgeber. Sie schaffen aber keine zusätzlichen Stellen oder Bewerber, und zur Wirkung auf die Personalstärke gibt es kaum Daten.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=166', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8668, 9, 18, 'ST', 'Ausreichend Personal in Gerichten und Staatsanwaltschaften gewährleisten.', '{902}', 7637, 2, 2, null, 'Fehlende Staatsanwälte und Richter gelten als Hauptgrund für die vielen offenen Verfahren; mehr Stellen setzen dort an. Das Land ist zuständig, doch Nachwuchs ist knapp und viele gehen in Pension.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=175', null, 'belegt', '2026-10-08', false, true, 'blind'),
  (8669, 9, 18, 'ST', 'Verbindliche Zielzeiten für Strafverfahren einführen.', '{902}', null, 1, 2, null, 'Zielzeiten machen lange Verfahren sichtbar und können die Steuerung verbessern. Ohne mehr Personal bleibt der Effekt begrenzt, für Gerichte setzt die richterliche Unabhängigkeit verbindlichen Vorgaben Grenzen, und Wirkungsstudien fehlen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=175', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8670, 9, 18, 'ST', 'KI-Assistenzsysteme an Gerichten erproben und einführen, um Verfahren zu beschleunigen.', '{902}', 7638, 1, 2, null, 'Digitale Akten und Verfahren können Abläufe beschleunigen. Der Rückstand entsteht aber vor allem durch fehlendes Personal, und die Einführung der E-Akte zieht sich seit Jahren.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=176', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8671, 9, 18, 'ST', 'Geringfügige Verfahren (Schwarzfahren) durch Staatsanwaltschaften öfter einstellen.', '{902}', 8642, 1, 3, null, 'Allein Fahren ohne Fahrschein führte 2021 zu über 38.000 Verurteilungen und fast einem Viertel der Ersatzfreiheitsstrafen; Einstellungsrichtlinien des Landes entlasten die Justiz rasch. Schwerere Taten werden dadurch nur indirekt schneller verfolgt.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=177', 'https://www.drb.de/positionen/stellungnahmen/stellungnahme/news/14-2023', 'belegt', '2026-10-08', false, true, 'blind'),
  (8672, 9, 18, 'ST', 'Bodycams im Polizeidienst einsetzen.', '{902}', 8640, 1, 3, null, 'Laut Campbell-Übersichtsstudie senken Bodycams Beschwerden etwas, Gewaltanwendung und Festnahmen aber nicht verlässlich; Folgen für Aufklärung und Verurteilungen sind kaum untersucht. Das Land kann Einsatz und Pflichten im Polizeigesetz regeln.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=170', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356344/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8673, 9, 18, 'ST', 'Unabhängige Ermittlungsstelle für mutmaßliche Polizeigewalt beim Justizministerium einrichten.', '{902}', 8641, 1, 3, null, 'Polizeigewalt wird laut einer Opferbefragung (KviAPol) nur selten angezeigt und verfolgt; eine unabhängige Stelle setzt dort an. Ob solche Stellen mehr Taten aufklären, ist kaum untersucht, und sie betreffen nur einen kleinen Teil der Straftaten.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=170', 'https://www.lto.de/recht/nachrichten/n/studie-polizeigewalt-singelnstein-zwischenbericht', 'offen', '2026-10-08', false, true, 'blind'),
  (8674, 9, 18, 'ST', 'Sonderdezernat für Finanzkriminalität und organisierte Kriminalität bei allen Staatsanwaltschaften.', '{902}', 7657, 1, 3, null, 'Dauerhafte Ermittlungsgruppen bündeln Wissen gegen organisierte Kriminalität. Auf die Aufklärung der vielen alltäglichen Taten wirken sie kaum, und Belege zur Wirkung fehlen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=168', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8675, 9, 18, 'ST', 'Ordnungsämter, Zoll, Polizei und weitere Behörden besser vernetzen.', '{902}', null, 1, 3, null, 'Gemeinsame Kontrollen mehrerer Behörden können Verstöße und Strukturen sichtbar machen, die einzelne Stellen übersehen. Ohne konkreten Auftrag bleibt die Wirkung auf die Aufklärung von Straftaten unbestimmt, Studien dazu fehlen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=168', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8676, 9, 18, 'ST', 'Frauen- und Schutzhäuser ausbauen und dauerhaft finanzieren.', '{904}', 7643, 2, 2, null, 'Laut Frauenhaus-Statistik fehlen über 12.000 Plätze; Schutz und Beratung helfen Betroffenen direkt. Die Gewalt selbst verhindern sie kaum. Das Gewalthilfegesetz verpflichtet die Länder, der Ausbau braucht Jahre und Personal.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=171', 'https://www.frauenhauskoordinierung.de/aktuelles/detail/frauenhaus-statistik-2024', 'belegt', '2026-10-08', false, true, 'blind'),
  (8677, 9, 18, 'ST', 'Elektronische Fußfesseln bei Hochrisikotätern nutzen, um Femizide zu verhindern.', '{904}', 7646, 2, 3, null, 'Überwachte Näherungsverbote nach spanischem Vorbild können Hochrisikofälle schützen. Die Geräte sind aber störanfällig, erreichen nur wenige Fälle und setzen eine Anzeige voraus. Länder können sie im Polizeirecht regeln.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=171', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8678, 9, 18, 'ST', 'Täterarbeit intensivieren, etwa mit Anti-Aggressionstrainings.', '{904}', 7644, 2, 2, null, 'Eine Meta-Analyse findet nach längeren Täterprogrammen deutlich weniger amtlich erfasste Rückfälle, nach Angaben der Partnerinnen aber keinen Effekt; kurze Programme wirken nicht. Das Land kann Angebote fördern.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=171', 'https://journals.copmadrid.org/pi/art/pi2020a11', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8679, 9, 18, 'ST', 'Anonyme Spurensicherung als niedrigschwelligen Zugang zur Beweissicherung ausweiten.', '{908}', 7652, 2, 3, null, 'Vertrauliche Spurensicherung und Ambulanzen sichern Beweise, auch wenn Betroffene erst später anzeigen. Wie stark das Anzeigen und Verurteilungen erhöht, ist kaum untersucht. Das Land kann die Angebote ausbauen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=171', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8680, 9, 18, 'ST', 'Prioritätsverfahren und spezialisierte Richter für Gewaltfälle gegen Frauen.', '{904}', 7649, 1, 3, null, 'Spezialisierte Staatsanwälte und Kammern können Verfahren beschleunigen und Betroffene schonen. Belege für mehr Anzeigen oder Verurteilungen fehlen weitgehend.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=125', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8681, 9, 18, 'ST', 'Zentrale Landeskoordinierungsstelle gegen häusliche und sexualisierte Gewalt einrichten.', '{904,908}', 7648, 1, 3, null, 'Ein Aktionsplan oder eine Koordinierungsstelle kann Zuständigkeiten klären und Lücken sichtbar machen. Ohne zusätzliche Mittel bleibt die Wirkung offen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=170', null, 'offen', '2026-10-08', false, true, 'blind'),
  (8683, 12, 18, 'BE', 'Sofortprogramm für sichere Kreuzungen: Unfallschwerpunkte beseitigen, getrennte Ampelphasen, Schutzinseln und abgesetzte Aufstellflächen.', '{1204}', 8682, 2, 3, null, 'Setzt dort an, wo sich Unfälle mit Radfahrenden häufen, etwa an Kreuzungen mit abbiegenden Autos; Auswertungen zeigen oft Rückgänge, strengere Studien mit Kontrolle der Regression zur Mitte finden aber deutlich kleinere Effekte.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=33', 'https://trid.trb.org/View/482195', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8684, 12, 18, 'BE', 'Radwege, Fahrradstraßen und Radschnellverbindungen zügig ausbauen, gestoppte Radschnellwege wieder aufnehmen.', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=34', null, 'gemischt', '2026-10-08', false, true, null),
  (8685, 12, 18, 'BE', 'An Schulen gezielt über Rücksichtnahme im Straßenverkehr aufklären.', '{1204}', 7066, 1, 3, null, 'Richtet sich an Gruppen mit hohem Risiko, etwa ältere Menschen auf Pedelecs; wie stark Trainings die Zahl schwerer Unfälle senken, ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=33', null, 'offen', '2026-10-08', false, true, null),
  (8686, 12, 18, 'MV', 'Das Land fördert kommunale Radverkehrsprojekte, die Radverkehr von Straßen und Fußgängern trennen, mit Vorrang für Schul- und Pendelwege.', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=56', null, 'gemischt', '2026-10-08', false, true, null),
  (8687, 12, 18, 'MV', 'Das Land gleicht neue gesetzliche Pflichten der Kommunen dauerhaft finanziell aus.', '{1202}', 7061, 1, 2, null, 'Gibt Kommunen Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden sie selbst, und der Landeshaushalt ist begrenzt.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=24', null, 'gemischt', '2026-10-08', false, true, null),
  (8688, 12, 18, 'ST', 'Verlässliche, planbare und bedarfsgerechte Landesfinanzierung der Kommunen, damit sie Aufgaben wie Infrastruktur erfüllen und investieren können.', '{1202}', 7061, 1, 2, null, 'Gibt Kommunen Spielraum für Investitionen; ob das Geld in Straßen fließt, entscheiden sie selbst, und der Landeshaushalt ist begrenzt.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=119', null, 'gemischt', '2026-10-08', false, true, null),
  (8689, 12, 18, 'ST', 'Feste Fristen und Genehmigungsfiktion bei Bau- und Infrastrukturprojekten, vereinfachte Prüfverfahren und mehr Entscheidungskompetenz der Kommunen.', '{1203}', 7062, 2, 3, null, 'Das Land kann Bauordnung, Vergaberecht und Verwaltungsabläufe selbst ändern und so Verfahren verkürzen; laut KfW bremst aber vor allem fehlendes Personal.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=118', null, 'gemischt', '2026-10-08', false, true, null),
  (8690, 12, 18, 'ST', 'Zusammenhängendes Radnetz mit priorisiertem Bau von Radwegen entlang von Bundes- und Landesstraßen, Lückenschlüssen und beschleunigten Verfahren.', '{1204}', 7064, 2, 3, null, 'Getrennte, durchgehende Radwege und sichere Kreuzungen senken das Unfallrisiko nach vielen Studien; die Wirkung hängt von der Gestaltung ab, und neue Wege entstehen nur nach und nach.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=98', null, 'gemischt', '2026-10-08', false, true, null),
  (8691, 12, 18, 'ST', 'Unfallhäufungsstellen an Landesstraßen systematisch beseitigen und gefährliche Kreuzungen umgestalten.', '{1204}', 8682, 2, 3, null, 'Setzt dort an, wo sich Unfälle mit Radfahrenden häufen, etwa an Kreuzungen mit abbiegenden Autos; Auswertungen zeigen oft Rückgänge, strengere Studien mit Kontrolle der Regression zur Mitte finden aber deutlich kleinere Effekte.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=92', 'https://trid.trb.org/View/482195', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8692, 12, 18, 'ST', 'Tempo 30 als Standard innerorts, Ausweitung auf Wohngebiete und Schulwege mit Kontrolle.', '{1204}', null, 2, 2, null, 'Weniger Tempo senkt Zahl und Schwere von Unfällen deutlich (Edinburgh: rund 40 % weniger Verletzte); Zonen kann das Land ausweiten, Tempo 30 als Regel innerorts braucht aber eine Änderung der StVO durch den Bund, sonst nur Modellversuche.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=89', 'https://www.engineersireland.ie/Engineers-Journal/News/revealed-slowing-city-traffic-reduces-road-deaths-by-25-study', 'belegt', '2026-10-08', false, true, 'blind'),
  (8696, 4, 18, 'BE', 'Lehrkräfte langfristiger gewinnen, Ausbildungs- und Qualifizierungswege ausbauen und den Quereinstieg bedarfsorientiert gestalten und pädagogisch begleiten.', '{401}', 6075, 2, 3, null, 'Seiten- und Quereinstieg mit Qualifizierung gewinnt kurzfristig zusätzliche Lehrkräfte; wie gut das gelingt, hängt stark von der Nachqualifizierung ab. Das Land ist zuständig und praktiziert das bereits.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=46', null, 'gemischt', '2026-10-08', false, true, null),
  (8697, 4, 18, 'BE', 'Sanierung und Modernisierung der Schulen beschleunigen und verlässlich in Gebäude, Lernräume und Ausstattung investieren.', '{402}', 6076, 2, 2, null, 'Ein Schulbauprogramm setzt direkt am Sanierungsstau an; wie weit es reicht, hängt von Umfang, Baukapazitäten und Kommunen ab. Das Programm nennt keinen Betrag, die Finanzierung muss das Land im Haushalt sichern.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=46', null, 'belegt', '2026-10-08', false, true, null),
  (8698, 4, 18, 'BE', 'Verbindliche Sprachtests mit vier Jahren, verknüpft mit gezielter Förderung durch qualifizierte Sprachlehrkräfte.', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=45', null, 'gemischt', '2026-10-08', false, true, null),
  (8699, 4, 18, 'BE', 'Kitabesuch ab dem dritten Lebensjahr gezielt fördern; Kitas in Quartieren mit hohem Bedarf beim Platzausbau bevorzugen.', '{404}', 8694, 2, 2, null, 'Kitabesuch ab drei verbessert die Schulfähigkeit benachteiligter und zugewanderter Kinder deutlich; wie der Besuch gefördert wird, bleibt offen. Der Ausbau braucht Fachkräfte, die knapp sind.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=45', 'https://iab.de/en/publications/publication/?id=8487991', 'belegt', '2026-10-08', false, true, 'blind'),
  (8700, 4, 18, 'BE', 'Mehrjähriges Turnaround-Programm für die am stärksten belasteten Schulen mit zusätzlichem Personal, stärkeren Schulleitungen und Ergebnisverantwortung.', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=46', null, 'gemischt', '2026-10-08', false, true, null),
  (8701, 4, 18, 'MV', 'Verbindlicher Lehrer-Schüler-Schlüssel mit klaren personellen Standards für Schulen', '{401}', null, 1, 1, null, 'Kleinere Klassen können Leistungen verbessern, Studien sind aber uneinheitlich. Ein verbindlicher Schlüssel schafft keine Lehrkräfte, sondern erhöht bei bestehendem Mangel den Bedarf; das Personal fehlt absehbar.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=12', 'https://wol.iza.org/articles/class-size-does-it-matter-for-student-achievement/lang/de', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8702, 4, 18, 'MV', 'Lehrkräfte von nichtpädagogischen Aufgaben entlasten durch Digitalisierung und zusätzliche Verwaltungs- und Unterstützungsstellen', '{401}', 6072, 2, 2, null, 'Verwaltungs- und Unterstützungskräfte nehmen Lehrkräften Aufgaben ab und schaffen Zeit für Unterricht; Studien zu solchen Assistenzkräften zeigen positive, aber unterschiedlich große Effekte. Das Land kann die Stellen schaffen, Finanzierung und Bewerberlage sind die Hürden.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=12', null, 'gemischt', '2026-10-08', false, true, null),
  (8703, 4, 18, 'MV', 'Verbindliche, kontinuierliche Sprachförderung in der Kita durch zusätzliche Fachkräfte', '{404}', 6077, 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=10', null, 'gemischt', '2026-10-08', false, true, null),
  (8704, 4, 18, 'MV', 'Flächendeckende Erhebung und gezielte Förderung von sprachlichen und mathematischen Defiziten, möglichst vor der Einschulung', '{404,403}', 8695, 2, 2, null, 'Frühe Erhebung mit gezielter Förderung setzt an Sprach- und Rechenrückständen vor Schulbeginn an; Studien zu vorschulischen Förderprogrammen zeigen unterschiedlich starke Effekte. Braucht Fachkräfte für die Förderung.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=11', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8705, 4, 18, 'MV', 'Dreigliedriges Schulsystem langfristig abschaffen zugunsten einer inklusiven Schule für alle', '{405}', 6079, 1, 2, null, 'Längeres gemeinsames Lernen soll den Einfluss der Herkunft verringern; ob die Schulstruktur den Schulerfolg beeinflusst, ist in der Forschung nicht entschieden. Eine Strukturreform braucht Jahre.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=11', null, 'offen', '2026-10-08', false, true, null),
  (8706, 4, 18, 'MV', 'Schulhefte und Schulbücher werden von der Schule gestellt, damit Familien keine Zusatzkosten tragen', '{405}', 6084, 1, 2, null, 'Kostenfreies Essen und Lernmittel entlasten benachteiligte Familien; Studien finden teils positive, meist kleine Effekte auf das Lernen. Dauerhafte Kosten für das Land.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=9', null, 'gemischt', '2026-10-08', false, true, null),
  (8707, 4, 18, 'ST', 'Beruf der Lehrkraft attraktiver machen: Teamzeiten im Stundenmodell, Entlastung durch Verwaltungs- und IT-Stellen, Abschaffung dauerhafter Mehrarbeit, verbindlicher Lehrer-Schüler-Schlüssel', '{401}', null, 2, 2, null, 'Entlastung und praxisnähere Ausbildung können den Beruf attraktiver machen und Abwanderung bremsen; weniger Mehrarbeit und ein fester Schlüssel erhöhen aber zunächst den Bedarf an Lehrkräften.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=22', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8708, 4, 18, 'ST', 'Verbindliche Sprachstandserhebungen vor der Einschulung einführen und frühe Förderung sicherstellen', '{404}', 6069, 2, 3, null, 'Eine verbindliche Sprachstandsfeststellung mit anschließender Förderpflicht setzt direkt am Sprachförderbedarf an; Studien zu Sprachförderprogrammen zeigen unterschiedlich starke Effekte. Das Land ist zuständig und kann das per Gesetz regeln.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=19', null, 'gemischt', '2026-10-08', false, true, null),
  (8709, 4, 18, 'ST', 'Sprachförderung und Sprach-Kitas dauerhaft absichern, Kita stärker auf Schulfähigkeit ausrichten', '{404}', 6077, 1, 3, null, 'Mehr Sprachförderung in Kitas setzt am Sprachförderbedarf an; ohne verbindliche Feststellung und Förderpflicht erreicht sie nicht sicher alle Kinder mit Bedarf. Das Land ist zuständig.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=14', null, 'gemischt', '2026-10-08', false, true, null),
  (8710, 4, 18, 'ST', 'Schulen in herausfordernden Lagen gezielt besser ausstatten', '{405}', 6071, 2, 2, null, 'Zusätzliche Mittel und Personal für Schulen in schwieriger Lage setzen an der Kopplung von Herkunft und Schulerfolg an; die Evaluation des Startchancen-Programms läuft noch, internationale Erfahrungen sind gemischt. Das Land kann Mittel umverteilen, zusätzliches Personal ist knapp.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=19', null, 'gemischt', '2026-10-08', false, true, null),
  (8711, 4, 18, 'ST', 'Kostenfreie schulische Förder- und Nachhilfeangebote flächendeckend einrichten', '{403}', 8693, 2, 2, null, 'Nachhilfe in Kleingruppen verbessert Leistungen laut Metaanalysen deutlich, vor allem in der Schule und durch geschultes Personal; Umfang und Form sind offen, Personal und dauerhafte Kosten sind die Hürde.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=19', 'https://www.nber.org/papers/w27476', 'belegt', '2026-10-08', false, true, 'blind'),
  (8712, 14, 18, 'BE', 'Einheitliches, mehrsprachiges Serviceportal für zentrale Verwaltungsleistungen, Anträge vollständig online, mit Statusanzeige.', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=15', null, 'gemischt', '2026-10-08', false, true, null),
  (8713, 14, 18, 'BE', 'E-Akte flächendeckend und verbindlich ausbauen, damit digitale Vorgänge nicht ausgedruckt und neu erfasst werden.', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=14', null, 'gemischt', '2026-10-08', false, true, null),
  (8714, 14, 18, 'BE', 'KI in der Verwaltung zur Vorprüfung von Anträgen, Vollständigkeitsprüfung, Priorisierung und Bescheidentwürfen einsetzen.', '{1402}', 7127, 2, 2, null, 'Kann Personalmangel abfedern und Bearbeitungszeiten senken; Voraussetzung sind digitale Akten und Daten, die vielerorts fehlen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=15', null, 'gemischt', '2026-10-08', false, true, null),
  (8715, 14, 18, 'BE', 'Besoldung der Berliner Verwaltung an Bundesniveau angleichen, Zulagen für gefragte Berufsgruppen.', '{1402}', 7128, 2, 2, null, 'Setzt am Personalmangel an, den der Normenkontrollrat als drängend beschreibt; das Land konkurriert aber mit Wirtschaft und anderen Ländern um dieselben Fachkräfte.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=17', null, 'gemischt', '2026-10-08', false, true, null),
  (8716, 14, 18, 'MV', 'Einheitliche digitale Bürgerplattform für alle Verwaltungsleistungen im Land, bis 2030', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=43', null, 'gemischt', '2026-10-08', false, true, null),
  (8717, 14, 18, 'MV', 'Durchgängig digitale Akten, transparente Bearbeitungsstände und einmalige Datenangabe (Once-Only)', '{1401}', null, 2, 2, null, 'Digitale Akten und Once-Only setzen an Medienbrüchen und doppelten Nachweisen an, die Nutzer als größte Ärgernisse nennen. Das Land kann eigene Register vernetzen, volle Wirkung braucht aber die mehrjährige Registermodernisierung mit Bund und Kommunen.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=43', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8718, 14, 18, 'MV', 'KI-gestützte Automatisierung und Standardisierung in der Ministerialverwaltung, Stellenabbau über Neubesetzungssperren', '{1402}', null, 1, 2, null, 'Automatisierung kann Routinearbeit abnehmen; Modellrechnungen sehen Potenzial, aber kein Allheilmittel. Die Einsparung betrifft die Ministerialverwaltung ohne Bürgerkontakt, und eine feste Stellenkürzung verbraucht den Gewinn, statt Engpässe zu lindern.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=23', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8719, 14, 18, 'ST', 'Einheitliche digitale Landesplattform für alle Verwaltungsleistungen bis 2030, OZG konsequent umsetzen', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=106', null, 'gemischt', '2026-10-08', false, true, null),
  (8720, 14, 18, 'ST', 'Vollständig digitale, medienbruchfreie Verfahren von der Antragstellung bis zum Bescheid', '{1401}', 7125, 2, 3, null, 'Setzt an den Hürden an, die Nutzer nennen: schwere Auffindbarkeit und Anträge, die hinterher doch auf Papier bearbeitet werden. Die meisten Leistungen erbringen Land und Kommunen selbst.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=106', null, 'gemischt', '2026-10-08', false, true, null),
  (8721, 14, 18, 'ST', 'Tools, die Formulare mit wenigen Klicks automatisiert ausfüllen', '{1401}', null, 1, 3, null, 'Einfacheres Ausfüllen senkt eine Hürde, die Nutzer bei komplizierten Anträgen nennen; ob Anträge dadurch schneller bearbeitet werden, hängt von der digitalen Bearbeitung dahinter ab und ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=117', 'https://initiatived21.de/publikationen/egovernment-monitor/2025', 'offen', '2026-10-08', false, true, 'blind'),
  (8725, 2, 18, 'BE', 'Abgabe für Sozialwohnungen mit deutlich überschrittener Einkommensgrenze; Einnahmen zweckgebunden in den Neubau weiterer Sozialwohnungen', '{206}', 6649, 1, 3, null, 'Lenkt Sozialwohnungen stärker zu Bedürftigen und bringt Geld für neue Förderung; schafft selbst kaum neue Wohnungen, der Verwaltungsaufwand ist hoch, und Besserverdienende ziehen aus, was die Durchmischung verringern kann.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=29', null, 'gemischt', '2026-10-08', false, true, null),
  (8726, 2, 18, 'BE', 'Verbindliche Sozialquoten bei großen Neubauprojekten beibehalten', '{206}', 8724, 1, 3, null, 'Sichert weiterhin einen Anteil Sozialwohnungen in neuen Quartieren ohne volle Landesförderung; als Fortführung ändert sie nichts daran, dass mehr Wohnungen aus der Bindung fallen, und kleinere Bauvorhaben sind nicht erfasst.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=29', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (8727, 2, 18, 'BE', 'Soziale Miet-Agentur mietet Wohnungen am freien Markt an und gibt sie an Menschen mit geringem Einkommen weiter, mit Mietgarantie des Landes', '{206}', null, 1, 3, null, 'Mietet schnell Wohnungen am Markt für Haushalte mit geringem Einkommen an, wie Sozialvermietungsagenturen in Belgien; als Modellprojekt klein, abhängig von Vermietern, und die Mietgarantie kostet Landesmittel dauerhaft.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=29', 'https://housingeurope.eu/?p=2387', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8728, 2, 18, 'MV', 'Landesprogramme zur Sicherung und zum Neubau von Sozialwohnungen; höhere Fehlbelegungsabgabe', '{206}', 8722, 2, 2, null, 'Neue geförderte Wohnungen und gesicherte Bindungen wirken dem schrumpfenden Bestand direkt entgegen; der Umfang ist nicht beziffert, und bisher reichte die Förderung nicht, um auslaufende Bindungen auszugleichen.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=61', 'https://www.bpb.de/kurz-knapp/zahlen-und-fakten/soziale-situation-in-deutschland/341826/sozialmietwohnungen/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8729, 2, 18, 'MV', 'Neu geschaffene Sozialwohnungen langfristig an Mietpreisgrenzen binden', '{206}', 8723, 1, 3, null, 'Längere Bindungen verhindern, dass neue Sozialwohnungen früh aus der Bindung fallen; die Dauer ist offen, viele Länder binden schon 25 bis 35 Jahre, die Wirkung zeigt sich erst in Jahrzehnten, und Bauherren nehmen Förderung womöglich seltener an.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=61', 'https://www.evangelisch.de/inhalte/243851/30-05-2025/kaum-neue-sozialwohnungen-immer-weniger-sozialwohnungen-deutschland', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8730, 2, 18, 'ST', 'Landesprogramme für den Neubau von Sozialwohnungen und ihre dauerhafte Bindung.', '{206}', 8722, 2, 2, null, 'Neue geförderte Wohnungen und gesicherte Bindungen wirken dem schrumpfenden Bestand direkt entgegen; der Umfang ist nicht beziffert, und bisher reichte die Förderung nicht, um auslaufende Bindungen auszugleichen.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=83', 'https://www.bpb.de/kurz-knapp/zahlen-und-fakten/soziale-situation-in-deutschland/341826/sozialmietwohnungen/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8731, 2, 18, 'ST', 'Fehlbelegungsabgabe erhöhen, damit Sozialwohnungen zielgenauer genutzt werden.', '{206}', 6649, 1, 3, null, 'Lenkt Sozialwohnungen stärker zu Bedürftigen und bringt Geld für neue Förderung; schafft selbst kaum neue Wohnungen, der Verwaltungsaufwand ist hoch, und Besserverdienende ziehen aus, was die Durchmischung verringern kann.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=83', null, 'gemischt', '2026-10-08', false, true, null),
  (8743, 18, 11, 'BE', 'Bestand an Straßenbäumen deutlich erhöhen, bis 2040 auf eine Million, gegen Hitze und Extremwetter', '{1803}', 8732, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C, Baumschatten deutlich mehr gefühlt); Pflanzprogramme kann das Land finanzieren. Dagegen: Wirkung bleibt lokal, junge Bäume kühlen erst nach Jahren.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=80', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8744, 18, 11, 'BE', 'Neuer Stadtwald auf Teilen des Tempelhofer Feldes zur Verbesserung des Stadtklimas', '{1803}', null, 1, 2, null, 'Ein großer Stadtwald kühlt tagsüber sein Umfeld. Dagegen: offene Wiesenflächen erzeugen nachts Kaltluft, die ein Wald teils mindert; die Fläche ist gesetzlich geschützt, Änderungen brauchen ein Landesgesetz.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=80', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8745, 18, 11, 'BE', 'Hitzeschutz früh in Planung und Bau einbinden, mehr Dach- und Fassadenbegrünung vor allem bei öffentlichen Gebäuden, verbindlicher Hitzeschutz bei Kitas und Schulen', '{1803}', 8733, 2, 3, null, 'Grün, Verschattung und baulicher Hitzeschutz senken die Hitzebelastung nachweislich; ein Landesprogramm ist im Haushalt umsetzbar. Dagegen: Wirkung hängt von Mitteln und Umsetzung in den Kommunen ab.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=80', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8746, 18, 11, 'BE', 'Mehr Sonnensegel und Verschattungselemente auf Spielplätzen, besonders in Neubaugebieten', '{1803}', 8734, 1, 3, null, 'Schatten senkt die gefühlte Temperatur vor Ort deutlich, Sonnensegel und Klimainseln sind schnell umsetzbar. Dagegen: Wirkung nur punktuell, an der Erwärmung der Stadt insgesamt ändert sich wenig.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=80', 'https://asu.elsevierpure.com/en/publications/effects-of-natural-and-artificial-shade-on-human-thermal-comfort-', 'belegt', '2026-10-08', false, true, 'blind'),
  (8747, 18, 11, 'BE', 'Schulhöfe, Kitagelände und Sportanlagen entsiegeln, begrünen und mit Wasserspeicherung ausstatten', '{1804}', 8737, 2, 3, null, 'Entsiegelte Flächen verringern Oberflächenabfluss (je nach Belag bis 40 bis 80 %) und Hitze; ein Fonds ist im Landeshaushalt umsetzbar. Dagegen: Private beteiligen sich oft wenig, der Umfang bleibt begrenzt.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=81', 'https://www.zh.ch/de/umwelt-tiere/klima/hitze-im-siedlungsraum/massnahmen-gegen-hitze/oberflaechen.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8748, 18, 11, 'BE', 'Berlin zur Schwammstadt entwickeln: Regenwasser auffangen und speichern, Infrastruktur und Speicherkapazitäten ausbauen', '{1804}', 8736, 2, 2, null, 'Dezentrale Regenwasserbewirtschaftung senkt Abflussspitzen im Mittel um rund 40 % (Übersichtsarbeit). Dagegen: bei extremem Starkregen geringere Wirkung, Umbau des Bestands dauert viele Jahre.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=82', 'https://research.daffodilvarsity.edu.bd/scopus-article/6948', 'belegt', '2026-10-08', false, true, 'blind'),
  (8749, 18, 11, 'MV', 'Deiche, Dünen und Hochwasserschutzanlagen sichern und modernisieren; regionale Hochwasser- und Küstenschutzprojekte unterstützen', '{1805}', 8740, 2, 3, null, 'Deiche schützen bestehende Siedlungen wirksam, Hochwasserschutz ist Landesaufgabe mit Bundesmitfinanzierung. Dagegen: Schutzbauten können neue Bebauung dahinter anziehen (Levee-Effekt) und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=93', 'https://hess.copernicus.org/articles/22/5629/2018/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8750, 18, 11, 'ST', 'Hitzeschutz in der Städtebauförderung stärken und Wasserspeicherung unterstützen, um klimaresiliente Stadtquartiere zu schaffen', '{1803,1804}', 8733, 2, 3, null, 'Grün, Verschattung und baulicher Hitzeschutz senken die Hitzebelastung nachweislich; ein Landesprogramm ist im Haushalt umsetzbar. Dagegen: Wirkung hängt von Mitteln und Umsetzung in den Kommunen ab.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=68', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8751, 18, 11, 'ST', 'Deiche dort zurückverlegen, wo eine Kosten-Nutzen-Abschätzung dies sinnvoll erscheinen lässt, sowie Aktionsplan Wassermanagement', '{1805}', 8741, 2, 2, null, 'Rückhalteräume und Auen dämpfen Hochwasserscheitel nachweislich und entlasten Orte flussabwärts. Dagegen: Flächenerwerb und Planung dauern oft länger als eine Wahlperiode.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=68', 'https://www.umweltbundesamt.de/hochwasser-durch-renaturierung-entschaerfen', 'belegt', '2026-10-08', false, true, 'blind'),
  (8752, 18, 11, 'ST', 'Förderkulisse für Entsiegelungsprojekte schaffen, auch zur Umsetzung kommunaler Hitzeschutzpläne', '{1804,1803}', 8737, 2, 3, null, 'Entsiegelte Flächen verringern Oberflächenabfluss (je nach Belag bis 40 bis 80 %) und Hitze; ein Fonds ist im Landeshaushalt umsetzbar. Dagegen: Private beteiligen sich oft wenig, der Umfang bleibt begrenzt.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=68', 'https://www.zh.ch/de/umwelt-tiere/klima/hitze-im-siedlungsraum/massnahmen-gegen-hitze/oberflaechen.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8753, 18, 12, 'BE', 'Stadtbaumbestand deutlich erhöhen, neue Baumstandorte und Baumscheiben bepflanzen, Altbäume schützen', '{1803}', 8732, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C, Baumschatten deutlich mehr gefühlt); Pflanzprogramme kann das Land finanzieren. Dagegen: Wirkung bleibt lokal, junge Bäume kühlen erst nach Jahren.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=22', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8754, 18, 12, 'BE', 'Mini-Parks und wohnortnahe Grünflächen als Abkühlung; Hitzehotspots entsiegeln oder begrünen', '{1803}', 8732, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C, Baumschatten deutlich mehr gefühlt); Pflanzprogramme kann das Land finanzieren. Dagegen: Wirkung bleibt lokal, junge Bäume kühlen erst nach Jahren.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=22', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8755, 18, 12, 'BE', 'Mehr Regenwasser von der Kanalisation abkoppeln, vor Ort versickern lassen (Schwammstadt), grundstücksübergreifendes Regenwassermanagement verbindlich', '{1804}', 8736, 2, 2, null, 'Dezentrale Regenwasserbewirtschaftung senkt Abflussspitzen im Mittel um rund 40 % (Übersichtsarbeit). Dagegen: bei extremem Starkregen geringere Wirkung, Umbau des Bestands dauert viele Jahre.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=23', 'https://research.daffodilvarsity.edu.bd/scopus-article/6948', 'belegt', '2026-10-08', false, true, 'blind'),
  (8756, 18, 12, 'MV', 'Alle zusammenhängend bebauten Gebiete an Küste und in Flusseinzugsgebieten sollen vor Hochwasser geschützt werden.', '{1805}', 8740, 2, 3, null, 'Deiche schützen bestehende Siedlungen wirksam, Hochwasserschutz ist Landesaufgabe mit Bundesmitfinanzierung. Dagegen: Schutzbauten können neue Bebauung dahinter anziehen (Levee-Effekt) und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=86', 'https://hess.copernicus.org/articles/22/5629/2018/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8757, 18, 12, 'MV', 'Wasser- und Bodenverbände werden bei Deichertüchtigung und Sanierung defekter Rohrleitungen investiv unterstützt.', '{1805}', 8740, 2, 3, null, 'Deiche schützen bestehende Siedlungen wirksam, Hochwasserschutz ist Landesaufgabe mit Bundesmitfinanzierung. Dagegen: Schutzbauten können neue Bebauung dahinter anziehen (Levee-Effekt) und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=86', 'https://hess.copernicus.org/articles/22/5629/2018/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8758, 18, 12, 'MV', 'Weitere Flächenversiegelung konsequent reduzieren; Innenentwicklung hat Vorrang vor der Ausweisung neuer Baugebiete.', '{1804}', 8738, 1, 3, null, 'Bremst neue Versiegelung und ist planerisch sofort möglich. Dagegen: Unverbindliche Flächensparziele wurden bundesweit lange deutlich verfehlt; an bestehender Versiegelung ändert sich nichts.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=87', 'https://www.umweltbundesamt.de/presse/pressemitteilungen/flaechenverbrauch-ziele-verbindlich-festlegen', 'belegt', '2026-10-08', false, true, 'blind'),
  (8759, 18, 12, 'MV', 'Projekte der blau/grünen Stadtentwicklung mit Wasserflächen, Bäumen und Grünflächen zur Verbesserung des Stadtklimas fördern.', '{1803}', 8732, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C, Baumschatten deutlich mehr gefühlt); Pflanzprogramme kann das Land finanzieren. Dagegen: Wirkung bleibt lokal, junge Bäume kühlen erst nach Jahren.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=87', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8760, 18, 12, 'ST', 'Bauliche Maßnahmen gegen Hitze fördern, etwa hellere Oberflächen an Gebäuden und Plätzen.', '{1803}', null, 1, 3, null, 'Helle Oberflächen heizen sich weniger auf und sind günstig. Dagegen: Auf Plätzen reflektieren sie Strahlung auf Menschen und können die gefühlte Hitze tagsüber erhöhen; Förderumfang offen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=24', 'https://iopscience.iop.org/article/10.1088/1748-9326/ab87d4', 'gemischt', '2026-10-08', false, true, 'blind'),
  (8761, 18, 12, 'ST', 'Kommunen bei Hitzeaktionsplänen und beim Schutz innerörtlicher Grünflächen fachlich und finanziell unterstützen.', '{1803}', 8735, 1, 2, null, 'Entsiegelung, Grün und Versickerung wirken nachweislich gegen Hitze und Abfluss; die Zusagen nennen aber weder Mittel noch verbindliches Instrument, daher ist kaum eine Verbesserung absehbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=24', 'https://www.zh.ch/de/umwelt-tiere/klima/hitze-im-siedlungsraum/massnahmen-gegen-hitze/oberflaechen.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8762, 18, 12, 'ST', 'Flächenrecycling hat Vorrang vor weiterer Versiegelung.', '{1804}', 8738, 1, 3, null, 'Bremst neue Versiegelung und ist planerisch sofort möglich. Dagegen: Unverbindliche Flächensparziele wurden bundesweit lange deutlich verfehlt; an bestehender Versiegelung ändert sich nichts.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=24', 'https://www.umweltbundesamt.de/presse/pressemitteilungen/flaechenverbrauch-ziele-verbindlich-festlegen', 'belegt', '2026-10-08', false, true, 'blind'),
  (8763, 18, 12, 'ST', 'Wasserrückhalt ausbauen durch Versickerung und Schwammstadtkonzepte.', '{1804}', 8736, 2, 2, null, 'Dezentrale Regenwasserbewirtschaftung senkt Abflussspitzen im Mittel um rund 40 % (Übersichtsarbeit). Dagegen: bei extremem Starkregen geringere Wirkung, Umbau des Bestands dauert viele Jahre.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=23', 'https://research.daffodilvarsity.edu.bd/scopus-article/6948', 'belegt', '2026-10-08', false, true, 'blind'),
  (8764, 18, 12, 'ST', 'Deichsanierung abschließen, Retentionsräume und Rückhalteflächen schaffen oder reaktivieren.', '{1805}', 8740, 2, 3, null, 'Deiche schützen bestehende Siedlungen wirksam, Hochwasserschutz ist Landesaufgabe mit Bundesmitfinanzierung. Dagegen: Schutzbauten können neue Bebauung dahinter anziehen (Levee-Effekt) und ändern das Bauen in Überschwemmungsgebieten nicht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=23', 'https://hess.copernicus.org/articles/22/5629/2018/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8765, 18, 13, 'BE', 'Umfassendes Entsiegelungsprogramm mit dem Ziel Netto-Null-Versiegelung.', '{1804}', 8737, 2, 3, null, 'Entsiegelte Flächen verringern Oberflächenabfluss (je nach Belag bis 40 bis 80 %) und Hitze; ein Fonds ist im Landeshaushalt umsetzbar. Dagegen: Private beteiligen sich oft wenig, der Umfang bleibt begrenzt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=21', 'https://www.zh.ch/de/umwelt-tiere/klima/hitze-im-siedlungsraum/massnahmen-gegen-hitze/oberflaechen.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8766, 18, 13, 'BE', 'Schwammstadt: Regenwasser durch Entsiegelung, begrünte Dächer und Versickerung in der Stadt halten; das kühlt zugleich die Stadt.', '{1803,1804}', 8736, 2, 2, null, 'Dezentrale Regenwasserbewirtschaftung senkt Abflussspitzen im Mittel um rund 40 % (Übersichtsarbeit). Dagegen: bei extremem Starkregen geringere Wirkung, Umbau des Bestands dauert viele Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=21', 'https://research.daffodilvarsity.edu.bd/scopus-article/6948', 'belegt', '2026-10-08', false, true, 'blind'),
  (8767, 18, 13, 'BE', 'Klimainseln mit Schatten und Wasser in besonders belasteten Quartieren.', '{1803}', 8734, 1, 3, null, 'Schatten senkt die gefühlte Temperatur vor Ort deutlich, Sonnensegel und Klimainseln sind schnell umsetzbar. Dagegen: Wirkung nur punktuell, an der Erwärmung der Stadt insgesamt ändert sich wenig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=21', 'https://asu.elsevierpure.com/en/publications/effects-of-natural-and-artificial-shade-on-human-thermal-comfort-', 'belegt', '2026-10-08', false, true, 'blind'),
  (8768, 18, 13, 'BE', 'Klimaresiliente Bäume vorrangig in Hitze-Hotspots und stark versiegelten, dicht bebauten Kiezen pflanzen.', '{1803}', 8732, 2, 3, null, 'Parks und Bäume kühlen nachweislich (große Parks 1 bis 2 °C, Baumschatten deutlich mehr gefühlt); Pflanzprogramme kann das Land finanzieren. Dagegen: Wirkung bleibt lokal, junge Bäume kühlen erst nach Jahren.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=42', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6458494/', 'belegt', '2026-10-08', false, true, 'blind'),
  (8769, 18, 13, 'BE', 'Kaltluftschneisen erhalten und wo möglich ausbauen.', '{1803}', null, 2, 3, null, 'Funktionierende Kaltluftzufuhr verringert Tropennächte und nächtlichen Hitzestress; Freihalten ist planerisch möglich. Dagegen: Reichweite in dichte Bebauung begrenzt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=22', 'https://www.zh.ch/de/umwelt-tiere/klima/hitze-im-siedlungsraum/massnahmen-gegen-hitze/kaltluftzirkulation.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8770, 18, 13, 'BE', 'Abkopplung von der Mischwasserkanalisation voranbringen, um Wasser in der Stadt zu halten.', '{1804}', 8736, 2, 2, null, 'Dezentrale Regenwasserbewirtschaftung senkt Abflussspitzen im Mittel um rund 40 % (Übersichtsarbeit). Dagegen: bei extremem Starkregen geringere Wirkung, Umbau des Bestands dauert viele Jahre.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=25', 'https://research.daffodilvarsity.edu.bd/scopus-article/6948', 'belegt', '2026-10-08', false, true, 'blind'),
  (8771, 18, 13, 'MV', 'Klimaanpassung in den Kommunen stärken: klimaresiliente Baumpflanzungen, Trinkwasserspender und Schwammstadt-Maßnahmen für kühlere Orte und Umgang mit Starkregen.', '{1803,1804}', 8735, 1, 2, null, 'Entsiegelung, Grün und Versickerung wirken nachweislich gegen Hitze und Abfluss; die Zusagen nennen aber weder Mittel noch verbindliches Instrument, daher ist kaum eine Verbesserung absehbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=13', 'https://www.zh.ch/de/umwelt-tiere/klima/hitze-im-siedlungsraum/massnahmen-gegen-hitze/oberflaechen.html', 'belegt', '2026-10-08', false, true, 'blind'),
  (8772, 18, 13, 'MV', 'Kommunale Klimaanpassungskonzepte fördern, damit Dörfer und Städte vor Hitze und Starkregen geschützt sind.', '{1803,1804}', 8735, 1, 2, null, 'Entsiegelung, Grün und Versickerung wirken nachweislich gegen Hitze und Abfluss; die Zusagen nennen aber weder Mittel noch verbindliches Instrument, daher ist kaum eine Verbesserung absehbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=11', 'https://www.zh.ch/de/umwelt-tiere/klima/hitze-im-siedlungsraum/massnahmen-gegen-hitze/oberflaechen.html', 'belegt', '2026-10-08', false, true, 'blind'),
